INSERT INTO public.operation_inputs_messages VALUES (1184115200, 24249, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAJecWiggylCw48TKO1itEmZNmUa9JQ2AAIv9DEbLrYJSfTurhVBpdK7AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}, "prompt": "Я делаю селфи в зеркале. За моей спиной стоит парень, чуть выше меня. Он почти полностью скрыт, создавая эффект таинственности. На нем черное худи с плотно надето капюшоном, но важно! – капюшон не должен касаться моей головы и не перекрывать мое лицо. Между моей головой и капюшоном должно быть небольшое расстояние. Видно, что у парня русые кудрявые волосы, немного выглядывающие из-под капюшона сзади и по бокам, создавая мягкий ореол. Из-за моей спины видны только его руки, нежно обнимающие меня за талию. Важно, чтобы руки выглядели молодыми. Освещение и тени должны быть реалистичными, чтобы всё выглядело естественно.\"", "sendAs": "photo", "operation": "edit"}');
