INSERT INTO public.operation_inputs_messages VALUES (2315850758, 41091, '{"ratio": "4:3", "prompt": "Крупный план удивленного русского мужчины в спортивном костюме, он смотрит в камеру и указывает пальцем в сторону. Позади него, в качестве фона, во всей красе стоит фотореалистичный агент из игры Counter-Strike 2 (например, Soldier | Phoenix). Агент в полной тактической экипировке, с винтовкой, он стоит на фоне типичного ночного двора с панельными пятиэтажками и ржавыми качелями. Сверхширокоугольный объектив, панорамный кадр с соотношением сторон 21:9, ночь, кинематографичное освещение от уличного фонаря, высокая детализация", "sendAs": "photo", "operation": "gen"}');
