INSERT INTO public.operation_inputs_messages VALUES (1581720354, 97750, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBfc9o5CBwERTpgYoLuvg-e3zMwOuk7gACFMkxG8abIVO7LG4ZZaGsvQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 796, "heightPx": 1013}], "prompt": "Create a cinematic professional football (soccer) poster featuring [refer image]. Keep the original face, hair, shape, and angle exactly as in the image. Show the person in three perspectives: a super close-up portrait with Arsenal jersey 2026, a side profile view wearing a Arsenal football jersey 2026 in the back name OMER, and a full-body shot in full football kit (jersey Arsenal 2026, shorts, socks, and cleats) with sponsor logos. At the bottom, place a dynamic action scene of the player performing a powerful bicycle high jump kick with motion blur and flying grass around. The jersey must clearly display the number 12 on the front, back, and shorts. Use a bold dark Blue Camp Nou stadium background with a large number 12 dan nama\n\n''OMER '' glowing behind", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (8866158195, 98154, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBf2Vo5XbdbZhn9oOaZWKsjMUZh_qzAAPU-TEbszgwS2TAoMb9SVqSAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 737, "heightPx": 1105}], "prompt": "Создайте сцену в галерее современного искусства, используя прилагаемое изображение лица и внешности девушки, не меняя её черты лица. На стене висит большой портрет девушки маслом. Ее лицо и верхняя часть тела написаны в реалистичной, экспрессивной манере масляной живописи с текстурированными мазками и приглушёнными цветами. Чистая красная стена галереи создает профессиональную атмосферу выставки благодаря мягкому освещению, освещающему произведение искусства. Сидит  парень на кресле со спины рассматривает\nкартину ,кинематографическое и таинственное настроение", "operation": "gen-multi-input"}');
