INSERT INTO public.operation_inputs_messages VALUES (7095755012, 94253, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAEBcCpo2exAXlaC-yXZ2BYAAeCl5Yb_XmgAAgvHMRudobBW4oeNpTRDBF4BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "1. Open Chatgpt / Neno Banana \n2. Upload Your Image \n3. Prompt 🔰 \nA black and white, medium shot photograph of a man in uploaded picture. He is wearing sunglasses, a collared jacket over a light-colored long-sleeve shirt, and jeans , luxury rolex watch. His hands are clasped together in front of him, resting near his chin. He is looking slightly upwards and to his left, with a thoughtful or pensive expression. The lighting is strong, creating clear shadows, suggesting an outdoor setting with dappled light on a textured background. The overall mood is cool and stylish size 4:5 image generate.\n\n#starseverywhereシ #Bangladesh #comillalalmai #alamgirhossen", "operation": "gen-multi-input"}');
