INSERT INTO public.operation_inputs_messages VALUES (3032507976, 94297, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBcFRo2f7mDGCNdkq-EZwl7poRheyT4wACl_4xG2QO0Epm4xX7kqM3SgEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1920, "heightPx": 2560}], "prompt": "Создайте мою фотографию в стиле y2k, где девушка стоит с Сукуной Ремёном, у него две пары рук, одной из них он обнимает девушку, они фотографируются в зеркале. На ней готические украшения. Комната за их спинами выглядит в готическом стиле с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Фон позади должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}');
