INSERT INTO public.operation_inputs_messages VALUES (5013320058, 99353, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhARo58CJOElMa7-VSMwL79WKIXPn-wACcvgxGzHRQEs-ovLkpqMVBQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая на фоне однотонной черной стены. Ее волосы гладко зачесаны назад. На ней надет белый жакет с широкими лацканами и одной пуговицей. Под жакетом видна тонкая золотая цепочка на шее. В ушах надеты золотые серьги.На женщину падает сценический свет, создающий круглый светлый участок на стене за ее спиной и выделяющий ее фигуру. Нижняя часть тела скрыта, но видны верхние части брюк черного цвета. Без очков", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6803093549, 99581, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBhPpo598-pIzYpiq-v9IrY17FUaEcwgACksoxG49zQFOj_7KoG22yxAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "> Please keep my real facial features exactly as they are, without any changes.\nGenerate a full-body professional photo of me wearing a clean white dentist’s coat, sitting confidently in my private dental clinic. I am seated on a modern chair with a small dental table in front of me. On the table, there is a nameplate that reads “Dr. Maher Saleh Al-Shaibi”. Also, place a dental model (set of teeth) beside or on the table. The background should clearly show a modern, elegant dental clinic environment with dental equipment and tools in the background. The lighting should be warm and soft, creating a welcoming and realistic atmosphere.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6803093549, 99591, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBhQRo5-BDTQE95rGabqyFzTCy4V8-4gAClcoxG49zQFNLsMamCNw08QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "Keep my real face exactly the same.\nMake a full-body realistic photo of me wearing a white dentist coat, sitting confidently in my private dental clinic. I sit on a modern chair with a small dental table in front. On the table, a nameplate says “Dr. Maher Saleh Al-Shaibi” and a dental model is beside it. The clinic looks modern and elegant with warm lighting.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6803093549, 99598, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBhQRo5-BDTQE95rGabqyFzTCy4V8-4gAClcoxG49zQFNLsMamCNw08QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "Keep my real face exactly the same.\nMake me in a dentist coat, sitting in my clinic with a small table and a nameplate “Dr. Maher Saleh Al-Shaibi” and a dental model on it. Warm lighting, realistic look.", "operation": "gen-multi-input"}');
