INSERT INTO public.operation_inputs_messages VALUES (3820043223, 98636, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBgUVo5pvBK9zP2QK1SCOUbx1PKlFtlAAC7vkxG9fAOUvw_UyxZJlQZQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "«Создайте сцену в галерее современного искусства, используя прилагаемое изображение лица и внешности девушки, не меняя её черты лица. На стене висит большой портрет девушки маслом. Её лицо и верхняя часть тела написаны в реалистичной, экспрессивной манере масляной живописи с текстурированными мазками и приглушенными цветами.\nЧистая красная стена галереи создаёт профессиональную атмосферу выставки благодаря мягкому освещению, освещающему произведение искусства.\nПеред картиной в тёмно-зелёном кресле, видимом сзади, сидит её мужчина, держа в руке сигарету, из которой поднимается тонкий дымок, что придаёт сцене кинематографическое и таинственное настроение»", "operation": "gen-multi-input"}');
