INSERT INTO public.operation_inputs_messages VALUES (6632681966, 100483, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBiIBo6QaeAVHQ5Itdt58KryO2lc9FjwAChv0xG1H0SUss61o6JtWYRwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 853, "heightPx": 1280}], "prompt": "«Создайте сцену в галерее современного искусства, используя прилагаемое изображение лица и внешности девушки, не меняя ее черты лица. На стене висит большой портрет девушки маслом. Ее лицо и верхняя часть тела написаны в реалистичной, экспрессивной манере масляной живописи с текстурированными мазками и приглушенными цветами.\nЧистая красная стена галереи создаёт профессиональную атмосферу выставки благодаря мягкому освещению, освещающему произведение искусства.\nПеред картиной в тёмно-зелёном кресле, видимом сзади, сидит ее мужчина, что придаёт сцене кинематографическое и таинственное настроение» фото 3:4", "operation": "gen-multi-input"}');
