INSERT INTO public.operation_inputs_messages VALUES (5013320058, 100558, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBiMBo6TUVDt_x-5yykKp58IQ3lEFemAACW_cxG2saUEvv_aH4sTdBeAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 978, "heightPx": 1280}], "prompt": "Изображение представляет собой чёрно-белую фотографию, на которой изображена женщина в облегающем чёрном платье без рукавов. Она стоит, закинув руки над головой приподнимая волнистые волосы, с слегка склоненной головой. Ее волосы волнисты и распущены и ниспадают на плечи. На шее у нее тонкая цепочка.За ней видна размытая тень ее же в похожей позе, но с закрытыми глазами и руками, поднятыми над головой.Свет падает на нее таким образом, что подчеркивает контуры ее тела и создает контраст между светлыми и темными участками фотографии. Фон неровный, с переходом от более светлых тонов к более темным. Без очков", "operation": "gen-multi-input"}');
