INSERT INTO public.operation_inputs_messages VALUES (7401583533, 102096, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBjsho6pU6gqO1ISayjaPIKquclICkbAAC8QQyG5L5WUtIMUG0TclMIQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Создай сцену в галерее современного искусства, используя прилагаемое изображение девушки в белом платье и жениха ни на 1% не меняя ничего во внешности На стене висит большой портрет девушки в белом платье и жениха маслом. верхняя часть тела написаны в реалистичной, экспрессивной манере масляной живописи с текстурированными мазками и приглушенными цветами.\nЧистая белая стена галереи создаёт профессиональную атмосферу выставки благодаря мягкому освещению, освещающему произведение искусства.", "operation": "gen-multi-input"}');
