INSERT INTO public.operation_inputs_messages VALUES (6965341115, 108117, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "Пусть эта девочка бежит по коричневой дороге из говна вся грязная а вокруг мир из говна и в руке цветок из говна а платье будет с говном", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (9293374457, 107055, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBRKlo0TvfohmAo5EfY5wvY1Ywur7WegACacsxG4aYkVKZ4WSvpRkpKgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 606, "heightPx": 1280}], "prompt": "@iofeen:Photorealistic image 4k of standing on a bright, green football pitch, taking a selfie with Cristiano Ronaldo and Lionel Messi. He is holding up a smartphone with one hand, smiling naturally. He is wearing a Arsenal FC shirt, He is Wear black jeans and white shoe of Adidas. Cristiano Ronaldo and Lionel Messi stand close on either side of him, smiling casually into the camera like friends posing for a fun picture. The stadium in the background is filled with cheering fans, blurred slightly to keep focus on the selfie group. Bright daylight, realistic details, crisp shadows, and vibrant. Note: use facial description from the uploaded image", "operation": "gen-multi-input"}');
