INSERT INTO public.operation_inputs_messages VALUES (7489847836, 103872, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBlbto685XoH1XUxs68Xud2JpkGiQcdAACS_8xGz53WEu4pP8fqagGxQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "Я доверительный платёж подключила нечаянно", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (7103588792, 102779, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBj7ho6qejvjquGA9j8TEAAeinddEKIxkAAvr_MRtZ1VBLB5WINJnQrIkBAAMCAAN4AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 757, "heightPx": 755}], "prompt": "«Сделать фото так, будто я держу маленькую чёрную пантеру (котёнка). Сохранить полностью лицо девушки без изменений. Не добавлять фильтры, оставить естественные тени и освещение. Руки слегка согнуть так, чтобы выглядело реалистично, будто я держу пантерёнка. Не менять фон, не менять одежду, не менять цвет кожи. Сделать максимально реалистично». подогни 2 руки чтобы не одна рука не была с низу при этом чтобы всё было МЕГО реалистично", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (5013320058, 102850, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBi1Vo6kgrzYK_KWj0WhRA-K5xLl8v5wACGAABMhsBe1hLTDfPVNq8UUIBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "На фотографии изображена женщина с длинными черными волнистыми волосами. Она одета в черную майку на тонких бретельках. На шее у неё золотая цепочка с кулоном в виде треугольника.Одна рука женщины поднята и касается ее волос в верхней части головы. Она смотрит в сторону, ее взгляд направлен вправо от зрителя. Фон белый и однотонный. У нее светлая кожа, выразительные брови и длинные ресницы. На ее лице практически отсутствует макияж.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (8333547791, 104813, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBmWlo6_thdRzzOg0QPEV5WG247tH8TAACWP0xG_5GYEu5giqKINyUDgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBmWpo6_thpvRhl-rU97mWwEtxH2in9gACWf0xG_5GYEtJFe-BQQEhVgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 719, "heightPx": 1280}], "prompt": "♾️: сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки не изменять чтобы была в точь точь", "operation": "gen-multi-input"}');
