INSERT INTO public.operation_inputs_messages VALUES (8720887459, 106108, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "4K", "custom": false, "aspectRatio": "9:16"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBnjho7SqufN1-dAQFJQtKDl4OOOFibAACf_sxG0MeaEvcutPdDkHlQQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBnnlo7TITw6vtmb7RdpnDey-BmwRSOAAC3PsxG0MeaEsOBvVnHU0YowEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1920, "heightPx": 2560}], "prompt": "Пара сидит, прижавшись друг к другу, в маленькой лодке на фоне спокойного озера. Женщина в бордовом платье сидит на краю лодки, свесив ноги за борт. Мужчина в чёрной рубашке и шортах сидит рядом с ней, перекинув через плечо пиджак с узором. Они смотрят друг другу в глаза и нежно улыбаются, создавая тёплую и интимную атмосферу. Небо затянуто облаками, мягкий рассеянный свет создаёт умиротворённую атмосферу». Сцена романтичная и безмятежная. Не меняйте выражение лица, убедитесь, что оно такое же.", "operation": "gen-multi-input"}');
