INSERT INTO public.operation_inputs_messages VALUES (3509907304, 104363, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "На фотографии изображены двое людей, стоящих под большим черным зонтом на мокрой мощеной улице в дождливую погоду, выполненной в стиле импрессионизма. Оба одеты элегантно: женщина — в длинном светлом платье и темном пиджаке, её длинные волосы уложены волнами и дополнены изысканным украшением; мужчина — в темном деловом костюме-тройке с белой рубашкой и галстуком. Они близко друг к другу, создавая атмосферу уюта и романтики. Фоновая часть картины изображает старинные здания и уличные фонари, которые мягко отражают теплый свет на влажной дороге, создавая игру света и тени, характерную для импрессионистского стиля и можно сказать стиля аниме.\nУ девушки карие глаза и волосы, красиво взяты волосы на ушко и закрепленные маленькой заколкой и видны серёжки из серебрянной цепочки , красиво падает челка на лицо, состоящая из двух частей, утончённые черты лица, она смотрит на парня и парень смотрит на неё, они держут один зонтик вместе. У парня темные волосы, корейская внешность, это Чонгук из БТС. У него коричневые волосы, челка раздвинула в обе стороны по краям.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (4972158222, 104356, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBl6Bo6-3QCmf-TODWiHExQaKKDxc4dgAC2PsxG52xYEs6jr-aFH-w4wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBl31o6-v3ysI1YP6tCb_-EUR3Yq1YRwACovkxG7KHYUv7KiAVkivsigEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности", "operation": "gen-multi-input"}');
