INSERT INTO public.operation_inputs_messages VALUES (8333547791, 104971, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBmf5o7BpJUiPoAAFW5rVsgA1IGicwfo0AAnz_MRv-RmBLN6hZiHkhscMBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1170, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBmgho7BrngZGD1nZK_XgiW1uoJXiyRwACOvwxG59bYEtj95lOmz6ShAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "♾️: сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки не изменять чтобы была в точь точь", "operation": "gen-multi-input"}');
