INSERT INTO public.operation_inputs_messages VALUES (1923220451, 110071, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBrfJo8jxCW3ThoOE_0RtaJ8BMbhQL2AACM_sxG5ZXmUtEj1F7ucuZLgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1216}], "prompt": "Создай гиперреалистичный портрет лица крупным планом, видно всё лицо. Сцена драматично освещена мягким неоново-голубым и розовым окружающим светом, который бросает красочные отражения на ее влажную кожу и мокрые волосы.\nКапли воды и мелкие пузырьки прилипают к ее лицу, усиливая кинематографическую атмосферу.\nХорошо видны текстура кожи и интенсивная концентрация взгляда.\nНе меняй черты лица.", "operation": "gen-multi-input"}');
