INSERT INTO public.operation_inputs_messages VALUES (5694210040, 104708, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBmOVo6_d211aHSx1OK6sqNenZ8MRbCAACyf4xG0pPYUtRSY-a_9NsuQEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 492, "heightPx": 1320}, {"file": {"fileId": "AgACAgIAAxkBAAEBmJVo6_TScVfZXjmOaAghuIXtU_Ss5AACzv4xG0pPYUs3s9doNbzgLwEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1919, "heightPx": 2560}], "prompt": "Сделайте чрезвычайно обычное и ничем не примечательное селфи на iPhone без четкого предмета или чувства композиции - просто быстрый случайный снимок. На фотографии небольшое размытие в движении и неравномерное освещение от уличных фонарей или внутренних фонарей, что приводит к легкой передержке в некоторых областях. Угол неудобный, а кадрирование грязное, что придает снимку намеренно посредственное ощущение, как будто он был сделан рассеянно, вытаскивая телефон из кармана. Главный герой [лицо загруженного человека], и …  стоит рядом с ним, оба пойманные в непринужденный, несовершенный момент. На заднем плане виден оживленный ночной город с проезжающими мимо неоновыми огнями, пробками и размытыми фигурами. Общий вид намеренно простой и случайный, запечатлевший аутентичную атмосферу плохо составленного, спонтанного селфи на iPhone.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (8052386672, 109036, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBqbJo8TeH4k5UewmG_wjWmPXlS-bnQgACdgQyGzR0iUvzTlEEII0MVgEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 800, "heightPx": 799}], "prompt": "сделай как будто Дженни Китти сделала селфи с моей машиной ночью", "operation": "gen-multi-input"}');
