INSERT INTO public.operation_inputs_messages VALUES (9163800988, 110660, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsD9o8mGPYkM2JOuhGybeBSJR2D4eEQACfPoxG5TfkEu7D2k_suHttgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Use the photo above as the reference. Create a photorealistic Hong Kong retro portrait with authentic 1990s film look, like a moody movie still. Strictly preserve identity (eyes shape, lips, nose bridge, jawline, skin tone). Vertical portrait, mid-thigh to head (3/4 body). Subject standing, leaning slightly toward camera with both hands resting on small wooden cabinet behind her; shoulders relaxed. Chin slightly down, gaze up toward camera with a melancholic, calm expression. Scene: tight messy Hong Kong room, walls plastered edge-to-edge with yellowed Cantonese newspapers. Behind subject: hazy neon Chinese signage (red + cyan) glowing through mist near the ceiling. Cluttered furniture, compact cabinet, scattered cobwebs, small mirror edge visible. Wardrobe & Styling: cream/ivory lace corset-style dress (tasteful, non-revealing), layered delicate gold necklaces, small hoop or pearl earrings. Hair tousled with wispy bangs across forehead. The face must be a precise copy of my real facial features, do not change the face, and make it a high-resolution photo.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6398827757, 110829, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsOho8pQKNNC_xRW8FBYPpaL3yi9FfAAClgIyG4_rmUsKJxdJ05MQYwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 670, "heightPx": 960}, {"file": {"fileId": "AgACAgIAAxkBAAEBsOlo8pQK4wJmwgQYyeA--W1Eri35VAAClwIyG4_rmUuK4yIx1J7yHwEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 604, "heightPx": 604}, {"file": {"fileId": "AgACAgIAAxkBAAEBsOpo8pQK7lWcW6dAuKJqbB_TLDMqNAACmAIyG4_rmUt5_EtJnVd2SQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "сделай так, чтобы фото трех людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\nЛица не изменять сделать точ в точ", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6025986290, 110683, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsFZo8nWpPH_PDpuKO5nAo9Td12iRmgACEvgxG1c4kEt4OqFXxxItNwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "Dark angel with smoldering, burning eyes, her gaze searing through swirling clouds of ash, a striking and dangerous beauty with raven-black wings unfurled. She stands in a ruined cathedral, moonlight filtering through shattered stained glass, illuminating her bare open torso adorned with ritual scars and glowing runes, the air thick with heat and smoke. An erotic and intense atmosphere, her hair whipping in the wind, embers dancing around her, rendered in the haunting, surreal style of Zdzisław Beksiński and Gerald Brom, with a dramatic chiaroscuro lighting, deep crimson and ashen gray color palette, cinematic composition, hyper-detailed textures.", "operation": "gen-multi-input"}');
