INSERT INTO public.operation_inputs_messages VALUES (4536900096, 131810, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAtRpAgQLHBtrAAG_wk-rvgAB5Udk_24pAAJI_zEb_UwZSCxciz6iO1spAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Сделать по светлее и более хорошое качество. Убрать человека на заднем фоне (в красно-бордовой кофте и джинсах)", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (5013320058, 116517, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Молодая Девушка стоит позади мужчины слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в черную кофту, мужчина одет в черную однотонную футболку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность девушки. Фон бежевый. На мужчину и девушку падает солнечный свет. На руке девушки тонкий золотой браслет.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (2424772408, 112946, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBuS5o8_rAxiR967WPQ2br0Fr6UARLcAACxvIxG3qL2UlVKaow12WPugEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 854, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBuS9o8_rAemaF7kk7v5M6yVZAbkqtGQACMAIyG6uAoEuPuVC56ukhKgEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 570, "heightPx": 600}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности", "operation": "gen-multi-input"}');
