INSERT INTO public.operation_inputs_messages VALUES (3160263571, 120347, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "на основе этих фото сделайте так, чтобы фотография двух людей выглядела так, будто её сняли на Polaroid. на ней не должно быть никаких очевидных объектов или реквизита. она должна выглядеть как мгновенный снимок без особых деталей. добавь легкое размытие движения и свет вспышки камеры к темной области, чтобы он равномерно распределялся по всей фотографии. не искажаете лицо. замени фон за двумя людьми на белую завесу. парень должен меня обнимать.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (9990176979, 111388, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBswxo83Z_e-Snvv5Cm-YrjR19JF3cQAACxxkyG5HniUv1XgNTHCKDlAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 852, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBswdo83WKjxj87F6bImllKnXLRDKZBwAC4vUxGwKgmEtgAtK64giq5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 974, "heightPx": 1280}], "prompt": "Соедините две фотографии в одну \nПарень одет а черную водолазку, бежевые брюки, среднее телосложения, сильные руки. \nДевушка одета в пиджак оверсайз \nВолосы у девушке корни светло русые, кончики светлые \nВолнистые средней длины \nПарень обнимает её за талию \nДевушка смотрит а другую сторону улыбается, легкий макияж \nФон Осенний парк\n\nЛица не меняете\nОни должны быть походы как на оригинальном фотографии", "operation": "gen-multi-input"}');
