INSERT INTO public.operation_inputs_messages VALUES (2225223347, 111425, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsz1o84TJCoDW8aBYCFx-WhmVGNQNmAACxvkxG91AmUuHqT7L30pJ4QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 438, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBsz5o84TJWTcOwyjvaTovPGdlyu-etQACx_kxG91AmUsX9EqloLbxFQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 492, "heightPx": 1280}], "prompt": "Make the image of the two people look like it was taken with a Polaroid camera.\nThere should be no obvious objects or props. It should look like a random shot taken by chance. The image should look like a snapshot that doesn''t attract much attention.\nAdd a slight motion blur and camera flash light to the dark area to distribute it evenly throughout the photo. Avoid distorting the face. Replace the background behind the two people with a white curtain. The guy embraces the girl and their hands are locked together", "operation": "gen-multi-input"}');
