INSERT INTO public.operation_inputs_messages VALUES (2950187302, 113559, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu5Ro9Lw5cEodMvif9U3OEt0fqd1hHwACX_oxGwr_qEv9jiuyxNLuqwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Изображение показывает женщину, сидящую на полу, прислонившись спиной к белой стене. Пол серый.На женщине надета большая черная меховая шуба, которая частично сползла с плеч. Она одета в черные чулки с цветочным узором. На шее у нее золотая цепочка с кулоном.У женщины длинные темные волосы, слегка вьющиеся на концах. У нее светлая кожа и светлые глаза. Ее взгляд направлен прямо в камеру. Ее рука слегка касается меха шубы.", "operation": "gen-multi-input"}');
