INSERT INTO public.operation_inputs_messages VALUES (5013320058, 111728, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы черные, длинные, уложены волнами, они объемны и они ниспадают на плечи. На ней надето несколько золотых украшений: кольцо на пальце, серьги-кольца в ушах, тонкая цепочка на шее и два браслета на запястье. Она смотрит в сторону от камеры, касаясь лица рукой. У неё маникюр в светлых тонах. Фон изображения - черный. Плечи обнажены.", "operation": "gen-multi-input"}');
