INSERT INTO public.operation_inputs_messages VALUES (5013320058, 113964, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото селфи молодой девушки в близи . Фон в комнате , белые  стены и свет тусклый. Максимально сохрани мою внешность. Девушка одета в черную кофту с рукавами и глубоким вырезом в груди. На ней надела цепочка с кулоном треугольника. У девушки черные густые и длинные, прямые волосы. макияж естественный, лицо направлено прямо в камеру, девушка смотрит в бок и слегка улыбается сжав пухлые губы. Качество фото более естественное и четкое. Лицо без сглаживания. Лицо слегка освещает солнечный свет.", "operation": "gen-multi-input"}');
