INSERT INTO public.operation_inputs_messages VALUES (4934258254, 126926, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB78lo_brzZIWoCgABSde6zoe6WtgmFlgAAjzyMRukx_BLFclDRCUe_9gBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "В естественном ультро-высоком разрешении изображение девушки,сидящей на лавочке в осеннем парке,сфотографированой с боку на телефонн.Она сидит боком  к камере без вспышки .Вокруг нее осенние листья ,улица ночью,она сфотографированная со вспышкой .На ней длинный черный кожаный тренч ,черное короткое платье под ним ,черные колготки и сапоги высше колени на каблуке .Съемка случайная.Освешение должен быть мягким .Атмосфера уютная с легким зернистым эффектом.Не меняй черты лица", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (7267149040, 120079, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB1Qto-K_pgCvwva-GxKLOh8GNWZFNQgAC-vsxG4swwEuDHx7c41hZGgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}, {"file": {"fileId": "AgACAgIAAxkBAAEB1Qxo-K_pJAQjMDF_c3X34N2rov9b8QAC-_sxG4swwEtkWQJDv9iAIQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 480, "heightPx": 1280}], "prompt": "На основе этих фото сделай так, чтобы фотография двух людей выглядела так, будто они сфотографировались в машине. Добавь лёгкое размытие движения и свет вспышки камеры к тёмной области, чтобы он равномерно распределился по всей фотографии. Не искажайте лицо. Добавь также закат", "operation": "gen-multi-input"}');
