INSERT INTO public.operation_inputs_messages VALUES (5013320058, 119539, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzlto95nSNub-AaYbMPhjnn4eAmBAmQACrv4xG68OuEsulJO8Og1oWgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 896, "heightPx": 1152}, {"file": {"fileId": "AgACAgIAAxkBAAEBzQNo93hFI4baWTU6gycG68mjh0pXygACo_0xG68OuEsBhIsYQssWlQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 739, "heightPx": 1280}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди.", "operation": "gen-multi-input"}');
