INSERT INTO public.operation_inputs_messages VALUES (1113296352, 118606, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBz0lo97IiJXRIckr6is_mkZtFu3yQ3QACLQABMhuGkcFL6otf09Xs-0gBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 926}], "prompt": "Покрась машину в цвет снежная королева", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (5222813234, 117292, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBye5o9sXb-yGkhjP9Kw1OdFaNhebVDAACTP8xG6QtuEtmObMU0KhuJgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1178, "heightPx": 1178}], "prompt": "нарисуй меня в полный рост, я одет серое худи с капюшоном, на шее у меня завязан галстуком палантин черного цвета с узором из серебристых ромбиков, он прячется под поверх одетый черный пуховик nike с коричневой окантовкой снизу, на мне черные брюки без стрелок в белую полоску, на ногах черные кожаные кеды и белые носки, в левой руке адрессная папка бордового цвета с золотистой гравировкой герба Российской Федерации, в правой руке у меня тлеющая сигарета, нахожусь я в городе Москва, рядом со зданиями Москва Сити, выражение лица у меня спокойное, ярко выраженные скулы и густые брови, убери по краям белые границы и вместо них добавь на фон города Москва, сделай формат 16:9, камера направлена на меня справа сверху, я стою к камере полу боком, взгляд направлен в камеру, добавь эффект рыбьего глаза, рисунок должен быть в стиле загрузочных экранов видеоигры grand theft auto san andreas", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (8539681495, 119099, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB0TZo9-tzftEPCvxCGclhPhkwu23FUgAC1P0xGw5twEtK7Zt6oJQX0QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 488, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB0MBo9-JY2Z3QTdFEhUpytGjlmPfArwACUQQyG7OKwUs8jwEcD4AjAgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB0MJo9-JYARZpw7k75wk9jWxMzl0P7AACUwQyG7OKwUsmvGuoMKUaugEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 816, "heightPx": 1215}], "prompt": "Портрет поколений, три человека , люди стоят в профиль слева направо, смотрят в одну сторону. Мужчина, женщина, девочка изображены на чёрном фоне. Освещение мягкое, подчёркивающее черты лиц. Все одеты в чёрные однотонные футболки, лица расположены близко друг к другу, создавая ощущение единства и преемственности. Не меняй и не искажай лица , нужно полностью сохранить черты лица людей , как в оригинале.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (9624634420, 126952, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7cBo_R5IIYYceVoujchc9HmRWDlpvQACf_cxG7ia6EsOfgXpe8PEZwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Добавить на фото исполнителя Егора Крида как будто он меня обнимает и чтобы это выглядело реалистично", "operation": "gen-multi-input"}');
