INSERT INTO public.operation_inputs_messages VALUES (3307802457, 124857, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB57Zo-7sws4SIVA1yZEPwduwkb_g9qgACJfoxG1in2Uv_8ygotHfaZAEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 640}], "prompt": "Создай Мою Гиперреалистичную Фотографию Без Изменения Черт Лица,на Портрете Мечты в стиле Y2K,лежащей на ярко-розовой атласной простыне,держа в руках Большой Проводной Телефон в стиле 90-х,и в задумчивой мечтательной позе ее Длинные Темные Волосы свободно ниспадают легкими распущенными локонами с помощью зажимов-бабочек золотистые с каждой стороны.Она носит изысканные украшения,в том числе изящные золотые ожерелья и аксессуары,а также массивные золотые кольца.Комната за ней девчачья и мечтательная, украшенная постерами Stray Kids.Ее макияж простой,но гламурный с розовым блеском для губ.Фотография должна быть выполнена в зернистом стиле 90-х годов с таким источником света,как лампа в тускло освещенной комнате ночью.Миска с попкорном лежит рядом с ней рядом с несколькими журналами Stray Kids в стиле 90-х.Певец Stray Kids Bang Chan должен стоять позади нее и смотреть на нее,держа в руке маску Призрачного лица, ее тело должно быть тускло освещено,и она должна стоять у двери в тускло освещенный коридор.Фон за ним должен быть слегка темным и зловещим.", "operation": "gen-multi-input"}');
