INSERT INTO public.operation_inputs_messages VALUES (6533000631, 131362, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECARxpATejrZfGsiOQdlj8iCuhbdD-WgAC-_sxG9rmCUhtzP08HNQoAgEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 637, "heightPx": 716}, {"file": {"fileId": "AgACAgIAAxkBAAECAAHlaQE1GciSAgmdNNh9o-yw8FogW4EAAsQCMht8IAlIUMscCMA1D28BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAHjaQE1Ge9e2ETJ_ej5zzQkg77DYtkAAsUCMht8IAlIsMCYV6eBfkkBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1120, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAHkaQE1GSxhbBQu7HjsWI_4tYbtN_AAAsYCMht8IAlIpj7cZF56fNEBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Эталонный образ: вдохновлен эстетикой гармонии розового и голубого цветов\nЛицо: та же женщина, макияж пастельных тонов — розовые румяна, сиреневые тени для век, блестящие губы.\nВолосы: длинные локоны, ниспадающие каскадом на плечи, с естественным пробором.\nОдежда: платье из сиреневого тюля с вырезом с открытыми плечами и полупрозрачными слоями.\nАксессуары: изящные серьги в цветочек и лента из мягкой ткани на шее.\nПоза: сидя на полу, в окружении лепестков сирени, поднеся один лепесток к губам.\nОсвещение: естественный мягкий утренний свет прохладных тонов.\nФон: комната с минимальным количеством света, белыми шторами и пастельными отблесками.\nКамера: съемка под низким углом, кинематографический фокус на лице и текстуре ткани.\nНастроение: романтическая мечтательность — хрупкая, женственная и неземная.\nФормат: портрет 2:3", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (1042000272, 127651, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB8p5o_jUyIB1q5MMrDROiMmMOFqURNgACx_YxG1wo8UtoMxrPzzGC8wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "Добавь на это фото снежную зиму, солнце должно рассеяно светить на человека с фото со стороны, оставляя мягкие блики. должны сыпаться небольшие хлопья снега, которые остаются на волосах девушки. во круг должна быть атмосфера красивой снежной зимы с белыми сугробами и с чистым снегом. итоговое фото должно выглядеть реалистично", "operation": "gen-multi-input"}');
