INSERT INTO public.operation_inputs_messages VALUES (2574576068, 129627, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB-ldo__7BCrjcjsEbgArHvPqppHFmGgAC4wIyGxWEAAFI1ZE_piZo5RQBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB-lFo__6AeMH8hifKJM_m2P0oKN9WmQACLvgxG4VTAUj5bo1znM7CXgEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 640}], "prompt": "Фотореалистичный\nдвухуровневый коллаж в стиле папарацци.\nВерхнее фото: мужчина и женщина в BMW M5 ночью, крупный план через лобовое стекло. Женщина откинулась назад и смотрит в камеру с отстранённым выражением.\nМужчина слегка подался вперед, его рука на руле, он тоже смотрит в камеру. Освещение - ночной свет и мягкая вспышка, пленочное зерно 35 мм.\nНижнее фото: тот же мужчина и женщина, ракурс через пассажирское окно снаружи.\nЖенщина опирает голову на руку, смотрит в сторону. Мужчина подался вперёд, его рука на руле, он смотрит на пассажирку.\nАтмосфера сырая, неотредактированная, с натуральным зерном плёнки 35 мм.", "operation": "gen-multi-input"}');
