INSERT INTO public.operation_inputs_messages VALUES (4786523001, 129379, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB-Vho_8oWKvMPi-U0cA14ur7UyKE3QAACw_wxGxfBAUhRqly5NMdfiAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "Создай изображение нас. Максимально сохрани нашу внешность. Нежный портрет двух молодых девушек с длинными  волосами, обнимающихся на открытом воздухе. Одна смотрит в сторону с мягким выражением лица, в то время как другая смотрит прямо в камеру с легкой улыбкой. Их руки сложены вместе, и обе одеты в темные повседневные топы на приглушенном, слегка пасмурном фоне. Снято на Fujifilm X-T4 с объективом 56 мм f/1.2, ISO 400, 1/250 с, f/1.8, при естественном пасмурном освещении.", "operation": "gen-multi-input"}');
