INSERT INTO public.operation_inputs_messages VALUES (2072545847, 147549, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECQC9pDDbN54Yedz99SvMd121jP6t9EgAC5AxrGymIYEg5NiHR8GEPSwEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 272, "heightPx": 608}], "prompt": "Convert this into a portrait of a teenage in casual outdoor wear, grilling steaks on a barbecue, with smoke rising around him, captured in golden evening light for a rugged, lifestyle look.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6385531300, 130312, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_QABaQABrf-SmTOoGRVsPYeoVmwd9GzTAAIdAAEyGzB8CEgCE5CrdSJpKAEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1080, "heightPx": 1413}], "prompt": "Сделайте чрезвычайно обычное и ничем не примечательное селфи на iPhone, без четкого предмета или чувства композиции. Просто быстрый случайный снимок. На фотографии небольшое размытие в движении и неравномерное освещение от уличных фонарей или внутренних ламп, что приводит к легкой передержке в некоторых областях. Угол неудобный, а обрамление грязное, что придает картине преднамеренно\nпосредственное чувство, как будто это было принято рассеянно, пока\nвытаскивание телефона из кармана.\nГлавный герой - [лицо загруженного человека), и (Егор Крид) стоит рядом с ним, оба пойманы в случайный, несовершенный момент. Фон\nпоказывает оживленную Таймс-сквер ночью, мимо которой проходят неоновые огни, пробки и размытые фигуры. Общий вид намеренно простой и случайный, запечатлевший аутентичную атмосферу плохо составленного спонтанного селфи на iPhone.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (5820338851, 142483, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkDAAECLIxpCSK5clIXHxKdDnf7McY2Pi_M_wACYAtrG4cgTFB66DtxnPL5ygEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 832, "heightPx": 1248}], "prompt": "Edit the resolution into 8K result", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (1931288462, 131432, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECAWNpAXN6JpoAAU1xkGgolc5jE2iybW0AAnUMaxvixQlQjAJMBIBS7EcBAAMCAAN4AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 439, "heightPx": 550}], "prompt": "put mizuki as my uniform name and don''t change anything else.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (5417676285, 131691, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAlhpAfQbHC7ZwMBxpPsnF1z_NruG8gACNfYxG3NdEUhysqK-XPlv-gEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 720}], "prompt": "Длинные волосы и офисный стиль", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (5013320058, 132110, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECA-BpAkoPW3mpeqDQYfUF7zbgPMiH4AACaQUyG4qQEUjDhyYHoKEqfQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1005, "heightPx": 1280}], "prompt": "Создай фото девушки. Максимально сохрани мою внешность. Девушка лежит горизонтально дивана головой к подлокотнику на спине на диване , фото сделано сверху . На девушке одет черный пиджак на обношенное тело. У девушки черные длинные волосы уложены большими локонами коровье лежит на диване в разные стороны . У девушки маленькие серьги и цепочка. Стена однотонного серого цвета.", "operation": "gen-multi-input"}');
