INSERT INTO public.operation_inputs_messages VALUES (8661139121, 155841, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECYJNpD7DYZ4dw_O3mhlgF3jkEkeVIlAACyRBrG8tdgEiPlzKNME4VgwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 959}], "prompt": "Сделай просто светлый фон , люди на фотке выглядят борзыми , без улыбок , чуть дальше от камеры и показывают средний палец в камеру , фото чб", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (4653923308, 156044, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECYYlpD9QnJw8RTWjvVRgfst3-EjuyigACbQtrG9LHgVB2AAHjcgjvWfgBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "با چهره ی عکس رفرنس، بدون کوچک ترین تغییری در چهره، با این مشخصات بساز:\n\nСоздайте фотографию, где я стою возле чёрного роскошного внедорожника, похожего на G-Wagon. Женщина на прикреплённом фото изображена с максимально точными и реалистичными чертами лица. На ней полностью чёрный зимний наряд, включающий очень пухлую куртку и повязку на голову. Её длинные тёмные волосы слегка ниспадают до талии. На ней необычные солнцезащитные очки с металлическим зеркальным покрытием.\nРазмытый фон создаёт впечатление роскошного снежного зимнего пейзажа. Это как роскошный горнолыжный курорт класса люкс.\nОна частично повернута к камере, её рука лежит на дверце автомобиля, как будто она собирается сесть в машину или выйти из неё.\nУльтрареалистичные, чёткие детали, элегантная композиция, профессиональная художественная фотография, качество 8K.", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (8639126828, 156317, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "Image", "operation": "gen-multi-input"}');
