INSERT INTO public.operation_inputs_messages VALUES (2931447169, 172130, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECoFRpEwVJ6r0a9LYF_ecZ0WbkBaZUgQAC1AxrG4A3mUhHRotEDOcFyQEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1920, "heightPx": 2560}], "prompt": "Преобразовать это изображение в профессиональную, детализированную предметную фотографию подвески. Подвеска из холодного мягкого, светлого белого золота. С узорами точно так как на фото. Крупный план, чтобы были видны все детали. Удалить весь фон и заменить его на чистый белый фон #fff. Улучшить освещение и четкость. Сохранить общий дизайн и пропорции подвески. Высокое разрешение.\n\nУбери лишние тени. Сделай так словно подвеска парит ( добавь снизу тень )", "operation": "gen-multi-input"}');
