INSERT INTO public.operation_inputs_messages VALUES (7472974079, 166926, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECjAtpEbQKCJ8gT-chZLjluawY4v6rFwACcwxrGylQkEi3mJ8AAV-_LcwBAAMCAAN3AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1183, "heightPx": 2560}], "prompt": "Преобразовать это изображение в профессиональную, детализированную предметную фотографию подвески. Подвеска из холодного мягкого, светлого белого золота. инкрустированная бриллиантами. Крупный план, чтобы были видны все детали. Логично посмотри и обдумай где расположение бриллиантов, а затем чётко очерти их и все остальные детали. Удалить весь фон и заменить его на чистый белый фон #fff. Улучшить освещение и четкость бриллиантов, чтобы подчеркнуть их блеск и игру. Сохранить общий дизайн и пропорции подвески. Высокое разрешение.\n\nУбери лишние тени. Сделай так словно подвеска красиво ровно парит ( добавь тень )", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (3410935410, 171240, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECnNtpEsP01AyRTmpIt2IyI301T8d4hQACEAxrG0wiaVCbKUgR3X7N0QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 478, "heightPx": 1080}], "prompt": "A highly stylized, editorial portrait of the person from the uploaded photo. They sit confidently against a deep black studio backdrop, embodying elegance and power through minimalist fashion. Apply the following style: a tailored black suit with a structured blazer and matching trousers, sitting cross-legged in a relaxed yet self-assured pose. [Adapt their hair from the photo to fit the scene, keeping it recognizable]. Their features are refined and polished, with flawless-looking skin and sharp, defined eyes. Gold accessories, including a sleek wristwatch and subtle jewelry, add a touch of luxury. The lighting is soft and controlled, emphasizing their features and the texture of their outfit while maintaining a rich, moody tone. The overall vibe is editorial and empowering. Ensure facial features from the uploaded photo are perfectly maintained.", "operation": "gen-multi-input"}');
