INSERT INTO public.operation_inputs_messages VALUES (5228683414, 176922, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECsxVpFJziGkqawEx3iL-o_mHSLSa9rQACqxBrG3nZoEii1xlQ2ibrTAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Я держу замысловатую золотую корону, почти над головой, с богато украшенной филиграной и большими, блестящими драгоценностями. Корона находится в резком фокусе, отбрасывая мягкую тень на ее лицо. Освещение падает сверху, подчеркивая корону и создавая драматический, высококонтрастный эффект. Легкая тень на ее лице усиливает чувство тайны и элегантности. Ее платье\n- это нежное черное кружево с высоким вырезом, а оправа отрезается на плечах. Фон остается темным и минималистичным, усиливая угрюмую и царственную атмосферу сцены.", "operation": "gen-multi-input"}');
