INSERT INTO public.operation_inputs_messages VALUES (6872151340, 182408, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECyGppFlC4WAtMY79m8GT9QEJVaa8BNgAC5xBrG-JwsEiT2UURcHRKaAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECyIVpFlN8dDm55cqd3--lMfgw5EAAAXAAAsUQaxsD-7FIpEM9bqaQTaoBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 591, "heightPx": 1280}], "prompt": "Двое в возрасте 20-21 года, стоящие на белом фоне, сочетающие позы и черты лица с двух предоставленных эталонных фотографий. Оба стоят, слегка развернувшись на 10-20°, один чуть впереди другого, руки расслаблены (по желанию, одна рука в кармане). Черно-белая фотография, высокая контрастность (или мягкие оттенки серого), студийное освещение в софтбоксе с тонкими тенями, подчеркивающими текстуру кожи и ткани. Камера: портретный объектив 50 мм/85 мм, малая глубина резкости f/2,8–f/4, съемка в полный рост или по пояс. Фотореалистичный, сверхдетализированный снимок.\"", "operation": "gen-multi-input"}');
