INSERT INTO public.operation_inputs_messages VALUES (4786523001, 205072, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDIQtpHejy68xF84lNAZSloTuuAVKdtAACzAtrG-kW6UhvkMI__K0KegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 606, "heightPx": 1007}], "prompt": "Создай изображение меня. Максимально сохрани мою внешность. Ультрареалистичный, высококачественный портрет девушки, стоящей на заснеженном горном склоне среди альпийских пейзажей. На ней объёмная белая шуба из мягкого меха, белые брюки, красные наушники и красные варежки, создающие контраст и акцент в образе. Она стоит напротив камеры и двумя руками поправляет наушники, слегка улыбаясь. Волосы естественные, распущенные, мягко ложатся на плечи. Выражение лица спокойное и уверенное, взгляд направлен в камеру, создавая ощущение уверенности и лёгкости. Фон — величественные заснеженные горы, частично укутанные облаками, внизу виднеется небольшая альпийская деревня с домиками, покрытыми снегом и огнями от уличных осветительных гирлянд. Освещение естественное, дневное, мягкое, с холодными голубовато-белыми тонами. Солнечный свет пробивается сквозь облака, создавая объём и лёгкое сияние на лице и одежде девушки. Объектив 50mm, f/2.2, выдержка 1/500, ISO 100, съёмка с естественным балансом белого. Цветовая палитра холодная, с доминированием белого, голубого и серебристого оттенков. Постобработка чистая, минималистичная, направленная на сохранение реализма и свежести воздуха. Фокус на девушке, фон слегка размытый, чтобы подчеркнуть глубину горного пространства. Качество 4KHD, ультрареалистично, глубокие детали, профессиональный fashion-портрет с атмосферой зимней сказки и гармонии.", "operation": "gen-multi-input"}');
