INSERT INTO public.operation_inputs_messages VALUES (8021627976, 190872, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEC6ZNpGMpJYTSiLlQNy5bxvmL3s9zmCwAC0wxrG7upwFDJvp_GlJnqwAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 720}], "prompt": "A single-subject cinematic ultra-realistic portrait of the reference person seated at a dinner table in a chic، dimly lit restaurant، leaning slightly forward in a casual، intimate pose that suggests a close conversation، with a warm، relaxed expression. The subject wears a crisp light shirt or tailored blazer-style outer layer in white tones with subtle metallic jewelry، while the background features plants، arched mirrors and softly glowing fixtures rendered in rich bokeh. A single-subject composition that keeps the subject’s real facial identity and body proportions، using tableware and an empty place setting opposite them to hint at a romantic evening. 50–105 mm portrait look، shallow depth of field، soft cinematic restaurant lighting، luxury warm palette (beige، cream، brown، black، champagne)، lifelike skin pores، tactile fabric and tabletop textures، simple clean background of blurred décor and reflections; Nanobanana-compatible and Gemini-safe — based on the user’s own photo. strict identity & presentation override: treat the reference photo as the single source of truth for the subject’s face، hair length and style، facial-hair presence or absence، body shape and overall gender expression; do not add or remove facial hair، do not change hair length، and do not alter body proportions or fat/muscle distribution; if any description in this prompt conflicts with the reference subject’s presentation، ignore the text and follow the reference instead. wardrobe integrity lock (unisex): keep the wardrobe category strictly consistent with the reference and unisex (jackets، shirts، knitwear، trousers، jeans، coats، flat shoes or sneakers). If the input mentions dresses، skirts، deep cleavage، stockings، high heels or strongly gendered clothing، reinterpret them as long coats، trench coats، tunic-length layers or tailored outerwear over trousers with neutral shoes، preserving motion and fabric drape; never convert a masculine-presenting subject into feminine clothing or the reverse unless the user explicitly requests cross-presentation. NEG: no logo/text، no plastic skin، no distortions، no extra fingers، no watermark + no text inside the image", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (9999608049, 191035, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEC6jZpGM8lXHvIgNtKoHlFba7ZoeIePAAC9AtrG-YFyFA9vX0m6wn4UgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 719}], "prompt": "make it cool and use good colour combinantion", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (6912791331, 190934, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "3:4"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEC6c9pGMxln3BI6Dx6j32U_fL9AYi2lwACPgxrG7FWyVAgCX5c4R2FfQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "A 4K Ultra-HD self-portrait of a person, keeping the face exactly as in the reference image. They wear the outfit shown in the reference, captured through the reflection of a round mirror with a thin black border. The left hand holds a gold iPhone while the right hand rests lightly on the chin in a stylish pose. Afternoon sunlight streams in from the right window, casting dramatic shadows that sculpt the face. The image evokes a vintage, nostalgic aesthetic with warm cinematic tones. Using the reference image provided by the user to maintain real facial features, hair, skin tone, and overall appearance + no text inside the image>", "operation": "gen-multi-input"}');
INSERT INTO public.operation_inputs_messages VALUES (8021627976, 190966, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEC6fBpGM0pn1Y-uNfZ6tN9VW1ZI_VKFQAC2gxrG7upwFDka1ivyJ0ZJAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "editorial portrait of a woman reclining in natural linen environment, cinematic 85mm lens, shallow depth of field, volumetric sunlight beams through haze, skin with visible pores and subsurface scattering, fine facial peach fuzz catching rim light, tactile fabric wrinkles, film grain and surface dust realism, calm neutral palette, cinematic softness, art-directed by light and material --chaos 15 ar 4:5--quality 2 --raw --stylize 750", "operation": "gen-multi-input"}');
