INSERT INTO public.operation_inputs_messages VALUES (1380298497, 198262, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEDBnNpGxxiffnb5uTKlOYI5k8jyCyswwACewtrG5Cj2VABpld35FPZFwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "کلاهم بردار \nموی سرم رو کوتاه کن،مدل بازکات بزن موی سرم رو\nو ابرو هام رو خط بنداز\nجوشای صورتم از بین ببر\nو یه جاکت تنم کن", "operation": "gen-multi-input"}');
