INSERT INTO public.operation_inputs_messages VALUES (6266853974, 198337, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAEDBrxpGx5H1rEOeCL2TwwTlhhJb1q1QwAC_w1rG7Sh2VTGavBkzcsKVwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Create a vertical ultra-HD 8K render (4320x7680 pixels) divided into three equal horizontal sections, stacked vertically.\nUse the uploaded image as the exact facial reference — preserve identical face, expression, hairstyle, and proportions with no stylization or alteration.\nScene Style: highly detailed, cinematic winter realism — inspired by fine-art portrait photography and high-end fashion editorials.\nCold, emotional, atmospheric, visually stunning.\nThe same character wears a premium matte-black puffer coat, wide-leg snow pants, and a wool scarf with fine fibers visible.\nThe environment is a snowy landscape under diffused cloudy light, with soft fog layers, drifting snowflakes, and cinematic volumetric lighting.\nLighting setup:\nsoft HDR key light from the left (simulating overcast daylight)\nsubtle rim light highlighting hair edges\nambient fill from reflected snow\nfaint golden flare for contrast balance\nvolumetric haze and bloom for depth and realism\nTop Section (Portrait):\nA close portrait of her holding a transparent umbrella covered with thin ice and falling snowflakes.\nShe looks slightly over her shoulder toward the camera, expression deeply emotional and poetic.\nVisible condensation breath in the air.\nBackground: glowing white snow and diffused fog with bokeh sparkles.\nMiddle Section (Full Body):\nFull-body cinematic shot, camera slightly above eye level.\nShe stands alone in a wide snowy field, umbrella tilted, looking upward at the falling snow.\nAdd soft god-rays through the mist, faint motion blur on snowflakes, and a subtle footprint trail behind her for realism.\nBottom Section (Close-up):\nExtreme close-up of her eyes — wet lashes, melting snowflakes, soft reflection of the snowy field and pale sky.\nSubsurface skin scattering for realistic cold texture.\nEmotion: pure melancholy and fragile beauty.\nRendering style:\nultra-realistic cinematic 8K HDR\nsoft contrast, desaturated cool tones with silver-blue highlights\ngentle film grain and lens bloom\ndepth-of-field focus consistency between sections\nhyper-detailed textures (fabric fibers, snow crystals, eyelashes)\nMood: poetic solitude, emotional depth, cold serenity, cinematic realism.", "operation": "gen-multi-input"}');
