INSERT INTO public.operation_inputs_messages VALUES (5013320058, 212647, '{"config": {"model": "google/nano-banana-pro", "nanoBananaPro": {"size": "1K", "format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDPitpIUdupPTkJ_JgmYB92if6ZHJAhAAChxFrG9e9CUmiWeLWU8Tj0AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создайте образ девушки сидящей на яхте в открытом море, на фоне морского пейзажа.\nДевушка с черными волосами , лицо не меняй , одета в элегантный черный Боди корсетного плана (без лямок) и в накидке белой изящно струящейся из мягкой, воздушной ткани, которая мягко колышется на ветру. Боди слегка блестит, подчеркивая гладкую текстуру материала, похожего на шелк, и мягко ниспадает к низу. Она сидит с безмятежным выражением Ю лица с закрытыми глазами, девушка одну руку засунула себе в волосы, второй упирается за спиной .\nумиротворяющая атмосфера, присутствует на снимке.\nНа заднем плане море , создавая обширную,открытую и естественную обстановку. Солнце освещает.", "operation": "gen-multi-input"}');
