INSERT INTO public.operations VALUES ('57105b3f-818e-41f4-94e4-b8889015d695', '2025-10-11 15:25:08.245908', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBi0do6kfeiptO-0ILOp9khtUftXYqxQACFAABMhsBe1hL-kLPZZ-AfNQBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Фотосессию в студии на белом фоне, фото сделано по пояс, у девушки длинные, черные распущенные и волнистые волосы , уложены на правый бок, девушка слегка смотрит в бок и одной рукой поправляет волосы от корня, у девушки черная майка, она сидит на стуле и в лицо попадает солнечный свет", "operation": "gen-multi-input"}', 'gxd9y0v2b1rmc0cstcxr2v52dw', 'succeeded', '{"date": 1760185492, "chatId": 1287537311, "messageId": 101342}', '{"date": 1760185495, "chatId": 1287537311, "messageId": 101347}', '[{"date": 1760185518, "chatId": 1287537311, "messageId": 101352}]');
