INSERT INTO public.operations VALUES ('8ce4cbcb-f40d-41f1-a93a-3367e660d0ad', '2025-10-23 14:37:24.609255', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB3Iho-hMv0d4MbqCkK42lHIjx6uMCawACYP8xGw2H0Eu52bm3-neN7QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Инструкция для обработки фотографии:\nБазовые требования:\nСохранить естественные черты лица без искажений\nСохранить натуральный цвет кожи\nСохранить особенности мимики и выражения лица\nОбраз и стиль:\nПрофессиональная фотосессия диджея\nСовременный, стильный образ\nУверенная поза\nЭлегантность в каждом элементе\nМакияж:\nПрофессиональный вечерний макияж\nАкцент на глаза с использованием блестящих теней\nПерламутровые и металлические оттенки\nАккуратные стрелки\nБлестящие элементы на скулах\nЕстественные губы с глянцевым эффектом\nЛёгкий шиммер на высоких точках лица\nПричёска:\nБлондинистые волосы\nДлина до плеч\nСтильная укладка с объёмом\nЛёгкие волны или локоны\nНесколько небрежных прядей у лица\nБлестящие аксессуары в волосах (по желанию)\nОсвещение и фон:\nПрофессиональное студийное освещение\nМягкий рассеянный свет\nАкцентные световые эффекты\nСтильный современный фон\nОтсутствие лишних деталей\nЧистое, ровное освещение без теней\nДополнительные элементы:\nМинималистичные украшения\nДиджейские наушники (по желанию)\nСтильный наряд в современном стиле\nКачественное разрешение изображения\nПрофессиональная ретушь без перебора\nЕстественные, живые цвета\nОбщее впечатление:\nПрофессиональная фотосессия\nВысокий уровень качества\nГармоничное сочетание всех элементов\nСовременный, модный образ", "operation": "gen-multi-input"}', 'jdypc9g0v1rma0ct23ea6zs7p8', 'succeeded', '{"date": 1761219375, "chatId": 1091595273, "messageId": 121992}', '{"date": 1761219395, "chatId": 1091595273, "messageId": 122001}', '[{"date": 1761219458, "chatId": 10915