INSERT INTO public.operations VALUES ('5a13b780-af55-43c2-b398-0476ed5596f3', '2025-10-23 14:44:38.206517', false, 2417679402, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB3KFo-hTrE2Tsk6i4dzj_mvoX98JbRgACb_8xGw2H0EuyQnJhiibA2AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Инструкция для обработки фотографии в полный рост:\nБазовые требования:\nСохранить естественные черты лица без искажений\nСохранить пропорции тела\nСохранить натуральный цвет кожи\nСохранить особенности мимики и выражения лица\nПричёска:\nДлинные светлые волосы ниже плеч\nСтильная укладка с объёмом у корней\nМягкие, естественные волны\nНесколько свободных прядей у лица\nБлестящие акценты в волосах (мелкие стразы или блёстки)\nВолосы аккуратно уложены, но с лёгкой небрежностью\nОбраз и стиль:\nПрофессиональная фотосессия диджея в полный рост\nСовременный, стильный образ\nУверенная поза\nЭлегантность в каждом элементе\nДинамичная, но сбалансированная композиция\nКостюм:\nСтильный диджейский костюм (брюки/юбка + топ или комбинезон)\nСовременные фасоны с акцентом на фигуру\nМеталлизированные или блестящие элементы\nКонтрастные цвета или монохромный комплект\nЛаконичные, но эффектные детали\nМакияж:\nПрофессиональный вечерний макияж\nАкцент на глаза с использованием блестящих теней\nПерламутровые и металлические оттенки\nАккуратные стрелки\nБлестящие элементы на скулах\nЕстественные губы с глянцевым эффектом\nЛёгкий шиммер на высоких точках лица\nОсвещение и фон:\nПрофессиональное студийное освещение\nМягкий рассеянный свет\nАкцентные световые эффекты\nСтильный современный фон\nОтсутствие лишних деталей\nЧистое, ровное освещение без теней\nДополнительные элементы:\nДиджейские наушники\nМинималистичные украшения\nСтильные туфли или ботинки\nКачественное разрешение изображения\nПрофессиональная ретушь без перебора\nЕстественные, живые цвета\nОбщее впечатление:\nПрофессиональная фотосессия\nВысокий уровень качества\nГармоничное сочетание всех элементов\nСовременный, модный образ\nДинамичность и элегантность в композиции", "operation": "gen-multi-input"}', '916ya1myxxrme0ct23h92fs1zg', 'succeeded', '{"date": 1761219819, "chatId": 1091595273, "messageId": 122017}', '{"date": 1761219827, "chatId": 1091595273, "messageId": 122022}', '[{"date": 1761219902, "chatId": 1091595273, "messageId": 122025}]');
