INSERT INTO public.operations VALUES ('3852b617-ad71-4f7c-be94-0895f999e663', '2025-10-23 14:54:35.309068', false, 3296053125, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB3NNo-hdsNjEKfV2-Va2toGhP5dQ-PQACLfoxG13q0UsSlyK4UBXgOAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 663, "heightPx": 926}, {"file": {"fileId": "AgACAgIAAxkBAAEB3NRo-hdsQegBtkDSaYxlxvk-6yzXNQACLvoxG13q0UsM_-AYvHH0jAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 780, "heightPx": 1040}], "prompt": "♾️: сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки не изменять чтобы была в точь точь", "operation": "gen-multi-input"}', 'vgs4eyntehrme0ct23nvveb294', 'succeeded', '{"date": 1761220460, "chatId": 6085830818, "messageId": 122067}', '{"date": 1761220473, "chatId": 6085830818, "messageId": 122073}', '[{"date": 1761220487, "chatId": 6085830818, "messageId": 122075}]');
