INSERT INTO public.operations VALUES ('a3dc93ec-70a1-4a20-8ab4-b92ab2ea072e', '2025-10-23 14:59:28.027054', false, 7186757113, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB3N9o-hiOUu_os0a0xfkz6AbB53idBwACngYyGzCO0EsDdUhKXCgzCwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай зимнюю версию загруженной фотографии. Тот человек, который на переднем плане. Сохрани лицо. Сохрани позу и освещение в точности. Добавь естественную снежную атмосферу, подающие с неба снежинки. Все поверхности должны быть покрыты слоем снега. Так же задний фон (горы) тоже должны быть покрыты снегом. Так же, сделай естественные снежинки, как в реальной жизни", "operation": "gen-multi-input"}', 'cjxd741jenrmc0ct23rb2gdxs4', 'succeeded', '{"date": 1761220750, "chatId": 6185361414, "messageId": 122079}', '{"date": 1761220760, "chatId": 6185361414, "messageId": 122084}', '[{"date": 1761220778, "chatId": 6185361414, "messageId": 122085}]');
