INSERT INTO public.operations VALUES ('dec7b6b6-9337-4df9-ac85-9645eb440059', '2025-10-23 18:48:46.226915', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB3bto-k5A2pv6KJhdUr8wx6O0fFtt-QAC9AEyGw2H0EsJQfnDZXroJgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Промпт для нейросети:\nПрофессиональная студийная фотография молодой девушки в полный рост. Сохранить все черты лица, включая естественную мимику и выражение. Блондинка с длинными волосами ниже плеч. на лице блестки. \nОсвещение:\nПреобладающий красный свет, создающий драматичный эффект\nСтудийное освещение\nКраевой свет для выделения силуэта\nТехнические параметры:\nDSLR камера\nУльтравысокое качество (8K UHD)\nРезкий фокус\nКристально чистое изображение\nГлубина резкости\nЗернистость пленки Fujifilm XT3\nДетализация:\nВысокодетализированные глянцевые глаза\nВысокодетализированная кожа\nЕстественные поры кожи\nПрофессиональная ретушь без излишнего фотошопа\nАтмосфера:\nРоскошная, элегантная поза\nУверенный, притягательный взгляд в камеру\nИзысканный, гламурный стиль съемки\nПрофессиональная фотосессия высшего уровня для обложки", "operation": "gen-multi-input"}', 'qf615rs1j5rmc0ct2719rmy2z4', 'succeeded', '{"date": 1761234496, "chatId": 1091595273, "messageId": 122299}', '{"date": 1761234511, "chatId": 1091595273, "messageId": 122304}', '[{"date": 1761234537, "chatId": 1091595273, "messageId": 122305}]');
