INSERT INTO public.operations VALUES ('22f326e4-f7f5-4d75-a5ff-9e5e75e520b2', '2025-10-28 12:26:45.534069', false, 6022001127, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "Фото женщины, держащей в руках профессиональную камеру, средний план, показывающий фигуру от головы до бедер, композиция с центральным расположением и прямым углом, на ней белый корсетный топ с квадратным вырезом, на плечах накинута черная объемная куртка с длинными рукавами, черные широкие брюки, на пальцах серебряные кольца и серьги, камера с черным ремешком, стоит на фоне серой студийной стены с двумя профессиональными осветительными приборами по бокам, яркий направленный свет от студийных прожекторов, боковое освещение с акцентом на лицо, резкие тени с четкими контрастами, драматичная и сфокусированная атмосфера, съемка объективом для портретов 85 мм, малая глубина резкости с мягким размытием фона, фотореалистичный стиль с текстурной детализацией, разрешение 8K, черно-белая цветовая палитра, очень детализировано.", "operation": "gen-multi-input"}', 'yww8tc1g2nrmc0ct58jb34c3jw', 'succeeded', '{"date": 1761643588, "chatId": 6682536549, "messageId": 129901}', '{"date": 1761643589, "chatId": 6682536549, "messageId": 129902}', '[{"date": 1761643615, "chatId": 6682536549, "messageId": 129903}]');
