INSERT INTO public.operations VALUES ('1ea702d8-1065-4b5d-8568-5f950b568d26', '2025-10-17 12:33:50.556843', false, 9559809088, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "3:4"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [], "prompt": "Мать из ''The Coffin of Andy and Leyley''. Женщина средних лет с изможденным, уставшим лицом. Резкие черты, тонкие поджатые губы, глубокие носогубные складки. Неаккуратные волосы мышиного цвета собраны в грязный пучок. Её глаза полны раздражения и неприязни. На ней поношенный домашний халат или простой свитер. Она стоит в защитной позе со скрещенными руками, её взгляд выражает холодное презрение и отчуждение. Мрачная, депрессивная атмосфера.\"", "operation": "gen-multi-input"}', 'bncnfqdqa5rme0csy62b3j8a14', 'succeeded', '{"date": 1760693593, "chatId": 332575783, "messageId": 109733}', '{"date": 1760693593, "chatId": 332575783, "messageId": 109734}', '[{"date": 1760693640, "chatId": 332575783, "messageId": 109735}]');
