INSERT INTO public.operations VALUES ('9440a855-fc91-4b59-9eac-8e0a52482345', '2025-09-26 15:17:22.346245', false, 4665051800, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAEBYTlo1WxMlj9gWqCoVwgiQp-zjUckTwACIcwxG4WZqFacuwsCbLYBfgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "4. isi prompt (tempel)\n\nedit foto ini menjadi potret realist.seorang pria muda (gunakan foto referensi yang saya unggah)berfoto selfie di depan cermin kamar mandi modern dengan dinding berwarna gelap.seperti kamar mandi mall.ia menggunakan kalo polo hitam polos dengan kerah,lengan pendek,dengan logo kecil di dada nya.serta celana hitam. tangan nya yang kanan di masukkan saku celana.sementara tangan kiri memegang ponsel iPhone 13 promax berwarna abu-abu silver dengan case transparan yang memiliki magnet lingkaran magsafe.wajah pria tersebut terlihat tersenyum manis tipis dengan expresi santai dan percaya diri.cahaya nya berasal dari lampu LED horizontal putih terang di bagian atas cermin, memberikan efek pencahayaan lembut pada wajah dan bajunya.di bagian bawah terlihat wastafel putih dengan keran metalik dan dispenser sabun stainless stel.foto bergaya kasual.tampak nyata, kualitas HD,detail jelas dan tetap mempertahankan wajah asli tanpa perubahan", "operation": "gen-multi-input"}', '0pb1vxf2k9rme0csgqta389tf4', 'succeeded', '{"date": 1758889016, "chatId": 8252459960, "messageId": 91982}', '{"date": 1758889033, "chatId": 8252459960, "messageId": 91987}', '[{"date": 1758889053, "chatId": 8252459960, "messageId": 91988}]');
