INSERT INTO public.operations VALUES ('b67f9add-ed84-4a99-9771-ddffca88dd17', '2025-10-11 21:13:56.420268', false, 2776659220, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBj59o6p3C6hYd6csoauf96lbUKCiKkAACUPoxG-dQWEthLcNwr5Hc8AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 828, "heightPx": 515}, {"file": {"fileId": "AgACAgIAAxkBAAEBj51o6p2yUzeqa26WKlHFil43nyEpqQACQfoxGyBHUEvjh4KV6hJRTAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок. Атмосфера должна быть спонтанной и живой, будто кадр случайно поймали без позирования и реквизита.\n\nДобавь лёгкое размытие от движения и мягкий свет вспышки, равномерно рассеивающийся в тёмном пространстве. Лица не искажай – они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску\n\nДвое людей обнимаются смотрят прямо в камеру, момент выглядит интимным и естественным, без постановочности.", "operation": "gen-multi-input"}', 'p4xqt05s85rme0csthx8zy3m5m', 'succeeded', '{"date": 1760206426, "chatId": 8391517320, "messageId": 102317}', '{"date": 1760206434, "chatId": 8391517320, "messageId": 102321}', '[{"date": 1760206448, "chatId": 8391517320, "messageId": 102324}]');
