INSERT INTO public.operations VALUES ('8deee294-7281-41f5-8ecc-2897ff985266', '2025-09-28 16:39:26.493143', false, 3632830161, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBbm9o2TpJR-wPqFWryN0VJ8QJnAerPgACPfYxG4Q2yEreqLsOISFHlAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 837, "heightPx": 1280}], "prompt": "Сделай портретное фото в стиле Polaroid, на котором двое стоят рядом на фоне простой белой занавески. Справа: [используйте моё референсное селфи], реалистичные оттенки кожи, естественное выражение лица, повседневная одежда. Слева: Декстер Морган (из сериала «Декстер») в своём типичном наряде из сериала (тёмная футболка или хенли, простой и лаконичный образ), реалистичные лица и естественный вид. Оба смотрят прямо в камеру, хорошо освещённая студийная атмосфера, минимум теней, нейтральное настроение, эстетика плёночной фотографии, рамка Polaroid.", "operation": "gen-multi-input"}', 'ewns6d5xt9rme0csj26a8jfpnw', 'succeeded', '{"date": 1759066738, "chatId": 5943607783, "messageId": 93812}', '{"date": 1759066754, "chatId": 5943607783, "messageId": 93817}', '[{"date": 1759066783, "chatId": 5943607783, "messageId": 93818}]');
