INSERT INTO public.operations VALUES ('906b0ab8-e128-4537-9cc6-0ffcc525178f', '2025-09-28 16:40:27.63805', false, 3632830161, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBbm9o2TpJR-wPqFWryN0VJ8QJnAerPgACPfYxG4Q2yEreqLsOISFHlAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 837, "heightPx": 1280}], "prompt": "Сделай портретное фото в стиле Polaroid, на котором двое стоят рядом на фоне простой белой занавески. Справа: [используйте моё референсное селфи], реалистичные оттенки кожи, естественное выражение лица, повседневная одежда. Слева: Декстер Морган (из сериала «Декстер») в своём типичном наряде из сериала (тёмная футболка или хенли, простой и лаконичный образ), реалистичные лица и естественный вид. Оба смотрят прямо в камеру, хорошо освещённая студийная атмосфера, минимум теней, нейтральное настроение, эстетика плёночной фотографии, рамка Polaroid. Не изменяй моё лицо, сделай его в точности как на фотографии", "operation": "gen-multi-input"}', 'vq49925cr9rme0csj26vrktkyg', 'succeeded', '{"date": 1759066801, "chatId": 5943607783, "messageId": 93819}', '{"date": 1759066815, "chatId": 5943607783, "messageId": 93824}', '[{"date": 1759066852, "chatId": 5943607783, "messageId": 93825}]');
