INSERT INTO public.operations VALUES ('91389a62-7f97-4a90-b2f5-096cb066a6e6', '2025-10-12 14:49:28.097836', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBkh9o65V1DpSNuOqzhm-pEqxqSAEUgQACh_wxGwF7YEvbNRwAAR7fKHEBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Изображение представляет собой чфотографию, на которой изображены две женщины. Одна лежит на спине, а другая положила голову на ее голову сверху, повернувшись лицом к камере.У обеих женщин тёмные распущенные и длинные волосы, уложенные назад, и выразительный макияж, включающий подводку для глаз и помаду тёмного оттенка. Они одеты в чёрные пиджаки.Лица обеих женщин находятся в фокусе, взгляды направлены в камеру. Фон белый, что позволяет сосредоточить внимание на лицах и одежде.", "operation": "gen-multi-input"}', 'p642ffrpghrma0csv10vtjgehg', 'succeeded', '{"date": 1760269685, "chatId": 1287537311, "messageId": 102943}', '{"date": 1760269751, "chatId": 1287537311, "messageId": 102948}', '[{"date": 1760269778, "chatId": 1287537311, "messageId": 102953}]');
