INSERT INTO public.operations VALUES ('afdee601-8ca8-4a81-8fe0-74c9e5f73a3b', '2025-09-29 06:22:13.807857', false, 3032507976, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBcDZo2ftSVeGLm1nJpAAB3M2j8u2_4PsAApD-MRtkDtBKkisSi8CagTkBAAMCAAN3AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1919, "heightPx": 2560}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где девушка лежит на леопардовом постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х.\nНа мне готические украшения. Комната за ее спиной выглядит, как у подростка в готическом стиле с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nGhostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. Фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', 'ye6bnv077drm80csjdz9m8wp8w', 'succeeded', '{"date": 1759116114, "chatId": 986120316, "messageId": 94262}', '{"date": 1759116128, "chatId": 986120316, "messageId": 94269}', '[{"date": 1759116144, "chatId": 986120316, "messageId": 94270}]');
