INSERT INTO public.operations VALUES ('6e271450-910c-471c-8a9e-4a5c42678b32', '2025-09-29 06:23:26.875434', false, 3032507976, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBcD9o2fuk-7qJzd0P18yk991NWNnfrQACkv4xG2QO0ErFMQAB7PwufmYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1056, "heightPx": 1280}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где девушка лежит на леопардовом постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х.\nНа мне готические украшения. Комната за ее спиной выглядит, как у подростка в готическом стиле с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nGhostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. Фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', '2g08bxs41drm80csjdztzxzfhm', 'succeeded', '{"date": 1759116196, "chatId": 986120316, "messageId": 94271}', '{"date": 1759116203, "chatId": 986120316, "messageId": 94276}', '[{"date": 1759116218, "chatId": 986120316, "messageId": 94277}]');
