INSERT INTO public.operations VALUES ('8db0e23b-16f6-422d-96e6-770732e2a840', '2025-10-12 14:55:49.463729', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBkj9o65b7iUdBriwNMINuJJ09_FlQmwAClvwxGwF7YEtpY7HZwJmpagEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 651, "heightPx": 1280}], "prompt": "Фотосессию в студии на белом фоне, фото сделано по пояс, у девушки черные распущенные и волнистые волосы , уложены на правый бок, девушка слегка смотрит в бок и одной рукой поправляет волосы от корня, у девушки черная майка", "operation": "gen-multi-input"}', '34q4xq780xrma0csv139ekznkm', 'succeeded', '{"date": 1760270112, "chatId": 1287537311, "messageId": 102986}', '{"date": 1760270136, "chatId": 1287537311, "messageId": 102991}', '[{"date": 1760270161, "chatId": 1287537311, "messageId": 102996}]');
INSERT INTO public.operations VALUES ('2f81ea3d-19f4-4870-b146-e53017ba6445', '2025-09-29 06:26:37.344068', false, 3032507976, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBcEZo2fxgqS_BfUR8X7tk_0EfHdK3PAACk_4xG2QO0Erzd8tBfTG3qwEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1919, "heightPx": 2560}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где девушка лежит на леопардовом постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х.\nНа мне готические украшения. Комната за ее спиной выглядит, как у подростка в готическом стиле с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nGhostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. Фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', 'jpgzz48bzsrm80csje1amz2mn4', 'succeeded', '{"date": 1759116384, "chatId": 986120316, "messageId": 94278}', '{"date": 1759116395, "chatId": 986120316, "messageId": 94283}', '[{"date": 1759116419, "chatId": 986120316, "messageId": 94284}]');
