INSERT INTO public.operations VALUES ('c25d5751-3a5a-4f8d-ad05-990900004918', '2025-10-12 18:30:15.179432', false, 3307802457, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBlSto68lmPfk0aPU8HRndkXEYNlz--wACK_oxGy5EYEtVkWzzmdZilAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 720}], "prompt": "создай фотографию без дефектов с прямыми руками не искажая лицо, в стиле Y2K, на которой я лежу на темно-розовой атласной простыне, задумчиво держа в руках большой проводной телефон в стиле 90-х. Мои длинные темные волосы с золотыми заколками-бабочками будут рассыпаны по подушке. На мне будут изысканные золотые украшения. Комната будет оформлена в темном цвете с плакатами Stray Kids. На лице будет простой, но гламурный макияж с темно- красной помадой. Фотография будет выполнена в зернистом стиле 90-х годов с приглушенным светом от лампы ночью. Рядом со мной будет стоять миска с попкорном и лежать несколько журналов Stray Kids в стиле 90-х. На заднем плане в дверном проеме будет стоять участник Stray Kids Хёнджин, смотрящий на вас, держа маску Призрачного лица в руке. Его тело будет в форме, с идеальной талией и в темной футболке и он будет слегка освещен. Фон за ним будет темноватым и зловещим.", "operation": "gen-multi-input"}', 'wmd4jesvrxrmc0csv45rwh1zc8', 'succeeded', '{"date": 1760282982, "chatId": 5867012452, "messageId": 103723}', '{"date": 1760282993, "chatId": 5867012452, "messageId": 103726}', '[{"date": 1760283025, "chatId": 5867012452, "messageId": 103727}]');
