INSERT INTO public.operations VALUES ('37bb153d-ad10-48a4-9ac3-6669975738c4', '2025-10-12 18:31:59.493777', false, 3307802457, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBlSto68lmPfk0aPU8HRndkXEYNlz--wACK_oxGy5EYEtVkWzzmdZilAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 720}], "prompt": "Создай Мою Гиперреалистичную Фотографию Без Изменения Черт Лица,на Портрете Мечты в стиле Y2K,лежащей на ярко-розовой атласной простыне,держа в руках Большой Проводной Телефон в стиле 90-х,и в задумчивой мечтательной позе ее Длинные Темные Волосы свободно ниспадают легкими распущенными локонами с помощью зажимов-бабочек золотистые с каждой стороны.Она носит изысканные украшения,в том числе изящные золотые ожерелья и аксессуары.Комната за ней девчачья и мечтательная, украшенная постерами Stray Kids.Ее макияж простой,но гламурный.Фотография должна быть выполнена в зернистом стиле 90-х годов с таким источником света,как лампа в тускло освещенной комнате ночью.Миска с попкорном лежит рядом с ней рядом с несколькими журналами Stray Kids в стиле 90-х.Певец Stray Kids Хëнджин должен стоять позади нее и смотреть на нее,держа в руке маску Призрачного лица, ее тело должно быть тускло освещено,и она должна стоять у двери в тускло освещенный коридор.Фон за ним должен быть слегка темным и зловещим.", "operation": "gen-multi-input"}', 'd96h10pgd5rm80csv46bz5szhg', 'succeeded', '{"date": 1760283087, "chatId": 5867012452, "messageId": 103728}', '{"date": 1760283117, "chatId": 5867012452, "messageId": 103733}', '[{"date": 1760283129, "chatId": 5867012452, "messageId": 103734}]');
