INSERT INTO public.operations VALUES ('d7b17f47-60ba-437a-a681-c1322fafa81e', '2025-10-13 13:55:55.082835', false, 4058304198, 8, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "4K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBnBNo7NqqxM63MXlA-K9ugHytPLOB0QACyfkxGy_NaEusr-9oiy89iwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBnBRo7Nqq5a4athyX8jLrldAKTWF5EQACyvkxGy_NaEsaj_r5XeSBugEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки не изменять чтобы была в точь точь", "operation": "gen-multi-input"}', 'jvy9y8vbq5rmc0csvmv81nq7rm', 'succeeded', '{"date": 1760352938, "chatId": 1044211827, "messageId": 105491}', '{"date": 1760352946, "chatId": 1044211827, "messageId": 105495}', '[{"date": 1760352977, "chatId": 1044211827, "messageId": 105496}]');
