INSERT INTO public.operations VALUES ('85956ac0-3695-446d-b482-ef6134f1f405', '2025-10-01 21:56:44.541898', false, 2626153410, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBdj1o3Xlf1dPQC7UDGLDApKrr6cceKAACqv0xGzJX6UppxcWhCiDWzwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где я лежу на блестящем розовом атласном постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х, а ее длинные волнистые волосы в задумчивой позе мечтательности свободно ниспадают свободными локонами с золотыми заколками-бабочками по бокам. \nНа ней украшения, включая изящные золотые ожерелья и аксессуары, а также массивные золотые кольца. Комната за ее спиной выглядит девчачьей и мечтательной с плакатами в стиле 90-х. Ее макияж простой, но гламурный с красным блеском для губ и золотыми тенями. Фотография должна иметь зернистый стиль 90-х с источником света, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nghostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', 'j1ejmzjh6hrma0csm4h8wh33fc', 'succeeded', '{"date": 1759344991, "chatId": 2116476517, "messageId": 95805}', '{"date": 1759345000, "chatId": 2116476517, "messageId": 95808}', '[{"date": 1759345016, "chatId": 2116476517, "messageId": 95813}]');
