INSERT INTO public.operations VALUES ('146c9431-668c-47ed-8efd-48f0126c7da7', '2025-10-01 22:02:29.887903', false, 2626153410, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBdito3Wd3huT4rQNFh_RCp7rMO3GtVAACygcyG7qYSUjKxScvDD6ykQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где я лежу на блестящем розовом атласном постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х, а ее длинные волнистые волосы в задумчивой позе мечтательности свободно ниспадают свободными локонами с золотыми заколками-бабочками по бокам. \nНа ней украшения, включая изящные золотые ожерелья и аксессуары, а также массивные золотые кольца. Комната за ее спиной выглядит девчачьей и мечтательной с плакатами в стиле 90-х. Ее макияж простой, но гламурный с красным блеском для губ и золотыми тенями. Фотография должна иметь зернистый стиль 90-х с источником света, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nghostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', 'zrhdn9mq51rm80csm4kscpxcfc', 'succeeded', '{"date": 1759345315, "chatId": 2116476517, "messageId": 95827}', '{"date": 1759345341, "chatId": 2116476517, "messageId": 95834}', '[{"date": 1759345369, "chatId": 2116476517, "messageId": 95835}]');
