INSERT INTO public.operations VALUES ('0681d810-947b-4335-b42c-24fea8b5f739', '2025-10-30 10:17:39.317614', false, 5698865448, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECBgNpAxC2Ogtw8V59Jt46-JSmeAdA5gAC-AUyG3YBGUgRlcSqEI2CywEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Сделай из этой фотографии куклу Блайз  карие глаза чёрное каре БЕЗ челки не сильно миловидное лицо и пусть фото выглядят как селфи и будут серёжки колечки среднего размера", "operation": "gen-multi-input"}', 'qgcgjzdmgxrme0ct6fx8m70qqw', 'succeeded', '{"date": 1761808641, "chatId": 6611288063, "messageId": 132626}', '{"date": 1761808657, "chatId": 6611288063, "messageId": 132629}', '[{"date": 1761808669, "chatId": 6611288063, "messageId": 132630}]');
INSERT INTO public.operations VALUES ('547af15d-1447-41a6-bd2b-48f5fbf02f04', '2025-10-01 22:49:49.602071', false, 4582245798, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBdnho3YXCaJSJbiXtfUIYOIlQok_v3gACpv4xG7Qn8UrY12gAAe95FpEBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 723, "heightPx": 1280}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где я лежу на блестящем розовом атласном постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х, а ее длинные волнистые волосы в задумчивой позе мечтательности свободно ниспадают свободными локонами с золотыми заколками-бабочками по бокам. \nНа ней украшения, включая изящные золотые ожерелья и аксессуары, а также массивные золотые кольца. Комната за ее спиной выглядит девчачьей и мечтательной с плакатами в стиле 90-х. Ее макияж простой, но гламурный с красным блеском для губ и золотыми тенями. Фотография должна иметь зернистый стиль 90-х с источником света, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nghostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', '9dcvcf7an5rmc0csm59aa212dw', 'failed', '{"date": 1759348162, "chatId": 1116236733, "messageId": 95864}', '{"date": 1759348167, "chatId": 1116236733, "messageId": 95867}', '[{"date": 1759348167, "chatId": 1116236733, "messageId": 95867}]');
