INSERT INTO public.operations VALUES ('76203de6-7a11-4b06-96a7-a9943476d232', '2025-10-18 17:51:55.390341', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы черные, длинные, уложены большими волнами, они объемны и они ниспадают на плечи. цепочка на шее. Она смотрит в сторону от камеры. Фон изображения - бежевый и на лицо попадает лучик солнца Плечи обнажены.", "operation": "gen-multi-input"}', 'wc2hz7t94xrm80csyz7brb709g', 'succeeded', '{"date": 1760799081, "chatId": 1287537311, "messageId": 111940}', '{"date": 1760799105, "chatId": 1287537311, "messageId": 111951}', '[{"date": 1760799125, "chatId": 1287537311, "messageId": 111957}]');
