INSERT INTO public.operations VALUES ('5e9d43c1-150e-44b9-bd27-f27bc953740c', '2025-10-01 22:51:49.954199', false, 4582245798, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBdnho3YXCaJSJbiXtfUIYOIlQok_v3gACpv4xG7Qn8UrY12gAAe95FpEBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 723, "heightPx": 1280}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где я лежу на блестящем розовом атласном постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х, а ее длинные волнистые волосы в задумчивой позе мечтательности свободно ниспадают свободными локонами с золотыми заколками-бабочками по бокам. \nНа ней украшения, включая изящные золотые ожерелья и аксессуары, а также массивные золотые кольца. Комната за ее спиной выглядит девчачьей и мечтательной с плакатами в стиле 90-х. Ее макияж простой, но гламурный с красным блеском для губ и золотыми тенями. Фотография должна иметь зернистый стиль 90-х с источником света, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nghostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', 'tgymtq60mnrm80csm5a9rzcfyw', 'succeeded', '{"date": 1759348293, "chatId": 1116236733, "messageId": 95870}', '{"date": 1759348307, "chatId": 1116236733, "messageId": 95873}', '[{"date": 1759348320, "chatId": 1116236733, "messageId": 95874}]');
