INSERT INTO public.operations VALUES ('a68b244d-df1f-4e3f-ba7b-8d2c75263461', '2025-10-02 10:34:38.282871', false, 7721511449, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBd0to3ir9bsBn696yyGlLfdLTQYeZCQACP_cxG-Tx8EqnoMz40vpbaQEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 768}], "prompt": "Создай мою фотографию в комнате стили 2000 года  где я выгляжу лежащим на ярко -розовой аланской кровати она держит большой ретро - лиловый телефон упираясь  лицом на одну руку в задумчивую почти в мечтательную в позу.  А взади меня стоит он  в этом костюме , он высокий он стоит за ней глядя на девушку , не меняйте лицо девушки и черты лица атас из неё стоит персонаж , представляющий призрачное лицо  из кино одетый в мантию  и черную маску", "operation": "gen-multi-input"}', '1ajqx99h99rmc0csmfc94m2xt4', 'succeeded', '{"date": 1759390461, "chatId": 8264535052, "messageId": 96075}', '{"date": 1759390473, "chatId": 8264535052, "messageId": 96078}', '[{"date": 1759390489, "chatId": 8264535052, "messageId": 96079}]');
INSERT INTO public.operations VALUES ('65e47881-d819-47ac-b110-80109c5032f1', '2025-10-12 21:03:11.394628', false, 4972158222, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBl5Fo6-xlqVzhUEXjL87_Qn1Oqypl_gACBgMyG9cvYEtCYA4Z47XNJwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 722, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBl5lo6-1ahFMF4GmUqsLLgmsxBUc45wAC1_sxG52xYEt6f3Wz_1s6cQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности", "operation": "gen-multi-input"}', 'km99xphxanrm80csv6bsjavw20', 'succeeded', '{"date": 1760292186, "chatId": 2098929055, "messageId": 104344}', '{"date": 1760292189, "chatId": 2098929055, "messageId": 104348}', '[{"date": 1760292205, "chatId": 2098929055, "messageId": 104349}]');
