INSERT INTO public.operations VALUES ('54e72bd7-76c7-4c92-a507-f4a2872963a8', '2025-10-24 14:19:37.773404', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB5G5o-2Av5gT-K1nGvdM-15iuJ0Z7CQACTPoxGw2H2EukbVoAAcXQv2kBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 854, "heightPx": 1280}], "prompt": "Для создания шикарного образа девушки на фото (без изменения черт лица) с акцентом на красоту, букет и детали — следуйте этому плану:\nКоррекция и ретушь кожи\nсгладить текстуру, убрать мелкие несовершенства (прыщи, покраснения);\nвыровнять тон кожи, добавить здоровое сияние;\nподчеркнуть естественный рельеф (скулы, подбородок), не меняя формы лица;\nсохранить поры и естественные нюансы кожи для реалистичности.\nМакияж (акцент на естественность и элегантность)\nнежные тени в пастельных тонах (бежевый, персиковый, розовый);\nчётко прорисованные, но не перегруженные брови;\nтушь для ресниц с эффектом объёма;\nгубы — лёгкий блеск или помада натурального оттенка;\nлёгкий румянец для свежести.\nПричёска\nаккуратные локоны или гладкие волосы с лёгким объёмом;\nнейтральный оттенок (если требуется коррекция цвета);\nаксессуары — минималистичная заколка или невидимки.\nБукет роз (101 штука)\nкрупные красные розы с насыщенными лепестками;\nгустая упаковка в матовую крафт‑бумагу или прозрачную плёнку с атласной лентой;\nбукет занимает нижнюю треть кадра, частично прикрывая руки;\nдобавить капли росы на лепестки для эффекта свежести.\nРуки и маникюр\nухоженные кисти с аккуратным маникюром;\nдизайн:\nклассический френч с перламутровым отливом;\nили однотонное покрытие в нюдовых/розовых тонах;\nдопускается минималистичный декор (точки, тонкие линии, микро‑стразы).\nКольца\nна безымянном пальце левой руки — изящное кольцо с прозрачным камнем (бриллиант/муассанит) в минималистичной оправе;\nна среднем пальце — тонкое кольцо с мелкими камнями или геометрическим узором;\nметалл — белое золото или платина.\nОбщие детали образа\nодежда — красный пиджак и черный топ под пиджаком.\nфон — размытый нейтральный (бежевый градиент или мягкая текстура камня/ткани);\nосвещение — мягкий студийный свет с лёгким контровым подсветом для объёма.\nФинальная обработка\nлёгкая виньетка для акцента на лице и букете;\nповышение контраста в тенях и светлых участках;\nдобавление лёгкого свечения вокруг силуэта для романтичного эффекта.\nРезультат: гармоничный, элегантный образ с акцентом на естественность, роскошь букета и утончённость деталей.", "operation": "gen-multi-input"}', 'wz5zkbrnkxrm80ct2qs8n8aggr', 'succeeded', '{"date": 1761304623, "chatId": 1091595273, "messageId": 124014}', '{"date": 1761304756, "chatId": 1091595273, "messageId": 124024}', '[{"date": 1761304790, "chatId": 1091595273, "messageId": 124025}]');
