INSERT INTO public.operations VALUES ('cabd8850-82d8-4101-a118-d64799ced267', '2025-10-12 21:09:56.973726', false, 2222288432, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBl7No6-7sTW1J_gzvQY2Hvf7HxsMTkQACHgUyG7LUYEuNoT9yQuryIwEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 512, "heightPx": 512}, {"file": {"fileId": "AgACAgIAAxkBAAEBl7Ro6-7sAf9ANVnO6thuPqCdy77FRAACHwUyG7LUYEuZI2chwGQQBgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности", "operation": "gen-multi-input"}', 'hpfc41vdyxrma0csv6esk5hehc', 'succeeded', '{"date": 1760292588, "chatId": 1389182764, "messageId": 104371}', '{"date": 1760292594, "chatId": 1389182764, "messageId": 104375}', '[{"date": 1760292608, "chatId": 1389182764, "messageId": 104376}]');
