INSERT INTO public.operations VALUES ('81b7260f-f47c-46dd-8b72-cba7ae1e9191', '2025-10-17 17:05:33.601375', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу. Голова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой. Причёска: зачёсана назад за плечи плавными естественными волнами. Макияж: мягко очерченный — сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 с объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица", "operation": "gen-multi-input"}', '4839r53vhhrmc0csy9ytvp5pe0', 'succeeded', '{"date": 1760709928, "chatId": 1287537311, "messageId": 110237}', '{"date": 1760709932, "chatId": 1287537311, "messageId": 110242}', '[{"date": 1760709947, "chatId": 1287537311, "messageId": 110243}]');
