INSERT INTO public.operations VALUES ('f7c53c2c-13de-4189-881b-2bb07d58eaa1', '2025-09-24 14:19:11.986957', false, 1391739003, 8, 0.03, '{"ratio": "4:3", "prompt": "“Buat poster promosi jasa perbaikan sepatu dengan desain modern, cerah, dan menarik. Gunakan kombinasi warna biru, hijau, dan oranye.\nJudul besar di bagian atas: Sepatu kesayanganmu mulai rusak? dengan ikon sepatu.\nTambahkan ilustrasi sepatu yang dijahit dan sepatu yang sudah dijahit (before–after).\n\nTampilkan poin layanan dengan ikon centang:\n✅ Jahit ulang sol\n✅ Lem kembali bagian lepas\n✅ Tambah kuat biar awet lagi\n\nTambahkan highlight promo di tengah dengan teks:\nPenawaran Terbatas hanya 5 pasang sepatu!\nBiaya hanya ganti bahan, jasa gratis!\nHarga promo khusus, fleksibel sesuai kondisi sepatu.\n\nSertakan informasi harga jelas:\n💰 Mulai Rp5.000/sepatu - Rp10.000/pasang\n\nDi bagian bawah, tampilkan call-to-action besar:\nHubungi WhatsApp: 088217802496 dengan ikon WhatsApp hijau.\n\nDesain clean, rapi, mudah dibaca, dan persuasif agar menarik perhatian.”", "sendAs": "photo", "operation": "gen"}', '4k5nffq87nrmc0csfdsawfrwdw', 'succeeded', '{"date": 1758712737, "chatId": 1217860653, "messageId": 87828}', '{"date": 1758712738, "chatId": 1217860653, "messageId": 87829}', '[{"date": 1758712767, "chatId": 1217860653, "messageId": 87830}]');
