INSERT INTO public.operations VALUES ('04496f86-09f3-4ede-af83-e580be8a68a9', '2025-10-12 21:30:38.6158', false, 3045059917, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBmEdo6_MNUonKp7ul0_CgGzDU1IxqUAACMAYyGx5UWEvYYfLr6kN88AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 591, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBmHFo6_PKVLz21mvvlBp4yn757jsvCQACQwYyGx5UWEv3omcl2FYkpgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "♾️: сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки не изменять чтобы была в точь точь", "operation": "gen-multi-input"}', '1x70st2zt9rme0csv6rb21a9qc', 'succeeded', '{"date": 1760293834, "chatId": 1301147450, "messageId": 104560}', '{"date": 1760293836, "chatId": 1301147450, "messageId": 104564}', '[{"date": 1760293851, "chatId": 1301147450, "messageId": 104566}]');
