INSERT INTO public.operations VALUES ('33e6d5ae-cb56-4398-8623-174b59c5b991', '2025-10-08 09:18:03.957658', false, 1927829084, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBf5Jo5gILaLIjGzcXNLt0nEZA2C9W9gACx_cxG2YmMUuElx0O6Or6BAEAAwIAA20AAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 200, "heightPx": 252}, {"file": {"fileId": "AgACAgIAAxkBAAEBf5No5gILHIKsjAgdq8ccpn77d4TapAACTwYyG6rHKUsUcn43v_cvagEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1919, "heightPx": 2560}], "prompt": ": «Сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок. Атмосфера должна быть спонтанной и живой, будто кадр случайно поймали без позирования и реквизита.\nДобавь лёгкое размытие от движения и мягкий свет вспышки, равномерно рассеивающийся в тёмном пространстве. Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на стену Голливуда, создавая ощущение непринуждённости.\nДвое людей смотрят прямо в камеру, и жмут друг другу руки. момент выглядит естественным, без постановочности»", "operation": "gen-multi-input"}', 'ye2k889yphrm80csr9w8sr1wfc', 'succeeded', '{"date": 1759904267, "chatId": 7875810093, "messageId": 98194}', '{"date": 1759904273, "chatId": 7875810093, "messageId": 98198}', '[{"date": 1759904296, "chatId": 7875810093, "messageId": 98199}]');
