INSERT INTO public.operations VALUES ('286e7bdc-35de-4043-83ea-0d784996c625', '2025-10-12 21:47:00.619869', false, 5694210040, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "Сделайте чрезвычайно обычное и ничем не примечательное селфи на iPhone без четкого предмета или чувства композиции - просто быстрый случайный снимок. На фотографии небольшое размытие в движении и неравномерное освещение от уличных фонарей или внутренних фонарей, что приводит к легкой передержке в некоторых областях. Угол неудобный, а кадрирование грязное, что придает снимку намеренно посредственное ощущение, как будто он был сделан рассеянно, вытаскивая телефон из кармана. Главный герой [лицо загруженного человека], и …  стоит рядом с ним, оба пойманные в непринужденный, несовершенный момент. На заднем плане виден оживленный ночной город с проезжающими мимо неоновыми огнями, пробками и размытыми фигурами. Общий вид намеренно простой и случайный, запечатлевший аутентичную атмосферу плохо составленного, спонтанного селфи на iPhone.", "operation": "gen-multi-input"}', '7ctjz1tw2drmc0csv6zsqmbwar', 'succeeded', '{"date": 1760294818, "chatId": 1464338659, "messageId": 104696}', '{"date": 1760294819, "chatId": 1464338659, "messageId": 104697}', '[{"date": 1760294827, "chatId": 1464338659, "messageId": 104698}]');
