INSERT INTO public.operations VALUES ('7624b3a5-31ec-48e6-99d8-43f784e7ee57', '2025-10-09 16:58:04.663019', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBg9do5702CVx77QABagfzU0Qbz6lpCxkAAtoDMhsx0ThLUfnSFSgxjdkBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "На фотографии изображена женщина с длинными темными волосами, одетая в сверкающее белое платье с глубоким V-образным вырезом. У нее загорелая кожа, выразительные брови и светлые губы.Освещение на фотографии сфокусировано на лице и верхней части тела женщины. На заднем плане видно круглое светлое пятно, которое создает эффект сияния вокруг нее. Остальная часть фона остается темной.Образ женщины демонстрирует утонченность и элегантность, подчеркнутую мягким освещением и тщательно подобранной одеждой. Без очков", "operation": "gen-multi-input"}', 'eg47wjp1k9rm80css51veb5bbg', 'succeeded', '{"date": 1760018237, "chatId": 1287537311, "messageId": 99312}', '{"date": 1760018267, "chatId": 1287537311, "messageId": 99315}', '[{"date": 1760018294, "chatId": 1287537311, "messageId": 99320}]');
