INSERT INTO public.operations VALUES ('3e494e59-e92e-40ed-a51b-ce5947f01844', '2025-10-09 17:02:16.612239', false, 5013320058, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBg9do5702CVx77QABagfzU0Qbz6lpCxkAAtoDMhsx0ThLUfnSFSgxjdkBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая на фоне однотонной черной стены. Ее волосы гладко зачесаны назад. На ней надет белый жакет с широкими лацканами и одной пуговицей. Под жакетом видна тонкая золотая цепочка на шее. В ушах надеты золотые серьги.На женщину падает сценический свет, создающий круглый светлый участок на стене за ее спиной и выделяющий ее фигуру. Нижняя часть тела скрыта, но видны верхние части брюк черного цвета. На лице женщины выражен серьезный взгляд. Без очков", "operation": "gen-multi-input"}', 'ck1vhhcsb9rmc0css53r236f20', 'succeeded', '{"date": 1760018437, "chatId": 1287537311, "messageId": 99323}', '{"date": 1760018507, "chatId": 1287537311, "messageId": 99326}', '[{"date": 1760018545, "chatId": 1287537311, "messageId": 99327}]');
