INSERT INTO public.operations VALUES ('d4f1b05b-16b8-4e09-beed-cb2b30f71fae', '2025-10-09 19:05:45.872663', false, 4972227842, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhONo590-Vw3pZLIeZGUKhjz6JtyOEAACMAIyG-BGQUsaI6p_kNtsbAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 622, "heightPx": 1280}], "prompt": "Создайте вертикальную рамку\nразмер 2160x3840 пикселей 4K Не\nменяет внешнего вида. Качество\nразделено на три горизонтальных\nизображения одинакового размера,\nрасположенных вместе\nГлавный герой основан на эталонной\nприческе лица и тела молодой\nфигуре с выражением грусти и\nностальгии, излучающими одиночество\nНаряд представляет собой свободный\nзимний пуховик с широкими\nштанами и черным шарфом\nОбщая атмосфера покрыта белым снегом\nс холодной цветовой палитрой,\nкоторая вызывает меланхолию и\nодиночество\n1.портрет персонажа держит\nпрозрачный зонтик, слегка\nповорачивая голову назад, глядя\nпрямо на кадр\nВыражение печально\nс душевными глазами\nФон размыт\nснежной белизной\n2.Всё тело с зонтом, стоит один на огромном снежном\nполе, идя, глядя на небо\nУгол\nкамеры смотрит сверху вниз\nэто выглядит так, как будто персонаж поднимает руку, чтобы поймать падающие снежинки\nВдалеке стоят несколько голых деревьев\n3.Увеличенный\nснимок глаз персонажей крупным планом с отстраненным печальным взглядом, вызывающим чувство одиночества и тоски", "operation": "gen-multi-input"}', '1t3w9sx8tnrma0css6w8qzp64w', 'succeeded', '{"date": 1760025918, "chatId": 6924855567, "messageId": 99555}', '{"date": 1760025928, "chatId": 6924855567, "messageId": 99558}', '[{"date": 1760025955, "chatId": 6924855567, "messageId": 99559}]');
