INSERT INTO public.operations VALUES ('a090e8a2-1db6-47e8-b99c-91d918e42b88', '2025-10-09 19:07:11.697676', false, 4972227842, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhOpo592mp6HFsXVTNeHfsmO4vmVPqgACt_cxGzkKQUstClBR3rmZswEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создайте вертикальную рамку\nразмер 2160x3840 пикселей 4K Не\nменяет внешнего вида. Качество\nразделено на три горизонтальных\nизображения одинакового размера,\nрасположенных вместе\nГлавный герой основан на эталонной\nприческе лица и тела молодой\nфигуре с выражением грусти и\nностальгии, излучающими одиночество\nНаряд представляет собой свободный\nзимний пуховик с широкими\nштанами и черным шарфом\nОбщая атмосфера покрыта белым снегом\nс холодной цветовой палитрой,\nкоторая вызывает меланхолию и\nодиночество\n1.портрет персонажа держит\nпрозрачный зонтик, слегка\nповорачивая голову назад, глядя\nпрямо на кадр\nВыражение печально\nс душевными глазами\nФон размыт\nснежной белизной\n2.Всё тело с зонтом, стоит один на огромном снежном\nполе, идя, глядя на небо\nУгол\nкамеры смотрит сверху вниз\nэто выглядит так, как будто персонаж поднимает руку, чтобы поймать падающие снежинки\nВдалеке стоят несколько голых деревьев\n3.Увеличенный\nснимок глаз персонажей крупным планом с отстраненным печальным взглядом, вызывающим чувство одиночества и тоски", "operation": "gen-multi-input"}', 'gdx23fqqg1rma0css6wryvw0vg', 'succeeded', '{"date": 1760026022, "chatId": 6924855567, "messageId": 99562}', '{"date": 1760026028, "chatId": 6924855567, "messageId": 99565}', '[{"date": 1760026042, "chatId": 6924855567, "messageId": 99566}]');
