INSERT INTO public.operations VALUES ('7b6c4469-06fe-48f4-b54d-c2f3efd82de8', '2025-10-09 19:46:33.906919', false, 1047793037, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgEAAxkBAAEBhTho5-bVdOYZJnGWJKhdUxB7tPmpMAACxgtrG_gDOUerYDrfQMGpzgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Change the paper in the picture to us dollars and make it look like the person is hold 4 fifty dollars which is a total of 200 dollars", "operation": "gen-multi-input"}', 'kg9ecs831hrme0css7fanaf1h0', 'succeeded', '{"date": 1760028373, "chatId": 5013619733, "messageId": 99640}', '{"date": 1760028382, "chatId": 5013619733, "messageId": 99643}', '[{"date": 1760028403, "chatId": 5013619733, "messageId": 99644}]');
INSERT INTO public.operations VALUES ('6b4a465c-c034-4c09-8742-4d66284f47f9', '2025-10-28 14:36:05.124636', false, 6385531300, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_H5pAAGqht7loK-Yzu7DyVi9tIWKoaIAAgIAATIbMHwISEYpSyT5v_9FAQADAgADdwADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1080, "heightPx": 2400}], "prompt": "Создайте вертикальный кадр размером 2160x3840 пикселей 4K. Не меняйте оригинальное лицо. Качество разделено на три одинаково расположенных по горизонтали изображения, размещенных вместе. Основной персонаж основан на референсной прическе и теле, молодая фигура с выражением печали и ностальгии, глубокие глаза излучают одиночество. Одежда — это свободный зимний пуховик в сочетании с широкими брюками и черным шарфом. Общая атмосфера покрыта белым снегом с холодной цветовой палитрой, которая вызывает меланхолию и одиночество.\n1. Портрет: Персонаж держит прозрачный зонт, слегка отворачивая голову назад, глядя прямо в кадр. Выражение лица печальное, с душевными глазами. Фон размыт снежной белизной.\n2. Полный рост: Персонаж с зонтом стоит один в огромном снежном поле, глядя на небо. Угол камеры направлен сверху вниз, как будто персонаж поднимает руку, чтобы поймать падающие снежинки. Вдалеке виднеются несколько голых, безлистных деревьев. Сцена передает ощущение малости и изоляции на фоне просторов природы.\n3. Крупный план: Увеличенный кадр глаз персонажа с далеким, печальным взглядом, который вызывает чувства одиночества и тоски.", "operation": "gen-multi-input"}', '5v5hp1mpn5rm80ct5ad9dfv8j8', 'succeeded', '{"date": 1761651334, "chatId": 1043471587, "messageId": 130174}', '{"date": 1761651358, "chatId": 1043471587, "messageId": 130183}', '[{"date": 1761651377, "chatId": 1043471587, "messageId": 130184}]');
INSERT INTO public.operations VALUES ('df7cfae3-3056-45dd-bbb7-db6c40306600', '2025-10-28 14:39:16.102619', false, 1646942622, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_IppAAGrG2pQW-Ioc80YmCIAAfqTu7P6AAKf_DEb7twAAUjBC2Z_HXvm9gEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Улучшить, поменять фон", "operation": "gen-multi-input"}', 'yybgzfm0b5rm80ct5aetb60qcg', 'succeeded', '{"date": 1761651483, "chatId": 6722091079, "messageId": 130186}', '{"date": 1761651523, "chatId": 6722091079, "messageId": 130191}', '[{"date": 1761651569, "chatId": 6722091079, "messageId": 130192}]');
