INSERT INTO public.operations VALUES ('00cee180-9cf9-44ce-b720-485d2d6c356d', '2025-10-12 22:05:28.223314', false, 2222288432, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBmXxo6_vzdZK09-2pA5qW1a5T2F26UgACsQUyG7LUYEs4k8fKSjpm7wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 903, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBmSVo6_iFatCkq5rA-w0SkD3nJzs7UQACmQUyG7LUYEsf22E7qWD85wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 736, "heightPx": 1104}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности", "operation": "gen-multi-input"}', 'wjsjc7a2ahrma0csv78ad6g84r', 'succeeded', '{"date": 1760295923, "chatId": 1389182764, "messageId": 104828}', '{"date": 1760295926, "chatId": 1389182764, "messageId": 104832}', '[{"date": 1760295939, "chatId": 1389182764, "messageId": 104833}]');
