INSERT INTO public.operations VALUES ('cc6d9153-34b3-402d-90cb-393d3acf4e13', '2025-10-10 09:36:33.703842', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На изображении изображена молодая женщина, смотрящая прямо в камеру. Её волосы зачёсаны назад, и они выглядят влажными. Она одета в облегающий наряд золотого цвета, напоминающий корсет или бюстье.На её руках надето золотых украшений, включая широкие браслеты, кольца и серьги. Её макияж включает выразительные стрелки и нейтральную помаду. Она касается руками висков, её пальцы слегка согнуты.Фон изображения - размытый светло-серый или белый цвет.Без головных уборов", "operation": "gen-multi-input"}', 'hng8sx754nrm80csskasmtaeyc', 'succeeded', '{"date": 1760078150, "chatId": 1287537311, "messageId": 99986}', '{"date": 1760078191, "chatId": 1287537311, "messageId": 99989}', '[{"date": 1760078203, "chatId": 1287537311, "messageId": 99990}]');
