INSERT INTO public.operations VALUES ('728698f4-b327-4c82-b11a-13a95d551f2b', '2025-10-10 09:38:38.387773', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая в воде. Она одета в белый раздельный купальник. Ее темные волосы мокрые и зачесаны назад. Она смотрит через плечо.На заднем плане пляж с пальмами. Свет яркий, создается ощущение тропического климата.\nБез головных уборов", "operation": "gen-multi-input"}', 'j42ba6ycc5rme0csskbtf3pxkw', 'succeeded', '{"date": 1760078277, "chatId": 1287537311, "messageId": 99991}', '{"date": 1760078304, "chatId": 1287537311, "messageId": 99998}', '[{"date": 1760078328, "chatId": 1287537311, "messageId": 100003}]');
INSERT INTO public.operations VALUES ('4cacc53e-55e1-4160-a9c1-67b7874e150b', '2025-10-25 10:41:40.653022', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB6Y9o_H8LfxfCXmih3GkAAbKTwwo4nU8AAikIMhu8EeFLNPkVMAycD7sBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с длинными темными волосами. На ней надеты черные прямоугольные солнцезащитные очки, черное платье, черный кожаный плащ с поясом, а на шее - две золотые цепочки. Она держит в руке зажженную сигарету.Женщина стоит, опираясь рукой на капот черного автомобиля.Фоном служит деревянный дом с коричневой крышей, а также зелень кустарников и деревьев. Дорога видна перед автомобилем. Освещение создает мягкий свет, что указывает на время суток ближе к вечеру.", "operation": "gen-multi-input"}', '6rzdf9q6anrmc0ct398bdfa2yg', 'succeeded', '{"date": 1761378059, "chatId": 991429758, "messageId": 125327}', '{"date": 1761378099, "chatId": 991429758, "messageId": 125330}', '[{"date": 1761378111, "chatId": 991429758, "messageId": 125331}]');
