INSERT INTO public.operations VALUES ('567651b3-620a-4fbe-bf77-ecea2393b53e', '2025-10-10 09:47:14.555133', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая в воде. Она одета в белый раздельный купальник, трусы стринги. Ее темные волосы мокрые и зачесаны назад. Она смотрит спиной и смотрит назад через левое плечо.На заднем плане пляж с пальмами. Свет яркий, создается ощущение тропического климата.\nБез головных уборов", "operation": "gen-multi-input"}', '8fybhn5cp1rme0csskfrs1zxd4', 'succeeded', '{"date": 1760078779, "chatId": 1287537311, "messageId": 100030}', '{"date": 1760078830, "chatId": 1287537311, "messageId": 100033}', '[{"date": 1760078851, "chatId": 1287537311, "messageId": 100034}]');
