INSERT INTO public.operations VALUES ('0f5db03f-f488-4419-82b4-642fcb5a0ad3', '2025-10-10 09:44:12.407545', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, лежащая в кресле. У неё тёмные волосы, гладко зачёсанные назад. На ней надето чёрное лакированное пальто, обнажающее одно плечо. Она также носит золотые украшения, включая серьги, цепочку и кольца на пальцах. Один палец касается её губ. Губы накрашены красной помадой.Кресло, в котором она лежит, имеет тёмный каркас и светлое сиденье. Фон - однотонная белая стена.\nБез головных уборов", "operation": "gen-multi-input"}', '95ptm4f5gdrme0csskebavmnr8', 'succeeded', '{"date": 1760078642, "chatId": 1287537311, "messageId": 100015}', '{"date": 1760078650, "chatId": 1287537311, "messageId": 100018}', '[{"date": 1760078661, "chatId": 1287537311, "messageId": 100019}]');
