INSERT INTO public.operations VALUES ('d6be9282-d535-44cf-8df1-e69fb42977e6', '2025-10-12 22:10:00.474824', false, 8333547791, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBmYJo6_zJIM2YnCYNZiKw7a0rGibR0wACY_0xG_5GYEuZUGlbWDzKrgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 412, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBmUto6_mxq8HhkOW9xabNE7Y2idn0DAACSP0xG_5GYEs00GtmLZGcGgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 876, "heightPx": 1280}], "prompt": ": сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей стоят рядом и  подимают руки , смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность мужчин не изменять чтобы была в точь точ", "operation": "gen-multi-input"}', 't2h9ymv9xdrme0csv7abczm52c', 'succeeded', '{"date": 1760296137, "chatId": 1018098447, "messageId": 104834}', '{"date": 1760296198, "chatId": 1018098447, "messageId": 104838}', '[{"date": 1760296213, "chatId": 1018098447, "messageId": 104839}]');
