INSERT INTO public.operations VALUES ('a6279d65-5011-4d1c-ba60-4a803837a620', '2025-10-10 09:56:20.44707', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На снимке изображена женщина, сидящая на полу в студийной обстановке. Фон однотонный, светлый.На женщине надет черный пиджак с глубоким вырезом, под которым ничего нет. На глазах у нее солнцезащитные очки с декоративной оправой. В ушах висят серьги. У нее короткие черные волосы, уложенные в легком беспорядке.На ногах у женщины сандалии на тонких ремешках, завязывающихся вокруг лодыжек. Ногти на ногах накрашены черным лаком. Ее ноги скрещены.\nБез головных уборов", "operation": "gen-multi-input"}', 'tt11eh00ynrma0csskm81wcj48', 'failed', '{"date": 1760079322, "chatId": 1287537311, "messageId": 100063}', '{"date": 1760079378, "chatId": 1287537311, "messageId": 100066}', '[{"date": 1760079378, "chatId": 1287537311, "messageId": 100066}]');
