INSERT INTO public.operations VALUES ('62710308-1e3b-457c-b632-9bd216603aac', '2025-10-10 09:57:35.562577', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "На снимке изображена женщина, сидящая на полу в студийной обстановке. Фон однотонный, светлый.На женщине надет черный пиджак с глубоким вырезом, под которым ничего нет. На глазах у нее солнцезащитные очки с декоративной оправой. В ушах висят серьги. У нее длинные черные волосы, уложенные в хвост .На ногах у женщины сандалии на тонких ремешках, завязывающихся вокруг лодыжек. Ногти на ногах накрашены черным лаком. Ее ноги скрещены.\nБез головных уборов", "operation": "gen-multi-input"}', 'emfp8696ghrmc0csskmvebm9gw', 'succeeded', '{"date": 1760079444, "chatId": 1287537311, "messageId": 100068}', '{"date": 1760079454, "chatId": 1287537311, "messageId": 100073}', '[{"date": 1760079464, "chatId": 1287537311, "messageId": 100074}]');
