INSERT INTO public.operations VALUES ('57538287-84d9-46b7-ae48-8ee0cfba1797', '2025-10-10 19:28:23.715431', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBhjFo6ITpD882KBNsnUw4KvdyanSLHQACyvYxG2saSEs-8kqT6WDRowEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 590, "heightPx": 1280}], "prompt": "Изображение представляет собой чёрно-белую фотографию, на которой изображена женщина в облегающем чёрном платье без рукавов. Она стоит, закинув руки над головой, с слегка склоненной головой. Ее волосы распущены и ниспадают на плечи. На шее у нее тонкая цепочка.За ней видна размытая тень ее же в похожей позе, но с закрытыми глазами и руками, поднятыми над головой.Свет падает на нее таким образом, что подчеркивает контуры ее тела и создает контраст между светлыми и темными участками фотографии. Фон неровный, с переходом от более светлых тонов к более темным.", "operation": "gen-multi-input"}', 'qfq2gfxw9srm80cssvsvdz9034', 'succeeded', '{"date": 1760113655, "chatId": 1287537311, "messageId": 100509}', '{"date": 1760113701, "chatId": 1287537311, "messageId": 100514}', '[{"date": 1760113713, "chatId": 1287537311, "messageId": 100515}]');
