INSERT INTO public.operations VALUES ('ce53d981-b973-4384-96cb-5a386079f328', '2025-10-11 15:07:30.660152', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBi1Vo6kgrzYK_KWj0WhRA-K5xLl8v5wACGAABMhsBe1hLTDfPVNq8UUIBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Изображение представляет собой чёрно-белую фотографию, на которой изображена женщина в облегающем чёрном платье без рукавов. Она стоит, закинув руки над головой приподнимая волнистые волосы, с слегка склоненной головой. Ее волосы волнисты и распущены и ниспадают на плечи. На шее у нее тонкая цепочка.За ней видна размытая тень ее же в похожей позе, но с закрытыми глазами и руками, поднятыми над головой.Свет падает на нее таким образом, что подчеркивает контуры ее тела и создает контраст между светлыми и темными участками фотографии. Фон неровный, с переходом от более светлых тонов к более темным.", "operation": "gen-multi-input"}', 'n8a9dd9zg9rmc0cstcntsjpn7w', 'succeeded', '{"date": 1760184444, "chatId": 1287537311, "messageId": 101221}', '{"date": 1760184449, "chatId": 1287537311, "messageId": 101226}', '[{"date": 1760184460, "chatId": 1287537311, "messageId": 101227}]');
