INSERT INTO public.operations VALUES ('b0632475-31e1-44f0-909a-279e6c3709c2', '2025-10-11 15:08:07.833067', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBi1Vo6kgrzYK_KWj0WhRA-K5xLl8v5wACGAABMhsBe1hLTDfPVNq8UUIBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Изображение представляет собой чёрно-белую фотографию, на которой изображена женщина в облегающем чёрном платье без рукавов. Она стоит, закинув руки над головой приподнимая волнистые волосы, с слегка склоненной головой. Ее волосы волнисты и распущены и ниспадают на плечи. На шее у нее тонкая цепочка.За ней видна размытая тень ее же в похожей позе, но с закрытыми глазами и руками, поднятыми над головой.Свет падает на нее таким образом, что подчеркивает контуры ее тела и создает контраст между светлыми и темными участками фотографии. Фон неровный, с переходом от более светлых тонов к более темным. Лицо без макияжа", "operation": "gen-multi-input"}', 'bah2cs6gb5rmc0cstcnvgqjx4w', 'succeeded', '{"date": 1760184476, "chatId": 1287537311, "messageId": 101228}', '{"date": 1760184486, "chatId": 1287537311, "messageId": 101233}', '[{"date": 1760184497, "chatId": 1287537311, "messageId": 101234}]');
