INSERT INTO public.operations VALUES ('7237913b-474b-4877-97ac-ced2d6d1a3e2', '2025-07-24 00:26:38.994945', false, 5040148734, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAIVMGiBU2sEXm9y2SqD6agV9_LJEtbyAAILFTIbtOMJSKRqFaET6Tw_AQADAgADeAADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 360, "heightPx": 582}, "prompt": "Create an image that looks like a selfie taken with an iPhone. There should be no clear subject or specific composition just a casual, unintentional snapshot. The image should be slightly blurred from motion and lit evenly by streetlights. The aspect ratio should be 9:16. It must not look Al-generated, but rather like it was taken by a real person", "sendAs": "photo", "operation": "edit"}', 'vt1g7qv74srmc0cr74qb8pqjs0', 'succeeded', '{"date": 1753305963, "chatId": 6576027684, "messageId": 5424}', '{"date": 1753305995, "chatId": 6576027684, "messageId": 5433}', '[{"date": 1753306005, "chatId": 6576027684, "messageId": 5434}]');
INSERT INTO public.operations VALUES ('1e0b6445-228a-4d85-839a-77b93e5d5cfd', '2025-07-24 00:27:50.715944', false, 5040148734, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAIVQmiBU8tw-S5dA1itmxZBKRWAF136AAIPFTIbtOMJSNLnNRlMI5TWAQADAgADeAADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 360, "heightPx": 545}, "prompt": "Создайте изображение, похожее на селфи, снятое на iPhone. Не должно быть чёткого объекта или определённой композиции, просто случайный, непреднамеренный снимок. Изображение должно быть слегка размыто", "sendAs": "photo", "operation": "edit"}', 'j6zacyw061rmc0cr74qt59agwm', 'succeeded', '{"date": 1753306059, "chatId": 6576027684, "messageId": 5442}', '{"date": 1753306068, "chatId": 6576027684, "messageId": 5447}', '[{"date": 1753306076, "chatId": 6576027684, "messageId": 5448}]');
INSERT INTO public.operations VALUES ('c708ba51-f8ab-40d5-a3fb-7371dd698eb0', '2025-07-21 01:01:22.924615', false, 8043297957, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgEAAxkBAAILvWh9ZwykM1Wl6KecF36qr3YMbVWgAAJ4rzEb3CbxR1kPMHhZA_IPAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 576}, "prompt": "Está foto créame una que en el lugar de Tupapiriko diga Mr Yunior", "sendAs": "photo", "operation": "edit"}', '90n0tsgzg1rme0cr57drmk41dm', 'succeeded', '{"date": 1753048844, "chatId": 6879536587, "messageId": 3005}', '{"date": 1753048878, "chatId": 6879536587, "messageId": 3008}', '[{"date": 1753048890, "chatId": 6879536587, "messageId": 3009}]');
