INSERT INTO public.operations VALUES ('86893fa8-8d9b-4078-b608-c8a06d7ef70d', '2025-07-21 21:28:32.028066', false, 8715071427, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgQAAxkBAAIOpWh-hnDAEx10YxO3aHu6Mr8arMqYAAJuyzEbeYn5Uw0SexueHaDQAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 851, "heightPx": 1280}, "prompt": "i need this cup attached by a red cute helicopter with a background like mountains with green grass and red flowers or trees and the sky is blue - green and some white clouds", "sendAs": "photo", "operation": "edit"}', '8s57hqcy05rme0cr5rzbdhhytr', 'succeeded', '{"date": 1753122416, "chatId": 5383874634, "messageId": 3749}', '{"date": 1753122509, "chatId": 5383874634, "messageId": 3754}', '[{"date": 1753122518, "chatId": 5383874634, "messageId": 3755}]');
INSERT INTO public.operations VALUES ('20e03751-d4a7-4894-a21e-4e801536c0c8', '2025-07-21 17:04:00.410626', false, 7324790181, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgQAAxkBAAIOLGh-SG0j60UlMdrD1UvzMA8GOLEZAAKtxzEbhYzwU_QyXJy-UsT2AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1081, "heightPx": 771}, "prompt": "Чёткость и качество:\n • Фото немного размытое и зернистое. Можно повысить резкость и убрать шум, чтобы кожа и детали выглядели чище.\n 2. Освещение и цвет:\n • Свет тёплый и желтоватый из-за занавесок и лампы. Можно скорректировать баланс белого, чтобы оттенок кожи стал более естественным.\n • Усилить контраст и яркость, сделать лицо более выразительным.\n 3. Кожа и текстура:\n • Лёгкая ретушь кожи (убрать блеск на лбу и подбородке, выровнять тон лица, убрать шум).\n • Подчеркнуть губы и ресницы чуть мягче, не переусердствуя.\n 4. Фон:\n • Желтый фон (занавеска) немного отвлекает. Можно слегка размыть его или затемнить, чтобы акцент ушёл на лицо.\n • Если хочется, можно заменить фон на более нейтральный (но это уже больше на вкус).\n 5. Обрезка (если нужно):\n • Можно немного обрезать левый край, чтобы убрать руку или сместить фокус ближе к центру лица.", "sendAs": "photo", "operation": "edit"}', 'd426v13ewnrme0cr5n69x4d39w', 'succeeded', '{"date": 1753106541, "chatId": 5356813934, "messageId": 3628}', '{"date": 1753106626, "chatId": 5356813934, "messageId": 3633}', '[{"date": 1753106647, "chatId": 5356813934, "messageId": 3634}]');
