INSERT INTO public.operations VALUES ('f8b1be7b-efe6-44b4-89c7-3deee8667ba1', '2025-07-24 08:27:51.490952', false, 5130533368, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgUAAxkBAAIWaWiBwiHam-zd40-O6tocQP5XO5S_AAJoxDEbxCcQVNzb1_rImuTHAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 719}, "prompt": "“Make a selfie photo taken with an iPhone, without any subject or clear composition — just a random snapshot taken accidentally. The photo should have a slight motion blur and consistent lighting from street lamps. Both images should be connected.”", "sendAs": "photo", "operation": "edit"}', 'f1tvya7p95rma0cr7bkamknqpm', 'succeeded', '{"date": 1753334305, "chatId": 1058981533, "messageId": 5737}', '{"date": 1753334305, "chatId": 1058981533, "messageId": 5738}', '[{"date": 1753334879, "chatId": 1058981533, "messageId": 5739}]');
INSERT INTO public.operations VALUES ('b89032d9-0ef1-4c82-8c29-669ab86d40fc', '2025-08-02 09:31:36.175569', false, 5633360236, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAIzP2iNRO9RJn53dMNYZpQSz_7AQDmIAAIQ-TEb7qRoSHPP9DckZWWkAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}, "prompt": "Сделай удлиненное каре, цвет волос русый теплый не совсем теплый, среднее между светлым и темным", "sendAs": "photo", "operation": "edit"}', 'bsxtgyweh1rme0crd5x8wg4rwc', 'succeeded', '{"date": 1754116222, "chatId": 366325005, "messageId": 13178}', '{"date": 1754116293, "chatId": 366325005, "messageId": 13181}', '[{"date": 1754116306, "chatId": 366325005, "messageId": 13182}]');
INSERT INTO public.operations VALUES ('799eb7b0-b4c6-4983-a6c0-4ec83f81bb9a', '2025-07-21 17:09:29.663268', false, 7324790181, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgQAAxkBAAIONGh-SgoexRL5hLV16qB8nDoC6-Q6AAK5xzEbhYzwU6hM166BisHAAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 821, "heightPx": 1083}, "prompt": "Убрать засвет от вспышки (или смягчить её) — она закрывает половину лица и создаёт сильный блик. Если убрать или приглушить — глаза станут виднее, и лицо заиграет.\n 2. Осветлить и выровнять тон кожи:\n • Мягко выровнять цвет на лице и руках (осветлить тени, убрать красноту щёк).\n 3. Улучшить резкость и контраст:\n • Сделать волосы более чёткими, а ткань — чуть более текстурной.\n 4. Фон:\n • Затемнить нижнюю часть, где виднеется унитаз — он немного портит атмосферу. Либо обрезать кадр повыше.\n 5. Смягчить лишние мелкие детали:\n • Например, торчащие волоски на руке — чуть приглушить (не убирать полностью, чтобы не было ненатурально).\n\n⸻\n • Добавить лёгкий блур на фон, чуть увеличить резкость на глазах и губах.\n • Цветокоррекция в холодных тонах — даст более модный вайб.\n • Обрезать фото чуть ближе к лицу — оставить плечо, волосы, телефон и лёгкий поворот головы (работает хорошо для профиля).", "sendAs": "photo", "operation": "edit"}', 'wkdsp1kmy5rme0cr5n8rvjfm4r', 'succeeded', '{"date": 1753106954, "chatId": 5356813934, "messageId": 3636}', '{"date": 1753106963, "chatId": 5356813934, "messageId": 3641}', '[{"date": 1753106976, "chatId": 5356813934, "messageId": 3642}]');
