INSERT INTO public.operations VALUES ('8500e95f-fc53-4e5d-88a4-ad0ef7d146cc', '2025-07-29 09:30:04.87816', false, 9557195286, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgUAAxkBAAIkEmiIakt9ke5f-7JK7oyfZGR6BeDIAAK_xjEbKiZJVKQbOgI4ClhcAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "prompt": "@Ai MGHTOO: Using a 4:6 ratio telephoto camera\nSit relaxed but firmly, leaning slightly back with your arms open on the back of the chair or on the table.One leg can be crossed over the knee or sit with your legs slightly open for a dominant impression.\nA sharp but calm gaze. No big smile - just a thin smile or a straight face with authority.\nThe chin is slightly raised, showing confidence and power.\nExpensive suit or suit, dark colors (black, navy, dark gray), neat tie or even no tie for a \"wilder\" impression.\nShiny leather shoes, a luxury watch, and maybe a gold ring or accessory.\nA cigar in hand, a glass of whiskey on the table, dim lighting, a classic background such as a library or a luxurious office space.", "sendAs": "photo", "operation": "edit"}', 'h5zg515szhrmc0crakfrcqt6dg', 'succeeded', '{"date": 1753770595, "chatId": 5279826584, "messageId": 9240}', '{"date": 1753770602, "chatId": 5279826584, "messageId": 9245}', '[{"date": 1753770618, "chatId": 5279826584, "messageId": 9246}]');
