INSERT INTO public.operations VALUES ('1ae27f4f-8092-4c7e-a662-f691fbb92795', '2025-08-01 01:36:23.293564', false, 8599162147, 10, 0.03, '{"ratio": "9:16", "prompt": "A high-quality 2D anime-style illustration of a teenage girl with long, straight black hair and big, expressive dark eyes. Her skin shows visible, natural-looking acne on her cheeks and forehead — not exaggerated but clearly noticeable. She is wearing black casual clothes (like a hoodie or sweater) that contrast beautifully with the background. The background is a soft, warm pink (#FF4DA6) with a subtle gradient and glow effect. Her pose is emotionally expressive — slightly shy but accepting, looking directly at the viewer with a hint of confidence. The lighting is soft and gentle, highlighting her skin imperfections in an honest, empowering way. Full body or upper-body framing, no other characters, no over-stylization. Make her look relatable, real, and youthful.", "sendAs": "photo", "operation": "gen"}', 'rjwjsb90mxrma0crcagtwsc3jr', 'succeeded', '{"date": 1754001380, "chatId": 6208508597, "messageId": 11971}', '{"date": 1754001380, "chatId": 6208508597, "messageId": 11972}', '[{"date": 1754001395, "chatId": 6208508597, "messageId": 11973}]');
