INSERT INTO public.operations VALUES ('d4da1119-8645-4d43-92ee-c7a5b61932b4', '2025-07-30 03:20:02.338383', false, 9999809893, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAInQ2iJZKvNst_9K8e9vhLrcEdy_EEjAAIJ8zEbDTRQSAwWZySWzX0SAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 720}, "prompt": "Номера нужно изменить на GEKTOR OBNAL  Надпись Розыск Гектор финансист нужно сделать над человеком с лева ,поменять ему кросовки на лоферы loro piano . Человеку справа добавить надпись над головой Розыск большими буквами и снизу \nГектор Медовик", "sendAs": "photo", "operation": "edit"}', 'n0qpnw2d25rmc0crb2srqq7t94', 'succeeded', '{"date": 1753834667, "chatId": 5883304347, "messageId": 10051}', '{"date": 1753834799, "chatId": 5883304347, "messageId": 10054}', '[{"date": 1753834811, "chatId": 5883304347, "messageId": 10055}]');
INSERT INTO public.operations VALUES ('91f9f260-47b6-49cb-b07c-29a1ed77248a', '2025-07-30 03:16:54.782086', false, 9999809893, 10, 0.03, '{"ratio": "16:9", "prompt": "Мне нужна фотография где 2 человека стоят у пляжа  с разных сторон машины bmw m5 f90 с номерами GEKTOR OBNAL , все это происходит на красивом пляже. Фотография в 2d.\nПервый человек должен быть ростом 197 , весом в 150кг именно мышечной массы. Одет в балаклаву с красным квадратом и надписью HUGO , футболку Armani, рваные джинсы stone island , кроссовки Balenciaga 3xl\nВторой человек должен быть ростом 187, весом 90 килограмм с мышцами , одет в балаклаву stone island, куртку c.p. company, футболка с надписью OBNAL , шорты nike и кросовки белые nike Cortez.\nТак же первому человеку подпиши сверху красными буквами Розыск и чуть ниже Гектор финансист\nА второму человеку сверху подпиши Розыск и снизу Гектор Meadxd", "sendAs": "photo", "operation": "gen"}', '76n2jyvgf5rma0crb2r9mx66cg', 'succeeded', '{"date": 1753834605, "chatId": 5883304347, "messageId": 10046}', '{"date": 1753834605, "chatId": 5883304347, "messageId": 10047}', '[{"date": 1753834625, "chatId": 5883304347, "messageId": 10048}]');
