INSERT INTO public.operations VALUES ('c5f67a1b-bf19-4fba-a9a7-ab3485f2c0a6', '2025-08-14 12:51:26.851813', false, 7715794058, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgQAAxkBAAJXumidsYfUNOpvuISftJyd_nopnDY3AAJPyjEb6N7xUCT-T9I3ZoZ0AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}, "prompt": "Make it like iphone photo", "sendAs": "photo", "operation": "edit"}', '55s667pndxrm80crmzysgwt97c', 'succeeded', '{"date": 1755165063, "chatId": 8198262857, "messageId": 22458}', '{"date": 1755165078, "chatId": 8198262857, "messageId": 22461}', '[{"date": 1755165098, "chatId": 8198262857, "messageId": 22462}]');
INSERT INTO public.operations VALUES ('c846789c-955f-47e3-96f4-869b423befda', '2025-08-15 18:12:14.583518', false, 2137063477, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgUAAxkBAAJbeGifSa2PPtfhDV-Xh6wBdMjncxxGAAKnxzEbAuT5VBgcXZnFRPS0AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "prompt": "\"Create a high-resolution, natural portrait of a young man with medium skin tone, wearing an elegant white kimono-style robe similar to Aizen’s outfit from Bleach. The robe should have clean lines, a high collar, and black inner lining visible subtly, capturing that sleek, commanding look.\n\nThe pose should be confident and relaxed, with a calm, handsome expression that radiates quiet strength. Add a sleek black eye patch over the right eye, inspired by Aizen, designed with subtle anime detailing but realistic and fitting naturally on the face.\n\nApply a slight anime art style: clean, precise linework with gentle shading and smooth skin textures that enhance but do not change the original facial features. Retain the natural skin tone, hair texture, and face shape without distortion.\n\nSet the background to a dark, cinematic gradient mixing deep purples and muted reds, creating a moody, mysterious atmosphere. Add soft, realistic sunray lines filtering through blinds, casting delicate shadows and light stripes across the face and robe to add dramatic depth.\nInclude subtle neon accents reflecting softly on the edges of the robe and face to create a modern, stylish look. The overall mood should blend realism with anime flair, maintaining a high level of detail and clarity suitable for a premium Instagram profile picture that stands out while preserving the subject’s identity.\"", "sendAs": "photo", "operation": "edit"}', '1vny07f4fxrmc0crns4sptcyym', 'succeeded', '{"date": 1755270725, "chatId": 5856158446, "messageId": 23468}', '{"date": 1755270732, "chatId": 5856158446, "messageId": 23473}', '[{"date": 1755270743, "chatId": 5856158446, "messageId": 23474}]');
