INSERT INTO public.operations VALUES ('73aaa009-c155-4d90-8bdf-77e416d3e6f5', '2025-08-15 18:16:42.169024', false, 2137063477, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgUAAxkBAAJbeGifSa2PPtfhDV-Xh6wBdMjncxxGAAKnxzEbAuT5VBgcXZnFRPS0AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "prompt": "\"Create a high-quality, realistic portrait of  18-year-old young man with natural skin tone and features, wearing a sleek, well-fitted dark suit with a crisp white shirt underneath — no tie for a youthful, stylish vibe. The pose should be confident yet relaxed, like sitting casually on a chair or leaning slightly forward, exuding calm professionalism with a subtle, approachable smile.\n\nUse minimalistic, cinematic lighting with deep, dark shadows and dramatic contrasts. Add subtle sunray lines or light streaks gently falling across the face and background, creating an artistic shadow effect without overpowering the natural look.\n\nThe background should be solid black or very deep charcoal with a soft gradient effect, making the subject stand out sharply. Keep the focus sharp on the face with natural textures and no heavy filters or anime effects. The overall mood is clean, modern, and luxurious but youthful and fresh, perfect for a sophisticated, cool Instagram profile picture with a dark vibe.\"", "sendAs": "photo", "operation": "edit"}', 'yw9apsfrsnrmc0crns6vgca2nr', 'succeeded', '{"date": 1755270993, "chatId": 5856158446, "messageId": 23475}', '{"date": 1755270999, "chatId": 5856158446, "messageId": 23480}', '[{"date": 1755271016, "chatId": 5856158446, "messageId": 23481}]');
