INSERT INTO public.operations VALUES ('fe092264-49a8-4a5d-a1ef-b04e2f5cb7b1', '2025-08-16 16:16:01.8643', false, 1184115200, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAJecWiggylCw48TKO1itEmZNmUa9JQ2AAIv9DEbLrYJSfTurhVBpdK7AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}, "prompt": "За мной должен стоять парень чуть выше меня, с кудрявыми русыми волосами. На нем чёрное худи с надвинутым на голову капюшоном, который частично закрывает его лицо, так что его лицо почти не видно. Он нежно обнимает меня за талию, создавая ощущение близости и тепла. Поза должна быть естественной и реалистичной, словно он действительно стоит рядом и поддерживает меня. Важно, чтобы освещение и тени на парне совпадали с общим светом на фото, а одежда гармонировала с моим образом. Максимально реалистично", "sendAs": "photo", "operation": "edit"}', 'h5swgpytb1rm80crpc2r4dhtzg', 'succeeded', '{"date": 1755350140, "chatId": 7771294031, "messageId": 24200}', '{"date": 1755350157, "chatId": 7771294031, "messageId": 24207}', '[{"date": 1755350169, "chatId": 7771294031, "messageId": 24208}]');
