INSERT INTO public.operations VALUES ('168e1e9b-6852-4085-b48d-38461a526986', '2025-08-26 20:49:14.937318', false, 6303029526, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAKGGWit85DzqtvkY0eInQkmjLbnIb5UAAJr-zEbs2hwSRykNs3CNyX0AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 721, "heightPx": 1280}, "prompt": "Создай изображение в Ultra-HD(8k) студийного портретадевушки с ярким летним макияжем. Одна половина её лицаприкрыта сочной долькой апельсина.Макияж насыщенный: оранжевые тени, подчёркнутыечерной графичной стрелкой,выразительные ресницы, матовые розово-нюдовые губы,сияющая кожа с лёгким эффектом свечения. Волосы темные, уложены гладко.Образ дополняетсяяркими жёлтыми серьгами геометрической формы. Фон- насыщенно-синий или контрастно-тёплый, подчёркивающий свежестькомпозиции.", "sendAs": "photo", "operation": "edit"}', '0c04p7cnvsrme0crwxzrkw4654', 'succeeded', '{"date": 1756230544, "chatId": 346198558, "messageId": 34329}', '{"date": 1756230549, "chatId": 346198558, "messageId": 34332}', '[{"date": 1756230563, "chatId": 346198558, "messageId": 34333}]');
INSERT INTO public.operations VALUES ('93a25b0b-dd84-442f-8a76-e7ab4096040e', '2025-09-04 14:12:56.315252', false, 8332532008, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAK112i5cr6i5BdETPIUp8SPyypM1_DYAALX-DEb-ILISfg4dBVDN1rvAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "prompt": "добавьте на мое фото реалистичное ночное небо. Небо должно быть глубокого черного или темно-синего цвета, с множеством ярких, четких звезд. Создайте эффект, как будто я стою под этим небом и показываю на одну или несколько звезд. Важно, чтобы небо выглядело естественно, без излишней \"нарисованности\". Освещение от звезд должно слегка отражаться на мне (если это возможно) или создавать соответствующую атмосферу.\"\n\nКлючевые элементы запроса:\nРеалистичное ночное небо: Основное требование к эффекту. Черное или темно-синее – уточнение желаемого оттенка.\nЗвезды Должны быть яркие, четкие, многочисленные.\n Избегать неестественных, \"мультяшных\" эффектов. Легкий эффект отражения звездного света на мне, чтобы улучшить интеграцию.", "sendAs": "photo", "operation": "edit"}', 'wxdv7xfwpsrmc0cs2hprvexk28', 'succeeded', '{"date": 1756984313, "chatId": 7259361296, "messageId": 46558}', '{"date": 1756984370, "chatId": 7259361296, "messageId": 46569}', '[{"date": 1756984389, "chatId": 7259361296, "messageId": 46570}]');
