INSERT INTO public.operations VALUES ('836c4232-7f5a-4bec-9f73-441b44ad3ff2', '2025-08-27 09:10:57.073991', false, 3152093894, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgQAAxkBAAKIhmiuoWgI9-MhV4GJIZzUE0rx-msqAAKJyzEbw0R4UVMAAZo4fMIFPAEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 471, "heightPx": 534}, "prompt": "To create a prompt for generating an image similar to the one you described, you can follow these guidelines:\n\n1. Subject Description: Clearly describe the main subject of the image (e.g., a person wearing specific clothing).\n2. Clothing Details: Specify the type of clothing and colors (e.g., \"a person wearing a black jacket over a light-colored shirt\").\n3. Accessories: Mention any accessories or additional elements (e.g., \"wearing necklaces\").\n4. Graphic Elements: Describe any graphic elements you want to include (e.g., \"include a gold crown emoji, a blue verification badge emoji, and a yellow badge emoji\").\n5. Text Elements: Specify the text you want in the image (e.g., \"add the text ''Esrael Jr'' and ''@Lewis_Esrael'' in a stylized font\").\n6. Style and Tone: Indicate the overall style or tone of the image (e.g., \"make it vibrant and modern\").\n\n▎Example Prompt\n\n\"Create an image of a person wearing a black jacket over a light-colored shirt, adorned with several necklaces. Include graphic elements like a gold crown emoji, a blue verification badge emoji, and a yellow badge emoji. Add the text ''ESRAEL JR'' and ''@Lewis_Esrael'' in a stylized font, ensuring the overall look is vibrant and modern.\"", "sendAs": "photo", "operation": "edit"}', 't439kbx2a9rma0crx8k8xwdgyr', 'succeeded', '{"date": 1756275048, "chatId": 7809704193, "messageId": 34950}', '{"date": 1756275054, "chatId": 7809704193, "messageId": 34955}', '[{"date": 1756275064, "chatId": 7809704193, "messageId": 34956}]');
