INSERT INTO public.operations VALUES ('e24dad12-5980-4838-a8be-789f6eab874b', '2025-08-27 21:58:16.370559', false, 8042265802, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAKMdGivVUCZlbJADrSDOVA57CrveOndAAKkAzIbEJuASdaAHyUMX04ZAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "prompt": "Создайте кинематографическое, ультрареалистичное изображение моей машины, катящейся по шоссе в сумерках, автомобиль находится в резком фокусе с естественным размытием движения на заднем плане и колесах, чтобы подчеркнуть скорость. Автомобиль опущен со смелой, агрессивной позой. Используйте объектив 24/70mm f/2 для малой глубины резкости и насыщенной контрастности. Молния должна быть драматичной - освещенная над головой Street, молния, проходящими фарами, и тонкими неоновыми отражениями, сцена должна запечатлеть угрюмую высокопроизводительную эстетику с темной глянцевой отделкой, подчеркивающей реализм, острые текстуры и отполированную зрительную атмосферу", "sendAs": "photo", "operation": "edit"}', '44jw0313asrma0crxkjt98336m', 'succeeded', '{"date": 1756321088, "chatId": 1355957314, "messageId": 35956}', '{"date": 1756321088, "chatId": 1355957314, "messageId": 35957}', '[{"date": 1756321104, "chatId": 1355957314, "messageId": 35958}]');
