INSERT INTO public.operations VALUES ('cb43eaa8-fa23-4ad9-bd19-472c0c9ed426', '2025-08-27 21:59:34.073853', false, 8042265802, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAKMd2ivVYjRDHoN-tCc1eD5e9jEjoUEAAKmAzIbEJuASYrY-89Btyg4AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "prompt": "Создайте кинематографическое, ультрареалистичное изображение моей машины, катящейся по шоссе в сумерках, автомобиль находится в резком фокусе с естественным размытием движения на заднем плане и колесах, чтобы подчеркнуть скорость. Автомобиль опущен со смелой, агрессивной позой. Используйте объектив 24/70mm f/2 для малой глубины резкости и насыщенной контрастности. Молния должна быть драматичной - освещенная над головой Street, молния, проходящими фарами, и тонкими неоновыми отражениями, сцена должна запечатлеть угрюмую высокопроизводительную эстетику с темной глянцевой отделкой, подчеркивающей реализм, острые текстуры и отполированную зрительную атмосферу", "sendAs": "photo", "operation": "edit"}', 'rg8159tjs9rmc0crxkkbfppa3c', 'succeeded', '{"date": 1756321160, "chatId": 1355957314, "messageId": 35959}', '{"date": 1756321170, "chatId": 1355957314, "messageId": 35964}', '[{"date": 1756321181, "chatId": 1355957314, "messageId": 35965}]');
INSERT INTO public.operations VALUES ('b3f069c6-0851-4cef-b570-17e3040f588b', '2025-08-27 22:03:35.485675', false, 8042265802, 10, 0.04, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAKMfmivVnh2Ae8YcGa8zoUkHRiJ-OFhAAKpAzIbEJuASXS69yc4TDSZAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1024, "heightPx": 1280}, "prompt": "@Srimbloli FF Go cnc: Сделайте чрезвычайно обычное и ничем не примечательное селфи на iPhone без четкого предмета или чувства композиции - просто быстрый случайный снимок. На фотографии небольшое размытие в движении и неравномерное освещение от уличных фонарей или внутренних фонарей, что приводит к легкой передержке в некоторых областях. Угол неудобный, а кадрирование грязное, что придает снимку намеренно посредственное ощущение, как будто он был сделан рассеянно, вытаскивая телефон из кармана. Главный герой [лицо загруженного человека], и ( Джейсоном Сттехомом )стоит рядом с ним, оба пойманные в непринужденный, несовершенный момент. На заднем плане виден оживленный ночной город с проезжающими мимо неоновыми огнями, пробками и размытыми фигурами. Общий вид намеренно простой и случайный, запечатлевший аутентичную атмосферу плохо составленного, спонтанного селфи на iPhone.", "sendAs": "photo", "operation": "edit"}', 'hxr26tr2q5rme0crxknagpytd8', 'succeeded', '{"date": 1756321400, "chatId": 1355957314, "messageId": 35966}', '{"date": 1756321410, "chatId": 1355957314, "messageId": 35971}', '[{"date": 1756321429, "chatId": 1355957314, "messageId": 35972}]');
