INSERT INTO public.operations VALUES ('fbeecb9c-063d-4272-b2fd-a9800f7216d2', '2025-10-29 20:04:44.23651', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAytpAg6fi4TsLlED4iQ1b6f5smYQ4AACOQIyG4qQEUgDW-cuUs0x6AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки. Максимально сохрани мою внешность. Девушка лежит на спине на диване , фото сделано сверху . На девушке одета белая свободная рубашка с глубоким открытым вырезом на груди. У девушки черные длинные волосы уложены большими локонами коровье лежит на диване в разные стороны . У девушки маленькие серьги и цепочка.", "operation": "gen-multi-input"}', '1ya4vxenwxrma0ct63pvf8fwt8', 'succeeded', '{"date": 1761757295, "chatId": 1287537311, "messageId": 132039}', '{"date": 1761757483, "chatId": 1287537311, "messageId": 132044}', '[{"date": 1761757495, "chatId": 1287537311, "messageId": 132045}]');
