INSERT INTO public.operations VALUES ('f24f1d46-59f2-4afd-93b9-580247d9a365', '2025-10-13 16:44:44.18152', false, 5465159283, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBnRpo7QI4V_qY3NuftNwv3ZlrLp_awwAC0vwxG-O4aEuApt35JpSFLAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Ты дизайнер и маркетолог.  Тебе необходимо сделать из фото которое я прикрепила крутой дизайн. Это фото из кофейни. Необходимо добавить больше зелени, разных элементов из декора чтобы все между собой сочеталось. Можно добавить неоновую ленту под зеркало чтобы хорошо смотрелось. Сбоку на Зеркале добавить куаркод на ссылку в соц сети. Чтобы в конечном итоге зона была инстраграмной но в то же время уютной.", "operation": "gen-multi-input"}', 'm4hhnaqtzsrmc0csvq89brbhzg', 'succeeded', '{"date": 1760363064, "chatId": 793317683, "messageId": 105754}', '{"date": 1760363076, "chatId": 793317683, "messageId": 105757}', '[{"date": 1760363096, "chatId": 793317683, "messageId": 105758}]');
