INSERT INTO public.operations VALUES ('537a4d7d-313e-4775-b734-5e9ae2aa2103', '2025-10-13 19:32:18.186715', false, 2303419069, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBnh5o7Sl6gsyX_PmNLhOtWw_geb_D4wACuP4xG6jpaUtFBuaSFO2t2wEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1920, "heightPx": 2560}, {"file": {"fileId": "AgACAgIAAxkBAAEBnh9o7Sl6yZfeooIDnYoX8mP0ZyG0ywACuf4xG6jpaUthQem_Y1SRswEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 2560, "heightPx": 1920}], "prompt": "объедини две фотографии, на первое фото к девочке, добавь женщину со второго", "operation": "gen-multi-input"}', '7cr9pw34n9rma0csvsnanqvvg8', 'failed', '{"date": 1760373114, "chatId": 5202009925, "messageId": 106014}', '{"date": 1760373128, "chatId": 5202009925, "messageId": 106018}', '[{"date": 1760373128, "chatId": 5202009925, "messageId": 106018}]');
INSERT INTO public.operations VALUES ('fd836f55-331d-4517-8912-91e02e0f6f82', '2025-10-17 17:11:31.074491', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу.\nГолова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой.\nМакияж: мягко очерченный - сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 c объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица", "operation": "gen-multi-input"}', 'n74z1hzf7srmc0csya1925wvwm', 'succeeded', '{"date": 1760710286, "chatId": 1287537311, "messageId": 110294}', '{"date": 1760710289, "chatId": 1287537311, "messageId": 110299}', '[{"date": 1760710301, "chatId": 1287537311, "messageId": 110301}]');
