INSERT INTO public.operations VALUES ('19e3b239-b3be-4618-8902-e173e96a88c2', '2025-10-15 10:49:35.49495', false, 2172308443, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBow9o71IKayyqDQhjzu-tVouWgQ-gnwACUvcxGy_MgUt9pUCiEajlSQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 572, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBovpo71C0gQzkXpzou36rsm0hiuJArgACLPcxGy_MgUs-y4C5cdx0LwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки  и парня не изменять чтобы была в точь точь", "operation": "gen-multi-input"}', 'n4ndycmdd1rma0cswvc8ev72g8', 'succeeded', '{"date": 1760514570, "chatId": 1216501596, "messageId": 107279}', '{"date": 1760514574, "chatId": 1216501596, "messageId": 107283}', '[{"date": 1760514589, "chatId": 1216501596, "messageId": 107284}]');
