INSERT INTO public.operations VALUES ('59dc467c-92d5-40f0-b646-2e1a60c27450', '2025-10-17 17:03:13.079783', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBrn9o8kyaC6tA3Qt280c_rp51YSebKQACEPYxG-zamUt16iqsOOMJhAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Создай портрет женщины в черно-белом стиле, лежащей на полу с упором на изысканный корсет.\nФон серый пол серый темный . Женщина в черном корсете, длинной юбке и перчатках с узорами. Она тянется рукой к огромной широкой хрустальной люстре, которая висит низко, почти касаясь пола. Люстра выполнена из хрусталя, с множеством кристаллов и свечей, которые ярко освещают сцену. Женщина смотрит на люстру с выражением восхищения и концентрации.\nОсвещение - контрастное, мягкое, с акцентом на её фигуру и детали люстры. Люстра прорабатывается в 4К-качестве, с четкими текстурами и рябью в свете, создавая атмосферу кинематографичного напряжения. Используй кинематографическое освещение, с глубокими тенями и высокой детализации. Не меняй черты", "operation": "gen-multi-input"}', 's5vkdtjp2srma0csy9xrb3rsd0', 'succeeded', '{"date": 1760709786, "chatId": 1287537311, "messageId": 110207}', '{"date": 1760709790, "chatId": 1287537311, "messageId": 110212}', '[{"date": 1760709804, "chatId": 1287537311, "messageId": 110213}]');
INSERT INTO public.operations VALUES ('ab792320-1158-4134-8a01-f811c03d75d4', '2025-10-17 17:04:17.226759', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай изображение меня,за основу возьми моё фото референс и Максимально сохрани мою внешность. Камера: Canon EOS R6 + RF 85mm f/1.4; f/2.0, ISO 100, 1/500s, WB 5800K; RAW 14-bit; 4KHD. Вертикальный портрет по бёдра, корпус в 3/4, плечи расслаблены. Правая рука у виска, пальцы мягко касаются лба, локоть отведён в сторону; левая рука опущена. Девушка у которой прямые/слегка волнистые волосы, объём у корней, лёгкий наветренный беспорядок. Брови естественные, тонкая стрелка на глазах, ресницы длинные; кожа тёплая с деликатным сиянием, губы нюд-розовые сатин. На мне чёрный кожаный тренч из мягкого экокожа с матовым полуглянцем, широкий лацкан, пояс завязан узлом, манжеты с хлястиками; под ним чёрный тонкий топ с трикотажной манжетой, выглядывающей у правой кисти. На шее крошечный кулон на тонкой цепочке. Я в солнечных очках. Фон — парк поздней осени: золотые кроны и ковёр листьев; вдаль уходит парковая дорожка в мягком боке. Освещение естественное: низкий тёплый контровой слева-сзади создаёт оранжевую кайму по волосам и плечам; спереди — большой мягкий небесный ключ + лёгкий отражатель снизу; слева от камеры — негатив-фил для объёма. ГРИП малая, фокус на ближайшем глазе и ресницах; тренч читается по бликам шва и складок. Цветокор: тёплые хайлайты «golden hour», фон слегка десатурирован, кожа естественная; микро-зерно минимальное. Атмосфера — спокойный осенний editorial с акцентом на фактуру кожи и экокожи.", "operation": "gen-multi-input"}', 'h73gcwtgwhrm80csy9yb8k4mkr', 'succeeded', '{"date": 1760709852, "chatId": 1287537311, "messageId": 110222}', '{"date": 1760709856, "chatId": 1287537311, "messageId": 110227}', '[{"date": 1760709870, "chatId": 1287537311, "messageId": 110229}]');
INSERT INTO public.operations VALUES ('b6cecbae-684f-4c5f-b721-b45e4f2961bf', '2025-10-25 18:29:56.391638', false, 7116811525, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "3:4"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7Gho_OwrEqP7qUEckpckaYn9IZNDUAAClAEyG-3i6Ut_1fR6W_eSbQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 1176}, {"file": {"fileId": "AgACAgIAAxkBAAEB7ENo_OlkY8vEZ91xxwlUdlIUfIkJagAChwEyG-3i6Uvahz51RjyGaAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Женщина обнимает ребенка на руках", "operation": "gen-multi-input"}', 'wex44bcvbxrm80ct3fysh7f7fm', 'succeeded', '{"date": 1761406172, "chatId": 1966741829, "messageId": 126092}', '{"date": 1761406188, "chatId": 1966741829, "messageId": 126096}', '[{"date": 1761406218, "chatId": 1966741829, "messageId": 126097}]');
INSERT INTO public.operations VALUES ('4ae0e8fe-24ba-4405-bb3e-145e70c81ddf', '2025-10-17 17:04:56.614777', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Сделай фото, темная улица с атмосферным голубым свечением, дождь на заднем плане, атмосфера дождя, я сырая, волосы мокрые, капли стекают по моему лицу и волосам, глаза закрыты я смотрю на верх.\nСделай только лицо, не нужно делать фото в полный рост", "operation": "gen-multi-input"}', 'p9r8g3qadnrm80csy9y8xg1de4', 'succeeded', '{"date": 1760709887, "chatId": 1287537311, "messageId": 110230}', '{"date": 1760709894, "chatId": 1287537311, "messageId": 110235}', '[{"date": 1760709907, "chatId": 1287537311, "messageId": 110236}]');
