INSERT INTO public.operations VALUES ('bcd80a77-7404-4b00-815e-8fa1390c96c6', '2025-10-17 17:11:06.548596', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу.\nГолова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой.\nМакияж: мягко очерченный - сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 c объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица", "operation": "gen-multi-input"}', '0hsy1mmfq1rm80csya1anfeczr', 'succeeded', '{"date": 1760710259, "chatId": 1287537311, "messageId": 110282}', '{"date": 1760710262, "chatId": 1287537311, "messageId": 110287}', '[{"date": 1760710276, "chatId": 1287537311, "messageId": 110293}]');
