INSERT INTO public.operations VALUES ('c8a76598-0496-4f76-bbe3-4a38e8aca5d0', '2025-10-17 17:21:11.216336', false, 1952220518, 3, 0.003, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAEBrylo8lCu_6OUtNnHjMN3rPE0E0_j1AACHvUxGyz9kEsvS4RyE0o9WQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, "operation": "remove-bg"}', 'syyqyep9d9rga0csya5t9kn0sw', 'succeeded', '{"date": 1760710830, "chatId": 5815423808, "messageId": 110377}', '{"date": 1760710868, "chatId": 5815423808, "messageId": 110399}', '[{"date": 1760710878, "chatId": 5815423808, "messageId": 110400}]');
INSERT INTO public.operations VALUES ('d87b5efb-b7dd-4834-8c6b-bd155be59ddd', '2025-10-17 17:12:37.447958', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу.\nГолова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой.\nМакияж: мягко очерченный - сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 c объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица у девушки прямые длинные черные волосы", "operation": "gen-multi-input"}', '5dprh8fkbdrm80csya1vh18t1r', 'succeeded', '{"date": 1760710341, "chatId": 1287537311, "messageId": 110306}', '{"date": 1760710356, "chatId": 1287537311, "messageId": 110311}', '[{"date": 1760710370, "chatId": 1287537311, "messageId": 110312}]');
INSERT INTO public.operations VALUES ('d1285f10-d3ab-4e16-b800-42c2b0cdd41b', '2025-10-17 17:21:07.613514', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая на фоне однотонной черной стены. Ее волосы гладко зачесаны назад. На ней надет белый жакет с широкими лацканами и одной пуговицей. Под жакетом видна тонкая золотая цепочка на шее. В ушах надеты золотые серьги.На женщину падает сценический свет, создающий круглый светлый участок на стене за ее спиной и выделяющий ее фигуру. Нижняя часть тела скрыта, но видны верхние части брюк черного цвета.", "operation": "gen-multi-input"}', '8mtmkwnvh9rm80csya5sp0tbtg', 'succeeded', '{"date": 1760710848, "chatId": 1287537311, "messageId": 110386}', '{"date": 1760710854, "chatId": 1287537311, "messageId": 110391}', '[{"date": 1760710878, "chatId": 1287537311, "messageId": 110401}]');
