INSERT INTO public.operations VALUES ('941dc95b-e503-4f1f-b707-7711ecf7f150', '2025-10-17 17:34:29.187224', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении представлена фотография женщины, выполненная в стиле двойной экспозиции.Слева в профиль изображена женщина с темными волосами, собранными в пучок, и серьгой-каффом на ухе. Она одета в топ с глубоким вырезом. Рядом с ней видна размытая кисть руки.Правая сторона изображения показывает полупрозрачное лицо женщины крупным планом, глаза закрыты, и есть блик на губах. Фон белый.", "operation": "gen-multi-input"}', 'fbybcezpqhrmc0csyabtr4gjc8', 'succeeded', '{"date": 1760711651, "chatId": 1287537311, "messageId": 110440}', '{"date": 1760711667, "chatId": 1287537311, "messageId": 110445}', '[{"date": 1760711680, "chatId": 1287537311, "messageId": 110446}]');
