INSERT INTO public.operations VALUES ('b7c4f5f2-246d-471c-9c22-05da1d694d9a', '2025-10-17 17:14:44.190193', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу. Голова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой. Причёска: зачёсана назад за плечи плавными естественными волнами. Макияж: мягко очерченный — сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 с объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица у девушки длинные черные прямые волосы", "operation": "gen-multi-input"}', 'qtn1d2z1j5rma0csya2vwh1me4', 'succeeded', '{"date": 1760710468, "chatId": 1287537311, "messageId": 110327}', '{"date": 1760710483, "chatId": 1287537311, "messageId": 110332}', '[{"date": 1760710496, "chatId": 1287537311, "messageId": 110335}]');
INSERT INTO public.operations VALUES ('af02c71e-8793-467c-9c08-6fcfdd3dd0a9', '2025-10-17 20:56:55.58265', false, 4454121671, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgEAAxkBAAEBsHpo8oHzoeYWRKPGHYjQrhx2zl4rSAACUAtrG6_ZmUeACF2y7UY-pAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 828, "heightPx": 1022}], "prompt": "Put her on an hospital bed with a tube in a nose. Her nails should be pink if you show them and a plaster on her hand with a little bruises also and that’s if you show her hand. I don’t want a portrait picture just a normal picture", "operation": "gen-multi-input"}', 'jyd8kdte51rm80csyd8vnn2njm', 'succeeded', '{"date": 1760723636, "chatId": 8055549141, "messageId": 110723}', '{"date": 1760723786, "chatId": 8055549141, "messageId": 110726}', '[{"date": 1760723826, "chatId": 8055549141, "messageId": 110727}]');
INSERT INTO public.operations VALUES ('0b6c5a4e-05f4-4d8b-be22-0f3c826fc155', '2025-10-18 15:32:22.414973', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении женщина лежит на полу, опираясь на локти. Она одета в черную шубу с открытыми плечами и черные кружевные колготки. У нее темные длинные волосы слегка вьются и свободно лежат на плечах. Пол серого цвета, стена за ней белая. Она смотрит в камеру.", "operation": "gen-multi-input"}', 'ehvdevc6fdrmc0csyx7azst4am', 'failed', '{"date": 1760790737, "chatId": 1287537311, "messageId": 111477}', '{"date": 1760790741, "chatId": 1287537311, "messageId": 111482}', '[{"date": 1760790741, "chatId": 1287537311, "messageId": 111482}]');
