INSERT INTO public.operations VALUES ('748e593b-c447-4f07-bd52-94da7bf38e8f', '2025-10-20 17:39:44.284254', false, 8045144904, 3, 0.003, '{"photo": {"file": {"fileId": "AgACAgIAAxkBAAEBxl5o9kkEst3uUZmvl0QRUIGh7oG9aAACSfoxG6h6sUuytC6iH8dIYQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1065}, "operation": "remove-bg"}', '3qxfvcyt2hrgc0ct087v3sxf8r', 'succeeded', '{"date": 1760971012, "chatId": 757925897, "messageId": 116318}', '{"date": 1760971013, "chatId": 757925897, "messageId": 116319}', '[{"date": 1760971188, "chatId": 757925897, "messageId": 116320}]');
INSERT INTO public.operations VALUES ('1065ea1f-a96a-4dd3-b427-7c954adbcd79', '2025-10-17 17:15:18.435247', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай портрет женщины в черно-белом стиле, лежащей на полу с упором на изысканный корсет.\nФон серый пол серый темный . Женщина в черном корсете, длинной юбке и перчатках с узорами. Она тянется рукой к огромной широкой хрустальной люстре, которая висит низко, почти касаясь пола. Люстра выполнена из хрусталя, с множеством кристаллов и свечей, которые ярко освещают сцену. Женщина смотрит на люстру с выражением восхищения и концентрации.\nОсвещение - контрастное, мягкое, с акцентом на её фигуру и детали люстры. Люстра прорабатывается в 4К-качестве, с четкими текстурами и рябью в свете, создавая атмосферу кинематографичного напряжения. Используй кинематографическое освещение, с глубокими тенями и высокой детализации. Не меняй черты,", "operation": "gen-multi-input"}', 'br9s8a37ydrme0csya3by2se80', 'succeeded', '{"date": 1760710495, "chatId": 1287537311, "messageId": 110333}', '{"date": 1760710516, "chatId": 1287537311, "messageId": 110339}', '[{"date": 1760710538, "chatId": 1287537311, "messageId": 110341}]');
INSERT INTO public.operations VALUES ('26bceda3-cb4b-45c6-9370-36b3814bc8f3', '2025-10-20 05:05:00.836025', false, 4203082631, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "4:3"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwW5o9ZiXh39qV0GNlrDG-hsIHYCV-QACCPsxG_8GsEt5UKl4hzPTkAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 559}], "prompt": "Убери весь текст с изображения и время", "operation": "gen-multi-input"}', '8ap3aaf0phrma0cszxe9p04p7c', 'succeeded', '{"date": 1760925847, "chatId": 6251165823, "messageId": 115054}', '{"date": 1760925870, "chatId": 6251165823, "messageId": 115057}', '[{"date": 1760925907, "chatId": 6251165823, "messageId": 115058}]');
