INSERT INTO public.operations VALUES ('978b2eab-b0ce-4c9d-8ab4-373c5d5d8eec', '2025-10-20 10:16:36.835472', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwwlo9eFmHW0RfuG69CxAYdsROW6OWgAChf4xG68OsEsuyRkWT0odgwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Create a cinematic black and white portrait of me in 8K, adjusting my tie while wearing a classic tailor-made suit, standing confidently in a studio with strong side lighting creating high contrast. Horizontal streaks of light (like light coming through curtains) cast shadows on my face and suit. The expression is calm and confident, exuding elegance and determination. High-fashion, editorial style. Highly detailed, minimal, and symmetrical composition.\n\n«Убери тени с лица»", "operation": "gen-multi-input"}', 'j2cq0x9afhrm80ct01xa33j9q4', 'succeeded', '{"date": 1760944486, "chatId": 1287537311, "messageId": 115465}', '{"date": 1760944535, "chatId": 1287537311, "messageId": 115470}', '[{"date": 1760944608, "chatId": 1287537311, "messageId": 115476}]');
