INSERT INTO public.operations VALUES ('497de3d1-0cf5-4690-b668-8951f09253a8', '2025-10-17 17:19:57.521289', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая на фоне однотонной черной стены. Ее волосы гладко зачесаны назад. На ней надет белый жакет с широкими лацканами и одной пуговицей. Под жакетом видна тонкая золотая цепочка на шее. В ушах надеты золотые серьги.На женщину падает сценический свет, создающий круглый светлый участок на стене за ее спиной и выделяющий ее фигуру. Нижняя часть тела скрыта, но видны верхние части брюк черного цвета. Без очков", "operation": "gen-multi-input"}', 'ywhav5d9ydrme0csya58jh8am4', 'failed', '{"date": 1760710792, "chatId": 1287537311, "messageId": 110371}', '{"date": 1760710796, "chatId": 1287537311, "messageId": 110376}', '[{"date": 1760710796, "chatId": 1287537311, "messageId": 110376}]');
INSERT INTO public.operations VALUES ('90761b30-4237-425d-a53d-de19d848ad1d', '2025-10-17 17:16:35.109668', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай портрет женщины в черно-белом стиле, лежащей на полу с упором на изысканный корсет.\nФон серый пол серый темный . Женщина в черном корсете, длинной юбке и перчатках с узорами. Она тянется рукой к огромной широкой хрустальной люстре, которая висит низко, почти касаясь пола. Люстра выполнена из хрусталя, с множеством кристаллов и свечей, которые ярко освещают сцену. Женщина смотрит на люстру с выражением восхищения и концентрации.\nОсвещение - контрастное, мягкое, с акцентом на её фигуру и детали люстры. Люстра прорабатывается в 4К-качестве, с четкими текстурами и рябью в свете, создавая атмосферу кинематографичного напряжения. Используй кинематографическое освещение, с глубокими тенями и высокой детализации. Не меняй черты, фото по пояс", "operation": "gen-multi-input"}', '505f3h4jwsrmc0csya3sg2vy9m', 'succeeded', '{"date": 1760710583, "chatId": 1287537311, "messageId": 110354}', '{"date": 1760710594, "chatId": 1287537311, "messageId": 110359}', '[{"date": 1760710605, "chatId": 1287537311, "messageId": 110360}]');
