INSERT INTO public.operations VALUES ('e53b6621-b646-4d56-85a5-5057f7af262c', '2025-10-17 17:20:35.946826', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Изображение представляет собой чёрно-белую фотографию, на которой изображена женщина в облегающем чёрном платье без рукавов. Она стоит, закинув руки над головой приподнимая волнистые волосы, с слегка склоненной головой. Ее волосы волнисты и распущены и ниспадают на плечи. На шее у нее тонкая цепочка.За ней видна размытая тень ее же в похожей позе, но с закрытыми глазами и руками, поднятыми над головой.Свет падает на нее таким образом, что подчеркивает контуры ее тела и создает контраст между светлыми и темными участками фотографии. Фон неровный, с переходом от более светлых тонов к более темным.", "operation": "gen-multi-input"}', '7q353bt045rm80csya5s7pr3zm', 'succeeded', '{"date": 1760710831, "chatId": 1287537311, "messageId": 110379}', '{"date": 1760710834, "chatId": 1287537311, "messageId": 110384}', '[{"date": 1760710846, "chatId": 1287537311, "messageId": 110385}]');
