INSERT INTO public.operations VALUES ('10a08209-35c0-4517-85ad-9c7f2cb8c85c', '2025-10-17 17:38:19.239209', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении представлена фотография женщины, выполненная в стиле двойной экспозиции.Слева в профиль изображена женщина с темными волосами, собранными в пучок, и серьгой-каффом на ухе. Она одета в топ с глубоким вырезом. Рядом с ней видна размытая кисть руки.Правая сторона изображения показывает полупрозрачное лицо женщины крупным планом, глаза закрыты, и есть блик на губах. Фон белый. У девушки черный корсет", "operation": "gen-multi-input"}', '2s041vbs79rma0csyadvpn5rdc', 'failed', '{"date": 1760711887, "chatId": 1287537311, "messageId": 110472}', '{"date": 1760711897, "chatId": 1287537311, "messageId": 110477}', '[{"date": 1760711897, "chatId": 1287537311, "messageId": 110477}]');
