INSERT INTO public.operations VALUES ('d783345f-23f7-4d4d-8b78-f4b537546ffa', '2025-10-17 17:44:55.641713', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении представлен портрет молодой женщины с темными волосами, собранными в высокий пучок. У нее гладкая кожа с контурингом, подчеркивающим скулы. Брови четко очерчены и уложены. У нее карие глаза с темной подводкой и длинными ресницами. Губы полные, с нежно-розовым оттенком.На ушах у женщины крупные золотые серьги. Руки сложены вместе, опираются на что-то. Ногти покрашены нежно-розовым лаком.Фон нейтральный, светло-серый. Освещение мягкое и равномерное, подчеркивающее черты лица модели.", "operation": "gen-multi-input"}', '1v4dk0w5mxrm80csyagr28y9c0', 'succeeded', '{"date": 1760712290, "chatId": 1287537311, "messageId": 110523}', '{"date": 1760712294, "chatId": 1287537311, "messageId": 110528}', '[{"date": 1760712305, "chatId": 1287537311, "messageId": 110529}]');
INSERT INTO public.operations VALUES ('85753562-db41-4eee-8720-5958ed9f5a2b', '2025-10-17 17:45:45.912323', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении изображена девушка с длинными темными волосами, часть которых падает на её лицо. Она смотрит вправо от зрителя.Девушка подпирает голову рукой, на запястье у неё браслет. На другом запястье также виден край браслета. Губы девушки накрашены помадой нюдового оттенка.", "operation": "gen-multi-input"}', '22mag5ta8hrma0csyahbxg3q0r', 'succeeded', '{"date": 1760712340, "chatId": 1287537311, "messageId": 110530}', '{"date": 1760712344, "chatId": 1287537311, "messageId": 110535}', '[{"date": 1760712358, "chatId": 1287537311, "messageId": 110536}]');
