INSERT INTO public.operations VALUES ('4df7f65a-3a75-4e05-8d7a-b6bff8ea81cc', '2025-10-17 17:46:50.206346', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении крупный план лица женщины. У нее светлая кожа, выразительные брови и длинные ресницы. Ее глаза карие. На ней нанесено макияж, подчеркивающий ее черты лица. Она держит руку в черной прозрачной перчатке у лица, закрывая часть своего лба. Ее пальцы касаются губ, обнажая белые зубы. В ухе у нее большая, многоуровневая серьга, украшенная блестящими камнями. Фон имеет теплый, нейтральный оттенок.", "operation": "gen-multi-input"}', 'gmdqrzj5d9rme0csyahr5rq3zm', 'succeeded', '{"date": 1760712388, "chatId": 1287537311, "messageId": 110537}', '{"date": 1760712391, "chatId": 1287537311, "messageId": 110542}', '[{"date": 1760712420, "chatId": 1287537311, "messageId": 110547}]');
