INSERT INTO public.operations VALUES ('3fdeffb4-82be-4906-a367-d5279838a74d', '2025-10-17 17:52:58.530286', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении крупный план лица женщины. У нее темная кожа, выразительные брови . Ее глаза карие. На ней нанесено легкий макияж, подчеркивающий ее черты лица. Она держит одну руку в черной прозрачной перчатке у лица, закрывая часть своего лба. Ее пальцы другой руки касаются губ, . В ухе  серьга, украшенная блестящими камнями. Фон имеет теплый, нейтральный оттенок. У нее черные прямые длинные волосы, качество фото представляет собой более естественное фото", "operation": "gen-multi-input"}', '92f8j7z4e9rm80csyam81gzy1c', 'succeeded', '{"date": 1760712773, "chatId": 1287537311, "messageId": 110576}', '{"date": 1760712777, "chatId": 1287537311, "messageId": 110581}', '[{"date": 1760712789, "chatId": 1287537311, "messageId": 110582}]');
