INSERT INTO public.operations VALUES ('af16332c-0a06-4574-81e1-99e3cd0cd4f3', '2025-10-28 14:51:55.280947', false, 6817359783, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_QRpAAGuPpmsjPdx1E2BR2zs_mjfYHwAAoz4MRvUfAABSNAGTXnI9-48AQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Сделайте чрезвычайно обычное и ничем не примечательное селфи на iPhone, без четкого предмета или чувства композиции. Просто быстрый случайный снимок. На фотографии небольшое размытие в движении и неравномерное освещение от уличных фонарей или внутренних ламп, что приводит к легкой передержке в некоторых областях. Угол неудобный, а обрамление грязное, что придает картине преднамеренно посредственное чувство, как будто это было принято рассеянно, пока вытаскивание телефона из кармана. Главный герой - [лицо человека на фото,которое я скинул), и (Егор Крид) стоит рядом с ним, оба пойманы в случайный, несовершенный момент. Фон показывает оживленную Таймс-сквер ночью, мимо которой проходят неоновые огни, пробки и размытые фигуры. Общий вид намеренно простой и случайный, запечатлевший аутентичную атмосферу плохо составленного спонтанного селфи на iPhone", "operation": "gen-multi-input"}', 'bs3haf8n75rma0ct5amsk82n0r', 'succeeded', '{"date": 1761652286, "chatId": 1092362431, "messageId": 130308}', '{"date": 1761652312, "chatId": 1092362431, "messageId": 130320}', '[{"date": 1761652326, "chatId": 1092362431, "messageId": 130321}]');
