INSERT INTO public.operations VALUES ('425f9990-0601-4789-be31-7dab74d222ec', '2025-10-17 17:59:53.865579', false, 9163800988, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsAdo8llnwZiH1BAYhZn9H3aS-TdJ3AACUfoxG5TfkEt9ZKYWKM54PgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Конечно, вот перевод:\n\nДизайн персонажа в узнаваемом стиле стоп-моушен студии Laika из фильма «Коралина». Персонаж должен обладать характерной кукольной эстетикой: ручной работой, текстурными волосами и кожей, слегка асимметричными чертами и очень большими выразительными глазами, которые заменены на блестящие чёрные пуговицы. Настроение — причудливое, но загадочное, с лёгкой долей мрачности. Освещение драматичное, с использованием глубоких теней и насыщенных цветов, похоже на фильм Тима Бёртона, но с уникальным почерком Laika.", "operation": "gen-multi-input"}', '38s1rg1tphrma0csyaqt01md5w', 'succeeded', '{"date": 1760713063, "chatId": 1618507681, "messageId": 110599}', '{"date": 1760713182, "chatId": 1618507681, "messageId": 110602}', '[{"date": 1760713206, "chatId": 1618507681, "messageId": 110603}]');
INSERT INTO public.operations VALUES ('c0c046fa-8711-48f1-a7e7-19f708ed7127', '2025-10-17 18:14:01.305225', false, 9163800988, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsAxo8l0KcZwwON27uIqHRN4Pt4WvIQACaPoxG5TfkEtUqj_-UsaukAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1252}], "prompt": "Стиль Тима Бёртона из \"Трупа невесты\", портрет персонажа, готическая стоп-моушен анимация. У персонажа стройное телосложение, очень длинные тонкие конечности, бледная серо-голубая кожа, большие выразительные глаза с меланхоличным взглядом и тёмные глазницы. Стиль — элегантно-потрёпанный, с цветовой палитрой из тёмных синих, фиолетовых и серых тонов. Атмосфера поэтичная, меланхоличная и мрачно-романтичная.", "operation": "gen-multi-input"}', 'e0yxw5990drmc0csyaybvkf1vw', 'succeeded', '{"date": 1760713994, "chatId": 1618507681, "messageId": 110604}', '{"date": 1760714038, "chatId": 1618507681, "messageId": 110611}', '[{"date": 1760714055, "chatId": 1618507681, "messageId": 110612}]');
