INSERT INTO public.operations VALUES ('4db0eb35-a9c7-4c3e-bb52-05cfab1def39', '2025-10-17 18:18:14.290905', false, 3007085081, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsB9o8l3oYIbIsH_KFYKiAAGV-Pj74gADJvwxG7yukUv8ai4CupecjQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 850, "heightPx": 1280}], "prompt": "Дизайн персонажа в узнаваемом стиле кукол Monster High. Персонаж — это модная ученица-монстр со стилизованной мультяшной внешностью: большая голова, очень большие блестящие глаза, маленький нос, стройное тело с чрезвычайно длинными и тонкими конечностями и драматичным макияжем. Стиль — «Готический Шик» — смесь панк, готической и гламурной моды с использованием яркой цветовой палитры. Наряд — дерзкий и трендовый, усыпанный уникальными аксессуарами и деталями. Персонаж должен выглядеть уверенно и дерзко.", "operation": "gen-multi-input"}', 'z3xk1cg51drmc0csyb0brevskr', 'succeeded', '{"date": 1760714267, "chatId": 8406578172, "messageId": 110632}', '{"date": 1760714292, "chatId": 8406578172, "messageId": 110639}', '[{"date": 1760714305, "chatId": 8406578172, "messageId": 110640}]');
