INSERT INTO public.operations VALUES ('10f3bc3b-d80f-4809-98b4-5ddab8227550', '2025-10-18 00:31:51.120434', false, 2260104030, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsXxo8rW7y_7iPG7_EvsxqdX_6os13wAC1v0xG5iTmEvkOLr6R8csdAEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1008, "heightPx": 1792}, {"file": {"fileId": "AgACAgIAAxkBAAEBsX1o8rW75stmwP8gmF8uDrsLPELZMQAC1_0xG5iTmEs-a5EINXC7sgEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 778, "heightPx": 2286}], "prompt": "Make the image of the two people look like it was taken with a Polaroid camera.\nThere should be no obvious objects or props. It should look like a random shot taken by chance. The image should look like a snapshot that doesn''t attract much attention.\nAdd a slight motion blur and camera flash light to the dark area to distribute it evenly throughout the photo. Avoid distorting the face. Replace the background behind the two people with a white curtain. The guy embraces the girl and their hands are locked together", "operation": "gen-multi-input"}', 'e3njmg8ke9rm80csygbaswf074', 'succeeded', '{"date": 1760736699, "chatId": 8166317868, "messageId": 110972}', '{"date": 1760736706, "chatId": 8166317868, "messageId": 110976}', '[{"date": 1760736724, "chatId": 8166317868, "messageId": 110977}]');
