INSERT INTO public.operations VALUES ('970cfbb0-24bc-4e5f-9d4a-64c99164a516', '2025-10-18 14:18:23.458579', false, 9990176979, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBswxo83Z_e-Snvv5Cm-YrjR19JF3cQAACxxkyG5HniUv1XgNTHCKDlAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 852, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBswdo83WKjxj87F6bImllKnXLRDKZBwAC4vUxGwKgmEtgAtK64giq5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 974, "heightPx": 1280}], "prompt": "Соедините две фотографии в одну \nПарень одет а черную водолазку, бежевые брюки, среднее телосложения, сильные руки. \nДевушка одета в пиджак оверсайз \nВолосы у девушке корни светло русые, кончики светлые \nВолнистые средней длины \nПарень обнимает её за талию \nЦелует голову. \nДевушка прижалась к его груди  \nФон Осенний парк\n\nЛица не меняете\nОни должны быть походы как на оригинальном фотографии", "operation": "gen-multi-input"}', '61gcndeamnrmc0csyw5bwk8w4r', 'succeeded', '{"date": 1760786266, "chatId": 1354365446, "messageId": 111378}', '{"date": 1760786301, "chatId": 1354365446, "messageId": 111382}', '[{"date": 1760786315, "chatId": 1354365446, "messageId": 111383}]');
INSERT INTO public.operations VALUES ('baa1beab-e054-416d-978e-39194383d0e5', '2025-10-18 15:06:43.137753', false, 2225223347, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBsyto84LNtsaMO-3t0oggHZY-RK7oxQACt_kxG91AmUsVYJuWkTIEvAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 549, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBsyxo84LNDpV_4_YgSm23wo9LN5n7dQACuPkxG91AmUu1rKvP2HKaDgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 514, "heightPx": 1280}], "prompt": "Make the image of the two people look like it was taken with a Polaroid camera.\nThere should be no obvious objects or props. It should look like a random shot taken by chance. The image should look like a snapshot that doesn''t attract much attention.\nAdd a slight motion blur and camera flash light to the dark area to distribute it evenly throughout the photo. Avoid distorting the face. Replace the background behind the two people with a white curtain. The guy embraces the girl and their hands are locked together", "operation": "gen-multi-input"}', 'j6w5fk09xxrmc0csywvsp44vgg', 'succeeded', '{"date": 1760789197, "chatId": 5000381505, "messageId": 111403}', '{"date": 1760789201, "chatId": 5000381505, "messageId": 111407}', '[{"date": 1760789219, "chatId": 5000381505, "messageId": 111408}]');
