INSERT INTO public.operations VALUES ('8e525bc3-d88b-4852-9957-61d87c4dc8ff', '2025-10-18 15:34:05.276702', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении женщина лежит на полу, опираясь на правую руку, левой рукой держит шубу. Она одета в черную шубу с открытыми плечами и черные кружевные колготки. У нее темные длинные волосы слегка вьются и свободно лежат на плечах. Пол серого цвета, стена за ней белая. Она смотрит в камеру.", "operation": "gen-multi-input"}', 'en3jecrr09rme0csyx894jftvg', 'succeeded', '{"date": 1760790837, "chatId": 1287537311, "messageId": 111493}', '{"date": 1760790841, "chatId": 1287537311, "messageId": 111498}', '[{"date": 1760790864, "chatId": 1287537311, "messageId": 111501}]');
