INSERT INTO public.operations VALUES ('09f46ddb-238e-4e08-9795-d15b942fa41b', '2025-10-18 15:12:38.554007', false, 2225223347, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBszdo84QxlbfiBQFxQCwEgNVESiDQNwACw_kxG91AmUvkTdDiAsC-MQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 581, "heightPx": 810}, {"file": {"fileId": "AgACAgIAAxkBAAEBszho84Qxfyif1oXqwCMDyLyb0uODVwACxPkxG91AmUvK-SwFNIcvfwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 460, "heightPx": 1280}], "prompt": "Make the image of the two people look like it was taken with a Polaroid camera.\nThere should be no obvious objects or props. It should look like a random shot taken by chance. The image should look like a snapshot that doesn''t attract much attention.\nAdd a slight motion blur and camera flash light to the dark area to distribute it evenly throughout the photo. Avoid distorting the face. Replace the background behind the two people with a white curtain. The guy embraces the girl and their hands are locked together", "operation": "gen-multi-input"}', 'bjnx8rknznrmc0csywy8bjd2hm', 'succeeded', '{"date": 1760789553, "chatId": 5000381505, "messageId": 111415}', '{"date": 1760789556, "chatId": 5000381505, "messageId": 111419}', '[{"date": 1760789572, "chatId": 5000381505, "messageId": 111420}]');
INSERT INTO public.operations VALUES ('c6b3311d-da10-412b-bfc6-5e9315bc85aa', '2025-10-25 22:46:14.036156', false, 4786523001, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7ido_Sjzyy3AuaJqjT5as5jIqeBYYAACuPoxG3We8UusxOztMEm_oAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "Создай изображение нас. Максимально сохрани нашу внешность. Ультрареалистичный портрет молодой пары, мужчины и девушки, в романтическом моменте на улице: мужчина в тёмной куртке и джинсах, целует девушку в щёку, находясь справа от неё. Девушка с волнистыми волосами, одета в тёмное пальто и белые джинсы. Они держатся за руки, глаза у обоих закрыты, выражая нежные чувства. Пара смещена влево от центра кадра. Фон размытый, с деревьями и городской архитектурой, создающий ощущение осеннего города, мягко отражающий приглушённые тёмные и землистые оттенки. Освещение естественное, мягкое, как в пасмурный день, подчёркивающее интимность сцены и натуральные цвета. Стиль фотографии — современный, с акцентом на эмоции, естественность, гармонию и теплоту момента, средний план, с фокусом на лицах и руках пары.", "operation": "gen-multi-input"}', '0m0jxza0snrma0ct3km8f3dzxw', 'succeeded', '{"date": 1761421555, "chatId": 7884764133, "messageId": 126503}', '{"date": 1761421570, "chatId": 7884764133, "messageId": 126508}', '[{"date": 1761421584, "chatId": 7884764133, "messageId": 126509}]');
INSERT INTO public.operations VALUES ('adb88481-08db-4dcb-bea1-8f6bcdd0d97f', '2025-10-25 22:47:07.201297', false, 4786523001, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7ido_Sjzyy3AuaJqjT5as5jIqeBYYAACuPoxG3We8UusxOztMEm_oAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "Создай изображение нас. Максимально сохрани нашу внешность. Пара обнимается и целуется на фоне дома, увитого плющом. Мужчина одет в черную куртку. Девушка с собранными волосами, в белом пальто и чёрном обтягивающем коротком платье. Они находятся в центре кадра, лица соприкасаются в поцелуе. Рука девушки без пальто, пальто просто накинуто на плечи. Фон – дом, покрытый густой зеленью и местами красными листьями, создающий осеннюю атмосферу. Погода пасмурная, небо серое, что подчеркивает мягкое освещение. Композиция вертикальная, с размытым фоном, фокусирующим внимание на паре. Свет рассеянный, создаёт мягкие тени и объем. Общая атмосфера романтическая и спокойная. Внизу слева видна часть припаркованной машины. Съемка в стиле fashion-art 2025 года, как на Canon EOS R6 с объективом RF 50mm f/1.2L, f/2.0, ISO 100, выдержка 1/500. Мягкий рассеянный свет акцентирует лица и детали одежды. Постобработка реалистичная, легкий пастельный или глянцевый эффект, без перебора. Внимание к композиции, деталям листьев, текстуре ткани и коже. 4KHD, реалистичные цвета, четкий фокус, без размытия.", "operation": "gen-multi-input"}', 'kc9p6j8g0xrme0ct3kmsdahayr', 'succeeded', '{"date": 1761421619, "chatId": 7884764133, "messageId": 126510}', '{"date": 1761421624, "chatId": 7884764133, "messageId": 126515}', '[{"date": 1761421638, "chatId": 7884764133, "messageId": 126516}]');
