INSERT INTO public.operations VALUES ('6e13dad2-9a16-4844-9edc-2b236054d72b', '2025-10-18 15:24:12.42115', false, 9794753397, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "3:4"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBs0lo84ZqRAGaiCAeKhTSAtSEA5Ii1QACr_8xG7kDoEsktC2bQ19AeQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBs0ho84Zq7HElMWM7Et9FA8HkxxDLggACrv8xG7kDoEuUN-GrA0MP1wEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 480}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки и парня не изменять чтобы была в точь точь", "operation": "gen-multi-input"}', '3a6bd60c8xrm80csyx3s24e0hm', 'succeeded', '{"date": 1760790235, "chatId": 1343186491, "messageId": 111448}', '{"date": 1760790239, "chatId": 1343186491, "messageId": 111452}', '[{"date": 1760790261, "chatId": 1343186491, "messageId": 111453}]');
