INSERT INTO public.operations VALUES ('3d399b6a-8b91-4426-8209-b4713672d31b', '2025-10-18 15:36:27.700232', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении женщина лежит на полу, опираясь на левую руку, правой рукой держит шубу. Она одета в черную шубу с открытыми плечами и черные кружевные колготки. У нее темные длинные волосы слегка вьются и свободно лежат на плечах. Пол серого цвета, стена за ней белая. Она смотрит в камеру.", "operation": "gen-multi-input"}', '11krwc24dhrme0csyx9avdfm14', 'failed', '{"date": 1760790960, "chatId": 1287537311, "messageId": 111518}', '{"date": 1760790984, "chatId": 1287537311, "messageId": 111523}', '[{"date": 1760790984, "chatId": 1287537311, "messageId": 111523}]');
INSERT INTO public.operations VALUES ('3cdab69b-ac52-41c5-93a3-3c2f9771a8e7', '2025-10-18 15:24:40.052063', false, 9794753397, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBs0ho84Zq7HElMWM7Et9FA8HkxxDLggACrv8xG7kDoEuUN-GrA0MP1wEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 480}, {"file": {"fileId": "AgACAgIAAxkBAAEBs0lo84ZqRAGaiCAeKhTSAtSEA5Ii1QACr_8xG7kDoEsktC2bQ19AeQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности\n\nВнешность девушки и парня не изменять чтобы была в точь точь", "operation": "gen-multi-input"}', 'gz7e8rvrcnrma0csyx3rgc9t7w', 'succeeded', '{"date": 1760790275, "chatId": 1343186491, "messageId": 111454}', '{"date": 1760790278, "chatId": 1343186491, "messageId": 111458}', '[{"date": 1760790292, "chatId": 1343186491, "messageId": 111459}]');
