INSERT INTO public.operations VALUES ('1d735432-fb2e-45ec-80c3-dc6eb283faa9', '2025-10-18 15:39:56.117956', false, 5013320058, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении женщина лежит на полу, опираясь на левую руку, правой рукой держит шубу. Она одета в черную шубу с открытыми плечами и черные кружевные колготки. У нее темные длинные волосы слегка вьются и свободно лежат на плечах. Пол серого цвета, стена за ней белая. Она смотрит в камеру.", "operation": "gen-multi-input"}', '5ffwhsbjwnrma0csyxas4nmdtg', 'succeeded', '{"date": 1760791174, "chatId": 1287537311, "messageId": 111548}', '{"date": 1760791180, "chatId": 1287537311, "messageId": 111553}', '[{"date": 1760791204, "chatId": 1287537311, "messageId": 111554}]');
