INSERT INTO public.operations VALUES ('2e0901d0-86eb-4f4d-955c-4493067058a1', '2025-10-25 22:48:58.789281', false, 4786523001, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7jVo_SmQ_nS06YNL8DRrYwAB1FSQlfgAArr6MRt1nvFLQz795LHhD9EBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 648, "heightPx": 1152}], "prompt": "Создай изображение меня. Максимально сохрани мою внешность. Мужчина сидит в студии на высоком стуле, тело слегка повернуто в сторону, взгляд прямой в камеру. На нем темная рубашка с высоким воротом. Свет направлен сбоку, создавая резкие тени на одной половине лица и мягкие блики на другой. Фон черный с легкой дымкой, чтобы усилить глубину. Атмосфера драматичная и стильная. Съемка в стиле fashion-art 2025 года, Canon EOS R6, RF 85mm f/1.4, f/2.0, ISO 100, выдержка 1/500. Постобработка реалистичная, легкий глянец на коже, внимание к теням и текстуре ткани. 8K, четкий фокус, кинематографическое качество.", "operation": "gen-multi-input"}', 'f1dqer63z1rme0ct3kna0gqqj4', 'succeeded', '{"date": 1761421712, "chatId": 7884764133, "messageId": 126517}', '{"date": 1761421736, "chatId": 7884764133, "messageId": 126522}', '[{"date": 1761421750, "chatId": 7884764133, "messageId": 126523}]');
