INSERT INTO public.operations VALUES ('0f57c070-066e-40d3-a442-1f99f6577cbb', '2025-10-18 17:25:52.145762', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы уложены волнами, они объемны и они ниспадают на плечи. На ней надето несколько золотых украшений: кольцо на пальце, серьги-кольца в ушах, тонкая цепочка на шее и два браслета на запястье. Она смотрит в сторону от камеры, касаясь лица рукой. У неё маникюр в светлых тонах. Фон изображения - серый. Плечи обнажены.", "operation": "gen-multi-input"}', 'yg9sbpvf6xrm80csyyva9km2nc', 'succeeded', '{"date": 1760797508, "chatId": 1287537311, "messageId": 111636}', '{"date": 1760797550, "chatId": 1287537311, "messageId": 111641}', '[{"date": 1760797562, "chatId": 1287537311, "messageId": 111642}]');
