INSERT INTO public.operations VALUES ('a90469a2-a03d-434e-8235-fe74acdd8e1a', '2025-10-18 17:28:42.149193', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы уложены волнами, они объемны и они ниспадают на плечи. На ней надето несколько золотых украшений: кольцо на пальце, серьги-кольца в ушах, тонкая цепочка на шее и два браслета на запястье. Она смотрит в сторону от камеры, касаясь лица рукой. У неё маникюр в светлых тонах. Фон изображения - черный. Плечи обнажены.", "operation": "gen-multi-input"}', 'shpq05r7h5rma0csyywsfv19n0', 'succeeded', '{"date": 1760797691, "chatId": 1287537311, "messageId": 111669}', '{"date": 1760797694, "chatId": 1287537311, "messageId": 111674}', '[{"date": 1760797733, "chatId": 1287537311, "messageId": 111681}]');
INSERT INTO public.operations VALUES ('5aebe805-7a90-47b6-824a-fb71cf1ed161', '2025-10-18 17:30:02.061082', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtEZo86RPNfbP4WKdQ1G7-MtGNKtjoAACg_UxGw9WoUvdfZCcjVj8CgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "Изображение в черно-белых тонах. В центре кадра находится женщина, сидящая на полу. Она одета в чулки, короткие шорты и топ без бретелек. Поверх топа на ней надета меховая накидка. В правой руке она держит туфлю на высоком каблуке.Волосы у женщины длинные и вьющиеся, уложены волнами. Она смотрит прямо в камеру. На заднем плане виден однотонный светлый фон. Слева внизу видна вторая туфля. В правом нижнем углу изображения располагается круглый значок с символом лупы со стрелкой по кругу.", "operation": "gen-multi-input"}', '5nx3v89zj9rm80csyyx9kxdsd8', 'succeeded', '{"date": 1760797775, "chatId": 991429758, "messageId": 111686}', '{"date": 1760797795, "chatId": 991429758, "messageId": 111695}', '[{"date": 1760797812, "chatId": 991429758, "messageId": 111700}]');
