INSERT INTO public.operations VALUES ('f67fdcdd-7557-413c-9765-208b0d1f8a55', '2025-10-18 17:31:22.60808', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы черные, длинные, уложены волнами, они объемны и они ниспадают на плечи. На ней надето несколько золотых украшений: кольцо на пальце, серьги-кольца в ушах, тонкая цепочка на шее и два браслета на запястье. Она смотрит в сторону от камеры, касаясь лица рукой. У неё маникюр в светлых тонах. Фон изображения - черный. Плечи обнажены.", "operation": "gen-multi-input"}', 'd5wydmvss5rma0csyyxtkpvfaw', 'succeeded', '{"date": 1760797852, "chatId": 1287537311, "messageId": 111705}', '{"date": 1760797881, "chatId": 1287537311, "messageId": 111714}', '[{"date": 1760797892, "chatId": 1287537311, "messageId": 111717}]');
INSERT INTO public.operations VALUES ('8480a6d8-407f-461d-bc71-7622003eecd3', '2025-10-26 00:05:02.721395', false, 9258734518, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7m5o_TtwaSQF0Ryhe3OCAtepgtNN6AACWwABMhs_d_BLZPPOpH4Fqh8BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1147, "heightPx": 1280}], "prompt": "Создай изображение меня. Максимально сохрани мою внешность. Спокойный и элегантный портрет девушки с длинными волнистыми волосами, сидящей по-турецки на светлом полу. Она в уютном белом вязаном свитере, белых шортах и высоких носках, держит маленький аккуратно упакованный белый подарок, взгляд мягкий, слегка в сторону. За ней стоит роскошная рождественская ёлка с белыми и золотыми украшениями и тёплыми огнями, окружённая множеством красиво упакованных подарков. Свет — мягкий золотой час, с лёгкими контровыми бликами на волосах, коже и ткани, создающий ощущение уюта и роскоши. Постобработка — пастельные и глянцевые акценты на коже, ткани и огоньках ёлки, 4KHD, фокус на лице, реалистичные цвета, мягкая глубина кадра.", "operation": "gen-multi-input"}', '680kbjb8rsrme0ct3mr8kdxk6g', 'succeeded', '{"date": 1761426289, "chatId": 1116763222, "messageId": 126574}', '{"date": 1761426299, "chatId": 1116763222, "messageId": 126579}', '[{"date": 1761426315, "chatId": 1116763222, "messageId": 126580}]');
INSERT INTO public.operations VALUES ('6736d11b-b77b-4e08-b8e0-32ceaf4b0f21', '2025-10-18 17:31:38.571088', false, 2783754515, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtGNo86S_3vXn6ou-GHmrDLjmw-HFFwACeQkyG3UMoUsLusjUetmc4AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 963, "heightPx": 1280}], "prompt": "Сделай на фоне зиму", "operation": "gen-multi-input"}', 'aw9x37xr2drme0csyyxrdrmgx0', 'succeeded', '{"date": 1760797887, "chatId": 5100791210, "messageId": 111715}', '{"date": 1760797896, "chatId": 5100791210, "messageId": 111719}', '[{"date": 1760797908, "chatId": 5100791210, "messageId": 111724}]');
INSERT INTO public.operations VALUES ('b4fca0aa-fa33-4b99-b373-9491b1a99bbc', '2025-10-18 17:31:39.527333', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtF9o86SeX-XjTERJtjENIYpipeUAAcMAAov1MRsPVqFLHUjNzzrwepsBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "🐇 Сгенерировал фото:\nНа изображении женщина лежит на полу, опираясь на правую руку, левой рукой держит шубу. Она одета в черную шубу с открытыми плечами и черные кружевные колготки. У нее темные длинные волосы слегка вьются и свободно лежат на плечах. Пол серого цвета, стена за ней белая. Она смотрит в камеру.", "operation": "gen-multi-input"}', 'w1aq4rxvnxrm80csyyxr80mdpr', 'failed', '{"date": 1760797854, "chatId": 991429758, "messageId": 111711}', '{"date": 1760797897, "chatId": 991429758, "messageId": 111721}', '[{"date": 1760797897, "chatId": 991429758, "messageId": 111721}]');
