INSERT INTO public.operations VALUES ('0d51cc4a-587e-4611-8b66-8e6a8454e26b', '2025-10-28 17:11:23.410122', false, 6785298344, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_ahpAAHO-NhEJhJkSCQ4-CyV_PY7q9MAAhP-MRtSCwhISHKw9iCVzj4BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Добавь Путина на фото с охраной", "operation": "gen-multi-input"}', 'd16f2ty5adrmc0ct5cm8ypkwa8', 'succeeded', '{"date": 1761660664, "chatId": 899895756, "messageId": 130472}', '{"date": 1761660681, "chatId": 899895756, "messageId": 130475}', '[{"date": 1761660694, "chatId": 899895756, "messageId": 130476}]');
INSERT INTO public.operations VALUES ('1c0fec9f-f5c8-4c5d-b66b-ec8a88bf4d3e', '2025-10-26 00:07:29.512946', false, 9258734518, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB7nVo_TwHJcIEnCilfxKly_a57DprzgACXAABMhs_d_BLhLu7oJRRPCABAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 852, "heightPx": 1280}], "prompt": "Создай изображение нас, максимально сохрани нашу внешность. Мужчина нежно целует женщину в щеку, оба стоят под деревом на фоне золотого заката. Женщина одета в белое платье с открытыми плечами и волнистыми рукавами, ее глаза закрыты, а рука лежит на шее мужчины. Мужчина в белой футболке, его рука обнимает женщину. Задний план размыт, с золотистыми оттенками заходящего солнца, пробивающегося сквозь листву. Камера: Sony α7 III с объективом Sony FE 85mm f/1.8. Настройки: f/2.2, 1/320 сек, ISO 160. Естественное мягкое закатное освещение, создающее романтический ореол и теплый свет на лицах. Цветовая палитра очень теплая, с доминированием золотых, оранжевых и бежевых оттенков, подчеркивающих интимность момента. Постобработка для усиления мягкости света, легкой цветокоррекции для создания мечтательной и романтической атмосферы.", "operation": "gen-multi-input"}', '536xmrd609rmc0ct3msax80414', 'succeeded', '{"date": 1761426439, "chatId": 1116763222, "messageId": 126581}', '{"date": 1761426447, "chatId": 1116763222, "messageId": 126586}', '[{"date": 1761426462, "chatId": 1116763222, "messageId": 126587}]');
INSERT INTO public.operations VALUES ('4f6adb86-e0eb-464f-a758-2d8df17b568a', '2025-10-18 17:32:22.687418', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы черные, длинные, уложены волнами, они объемны и они ниспадают на плечи. На ней надето несколько золотых украшений: кольцо на пальце, серьги-кольца в ушах, тонкая цепочка на шее и два браслета на запястье. Она смотрит в сторону от камеры, касаясь лица рукой. У неё маникюр френч. Фон изображения - черный. Плечи обнажены.", "operation": "gen-multi-input"}', '86ypvc34gdrme0csyyy98ab098', 'succeeded', '{"date": 1760797925, "chatId": 1287537311, "messageId": 111729}', '{"date": 1760797941, "chatId": 1287537311, "messageId": 111734}', '[{"date": 1760797952, "chatId": 1287537311, "messageId": 111735}]');
