INSERT INTO public.operations VALUES ('7684efe2-d3ad-4e24-99a2-9db37460bdae', '2025-11-01 09:38:14.105798', false, 1654517396, 3, 0.003, '{"photo": {"file": {"fileId": "AgACAgQAAxkBAAECEa1pBarDOp7P08_a2j4zlP4xrmXPTAACTwtrGxsZMVC8qI4lj4IZBwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 828, "heightPx": 1054}, "operation": "remove-bg"}', '006eftjp55rge0ct7rhr117kq0', 'succeeded', '{"date": 1761979075, "chatId": 1714566697, "messageId": 135597}', '{"date": 1761979084, "chatId": 1714566697, "messageId": 135600}', '[{"date": 1761979098, "chatId": 1714566697, "messageId": 135601}]');
INSERT INTO public.operations VALUES ('501bbe43-69b2-45fd-9d95-cca756f8798c', '2025-10-18 17:43:00.830037', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу.\nГолова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой.\nМакияж: мягко очерченный - сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 c объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица", "operation": "gen-multi-input"}', 'wzen2a919xrm80csyz38fa0yrm', 'succeeded', '{"date": 1760798574, "chatId": 991429758, "messageId": 111832}', '{"date": 1760798579, "chatId": 991429758, "messageId": 111835}', '[{"date": 1760798592, "chatId": 991429758, "messageId": 111836}]');
INSERT INTO public.operations VALUES ('b8edff2c-e623-401a-8343-5b7bd0412ff0', '2025-10-18 17:41:57.604281', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении крупный план лица женщины. У нее темная кожа, выразительные брови . Ее глаза карие. На ней нанесено легкий макияж, подчеркивающий ее черты лица. Она держит одну руку в черной прозрачной перчатке у лица, закрывая часть своего лба. Ее пальцы другой руки касаются губ, . В ухе  серьга, украшенная блестящими камнями. Фон имеет теплый, нейтральный оттенок. У нее черные прямые длинные волосы, качество фото представляет собой более естественное фото", "operation": "gen-multi-input"}', '7apntrsa2xrma0csyz2rf1d1pg', 'succeeded', '{"date": 1760798511, "chatId": 991429758, "messageId": 111825}', '{"date": 1760798515, "chatId": 991429758, "messageId": 111828}', '[{"date": 1760798527, "chatId": 991429758, "messageId": 111829}]');
