INSERT INTO public.operations VALUES ('faff370b-a4e7-4918-9ea4-590ca68dbf0c', '2025-10-18 17:45:51.740742', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Изображение представляет собой черно-белую фотографию женщины, сидящей на полу на фоне светлой стены. Она одета в черные чулки, туфли на каблуках, темный топ без бретелек и темную шубу. Одна из туфель лежит на полу рядом с ее левой ногой, другую она держит в правой руке. У женщины длинные темные волосы, которые волнами спадают на плечи. Она смотрит прямо в камеру.", "operation": "gen-multi-input"}', 'xtmw4nxwt5rma0csyz4bzhzkt8', 'failed', '{"date": 1760798719, "chatId": 991429758, "messageId": 111850}', '{"date": 1760798749, "chatId": 991429758, "messageId": 111853}', '[{"date": 1760798749, "chatId": 991429758, "messageId": 111853}]');
