INSERT INTO public.operations VALUES ('2154d9f1-955d-4ebe-9558-2c6db09b1d27', '2025-10-18 17:47:57.943785', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, стоящая в воде. Она одета в черный раздельный купальник, трусы стринги. Ее темные волосы мокрые и зачесаны назад. Она стоит спиной к камере и смотрит назад через левое плечо.На заднем плане пляж с пальмами. Свет яркий, создается ощущение тропического климата.\nБез головных уборов", "operation": "gen-multi-input"}', 'pgtjkg5a2hrmc0csyz5974cpp0', 'succeeded', '{"date": 1760798872, "chatId": 991429758, "messageId": 111885}', '{"date": 1760798876, "chatId": 991429758, "messageId": 111890}', '[{"date": 1760798887, "chatId": 991429758, "messageId": 111891}]');
