INSERT INTO public.operations VALUES ('cabd3bd0-8312-4550-b7db-74e731b0ff2f', '2025-10-18 17:51:43.758576', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На изображении запечатлена женщина, стоящая у передней части автомобиля. Она одета в черное облегающее платье, поверх которого надет черный кожаный плащ, застегнутый на широкий пояс с круглой пряжкой. На шее у нее несколько золотых цепочек разной толщины и длины. На глазах у нее узкие прямоугольные солнцезащитные очки.В руке женщина держит сигарету, поднося ее ко рту. Ее волосы темные, слегка взъерошены. За ней видна часть автомобиля, а также деревянный дом с коричневой черепичной крышей. Рядом с домом растут кусты. На лобовом стекле машины видны размытые цифры и буквы, похожие на дату.", "operation": "gen-multi-input"}', '95mz030vwdrme0csyz7b2mkcqg', 'succeeded', '{"date": 1760799097, "chatId": 991429758, "messageId": 111946}', '{"date": 1760799101, "chatId": 991429758, "messageId": 111949}', '[{"date": 1760799114, "chatId": 991429758, "messageId": 111956}]');
