INSERT INTO public.operations VALUES ('a105c727-06c8-435a-af94-da288aae4f99', '2025-10-18 17:54:32.798333', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Женщина стоит в кадре, она запечатлена выше пояса, голова расположена по центру большого белого круглого фона. На ней облегающий топ-корсет со спущенными широкими лямками угольно-чёрного цвета — минималистичный и лаконичный по крою.\nОсанка женщины прямая и сдержанная, плечи расслаблены, локти мягко опираются на столешницу.\nГолова слегка наклонена, взгляд устремлён прямо в объектив с безмятежной, понимающей полуулыбкой.\nМакияж: мягко очерченный - сияющая основа, лёгкий румянец на щеках, серо-коричневые тени и увлажняющий нюдовый блеск на губах.\nОсвещение сияющее, исходит от фронтального источника красоты с мягким рассеиванием. Эффект глянцевого журнала. Снято на Canon EOS R5 c объективом RF 85mm f/1.2L. Атмосфера дорогого модного журнала, современная, перекликающаяся с редакционной портретной съёмкой. Не меняй черты лица", "operation": "gen-multi-input"}', 'y6wq12ng3hrm80csyz8assep3g', 'succeeded', '{"date": 1760799267, "chatId": 991429758, "messageId": 111978}', '{"date": 1760799271, "chatId": 991429758, "messageId": 111981}', '[{"date": 1760799284, "chatId": 991429758, "messageId": 111984}]');
