INSERT INTO public.operations VALUES ('e4823c30-8585-4b68-a8d1-4cde7de282b1', '2025-10-18 18:02:39.205771', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На фотографии изображена молодая женщина, сидящая на полу перед серой стеной. Свет падает на нее с левой стороны, создавая тень на стене за ней.У нее длинные темные волосы, которые частично закрывают ее глаза. На ней надета белая майка и голубые джинсы. На шее у нее несколько золотых цепочек разной длины.Женщина слегка надула губы. На ней также видны золотые серьги-кольца. Ее руки лежат на коленях.", "operation": "gen-multi-input"}', 'dx8hr9gw3drmc0csyzcbjzhd7r', 'succeeded', '{"date": 1760799754, "chatId": 1287537311, "messageId": 112040}', '{"date": 1760799758, "chatId": 1287537311, "messageId": 112045}', '[{"date": 1760799767, "chatId": 1287537311, "messageId": 112049}]');
