INSERT INTO public.operations VALUES ('1e295f7c-f598-40ce-ab90-172d96257576', '2025-10-18 18:06:14.646115', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "На изображении представлена молодая женщина с серными прямыми длинными волосами, уложенными сзади, создающий мокрый эффект. Она одета в простую белую футболку. Через футболку виден контур бюстгальтера.Лицо женщины обращено вправо от зрителя. У нее выразительные брови, большие карие глаза и полные губы. На ее лице виден легкий макияж, подчеркивающий черты лица.Фон за женщиной темно-серый или темно-синий. На нем виден фрагмент тени, падающий от какого-то объекта, находящегося за кадром. Свет падает на лицо женщины слева, создавая контраст между светлыми и темными участками.", "operation": "gen-multi-input"}', '4w30snb5vxrme0csyzdtwp9t14', 'succeeded', '{"date": 1760799921, "chatId": 1287537311, "messageId": 112071}', '{"date": 1760799972, "chatId": 1287537311, "messageId": 112082}', '[{"date": 1760799984, "chatId": 1287537311, "messageId": 112084}]');
