INSERT INTO public.operations VALUES ('d6a6600c-d0b5-4d4e-a697-fd1603189cd8', '2025-10-18 18:20:12.842524', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На фотографии изображена женщина с длинными темными волосами, сидящая в позе лотоса в воде. Она одета в облегающий черный комбинезон с глубоким V-образным вырезом и кружевными рукавами.Вода и небо за ней серого цвета, что создает туманную и таинственную атмосферу. Женщина смотрит прямо в камеру с серьезным выражением лица. Её руки сложены вместе на коленях. На поверхности воды видны отражения женщины и ее одежды.", "operation": "gen-multi-input"}', 'z5s9d29g6hrmc0csyzma03hyk0', 'succeeded', '{"date": 1760800806, "chatId": 991429758, "messageId": 112171}', '{"date": 1760800811, "chatId": 991429758, "messageId": 112174}', '[{"date": 1760800821, "chatId": 991429758, "messageId": 112179}]');
INSERT INTO public.operations VALUES ('bb517b8c-cd54-4a91-902e-f0da8859da5d', '2025-10-18 18:06:10.480086', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На изображении молодая женщина с длинными темными волосами, частично прикрывающими лицо. Её глаза закрыты. На ней светло-голубые джинсы с высокой талией и что-то вроде топа или накидки, сделанных из зеленых листьев и бордовых роз. Она держит букет бордовых роз, которые частично закрывают её грудь. Видна небольшая татуировка на животе. На пальце надето кольцо. Фон светлый, однотонный.", "operation": "gen-multi-input"}', '278t8yjnb1rma0csyzdv95at2c', 'succeeded', '{"date": 1760799964, "chatId": 991429758, "messageId": 112077}', '{"date": 1760799969, "chatId": 991429758, "messageId": 112080}', '[{"date": 1760799980, "chatId": 991429758, "messageId": 112083}]');
