INSERT INTO public.operations VALUES ('0de00a12-8032-43de-843a-6535e69a3539', '2025-10-18 18:13:29.99374', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На снимке изображена женщина, стоящая боком к камере. Она одета в черный блейзер и топ с глубоким вырезом. На шее у нее надет широкий чокер, украшенный блестящими камнями. На глазах у нее темные очки с тонкой металлической оправой.Волосы у женщины тёмные,волнистые.Она высунула язык. В правой руке она держит зажженную зажигалку. На пальце правой руки надето кольцо.Фон изображения – стена темно-серого цвета. Освещение приглушенное, создающее интимную атмосферу.", "operation": "gen-multi-input"}', '9vgdzd0ac5rmc0csyzh9xn3nkm', 'failed', '{"date": 1760800380, "chatId": 991429758, "messageId": 112141}', '{"date": 1760800408, "chatId": 991429758, "messageId": 112144}', '[{"date": 1760800408, "chatId": 991429758, "messageId": 112144}]');
