INSERT INTO public.operations VALUES ('036af81a-5454-47ec-9114-78231fb2ca7d', '2025-10-26 09:07:55.354381', false, 4934258254, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB78Jo_bqR2ijTWo0a6u1kAYYkKFrSugACrPAxG62c8EtdcNbh4rrATAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "В естественном ультро-высоком разрешении изображение девушки,сидящей на лавочке в осеннем парке,сфотографированой с боку на телефонн.Она сидит боком  к камере без вспышки .Вокруг нее осенние листья ,улица ночью,она сфотографированная со вспышкой .На ней длинный черный кожаный тренч ,черное короткое платье под ним ,черные колготки и сапоги высше колени на каблуке .Съемка случайная.Освешение должен быть мягким .Атмосфера уютная с легким зернистым эффектом.Не меняй черты лица", "operation": "gen-multi-input"}', '8kjhwhbcjdrme0ct3wgty7wnbc', 'succeeded', '{"date": 1761458833, "chatId": 5292579388, "messageId": 126914}', '{"date": 1761458853, "chatId": 5292579388, "messageId": 126919}', '[{"date": 1761458885, "chatId": 5292579388, "messageId": 126920}]');
