INSERT INTO public.operations VALUES ('1d362a1d-b91b-4759-bb49-592ca93bb618', '2025-10-18 18:14:04.131917', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На снимке изображена женщина, стоящая боком к камере. Она одета в черный блейзер и топ с глубоким вырезом. На шее у нее надет широкий чокер, украшенный блестящими камнями. На глазах у нее темные очки с тонкой металлической оправой.Волосы у женщины тёмные.Она высунула язык. В правой руке она держит зажженную зажигалку. На пальце правой руки надето кольцо.Фон изображения – стена темно-серого цвета. Освещение приглушенное, создающее интимную атмосферу.", "operation": "gen-multi-input"}', 'gp8vswcfjhrmc0csyzh81r0gfw', 'failed', '{"date": 1760800425, "chatId": 991429758, "messageId": 112147}', '{"date": 1760800443, "chatId": 991429758, "messageId": 112150}', '[{"date": 1760800443, "chatId": 991429758, "messageId": 112150}]');
