INSERT INTO public.operations VALUES ('82f5d704-ca8c-45f4-84fd-cb3dad318663', '2025-10-18 18:26:50.580808', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении девушка лежит на спине, повернувшись лицом к зрителю. У нее сигарета во рту, и она поджигает ее зажигалкой. Девушка одета в черное белье. На запястье левой руки надет черный браслет. На пальце левой руки кольцо. У девушки темные волосы и темные брови. Она смотрит вверх. Фон светлый, однотонный.", "operation": "gen-multi-input"}', 'kqc6fy223srm80csyzqb6nfe1g', 'failed', '{"date": 1760801107, "chatId": 991429758, "messageId": 112216}', '{"date": 1760801119, "chatId": 991429758, "messageId": 112219}', '[{"date": 1760801119, "chatId": 991429758, "messageId": 112219}]');
INSERT INTO public.operations VALUES ('46a11ae6-910d-4903-9163-91a5138db591', '2025-10-18 18:23:28.780585', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фотографии изображена женщина с длинными темными волосами, сидящая в позе лотоса в воде. Она одета в облегающий черный комбинезон с глубоким V-образным вырезом и кружевными рукавами.Вода и небо за ней серого цвета, что создает туманную и таинственную атмосферу. Женщина смотрит прямо в камеру с серьезным выражением лица. Её руки сложены вместе на коленях. На поверхности воды видны отражения женщины и ее одежды.", "operation": "gen-multi-input"}', '2x5k559dc1rm80csyznrq5qrfc', 'succeeded', '{"date": 1760801002, "chatId": 991429758, "messageId": 112202}', '{"date": 1760801007, "chatId": 991429758, "messageId": 112205}', '[{"date": 1760801019, "chatId": 991429758, "messageId": 112206}]');
INSERT INTO public.operations VALUES ('132a4264-9ac0-400a-be1e-1e7c548ed3e2', '2025-10-18 18:30:09.198698', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На фотографии изображена молодая женщина с темными волосами и карими глазами. Её волосы черные, длинные, уложены большими волнами, они объемны и они ниспадают на плечи. цепочка на шее. Она смотрит в сторону от камеры. Фон изображения - бежевый и на лицо попадает лучик солнца Плечи обнажены.", "operation": "gen-multi-input"}', '3ea091t9h9rme0csyzrrg2qw1m', 'succeeded', '{"date": 1760801403, "chatId": 991429758, "messageId": 112235}', '{"date": 1760801407, "chatId": 991429758, "messageId": 112238}', '[{"date": 1760801418, "chatId": 991429758, "messageId": 112239}]');
INSERT INTO public.operations VALUES ('23562e87-df55-48b5-91db-73f9fb807f9c', '2025-10-18 18:32:42.583286', false, 2783754515, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtnJo87Lle_l0FBQnc25osRztQcH8ngACPAoyG3UMoUtukDv9YpHtlgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Девушка должна висеть  на знаке дорожного движения", "operation": "gen-multi-input"}', '8b02kt50khrma0csyzss6ve4m8', 'succeeded', '{"date": 1760801509, "chatId": 5100791210, "messageId": 112242}', '{"date": 1760801560, "chatId": 5100791210, "messageId": 112245}', '[{"date": 1760801572, "chatId": 5100791210, "messageId": 112248}]');
INSERT INTO public.operations VALUES ('926773b7-5764-47f6-8b64-64ee74b84056', '2025-10-18 18:43:10.659122', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На изображении изображена женщина с длинными темными волосами, одетая в черное облегающее платье с открытыми плечами. Она стоит возле белой стены, а ее глаза закрыты. На шее у нее серебряная цепочка с небольшим кулоном в виде крестика.Над женщиной виден круглый светлый участок на стене, который является частью освещения. Тень от ее фигуры заметна на стене справа от нее. Ее руки сложены перед ней.", "operation": "gen-multi-input"}', 'a331zfhpmxrma0csyzyrt95kwc', 'succeeded', '{"date": 1760802173, "chatId": 991429758, "messageId": 112308}', '{"date": 1760802178, "chatId": 991429758, "messageId": 112311}', '[{"date": 1760802200, "chatId": 991429758, "messageId": 112312}]');
