INSERT INTO public.operations VALUES ('d56d326c-87ea-4b93-bf43-1d5430abca49', '2025-10-18 18:33:03.012704', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На изображении представлена молодая женщина с длинными темными волосами, уложенными так, что часть прядей обрамляет лицо. На волосах, у линии роста волос, видны маленькие стразы. У неё выразительный макияж, включающий интенсивные тени для век в оттенках красного и коричневого, подчеркнутые скулы и накрашенные губы.Женщина одета в черный комплект, который включает в себя тонкий топ-сетку и черные кожаные брюки. На руках у нее длинные черные полупрозрачные перчатки. Она сидит, поджав колени, и держит руки у лица.Фон светлый, почти белый, что позволяет сосредоточить внимание на фигуре женщины.", "operation": "gen-multi-input"}', '9sv2qgfgs1rma0csyzsr5xd20c', 'succeeded', '{"date": 1760801576, "chatId": 991429758, "messageId": 112249}', '{"date": 1760801581, "chatId": 991429758, "messageId": 112252}', '[{"date": 1760801592, "chatId": 991429758, "messageId": 112253}]');
