INSERT INTO public.operations VALUES ('19e7ecee-436b-4d2b-9543-f932a29d68d9', '2025-10-18 18:36:13.99359', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "На изображении запечатлена молодая женщина в модной одежде, позирующая на светло-сером фоне. Она одета в черный короткий топ, который открывает часть её живота. На ней надета объемная кожаная куртка темно-коричневого цвета, которая выглядит поношенной.На женщине надеты свободные джинсы светло-голубого цвета, с дырами на коленях. Джинсы спущены так, что видна верхняя часть её бедер. На ногах у неё черные ботинки на толстой подошве.Женщина стоит на одной ноге, согнув другую в колене и подняв её вверх. Обеими руками она подняла над головой, касаясь ими своих волос. У неё тёмные волосы, смуглая кожа и выразительные черты лица. Выражение лица спокойное.", "operation": "gen-multi-input"}', '5mndxh6tp1rma0csyzv9v4j6xc', 'failed', '{"date": 1760801767, "chatId": 991429758, "messageId": 112282}', '{"date": 1760801772, "chatId": 991429758, "messageId": 112285}', '[{"date": 1760801772, "chatId": 991429758, "messageId": 112285}]');
INSERT INTO public.operations VALUES ('c5f93ffb-cd01-4326-9aa2-bd5b1e88411a', '2025-10-18 18:35:41.166218', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtK1o86Zq4W_ghlctzN7FMDOSx4KB5QAClvUxGw9WoUu8Nl0jdKi3YAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении запечатлена молодая женщина в модной одежде, позирующая на светло-сером фоне. Она одета в черный короткий топ, который открывает часть её живота. На ней надета объемная кожаная куртка темно-коричневого цвета, которая выглядит поношенной.На женщине надеты свободные джинсы светло-голубого цвета, с дырами на коленях. Джинсы спущены так, что видна верхняя часть её бедер. На ногах у неё черные ботинки на толстой подошве.Женщина стоит на одной ноге, согнув другую в колене и подняв её вверх. Обеими руками она подняла над головой, касаясь ими своих волос. У неё тёмные волосы, смуглая кожа и выразительные черты лица. Выражение лица спокойное.", "operation": "gen-multi-input"}', 'kpq34ptt6srmc0csyzvavhrw44', 'succeeded', '{"date": 1760801735, "chatId": 991429758, "messageId": 112272}', '{"date": 1760801739, "chatId": 991429758, "messageId": 112275}', '[{"date": 1760801751, "chatId": 991429758, "messageId": 112276}]');
