INSERT INTO public.operations VALUES ('f9f789ae-193f-4313-9c1c-86c093d7c049', '2025-10-18 18:38:20.924985', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtUpo86l5BS9VBBQDC19XW0Zo3yu46AACr_UxGw9WoUtd0ZdsSNxKsgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 915}], "prompt": "Это черно-белое портретное фото молодой женщины. Она стоит, слегка повернувшись к зрителю, и смотрит прямо в камеру. Обе руки подняты и заведены за голову, кисти рук касаются затылка.На ней надето облегающее платье с длинными рукавами и высоким воротником-стойкой. Ткань платья имеет ребристую текстуру. Её длинные волнистые волосы ниспадают на плечи и грудь.У женщины правильные черты лица, светлая кожа, выразительные глаза и полные губы. В правом ухе видна маленькая серьга. Фон изображения однотонный, серый.", "operation": "gen-multi-input"}', 'nv9710panhrm80csyzw8x90hqg', 'succeeded', '{"date": 1760801894, "chatId": 991429758, "messageId": 112301}', '{"date": 1760801898, "chatId": 991429758, "messageId": 112304}', '[{"date": 1760801910, "chatId": 991429758, "messageId": 112305}]');
