INSERT INTO public.operations VALUES ('a58b8e58-a14a-4ebc-8309-c24fc3d8927a', '2025-10-18 18:52:27.631141', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtsdo87cMmUrCyDwtYdwAAci0zwMXsdYAAkL2MRsPVqFLu70v7g7prPkBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Изображение представляет собой фотографию девушки, сидящей на каменном постаменте. Она держит сигарету в руке и курит. Дым поднимается вверх от сигареты. На ней надет длинный кожаный плащ или пальто, черные колготки и блестящие ботинки на каблуке.Девушка сидит, закинув ногу на ногу. На заднем плане видны деревья и какая-то каменная структура, предположительно часть фонтана. У нее длинные волосы, распущенные по плечам. Ее взгляд направлен вниз.", "operation": "gen-multi-input"}', 'y6bqzcdnrnrma0csz02rz6g58g', 'succeeded', '{"date": 1760802708, "chatId": 991429758, "messageId": 112333}', '{"date": 1760802746, "chatId": 991429758, "messageId": 112336}', '[{"date": 1760802757, "chatId": 991429758, "messageId": 112337}]');
INSERT INTO public.operations VALUES ('f474c9b0-da4a-44a1-9330-5de3e0ae9fb4', '2025-10-18 18:47:40.195956', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBtsFo87aVVBU8CZZL2K6iKzWvoaEt4gACM_YxGw9WoUsdDBNUnY70TAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Изображена женщина в бюстье. Она стоит рядом со стеной, при этом одна её рука поднята вверх, а другая согнута и держит поднятую руку.У женщины длинные темные волосы, на шее массивная золотая цепь. На ней бюстье из черного материала, который выглядит как кожа, с прозрачной сетчатой тканью ниже. Видна золотая цепочка, которая проходит от бюстье к ее руке.Макияж женщины включает выразительные черные стрелки на глазах и нейтральный цвет губ. У нее также ухоженные ногти с легким блеском.", "operation": "gen-multi-input"}', 'wcxw8yajv9rma0csz00t6d52r8', 'failed', '{"date": 1760802453, "chatId": 991429758, "messageId": 112321}', '{"date": 1760802458, "chatId": 991429758, "messageId": 112324}', '[{"date": 1760802458, "chatId": 991429758, "messageId": 112324}]');
