INSERT INTO public.operations VALUES ('1488eea0-f3f9-4679-8e99-794f98398b55', '2025-10-26 11:24:19.23165', false, 6960361693, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB8Fho_dqX5DR5DheEK_FcvFTdZJclcQAC5voxGzSs8UtJn4A6Mff85AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Стоит рядом с Владом а4", "operation": "gen-multi-input"}', 'apvz57jd01rma0ct3yfajvmqmr', 'failed', '{"date": 1761467031, "chatId": 5991346679, "messageId": 127064}', '{"date": 1761467057, "chatId": 5991346679, "messageId": 127067}', '[{"date": 1761467057, "chatId": 5991346679, "messageId": 127067}]');
INSERT INTO public.operations VALUES ('0d02effb-2034-415a-8c7e-4e9fa3872d2f', '2025-10-18 18:55:40.745253', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBttto87hgpSIf45TJ-qgPakFU9ps11wACUPYxGw9WoUssOgowzp4fUQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении представлена молодая женщина, сидящая на табурете на фоне серой стены. На ней надета большая белая мужская рубашка, на ногах черные трусы и белые носки с логотипом Nike.В правой руке женщина держит стакан с водой и двумя дольками лимона. У нее длинные темные волосы, спадающие волнами на плечи, и выразительные черты лица. На ней серьги-кольца.Табурет имеет черную металлическую основу с круглым деревянным сиденьем. Фон простой и не отвлекает от главной фигуры на снимке.", "operation": "gen-multi-input"}', 'epqz3vn8g9rma0csz04a7qtjew', 'succeeded', '{"date": 1760802912, "chatId": 991429758, "messageId": 112347}', '{"date": 1760802938, "chatId": 991429758, "messageId": 112354}', '[{"date": 1760802950, "chatId": 991429758, "messageId": 112355}]');
