INSERT INTO public.operations VALUES ('8d6f9021-48f0-4a85-aab1-d1b5955cff84', '2025-10-18 22:02:04.512297', false, 7809863613, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBuGRo8-QSou0UoASpxUswru3R2BjKtwAC-QABMhs_4KBLL13Na6LsAsUBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Используй\nприлагаемое изображение в качестве ссылки на лицо и внешность девушки, он создает сцену, в которой мужчина сидит на кожаном кресле спиной в своем доме, вид сзади, смотрит на большой портрет масляной картины на стене, в руках бокал виски. На картине должна быть изображена одна и та же девушка в реалистичном выразительном стиле масляной живописи, лицо не искажай, показывая ее лицо и верхнюю часть тела текстурированными мазками и мягкими цветами. Стена дома чистая И красная с мягким отражателем, который освещает произведение искусства, создавая профессиональную атмосферу выставки.\nПомещение тёмное в атмосфере выставки.", "operation": "gen-multi-input"}', 'v7pxgbjfwxrme0csz2sr7v2b1r', 'succeeded', '{"date": 1760814098, "chatId": 8202375957, "messageId": 112740}', '{"date": 1760814123, "chatId": 8202375957, "messageId": 112745}', '[{"date": 1760814135, "chatId": 8202375957, "messageId": 112746}]');
