INSERT INTO public.operations VALUES ('c761e23d-d05c-4ecd-a38d-a1a04683a136', '2025-10-31 07:45:59.585527', false, 8416978935, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECChRpBD7I7f7WcXUDGY3RlyDk-S6SJQACcPkxG4GIIUjYIV_60lA-lAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 864, "heightPx": 1184}], "prompt": "Сгенирируй как я танцую вальс с мальчиком выше меня ростом он в белой рубашке и классических штанах, он держит меня за талию и смотрит в глаза , фон сделай красивый ресторан", "operation": "gen-multi-input"}', '6w0kdy9pc5rme0ct72b8z1zn5r', 'succeeded', '{"date": 1761885896, "chatId": 5693380530, "messageId": 133652}', '{"date": 1761885958, "chatId": 5693380530, "messageId": 133655}', '[{"date": 1761885969, "chatId": 5693380530, "messageId": 133656}]');
INSERT INTO public.operations VALUES ('f5573858-8309-4e19-80a2-317b82e40e55', '2025-10-18 22:04:03.314178', false, 7809863613, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBuGto8-R7zcg_ytouqOfrvHFXncnKBAAC-wABMhs_4KBLX6Ij-GwIEwcBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1047, "heightPx": 1280}], "prompt": "Используй\nприлагаемое изображение в качестве ссылки на лицо и внешность девушки, он создает сцену, в которой мужчина сидит на кожаном кресле спиной в своем доме, вид сзади, смотрит на большой портрет масляной картины на стене, в руках бокал виски. На картине должна быть изображена одна и та же девушка в реалистичном выразительном стиле масляной живописи, лицо не меняй, показывая ее лицо и верхнюю часть тела текстурированными мазками и мягкими цветами. Стена дома чистая И красная с мягким отражателем, который освещает произведение искусства, создавая профессиональную атмосферу выставки.\nПомещение тёмное в атмосфере выставки.", "operation": "gen-multi-input"}', 'jajs9qryzdrma0csz2tvnepej0', 'succeeded', '{"date": 1760814203, "chatId": 8202375957, "messageId": 112747}', '{"date": 1760814240, "chatId": 8202375957, "messageId": 112752}', '[{"date": 1760814253, "chatId": 8202375957, "messageId": 112753}]');
