INSERT INTO public.operations VALUES ('e29fab0d-bb4f-482c-9259-d656e2399a92', '2025-10-19 10:23:15.987525', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай изображение меня, максимально сохрани мою внешность.\nУльтрадетализированный студийный fashion-art портрет женщины в стиле “neon noir”. Я стою у стены, освещённой бликами фиолетового и мятного неона. На мне чёрный глянцевый оверсайз-пиджак на голое тело, подчеркивающий шею и ключицы; отражения неона ложатся на лакированную ткань. Волосы распущены, подсвечены контровым светом, глаза блестят в полумраке. Освещение — смесь мягкого бокового и холодного неонового света, лёгкий дым создаёт атмосферу. Камера Canon EOS R6 + RF 50mm f/1.2L, f/2.0, ISO 100, 1/500, 4KHD. Постобработка — реалистичная с лёгким глянцевым эффектом. Настроение — дерзкое, кинематографичное, как кадр из модного фильма о будущем", "operation": "gen-multi-input"}', 'pjer5zf4x9rme0cszdct45xdq4', 'succeeded', '{"date": 1760858585, "chatId": 1287537311, "messageId": 113401}', '{"date": 1760858594, "chatId": 1287537311, "messageId": 113406}', '[{"date": 1760858609, "chatId": 1287537311, "messageId": 113407}]');
