INSERT INTO public.operations VALUES ('fd32f85f-867f-4522-b094-e259a73c288e', '2025-11-02 19:53:47.397779', false, 9496302793, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECH2xpB4yFmCs6Bl4IGG_p_6OFeXFZbwAC9wtrG8E_QFAFOFSOMBH8UgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1024, "heightPx": 1024}], "prompt": "Yeah", "operation": "gen-multi-input"}', '5ykxy2t0dhrma0ct8nyr9c4q80', 'succeeded', '{"date": 1762102405, "chatId": 7572787811, "messageId": 139116}', '{"date": 1762102419, "chatId": 7572787811, "messageId": 139119}', '[{"date": 1762102438, "chatId": 7572787811, "messageId": 139120}]');
INSERT INTO public.operations VALUES ('65c0c56f-2c07-46f9-a0d2-719d647339cb', '2025-10-19 10:28:02.288713', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай портрет на открытом воздухе в стиле высокой моды, вдохновлённый редакционной фотографией Vogue.\nЧеловек элегантно позирует на фоне заснеженных гор под ярким солнечным светом.\nНа заднем плане - кинематографический альпийский пейзаж с чистым небом и свежим воздухом. Модель одета в роскошную красную шубу с плотной текстурой, украшенная детализированным ювелирным головным убором похожий на кокошник и подходящими серьгами, которые сверкают на свету, черные солнцезащитные очки.\nВолосы длинные распущенные, прямые. Кожа светящаяся, губы слегка приоткрыты, макияж с ярким румянцем и глянцевым финишем.\nОсвещение яркое, насыщенное и кинематографическое, подчёркивающее контраст между красной шубой и холодными тонами заснеженных гор.\nПоза: плечи повернуты, подбородок слегка приподнят, взгляд уверенный. Не меняй черты лица.\nСтиль: мода Vogue, высокая мода, ультрареализм, богатая цветовая палитра, разрешение 8K, естественный солнечный свет, редакционная элегантность.", "operation": "gen-multi-input"}', '2a33sqt235rma0cszdfbqfy4m4', 'succeeded', '{"date": 1760858653, "chatId": 1287537311, "messageId": 113412}', '{"date": 1760858666, "chatId": 1287537311, "messageId": 113417}', '[{"date": 1760858892, "chatId": 1287537311, "messageId": 113422}]');
INSERT INTO public.operations VALUES ('6056b7da-00cd-4459-b676-51f1c47b6f26', '2025-10-19 10:29:26.438671', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай изображение меня, максимально сохрани мою внешность.\nУльтрадетализированный студийный fashion-art портрет женщины в стиле “neon noir”. Я стою у стены, освещённой бликами фиолетового и мятного неона. На мне чёрный глянцевый оверсайз-пиджак на голое тело, подчеркивающий шею и ключицы; отражения неона ложатся на лакированную ткань. Волосы длинные , прямые, черные , распущены, подсвечены контровым светом, глаза блестят в полумраке. Освещение — смесь мягкого бокового и холодного неонового света, лёгкий дым создаёт атмосферу. Камера Canon EOS R6 + RF 50mm f/1.2L, f/2.0, ISO 100, 1/500, 4KHD. Постобработка — реалистичная с лёгким глянцевым эффектом. Настроение — дерзкое, кинематографичное, как кадр из модного фильма о будущем", "operation": "gen-multi-input"}', 'rg81en4ad1rm80cszdfrerkfng', 'succeeded', '{"date": 1760858930, "chatId": 1287537311, "messageId": 113423}', '{"date": 1760858953, "chatId": 1287537311, "messageId": 113428}', '[{"date": 1760858977, "chatId": 1287537311, "messageId": 113433}]');
