INSERT INTO public.operations VALUES ('cdfa7837-e63b-497a-ae26-db1cbf608664', '2025-10-19 10:33:02.088146', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай гламурный портрет для дня рождения со вспышкой.Максимально сохрани мою внешность.\nФон - простая нейтральная стена, освещённая круглым прожектором, я позирую слегка наклонившись вперед, словно задуваю свечи на торте. На торте стоят зажженные свечи в форме числа (23), а также число (23) от проектора отображено на стене. На мне обтягивающее черное платье в пол. На голове изящно надета серебряная корона. Волосы длинные, черные Я стою боком к камере впереди меня торт", "operation": "gen-multi-input"}', 'p87p066ne5rmc0cszdh820yqw0', 'succeeded', '{"date": 1760859077, "chatId": 1287537311, "messageId": 113434}', '{"date": 1760859180, "chatId": 1287537311, "messageId": 113449}', '[{"date": 1760859192, "chatId": 1287537311, "messageId": 113450}]');
