INSERT INTO public.operations VALUES ('dfec4b19-fec3-4f91-8ef6-07dd0091d362', '2025-10-19 13:15:49.065515', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки с цветами. максимально сохрани мою внешность. Фон - в комнате на темном паркетном полу сидит девушка положив ноги в левую сторону , опираясь на правую руку., по середине стоит букет из 150 красных роз в корзине. Девушка одета в обтягивающие черное платье, выше колена. Волос ее черный,длинный и прямой. Макияж максимально естественный. Девушка смотрит в камеру . Фото сделаномаксимально естественным , с верху, девушка сидит возле бежевой стены. У девушки загорелая кожа .", "operation": "gen-multi-input"}', 'qke1qtyx0hrme0cszfvvqsnje8', 'succeeded', '{"date": 1760868917, "chatId": 1287537311, "messageId": 113543}', '{"date": 1760868936, "chatId": 1287537311, "messageId": 113548}', '[{"date": 1760868958, "chatId": 1287537311, "messageId": 113553}]');
