INSERT INTO public.operations VALUES ('0fcd49f8-f0cc-4409-aa8c-19c41baedab8', '2025-10-19 13:36:06.470073', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBro5o8kzc1_lPT3GF0Uq7gR71gkN52gACEvYxG-zamUsnmth5YMY5_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1001, "heightPx": 1280}], "prompt": "Создай фото девушки с цветами. максимально сохрани мою внешность. Фон - в комнате на бельевом плющевом ковре сидит девушка положив ноги в левую сторону , опираясь на руки сзади. по середине стоит букет из 150 красных роз в корзине. Девушка одета в обтягивающие черное платье, выше колена и черные капроновые колготки. Волос ее черный,длинный и прямой , уложенный сзади, в ушах серьги-гвоздики с камушками. Макияж максимально естественный. Девушка смотрит в камеру . Фото сделаномаксимально естественным , с верху, девушка сидит возле белых замшевых обой. У девушки загорелая кожа .", "operation": "gen-multi-input"}', 'c80xy2kgj9rme0cszg5b5tkv50', 'succeeded', '{"date": 1760870161, "chatId": 1287537311, "messageId": 113591}', '{"date": 1760870165, "chatId": 1287537311, "messageId": 113596}', '[{"date": 1760870176, "chatId": 1287537311, "messageId": 113597}]');
