INSERT INTO public.operations VALUES ('0841717b-41f2-4bcb-94b1-23f371afa9d8', '2025-10-19 17:29:43.709113', false, 6411124282, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBvLRo9PXJgZ5C6sQcK9zuntNwxszsMwAC0AABMhvaAqlLztrAMonX12gBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 827, "heightPx": 1053}], "prompt": "Создай зимнюю версию загруженной фотографии. Сохрани позу и освещение в точности. Добавь естественную снежную атмосферу, падающие с неба снежинки. Земля, крыши и деревья должны быть покрыты слоем снега", "operation": "gen-multi-input"}', 'czsg4raka1rma0cszkgbmx90g0', 'succeeded', '{"date": 1760884169, "chatId": 5683026301, "messageId": 113844}', '{"date": 1760884180, "chatId": 5683026301, "messageId": 113849}', '[{"date": 1760884195, "chatId": 5683026301, "messageId": 113850}]');
INSERT INTO public.operations VALUES ('649a68d0-eeea-41f0-9ce9-aec09190ab84', '2025-10-19 13:43:23.165942', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки с цветами. максимально сохрани мою внешность. Фон - в комнате на бежевом ковре сидит девушка положив ноги в левую сторону , опираясь на правую руку., левая Кука сзади. по середине стоит букет из 150 красных роз в корзине. Девушка одета в обтягивающие черное платье с рукавами, выше колена. Волос ее черный,длинный и прямой , ниже талии. Макияж максимально естественный. На шее висит цепочка, в ушах маленькие серьги. Девушка смотрит в камеру . Фото сделаномаксимально естественным , с верху, девушка сидит возле бежевой стены. На девушке надеты черный капроновые колготки.", "operation": "gen-multi-input"}', '5d0p38rtksrmc0cszg8sehjmx0', 'succeeded', '{"date": 1760870526, "chatId": 1287537311, "messageId": 113632}', '{"date": 1760870602, "chatId": 1287537311, "messageId": 113644}', '[{"date": 1760870613, "chatId": 1287537311, "messageId": 113645}]');
