INSERT INTO public.operations VALUES ('125adc74-6409-4403-af16-28b11232e7fd', '2025-10-19 13:48:55.354298', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки с цветами. максимально сохрани мою внешность. Фон - в комнате на бежевом ковре сидит девушка положив ноги в левую сторону , опираясь на правую руку., левая Кука сзади. по середине стоит букет из 150 красных роз в корзине. Девушка одета в обтягивающие черное платье с рукавами, выше колена. Волос ее черный,длинный и прямой , ниже талии. Макияж максимально естественный. На шее висит цепочка с кулоном в виде длинного треугольника в ушах маленькие серьги. Девушка смотрит в камеру . Фото сделаномаксимально естественным , с верху, девушка сидит возле бежевой стены. На девушке надеты черный капроновые колготки.", "operation": "gen-multi-input"}', 'wjcsw4hcnxrmc0cszgbb9b0htr', 'succeeded', '{"date": 1760870910, "chatId": 1287537311, "messageId": 113668}', '{"date": 1760870914, "chatId": 1287537311, "messageId": 113673}', '[{"date": 1760870945, "chatId": 1287537311, "messageId": 113680}]');
