INSERT INTO public.operations VALUES ('c5f5e3e2-9b0d-41fc-b5eb-b1ebf9f24237', '2025-10-19 13:51:06.080819', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото  молодой девушки с цветами. максимально сохрани мою внешность. Фон - в комнате на бежевом ковре сидит девушка положив ноги в левую сторону , опираясь на правую руку., левая Кука сзади. по середине стоит букет из 150 красных роз в корзине. Девушка одета в обтягивающие черное платье с рукавами, выше колена. Волос ее черный,длинный и прямой , ниже талии. Макияж максимально естественный. На шее висит цепочка с кулоном в виде длинного треугольника в ушах маленькие серьги. Девушка смотрит в камеру . Фото сделаномаксимально естественным , с верху, девушка сидит возле бежевой стены. На девушке надеты черный капроновые колготки.", "operation": "gen-multi-input"}', 'qj29gm9akxrme0cszgc80zhkac', 'succeeded', '{"date": 1760871061, "chatId": 1287537311, "messageId": 113695}', '{"date": 1760871065, "chatId": 1287537311, "messageId": 113700}', '[{"date": 1760871076, "chatId": 1287537311, "messageId": 113701}]');
