INSERT INTO public.operations VALUES ('c927f0de-d591-4138-961e-82db8e250c94', '2025-10-19 18:28:40.510413', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото селфи молодой девушки в близи . Фон в комнате , белые  стены и свет тусклый. Максимально сохрани мою внешность. Девушка одета в черную кофту с рукавами и глубоким вырезом в груди. На ней надела цепочка с кулоном треугольника. У девушки черные густые и длинные волосы. Волосы накручены в мелкую волну. Макияж естественный, лицо направлено прямо в камеру, девушка смотрит в бок и слегка улыбается сжав пухлые губы.", "operation": "gen-multi-input"}', 'a63fv8abjdrm80cszmbajs6zaw', 'succeeded', '{"date": 1760887704, "chatId": 1287537311, "messageId": 113874}', '{"date": 1760887708, "chatId": 1287537311, "messageId": 113879}', '[{"date": 1760887731, "chatId": 1287537311, "messageId": 113880}]');
