INSERT INTO public.operations VALUES ('455183af-b5a9-4136-b4f7-0039da015864', '2025-10-19 22:58:07.941642', false, 1545995087, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBv6Fo9UKU0pfVVi-fL0GP2QABFRng5TEAAhTJMRv9FKlTihdCjpgErVIBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Добавь снежную зиму, солнце должно нежно светить на человека со стороны, оставляя мягкие блики. Должны сыпаться небольшие хлопья и снег, вокруг должны быть атмосфера красивые снежные зимы с белыми сугробами и чистым снегом. Многое фото должно выглядеть реалистично. И чтобы на человеке была куртка черная.", "operation": "gen-multi-input"}', 'gm3v6dzx2xrm80cszr68xqnn4g', 'succeeded', '{"date": 1760903828, "chatId": 7870546009, "messageId": 114593}', '{"date": 1760903886, "chatId": 7870546009, "messageId": 114598}', '[{"date": 1760903897, "chatId": 7870546009, "messageId": 114599}]');
