INSERT INTO public.operations VALUES ('bd948729-9dfe-43ce-9018-bf5aa8412561', '2025-10-28 18:03:41.913898', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_nlpAAHa1wABqP48zNBvbb8NC9q--IkFAAL-AAEyG5JeCUg5gYspokv7dwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Задание для нейросети\nЦель: создать серию фотореалистичных снимков для осенней фотосессии мальчика 13 лет.\nИсходное изображение: фото мальчика с сохранёнными чертами лица и причёской (без изменений).\nТребования к результату:\nЛицо и причёска:\nполностью сохранить индивидуальные черты лица, мимику и выражение;\nпричёска — без изменений (форма, объём, цвет, укладка).\nОдежда (осенний модный образ):\nактуальный подростковый стиль 2024–2025 (оверсайз, многослойность, деним);\nпримеры элементов:\nобъёмный бомбер или пальто нейтрального оттенка (бежевый, серый, хаки);\nхуди или свитер с фактурной вязкой;\nджинсы свободного кроя (возможно, с потёртостями);\nаксессуары: вязаная шапка, шарф, рюкзак в тон.\nцветовая гамма: тёплые осенние тона (горчичный, терракотовый, оливковый) + базовые (чёрный, белый, серый).\nЛокация и атмосфера:\nуличный пейзаж осенью: парк с опавшими листьями, аллея с деревьями в золотистой листве;\nмягкое дневное освещение (ранний вечер или утро), лёгкие тени;\nфон слегка размыт для акцента на объекте.\nДетализация:\nвысокая чёткость изображения (4K);\nреалистичная текстура тканей, игра света на поверхностях;\nестественные складки одежды, объёмность образа.\nКомпозиция:\nпоза динамичная (например, шаг, поворот головы), но без искажения мимики;\nруки в карманах или свободно опущены.\nСтиль обработки:\nфотореализм с лёгкой художественной ретушью;\nтёплые тона, приглушённая контрастность для осеннего настроения.", "operation": "gen-multi-input"}', '6njk7hd8ydrma0ct5dcb3tyc1w', 'succeeded', '{"date": 1761663763, "chatId": 1091595273, "messageId": 130688}', '{"date": 1761663820, "chatId": 1091595273, "messageId": 130693}', '[{"date": 1761663841, "chatId": 1091595273, "messageId": 130694}]');
