INSERT INTO public.operations VALUES ('b3d35b8c-34b6-4ab6-8ed4-f3340e365ca3', '2025-10-29 20:32:24.521825', false, 4015001031, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECBFtpAk8bx9OmDwl-plmETlK1G0hfDQACRwxrG2j5CFBlGvmmW7558gEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 773, "heightPx": 1280}], "prompt": "A cinematic photo of a beautiful 22-year-old woman with long, flowing auburn hair, celebrating her birthday. She is wearing an elegant red dress, laughing joyfully. In front of her is a stunning white birthday cake with delicate details and lit candles. The scene has a romantic and festive red and white theme, with soft bokeh lights and red rose petals in the background. The lighting is warm and soft, creating a magical and joyful atmosphere. Hyperrealistic, 8k, high detail.", "operation": "gen-multi-input"}', '48d3m0sb8srmc0ct643smcyrnm', 'succeeded', '{"date": 1761759136, "chatId": 7794515057, "messageId": 132200}', '{"date": 1761759142, "chatId": 7794515057, "messageId": 132203}', '[{"date": 1761759154, "chatId": 7794515057, "messageId": 132204}]');
INSERT INTO public.operations VALUES ('3b1255e4-ea25-4dc8-b2e2-e8a08cc74d0a', '2025-10-20 02:44:20.725787', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Черно-белая студийная фотография женщины, сидящей в приседшей позе и закутанной в большой пушистый белый меховой плащ. Ее обнаженные плечи и ноги частично видны, голова нежно опирается на руку. Фон простой и минималистичный, создающий мягкий редакционный образ в стиле модной фотосессии.\nСнимок обладает утонченной, элегантной атмосферой, напоминающей профессиональную журнальную съемку.\nХудая девушка, волос черный , длинный и прямой. Максимально сохрани мою внешность", "operation": "gen-multi-input"}', '479cjs8qzxrma0cszve8nbn1fg', 'failed', '{"date": 1760917404, "chatId": 1287537311, "messageId": 114925}', '{"date": 1760917459, "chatId": 1287537311, "messageId": 114930}', '[{"date": 1760917459, "chatId": 1287537311, "messageId": 114930}]');
