INSERT INTO public.operations VALUES ('7f1b032a-182c-474a-b9e6-ff1cf83dbb11', '2025-10-30 17:35:03.187403', false, 4080032007, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECB8hpA3STLt6VHyl5SfJ9GGOJvpJ4zAACxAABMhsVWxlIzZ6jC7PnEF8BAAMCAAN4AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 474, "heightPx": 474}], "prompt": "Создай картинку в этом же стиле. На картинке бабушка на костылях идёт к церкви, а перед ней красиво освещается путь, а вдоль него растут красивые цветы. Церковь православная. С куполами. Бабушка в платке и длинной юбке. Одета православно.", "operation": "gen-multi-input"}', 'rnp259s7f9rme0ct6p5t317g8c', 'succeeded', '{"date": 1761834862, "chatId": 7794324884, "messageId": 133101}', '{"date": 1761834901, "chatId": 7794324884, "messageId": 133110}', '[{"date": 1761834913, "chatId": 7794324884, "messageId": 133113}]');
INSERT INTO public.operations VALUES ('be4e4e1c-1f18-4ee2-a81f-fb395e367d28', '2025-10-26 17:45:21.669674', false, 1042000272, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB8pdo_jPyES5YJt-zaULVbCkI2ecXlgAC6fUxG-LVmEvNBC1GRB9vSgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "Добавь на это фото снежную зиму, солнце должно рассеяно светить на человека с фото со стороны, оставляя мягкие блики. должны сыпаться небольшие хлопья снега, которые остаются на волосах девушки. во круг должна быть атмосфера красивой снежной зимы с белыми сугробами и с чистым снегом. итоговое фото должно выглядеть реалистично", "operation": "gen-multi-input"}', 'ws4fbd97gsrme0ct43xvecw878', 'succeeded', '{"date": 1761489906, "chatId": 5202592050, "messageId": 127639}', '{"date": 1761489917, "chatId": 5202592050, "messageId": 127644}', '[{"date": 1761489934, "chatId": 5202592050, "messageId": 127645}]');
