INSERT INTO public.operations VALUES ('0b5a8584-a30c-485b-b26c-5718ec5bbd83', '2025-10-28 18:27:41.727643', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_oppAAHg5Gto1olk2g7sT3pyVhRp000AAjYBMhuSXglIjZHyYAABBCVgAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 866, "heightPx": 1280}], "prompt": "Преобразуй фото в осеннюю фотосессию. Сохраняй черты лица и индивидуальность человека, но полностью смени одежду и фон. Одежда — модная, из коллекций осени‑зимы 2024–2025, подходит для подростка. Стиль: современный уличный (street style), сдержанные осенние цвета (охра, бордо, оливковый, бежевый), качественные ткани (твид, шерсть, кожа). Фон — осенний парк, тёплые тона, мягкий свет. Высокое качество, детализация, реалистичная текстура одежды и волос.", "operation": "gen-multi-input"}', '2zjmm3n1vnrme0ct5dqbkmpnv4', 'succeeded', '{"date": 1761665252, "chatId": 1091595273, "messageId": 130698}', '{"date": 1761665259, "chatId": 1091595273, "messageId": 130703}', '[{"date": 1761665279, "chatId": 1091595273, "messageId": 130704}]');
