INSERT INTO public.operations VALUES ('d16447bf-e883-40c9-8358-f599d630dbfa', '2025-10-20 05:05:23.21432', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwWho9ZiN3bwq748a-7vFk99xo9Fu_wACcfsxG3bHsUtkH59h5s83RwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "Создай фото молодой девушки. Максимально сохрани мою внешность. Качество фото более естественное и четкое . Девушка сидит на низком пластиков вязаном кресле темно коричнево цвета , на против  стоит такой же стол, на стеклянном балконе. На фоне виден бассейн и пальмы. Девушка одета в белый халат и на голове волосы замотаны в белое полотенце. Погода яркая солнечная. Девушка смотрит в бок", "operation": "gen-multi-input"}', 'zwwk7w1r75rm80cszxerba1z58', 'succeeded', '{"date": 1760925837, "chatId": 1287537311, "messageId": 115048}', '{"date": 1760925922, "chatId": 1287537311, "messageId": 115060}', '[{"date": 1760925938, "chatId": 1287537311, "messageId": 115063}]');
