INSERT INTO public.operations VALUES ('01f63021-405b-47b2-a8ca-1fcbf2ad30a1', '2025-10-20 06:27:17.16203', false, 9313259986, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwhRo9awAAeV8RJGZko56xyk5JXCjFuUAAqP4MRuusLBLEkzSf0MZ9REBAAMCAAN3AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1242, "heightPx": 2208}], "prompt": "сделай зеркало чистым,убери блики,грязь с верху зеркала", "operation": "gen-multi-input"}', 'yj3hvp1kghrmc0cszym854n6ew', 'succeeded', '{"date": 1760930816, "chatId": 7892875910, "messageId": 115220}', '{"date": 1760930836, "chatId": 7892875910, "messageId": 115225}', '[{"date": 1760930847, "chatId": 7892875910, "messageId": 115226}]');
INSERT INTO public.operations VALUES ('953ebe36-5f57-4b33-b85f-c2c552fd8848', '2025-10-20 03:21:11.614333', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "фон белый, пол белый, студийная фотография женщины, сидящей в приседшей позе и закутанной в большой пушистый белый меховой плащ. Ее обнаженные плечи и ноги частично видны, голова нежно опирается на руку. Фон простой и минималистичный, создающий мягкий редакционный образ в стиле модной фотосессии.\nСнимок обладает утонченной, элегантной атмосферой, напоминающей профессиональную журнальную съемку.\nХудая девушка, волос черный , длинный и прямой. Максимально сохрани мою внешность . Девушка смотрит прямо в камеру, у нее пухлые губы и реснички. Качество фото не замыленно, четкие черты лица. У девушки загорелая кожа .", "operation": "gen-multi-input"}', '70bzc7ykwhrma0cszvyrrb1278', 'succeeded', '{"date": 1760919658, "chatId": 1287537311, "messageId": 114996}', '{"date": 1760919670, "chatId": 1287537311, "messageId": 115001}', '[{"date": 1760919682, "chatId": 1287537311, "messageId": 115002}]');
INSERT INTO public.operations VALUES ('93584497-8eb9-43d8-b9fc-8c3658c9500a', '2025-10-20 06:38:26.649038', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Изображение показывает женщину, сидящую на полу, прислонившись спиной к белой стене. Пол серый.На женщине надета большая черная меховая шуба, которая частично сползла с плеч. Она одета в черные чулки с цветочным узором. На шее у нее золотая цепочка с кулоном.У женщины длинные темные волосы, слегка вьющиеся на концах. У нее светлая кожа и светлые глаза. Ее взгляд направлен прямо в камеру. Ее рука слегка касается меха шубы.", "operation": "gen-multi-input"}', '54jsn2vap1rma0cszys943663g', 'failed', '{"date": 1760931475, "chatId": 991429758, "messageId": 115256}', '{"date": 1760931505, "chatId": 991429758, "messageId": 115259}', '[{"date": 1760931505, "chatId": 991429758, "messageId": 115259}]');
