INSERT INTO public.operations VALUES ('044b0f19-00bf-4c5d-ba95-f5efc4ef452a', '2025-10-26 19:28:36.598738', false, 2475391303, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB8ddo_iFD1brjyeOpwcG5jqL2QRtIOQAC4f0xG3cc8Us4mF9xxfkdvAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 885, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB8dho_iFDcDkr3xCC9ziNSTTy1G9-rQAC4v0xG3cc8UtoiukyhvWRXQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 852}, {"file": {"fileId": "AgACAgIAAxkBAAEB8dlo_iFDfcwxSy5pBLg3byQBsw4xIgAC4_0xG3cc8UvMcVXuvtje9QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB8dpo_iFD4iRJf_2DDsb--ecMCdIZtQAC5P0xG3cc8UtwYMXYFPIyPQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Фотореалистичное портретное фото в формате вертикального кадра, высокая детализация, мягкий естественный свет на открытом воздухе. Женщина слегка наклоняет голову и бережно держит младенца, прижатого к груди; ребёнок накрыт лёгким белым пледом с мелким детским принтом (милые синие зверюшки, пастельные оттенки). Женщина в простой белой рубашке с мягкой текстурой хлопка, видны руки, аккуратно поддерживающие спину и голову ребёнка. Фон — зелёная трава с мягким боке и тёплым дневным светом, нежные тени, спокойная тёплая цветовая палитра (зелёный, белый, пастель). Низкая глубина резкости, естественная кожа, мягкая фильмовая зернистость, реалистичные текстуры ткани и волос, интимная тёплая атмосфера, 85mm портретный объектив, f/1.8, мягкая постобработка, высокое разрешение.", "operation": "gen-multi-input"}', '1e8zk3netxrm80ct45crtnq0fw', 'succeeded', '{"date": 1761496050, "chatId": 856856273, "messageId": 127697}', '{"date": 1761496115, "chatId": 856856273, "messageId": 127703}', '[{"date": 1761496134, "chatId": 856856273, "messageId": 127704}]');
