INSERT INTO public.operations VALUES ('43efff37-ebd6-4994-9d9a-aab6d21e7e75', '2025-10-20 05:07:12.606025', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото молодой девушки. Максимально сохрани мою внешность. Качество фото более естественное и четкое . Девушка сидит облокотившись на спинку кресла,  на низком пластиков вязаном кресле темно коричнево цвета , на против  стоит такой же стол, на стеклянном балконе. На фоне виден бассейн и пальмы. Девушка одета в белый халат и на голове волосы замотаны в белое полотенце. Погода яркая солнечная. Девушка смотрит в бок", "operation": "gen-multi-input"}', 'rtamfjq3fsrma0cszxfbt5av78', 'succeeded', '{"date": 1760925961, "chatId": 1287537311, "messageId": 115064}', '{"date": 1760926031, "chatId": 1287537311, "messageId": 115075}', '[{"date": 1760926043, "chatId": 1287537311, "messageId": 115077}]');
