INSERT INTO public.operations VALUES ('9706bee6-5aa5-49d7-b1a2-658355630f04', '2025-10-20 03:50:57.506406', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwUlo9YdJxERp6ykagUt3IrCm-jf3swAChfMxG_kQsEsn_WegFanpdAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 631, "heightPx": 1163}], "prompt": "Создай фото селфи молодой девушки в близи . Фон в комнате , белые  стены и свет тусклый. Максимально сохрани мою внешность. Девушка одета в черную кофту с рукавами и глубоким вырезом в груди. На ней надела цепочка с кулоном треугольника. У девушки коричневые густые и длинные, прямые волосы. макияж естественный, лицо направлено прямо в камеру, девушка смотрит в бок и слегка улыбается сжав пухлые губы. Качество фото более естественное и четкое. Лицо без сглаживания. Лицо слегка освещает солнечный свет.", "operation": "gen-multi-input"}', 'j9gnvpgmdnrmc0cszwcrg4kdb8', 'succeeded', '{"date": 1760921417, "chatId": 1287537311, "messageId": 115017}', '{"date": 1760921456, "chatId": 1287537311, "messageId": 115022}', '[{"date": 1760921466, "chatId": 1287537311, "messageId": 115023}]');
