INSERT INTO public.operations VALUES ('26a145d0-84e7-4121-b7fc-d79efd3680fa', '2025-10-20 05:10:27.910718', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото молодой девушки. Максимально сохрани мою внешность. Качество фото более естественное и четкое . Девушка сидит облокотившись на спинку кресла,  на низком пластиков вязаном кресле темно коричнево цвета , на против  стоит такой же стол, на стеклянном балконе. На фоне виден бассейн и пальмы. Девушка одета в белый халат, волосы длинные, черные и прямые. Погода яркая солнечная. Девушка смотрит в бок. Ногу закинула на другую ногу . Голову положила на руку которая стоит на подлокотнике. Лицо направлено на камеру. Девушка слегка улыбается", "operation": "gen-multi-input"}', 'cnswt96yghrme0cszxgsfr1f4m', 'succeeded', '{"date": 1760926211, "chatId": 1287537311, "messageId": 115094}', '{"date": 1760926226, "chatId": 1287537311, "messageId": 115099}', '[{"date": 1760926237, "chatId": 1287537311, "messageId": 115100}]');
INSERT INTO public.operations VALUES ('ec010195-e6e1-4b03-8aec-afa4231368ab', '2025-10-20 06:39:17.62169', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Изображение показывает женщину, сидящую на полу, прислонившись спиной к белой стене. Пол серый.На женщине надета большая черная меховая шуба, которая частично сползла с плеч. Она одета в черные чулки с цветочным узором. На шее у нее золотая цепочка с кулоном.У женщины длинные темные волосы, слегка вьющиеся на концах. У нее светлая кожа и светлые глаза. Ее взгляд направлен прямо в камеру. Ее рука слегка касается меха шубы.", "operation": "gen-multi-input"}', 'zrxpfa9hjsrma0cszysv74sm4r', 'failed', '{"date": 1760931550, "chatId": 991429758, "messageId": 115262}', '{"date": 1760931554, "chatId": 991429758, "messageId": 115265}', '[{"date": 1760931554, "chatId": 991429758, "messageId": 115265}]');
