INSERT INTO public.operations VALUES ('6d68bb1c-cc3c-40ab-9203-8280ac880f02', '2025-10-20 06:41:29.985874', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении запечатлена женщина, сидящая на полу на фоне серого градиентного фона. Свет падает на нее сверху и спереди, создавая драматические тени.У женщины длинные темные волосы с челкой, падающей на лоб. У нее светлая кожа, выразительные темные глаза и полные губы. На женщине надето белое облегающее платье с длинными рукавами и открытыми плечами. Платье имеет разрез на бедре.На пальце левой руки женщины видно кольцо. У нее темный лак на ногтях. Ее поза излучает уверенность и расслабленность.", "operation": "gen-multi-input"}', 'j3qve91pw1rmc0cszytr0pp3bm', 'failed', '{"date": 1760931633, "chatId": 991429758, "messageId": 115278}', '{"date": 1760931688, "chatId": 991429758, "messageId": 115281}', '[{"date": 1760931688, "chatId": 991429758, "messageId": 115281}]');
