INSERT INTO public.operations VALUES ('12865e9b-fb48-411a-b2f5-28151b860e7f', '2025-10-20 06:42:29.559121', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении запечатлена женщина, сидящая на полу на фоне серого градиентного фона. Свет падает на нее сверху и спереди, создавая драматические тени.У женщины длинные темные волосы с челкой, падающей на лоб. У нее светлая кожа, выразительные темные глаза и полные губы. На женщине надето белое облегающее платье с длинными рукавами и открытыми плечами. Платье имеет разрез на бедре.На пальце левой руки женщины видно кольцо. У нее темный лак на ногтях. Ее поза излучает уверенность и расслабленность.", "operation": "gen-multi-input"}', '0bw7tqrzgxrm80cszyvactenqg', 'failed', '{"date": 1760931744, "chatId": 991429758, "messageId": 115290}', '{"date": 1760931748, "chatId": 991429758, "messageId": 115293}', '[{"date": 1760931748, "chatId": 991429758, "messageId": 115293}]');
INSERT INTO public.operations VALUES ('ca057f47-ceda-4d91-b022-ef9cf1f7a3c3', '2025-10-20 06:45:49.720033', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фотографии изображена девушка в полный рост, позирующая на фоне серой стены. На стене присутствуют размытые световые пятна, имитирующие облака или движение света. Справа от девушки видна ее тень.Девушка одета в черное платье с длинными рукавами и вырезом в области груди. На шее у нее тонкая золотая цепочка с кулоном. На запястье правой руки надет браслет. На ногах у девушки босоножки на каблуке с золотыми цепочками.Девушка смотрит прямо в камеру, ее правая рука поднята к лицу, пальцы касаются подбородка. Ее левая рука расположена на бедре. У нее темные длинные волосы, уложенные волнами.", "operation": "gen-multi-input"}', 'hngek91d99rme0cszywvhdcxj0', 'succeeded', '{"date": 1760931917, "chatId": 991429758, "messageId": 115303}', '{"date": 1760931948, "chatId": 991429758, "messageId": 115306}', '[{"date": 1760931960, "chatId": 991429758, "messageId": 115307}]');
INSERT INTO public.operations VALUES ('e3d3b823-9adf-4004-95a5-b7ee0952493e', '2025-10-20 06:55:22.610394', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwm5o9bKh-tKjcwMB4sGEAAGKau7NW4EAAgcAATIbCv-oSxkIjvVLD4rjAQADAgADeQADNgQ", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении запечатлена женщина, сидящая на полу на фоне серого градиентного фона. Свет падает на нее сверху и спереди, создавая драматические тени.У женщины длинные темные волосы с челкой, падающей на лоб. У нее светлая кожа, выразительные темные глаза и полные губы. На женщине надето белое облегающее платье с длинными рукавами и открытыми плечами. Платье имеет разрез на бедре.На пальце левой руки женщины видно кольцо. У нее темный лак на ногтях. Ее поза излучает уверенность и расслабленность.", "operation": "gen-multi-input"}', 'radt7zfb7srme0cszz0s94f32w', 'succeeded', '{"date": 1760932513, "chatId": 991429758, "messageId": 115310}', '{"date": 1760932519, "chatId": 991429758, "messageId": 115313}', '[{"date": 1760932532, "chatId": 991429758, "messageId": 115314}]');
INSERT INTO public.operations VALUES ('b3eaec8b-6fb4-4c5c-8e76-0e0b98725600', '2025-10-20 06:43:51.923688', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении девушка сидит на белом кубе. Она одета в черное платье с открытыми плечами и черные колготки. У нее длинные прямые каштановые волосы, зачесанные назад. Девушка смотрит в сторону от камеры. Фон изображения розово-красный.", "operation": "gen-multi-input"}', 'wsxzceb18hrma0cszyvt4mgtw0', 'succeeded', '{"date": 1760931812, "chatId": 991429758, "messageId": 115296}', '{"date": 1760931830, "chatId": 991429758, "messageId": 115299}', '[{"date": 1760931841, "chatId": 991429758, "messageId": 115300}]');
INSERT INTO public.operations VALUES ('0acd93f8-6c38-44e3-bc61-e4db9b02e8e7', '2025-10-26 20:03:48.645447', false, 8983964851, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB80Bo_lQ46cP6dkk13BiJ9mAFE9wv6gACQQIyG07G8EtwhSNHaoNNKwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 975, "heightPx": 1280}], "prompt": "Добавь красивого парня рядом чтобы обнимал меня", "operation": "gen-multi-input"}', 'a68cqgq9c9rma0ct45ws1yv2p4', 'succeeded', '{"date": 1761498168, "chatId": 1855852634, "messageId": 127808}', '{"date": 1761498193, "chatId": 1855852634, "messageId": 127816}', '[{"date": 1761498236, "chatId": 1855852634, "messageId": 127819}]');
