INSERT INTO public.operations VALUES ('e76a266f-e4ec-459a-9cd7-051a6d597193', '2025-10-20 10:32:53.88658', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении запечатлена женщина, сидящая на полу на фоне серого градиентного фона. Свет падает на нее сверху и спереди, создавая драматические тени.У женщины длинные темные волосы с челкой, падающей на лоб. У нее светлая кожа, выразительные темные глаза и полные губы. На женщине надето белое облегающее платье с длинными рукавами и открытыми плечами. Платье имеет разрез на бедре.На пальце левой руки женщины видно кольцо. У нее темный лак на ногтях. Ее поза излучает уверенность и расслабленность.", "operation": "gen-multi-input"}', '0cggpbgh59rma0ct024r8gk84m', 'succeeded', '{"date": 1760932546, "chatId": 991429758, "messageId": 115317}', '{"date": 1760945571, "chatId": 991429758, "messageId": 115492}', '[{"date": 1760945586, "chatId": 991429758, "messageId": 115493}]');
INSERT INTO public.operations VALUES ('199c0585-e497-4c08-8dd4-558a435e6d74', '2025-10-20 11:47:52.032357', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фотографии изображена девушка в черном пальто, стоящая на фоне белой стены. У нее длинные темные волосы, которые слегка волнистые. Ее глаза закрыты, и она, судя по всему, слегка наклонила голову вниз. Ее левая рука поднята вверх, а правая рука касается ее волос. Пальто завязано поясом на талии. Подол пальто с разрезом показывает часть ее ноги.\nМакияж естественный. сохрани черты лица.", "operation": "gen-multi-input"}', 'r0w5a1dm6srm80ct036tem7xr0', 'succeeded', '{"date": 1760949973, "chatId": 991429758, "messageId": 115501}', '{"date": 1760950070, "chatId": 991429758, "messageId": 115504}', '[{"date": 1760950082, "chatId": 991429758, "messageId": 115505}]');
