INSERT INTO public.operations VALUES ('b4476d63-3a8b-4249-91ca-0a5f531ba7d7', '2025-11-14 11:02:14.293985', false, 1727148707, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECzFlpFuHmHGeOP1IDbSVIsoGci1C04AACRwtrG0n7uFAkskOYPJfd0AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "میخوام سوار اسب قرمز باشه تو طبیعت و یه کره اسب هم همراش باشه", "operation": "gen-multi-input"}', 'hg056c79wsrme0ctg5hbbyqhqm', 'failed', '{"date": 1763107302, "chatId": 1849784736, "messageId": 183385}', '{"date": 1763107333, "chatId": 1849784736, "messageId": 183390}', '[{"date": 1763107333, "chatId": 1849784736, "messageId": 183390}]');
INSERT INTO public.operations VALUES ('741c9343-2694-4040-a343-c3314403cf64', '2025-10-26 20:04:42.31072', false, 7623864401, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB8z5o_lQ0Em5r5RenWLcWij0yGlTI8gACO_YxG-iz-Uv9O8oAAV89z5gBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 731, "heightPx": 1280}], "prompt": "Сделать чётче и естестественнее руки\nВолосы чуть пышнее", "operation": "gen-multi-input"}', 'kchkmwdtmhrm80ct45xavne7rw', 'succeeded', '{"date": 1761498224, "chatId": 7828225210, "messageId": 127817}', '{"date": 1761498275, "chatId": 7828225210, "messageId": 127825}', '[{"date": 1761498293, "chatId": 7828225210, "messageId": 127828}]');
INSERT INTO public.operations VALUES ('d2075910-38ed-4cbb-926e-b9da34ecab77', '2025-10-20 11:50:13.613765', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото молодой девушки. Максимально сохрани мою внешность. Качество фото более естественное и четкое . Девушка сидит облокотившись на спинку кресла,  на низком пластиков вязаном кресле темно коричнево цвета , на против  стоит такой же стол, на стеклянном балконе. На фоне виден бассейн и пальмы. Девушка одета в белый халат, волосы длинные, черные и прямые. Погода яркая солнечная. Девушка смотрит в бок. Ногу закинула на другую ногу . Голову положила на руку которая стоит на подлокотнике. Лицо направлено на камеру.", "operation": "gen-multi-input"}', 'j3bhsd6xdhrma0ct037sa8m6pw', 'succeeded', '{"date": 1760926285, "chatId": 1287537311, "messageId": 115112}', '{"date": 1760926289, "chatId": 1287537311, "messageId": 115117}', '[{"date": 1760950224, "chatId": 1287537311, "messageId": 115510}]');
INSERT INTO public.operations VALUES ('cc4c9104-0ade-4d8a-8f37-2e4784969544', '2025-10-20 11:51:02.061569', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении изображена стройная девушка позирующая в облегающем красном платье в пол. У платья длинные рукава и драпировка в области шеи.У девушки длинные темные волнистые волосы, которые спадают ей на плечи. Обеими руками она касается своей головы, одна рука лежит на волосах возле виска, а другая - возле щеки. У нее накрашены глаза и губы.Фон изображения однотонный, серого цвета. Освещение создает тень от фигуры, подчеркивая ее изгибы.", "operation": "gen-multi-input"}', '9xwvkswtfsrm80ct0388m333nw', 'succeeded', '{"date": 1760950196, "chatId": 991429758, "messageId": 115508}', '{"date": 1760950260, "chatId": 991429758, "messageId": 115512}', '[{"date": 1760950271, "chatId": 991429758, "messageId": 115513}]');
INSERT INTO public.operations VALUES ('ab040246-eb58-4e7a-89f6-433dbde75ce5', '2025-10-26 20:05:42.646985', false, 8983964851, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB81Jo_lSxr_iagjKyNCmJm54fkqOBcQACqPoxG3KC-Ut_z_HYYYNf7QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 880, "heightPx": 1184}], "prompt": "Изменить фон чтобы сзади нас стоял черный геленваген", "operation": "gen-multi-input"}', 'zktzk6na2xrme0ct45xr1p10rm', 'succeeded', '{"date": 1761498289, "chatId": 1855852634, "messageId": 127826}', '{"date": 1761498338, "chatId": 1855852634, "messageId": 127834}', '[{"date": 1761498354, "chatId": 1855852634, "messageId": 127841}]');
INSERT INTO public.operations VALUES ('dbd93354-3282-4b17-aec2-0089cd7d8c66', '2025-10-26 20:19:28.213188', false, 8983964851, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB825o_le0ibI6myyVGJfb2sMv-3G0NgACxPoxG3KC-UtbCZjuGuLqAAEBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1016, "heightPx": 1280}], "prompt": "Убери телефон из моей руки и руку опусти вниз, поставь рядом красивого высокого парня блондина с голубыми глазами с голубых джинсах и белой футболке, измени фон чтобы сзади нас стоял белый геленваген", "operation": "gen-multi-input"}', 'p1bwhnhyghrmc0ct4649xwdxng', 'succeeded', '{"date": 1761499060, "chatId": 1855852634, "messageId": 127854}', '{"date": 1761499159, "chatId": 1855852634, "messageId": 127859}', '[{"date": 1761499176, "chatId": 1855852634, "messageId": 127860}]');
INSERT INTO public.operations VALUES ('9dfa9e4f-c1e6-44bc-879a-b6dfe258b8c1', '2025-10-28 19:31:11.869425', false, 8550819949, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_tFpAAHvhpGGOOXT0QIkvRDUvYopzesAAp38MRuGEglIhsQpIenl69UBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1024, "heightPx": 1024}], "prompt": "сделай человека на фото больше", "operation": "gen-multi-input"}', '7pddr0p4rxrma0ct5emb01cckc', 'succeeded', '{"date": 1761669064, "chatId": 1732878468, "messageId": 130777}', '{"date": 1761669069, "chatId": 1732878468, "messageId": 130782}', '[{"date": 1761669083, "chatId": 1732878468, "messageId": 130783}]');
INSERT INTO public.operations VALUES ('7aa87fb2-5857-4719-a6b3-eeb8aa338c4e', '2025-11-11 01:32:09.015008', false, 1359356949, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECmmdpEmOeUsoBBXUv0zthVWSw5UbmUAACkRBrG3lKkUgTGTrlHiaGxgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "КиберПанк ,с красивым ширифтом", "operation": "gen-multi-input"}', 'hqrc17q6zsrma0ctdzjty4vyw4', 'succeeded', '{"date": 1762813894, "chatId": 7906185103, "messageId": 170682}', '{"date": 1762813914, "chatId": 7906185103, "messageId": 170687}', '[{"date": 1762813939, "chatId": 7906185103, "messageId": 170693}]');
INSERT INTO public.operations VALUES ('94005ff9-0b51-4d94-b61c-9a856ccf8b71', '2025-10-20 13:58:51.758773', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Создай фото мужчины и девушки  по пояс. Максимально сохрани внешность мужчины и девушки . Мужчина смотрит в камеру , девушка стоит по правую сторону за его спиной и тоже смотрит в камеру касаясь правой рукой его плечо. Мужчина одет в белую рубашку с открытым воротником. У девушки виден черное платье с рукавами и глубоким вырезом на груди. У девушки черные, длинные, прямые волосы. Фон черный. Внешность девушки максимально естественна, без макияжа.", "operation": "gen-multi-input"}', 'vzg4q3n1ndrmc0ct052spyfndw', 'succeeded', '{"date": 1760957919, "chatId": 1287537311, "messageId": 115802}', '{"date": 1760957930, "chatId": 1287537311, "messageId": 115807}', '[{"date": 1760957941, "chatId": 1287537311, "messageId": 115808}]');
INSERT INTO public.operations VALUES ('f3cc1f09-ea00-4b3e-a573-b18670087fbe', '2025-10-20 11:51:49.627364', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото молодой девушки. Максимально сохрани мою внешность. Качество фото более естественное и четкое . Девушка сидит облокотившись на спинку кресла,  на низком пластиков вязаном кресле темно коричнево цвета , на против  стоит такой же стол, на стеклянном балконе. На фоне виден бассейн и пальмы. Девушка одета в белый халат, волосы длинные, черные и прямые. Погода яркая солнечная. Девушка смотрит в бок. Ногу закинула на другую ногу . Голову положила на руку которая стоит на подлокотнике. Лицо направлено на камеру. На столе стоит Бакал на длинной ножке с коктейлем.", "operation": "gen-multi-input"}', '88s76ftm29rme0ct038rt5xprr', 'succeeded', '{"date": 1760950284, "chatId": 1287537311, "messageId": 115514}', '{"date": 1760950308, "chatId": 1287537311, "messageId": 115519}', '[{"date": 1760950319, "chatId": 1287537311, "messageId": 115520}]');
INSERT INTO public.operations VALUES ('4405111f-57b1-4cec-8efa-69034e7a0352', '2025-10-20 12:51:34.184812', false, 9589215708, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBw8Fo9gX8notE8iCIN_gttwsGYiyaMQACsPoxGy09sEs4QJzL33yq2AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай зимнюю версию загруженной фотографии. Сохрани позу и освещение в точности. Добачь естесвенную снежную атмосферу и падающие с неба снежинки. Земля, крыши, деревья должны быть покрыты слоем снега, озеро должно покрыться льдом. Тропинки могут засыппны слоем снега", "operation": "gen-multi-input"}', 'j6wbgtg6m1rma0ct0449my4eq8', 'succeeded', '{"date": 1760953852, "chatId": 5249767944, "messageId": 115649}', '{"date": 1760953861, "chatId": 5249767944, "messageId": 115654}', '[{"date": 1760953905, "chatId": 5249767944, "messageId": 115655}]');
INSERT INTO public.operations VALUES ('5e60bdda-8c08-4671-b331-c9c0bdd227c7', '2025-10-20 14:08:48.195279', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Девушка стоит слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в белую рубашку, мужчина одет в черную водолазку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность пары", "operation": "gen-multi-input"}', '715rs4xvtsrmc0ct057ayankdw', 'succeeded', '{"date": 1760958520, "chatId": 1287537311, "messageId": 115818}', '{"date": 1760958527, "chatId": 1287537311, "messageId": 115823}', '[{"date": 1760958538, "chatId": 1287537311, "messageId": 115824}]');
