INSERT INTO public.operations VALUES ('d53aec25-4476-4ecb-bdc4-f27bdb0bcde8', '2025-10-20 11:53:04.012786', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBu4Bo9Ln_YJaAkerwvHXjmgeYnn-YCQACtvIxG_kQqEvxg1VFJ6-k5AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото молодой девушки. Максимально сохрани мою внешность. Качество фото более естественное и четкое . Девушка сидит облокотившись на спинку кресла,  на низком пластиков вязаном кресле темно коричнево цвета , на против  стоит такой же стол, на стеклянном балконе. На фоне виден бассейн и пальмы. Девушка одета в белый халат, волосы длинные, черные и прямые. Погода яркая солнечная. Девушка смотрит в бок. Ногу закинула на другую ногу . Голову положила на руку которая стоит на подлокотнике. Лицо направлено на камеру. На столе стоит Бакал на длинной ножке с коктейлем.", "operation": "gen-multi-input"}', 'qwgk8qbpd1rme0ct039a1zazq0', 'succeeded', '{"date": 1760950370, "chatId": 1287537311, "messageId": 115528}', '{"date": 1760950373, "chatId": 1287537311, "messageId": 115533}', '[{"date": 1760950395, "chatId": 1287537311, "messageId": 115538}]');
