INSERT INTO public.operations VALUES ('45868c14-d31b-4147-a826-f047cf893741', '2025-10-20 12:00:49.868864', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBw3Vo9fl_FZeKcH0TXeayzirN3XhnwAACsPwxG3jmsUu52AcfeKY6OgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "На изображении в полный рост запечатлена  стройная девушка, лежащая на полу. Фон белый и размытый.Она одета в черный облегающий комбинезон с длинными рукавами и колготки. На ногах у нее черные туфли на каблуках. Волосы длинные, прямые и черные, распущены и падают на плечи.Она смотрит прямо в камеру с нейтральным выражением лица. Одна рука лежит на согнутом колене, другая опирается на пол.", "operation": "gen-multi-input"}', 'hgp4jemj6nrme0ct03cvpepkrc', 'succeeded', '{"date": 1760950799, "chatId": 991429758, "messageId": 115587}', '{"date": 1760950848, "chatId": 991429758, "messageId": 115593}', '[{"date": 1760950860, "chatId": 991429758, "messageId": 115596}]');
