INSERT INTO public.operations VALUES ('5cea1a6e-7aab-4a52-b39c-18db32f3f78c', '2025-10-20 11:57:44.852686', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBw3Vo9fl_FZeKcH0TXeayzirN3XhnwAACsPwxG3jmsUu52AcfeKY6OgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "На изображении крупным планом изображена женщина с ярким макияжем и украшениями. У нее светлая кожа, голубые глаза, подчеркнутые черной подводкой, и четко очерченные брови. На губах - красная помада. Волосы уложены назад и выглядят влажными.Она одета в красную водолазку. На шее надето золотое ожерелье в виде широкой металлической полосы. На ушах видны крупные золотые серьги, а на запястьях – широкие золотые браслеты. Руки женщины находятся за головой. Фон нейтральный, серого цвета.", "operation": "gen-multi-input"}', 'hnp43k5zn9rm80ct03b9xb53f4', 'succeeded', '{"date": 1760950655, "chatId": 991429758, "messageId": 115573}', '{"date": 1760950659, "chatId": 991429758, "messageId": 115576}', '[{"date": 1760950674, "chatId": 991429758, "messageId": 115577}]');
