INSERT INTO public.operations VALUES ('68ab0571-fc98-4a26-8ceb-0ac0da8d2897', '2025-10-20 12:02:32.396016', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBwjho9a6TRSoWZJWB39CGU_ToivyfgwAC_v8xGwr_qEvalxMozKmB_QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На изображении в полный рост запечатлена стройная девушка, лежащая на полу. Фон белый и размытый.Она одета в черный облегающий комбинезон с длинными рукавами и колготки. На ногах у нее черные туфли на каблуках. Волосы длинные, прямые и черные, распущены и падают на плечи.Она смотрит прямо в камеру с нейтральным выражением лица. Одна рука лежит на согнутом колене, другая опирается на пол.Черты лица хорошо выражены.", "operation": "gen-multi-input"}', 'x1fjnd12jnrmc0ct03dvnhyf58', 'succeeded', '{"date": 1760950912, "chatId": 991429758, "messageId": 115602}', '{"date": 1760950950, "chatId": 991429758, "messageId": 115615}', '[{"date": 1760950963, "chatId": 991429758, "messageId": 115616}]');
INSERT INTO public.operations VALUES ('f78db2f0-7ad2-4296-bbd7-ab7605b8e89e', '2025-10-20 13:56:41.575036', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Создай фото мужчины и девушки  по пояс. Максимально сохрани внешность мужчины и девушки . Мужчина смотрит в камеру , девушка стоит за его спиной и тоже смотрит в камеру касаясь правой рукой его плечо. Мужчина одет в белую рубашку с открытым воротником. У девушки виден черное платье с рукавами и глубоким вырезом на груди. У девушки черные, длинные, прямые волосы. Фон белый", "operation": "gen-multi-input"}', '1cw8mqx579rme0ct051r7gscjc', 'succeeded', '{"date": 1760957764, "chatId": 1287537311, "messageId": 115794}', '{"date": 1760957800, "chatId": 1287537311, "messageId": 115799}', '[{"date": 1760957812, "chatId": 1287537311, "messageId": 115800}]');
INSERT INTO public.operations VALUES ('1f560f5d-f052-4eb7-a6cf-3fb313624725', '2025-10-20 12:12:13.9569', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBw6No9fyt8XTjTMebysMGbTH5piJtDQACwPwxG3jmsUt_fYEiYAdkJgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "На фотографии изображена стройная девушка, сидящая на корточках на фоне стены.У девушки длинные темные волосы, уложенные на одну сторону. Она одета в короткое белое атласное платье с открытой спиной и завязками сзади. На ногах у нее белые туфли на каблуке с тонкими ремешками, завязывающимися вокруг щиколотки.За девушкой находится стена, отделанная серыми деревянными панелями. В верхнем левом углу стены находится квадратное вентиляционное отверстие с горизонтальными черными решетками.Пол под женщиной покрыт серым текстурированным покрытием, напоминающим плитку.", "operation": "gen-multi-input"}', 'nsx26b82vnrmc0ct03j90prjf0', 'succeeded', '{"date": 1760951469, "chatId": 991429758, "messageId": 115619}', '{"date": 1760951532, "chatId": 991429758, "messageId": 115622}', '[{"date": 1760951543, "chatId": 991429758, "messageId": 115623}]');
INSERT INTO public.operations VALUES ('c1089647-bdd8-44fa-9c1c-5ffb47b9d1f8', '2025-10-20 14:52:14.80195', false, 8527591795, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "9:16"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEBxRlo9iAwmxWDTHe_Ieibr0kPGJ3rowACttAxG4qhsVMBctXpVXO3qwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1064, "heightPx": 1280}], "prompt": "Ai", "operation": "gen-multi-input"}', '9ya2qkc1wdrma0ct05va2tgbxg', 'succeeded', '{"date": 1760960560, "chatId": 691784114, "messageId": 115993}', '{"date": 1760961114, "chatId": 691784114, "messageId": 116018}', '[{"date": 1760961152, "chatId": 691784114, "messageId": 116019}]');
