INSERT INTO public.operations VALUES ('02b0243e-92cb-4fc4-84ce-30a46e0a8d01', '2025-10-20 13:44:23.612324', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxDdo9hJ65ATHP-WvvT6uzK8UacQfywACmwABMhuvDrBLKGfk30vnjL8BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Create a cinematic black and white portrait of me in 8K, adjusting my tie while wearing a classic tailor-made suit, standing confidently in a studio with strong side lighting creating high contrast. Horizontal streaks of light (like light coming through curtains) cast shadows on my face and suit. The expression is calm and confident, exuding elegance and determination. High-fashion, editorial style. Highly detailed, minimal, and symmetrical composition.", "operation": "gen-multi-input"}', 'fzb7zf32hxrm80ct04w997a680', 'succeeded', '{"date": 1760957050, "chatId": 1287537311, "messageId": 115767}', '{"date": 1760957062, "chatId": 1287537311, "messageId": 115772}', '[{"date": 1760957074, "chatId": 1287537311, "messageId": 115773}]');
INSERT INTO public.operations VALUES ('f77dc860-44c8-401e-aa12-fa348dca7cf1', '2025-10-20 12:13:00.102333', false, 2950187302, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBw6No9fyt8XTjTMebysMGbTH5piJtDQACwPwxG3jmsUt_fYEiYAdkJgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "На фотографии изображена женщина, сидящая на корточках на фоне стены.У женщины длинные темные волосы, уложенные на одну сторону. Она одета в короткое белое атласное платье с открытой спиной и завязками сзади. На ногах у нее белые туфли на каблуке с тонкими ремешками, завязывающимися вокруг щиколотки.За женщиной находится стена, отделанная серыми деревянными панелями. В верхнем левом углу стены находится квадратное вентиляционное отверстие с горизонтальными черными решетками.Пол под женщиной покрыт серым текстурированным покрытием, напоминающим плитку.\nСохрани черты лица", "operation": "gen-multi-input"}', '0t8qfpnpg1rmc0ct03j95bj938', 'failed', '{"date": 1760951567, "chatId": 991429758, "messageId": 115626}', '{"date": 1760951578, "chatId": 991429758, "messageId": 115629}', '[{"date": 1760951578, "chatId": 991429758, "messageId": 115629}]');
