INSERT INTO public.operations VALUES ('58d423ae-5905-4c22-bc95-2ab495946025', '2025-10-20 13:47:27.917304', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxDdo9hJ65ATHP-WvvT6uzK8UacQfywACmwABMhuvDrBLKGfk30vnjL8BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Мужской Промт: \n\nСделай мою фотографию с высоты птичьего полета, с высоким углом обзора 3:4, в полный рост, на которой изображен парень, расслабленно облакотившийся на капот оранжевого Lamborghini Urus в полутемном подвальном гараже.\nОдетый в черный костю кэжуал , на черно-белые кроссовки найк Джордан. Мягкое освещение в виде солнечных лучей с естественными отражениями от автомобиля,\nкинематографическая теплая цветопередача, небольшая глубина резкости, кремовое боке, гиперреалистичная детализация 8K, ат-\nАтмосфера миллиардера. Не меняй черты лица", "operation": "gen-multi-input"}', '7vswkq9jhnrma0ct04xrkatxjw', 'succeeded', '{"date": 1760957239, "chatId": 1287537311, "messageId": 115774}', '{"date": 1760957246, "chatId": 1287537311, "messageId": 115779}', '[{"date": 1760957258, "chatId": 1287537311, "messageId": 115780}]');
INSERT INTO public.operations VALUES ('24f7f9f0-a1bc-4234-bcb2-48cb406e4535', '2025-10-20 14:01:47.685387', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Создай фото мужчины и девушки  по пояс. Максимально сохрани внешность мужчины и девушки . Мужчина смотрит в камеру , девушка стоит по правую сторону за его спиной и тоже смотрит в камеру . Мужчина одет в белую рубашку с открытым воротником. Девушку видно чуть выше груди. У девушки черные, длинные, прямые волосы. Фон черный. Внешность девушки максимально естественна, без макияжа.", "operation": "gen-multi-input"}', 'bn7248jh6nrmc0ct054btbxheg', 'succeeded', '{"date": 1760958103, "chatId": 1287537311, "messageId": 115810}', '{"date": 1760958106, "chatId": 1287537311, "messageId": 115815}', '[{"date": 1760958118, "chatId": 1287537311, "messageId": 115816}]');
INSERT INTO public.operations VALUES ('e25cd382-b054-4e0b-98ef-f2e6dbb41da1', '2025-10-20 13:55:05.167236', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Создай фото мужчины и девушки  по пояс. Максимально сохрани внешность мужчины и девушки . Мужчина смотрит в камеру , девушка стоит за его спиной и тоже смотрит в камеру касаясь правой рукой его плечо. Мужчина одет в белую рубашку с открытым воротником. У девушки виден черное платье с рукавами и глубоким вырезом на груди. У девушки черные, длинные, прямые волосы.", "operation": "gen-multi-input"}', 'hhvv9bhcn5rme0ct0518bhw6cr', 'succeeded', '{"date": 1760957675, "chatId": 1287537311, "messageId": 115782}', '{"date": 1760957703, "chatId": 1287537311, "messageId": 115787}', '[{"date": 1760957715, "chatId": 1287537311, "messageId": 115788}]');
