INSERT INTO public.operations VALUES ('7c12baa3-c615-4a9e-9e8c-68ecea390ef1', '2025-10-20 14:10:28.175844', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Девушка стоит позади мужчины слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в белую рубашку, мужчина одет в черную водолазку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность пары. Фон белый", "operation": "gen-multi-input"}', '30hxewa7edrm80ct0589hjxdnc', 'succeeded', '{"date": 1760958593, "chatId": 1287537311, "messageId": 115825}', '{"date": 1760958627, "chatId": 1287537311, "messageId": 115830}', '[{"date": 1760958639, "chatId": 1287537311, "messageId": 115831}]');
