INSERT INTO public.operations VALUES ('85e06450-f078-4dbc-aa7d-e473945ab4d9', '2025-10-20 14:14:39.989376', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Девушка стоит позади мужчины слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в черную кофту, мужчина одет в белую рубашку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность девушки. Фон белый.", "operation": "gen-multi-input"}', '4vbvmgrswdrme0ct05aa7jmxtc', 'succeeded', '{"date": 1760958794, "chatId": 1287537311, "messageId": 115839}', '{"date": 1760958879, "chatId": 1287537311, "messageId": 115844}', '[{"date": 1760958891, "chatId": 1287537311, "messageId": 115845}]');
