INSERT INTO public.operations VALUES ('7a3d54a7-220f-4774-8b82-e771b02f60b1', '2025-10-20 14:17:43.633941', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Молодая Девушка стоит позади мужчины слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в черную кофту, мужчина одет в белую рубашку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность девушки. Фон бежевый. На пару падает солнечный свет", "operation": "gen-multi-input"}', 'stz8waz73nrmc0ct05bae451rc', 'failed', '{"date": 1760959038, "chatId": 1287537311, "messageId": 115871}', '{"date": 1760959062, "chatId": 1287537311, "messageId": 115883}', '[{"date": 1760959062, "chatId": 1287537311, "messageId": 115883}]');
