INSERT INTO public.operations VALUES ('64a01e30-6988-4ce8-b5ca-59d715345990', '2025-10-20 18:33:21.018001', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Молодая Девушка стоит позади мужчины слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в черную кофту, мужчина одет в белую рубашку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность девушки. Фон бежевый. На мужчину и девушку падает солнечный свет. На руке девушки тонкий золотой браслет. Фото сделано в черно-белом цвете", "operation": "gen-multi-input"}', 'n4b1wfqemnrmc0ct0909rx3emc', 'succeeded', '{"date": 1760974360, "chatId": 1287537311, "messageId": 116398}', '{"date": 1760974399, "chatId": 1287537311, "messageId": 116406}', '[{"date": 1760974411, "chatId": 1287537311, "messageId": 116407}]');
