INSERT INTO public.operations VALUES ('03e7bc17-24c0-44a8-887d-bec1bd212d02', '2025-10-20 18:40:28.290533', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBxEZo9hTrnuen9EwNW2mtu8GZw6I2CQACvwABMhuvDrBLz2Ti94RplBYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "На фото изображена пара . Молодая Девушка стоит позади мужчины слева и положила руку на плечо мужчины , чуть касаясь подбородком руку. Другой рукой она обнимает мужчину по стороны шеи положив руку на грудь. Мужчина положил свою руку на руку женщины которой она его обнимает. Девушка одета в черную кофту, мужчина одет в черную однотонную футболку . Волосы девушки черные, длинные и прямые. Фото сделано по пояс, мужчина и девушка смотрят прямо в камеру. Максимально сохрани внешность девушки. Фон бежевый. На мужчину и девушку падает солнечный свет. На руке девушки тонкий золотой браслет.", "operation": "gen-multi-input"}', 'e9814w3vd1rme0ct093taw2930', 'succeeded', '{"date": 1760974823, "chatId": 1287537311, "messageId": 116472}', '{"date": 1760974826, "chatId": 1287537311, "messageId": 116477}', '[{"date": 1760974840, "chatId": 1287537311, "messageId": 116478}]');
