INSERT INTO public.operations VALUES ('d265b2be-7491-4ea1-9cf6-75499d71b171', '2025-10-21 03:03:57.173494', false, 9714620937, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEByjNo9srfISyGCEFI9WaEN7NbpkakZgACGvcxG_F2uUunRfZDWhuL5QEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 710}], "prompt": "Фотореалистичное изображение:парень с девушкой в полный рост у девушки такие же\n, нос  более аккуратный , замени щеки на скулы лицо худое , в губах она держит косяк ,легкий макияж в носу пирсинг типа кольца , на девушке черная толстовка на голове капюшон , на пальцах маникюр , парень игриво улыбаясь смотря в камеру типа кусает ее за щеку) на парне коротенькая.черная шапка , замени фон на рейв тусовку", "operation": "gen-multi-input"}', 'e5p3amb77srme0ct0gaax85r9m', 'succeeded', '{"date": 1761005021, "chatId": 7972373585, "messageId": 117321}', '{"date": 1761005035, "chatId": 7972373585, "messageId": 117328}', '[{"date": 1761005047, "chatId": 7972373585, "messageId": 117329}]');
