INSERT INTO public.operations VALUES ('9e68156e-90b9-46ec-bdf1-a928ea63d064', '2025-10-21 11:05:59.956554', false, 7267149040, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBy3Fo9z7a3dcDXHfePTi8X5NP9OEQhwACRPoxG408uUt8Rmn9bVhCYQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}, {"file": {"fileId": "AgACAgIAAxkBAAEBy3Jo9z7aiujY71MQGDerbPtsoNoDKgACRfoxG408uUtySdB70v0TFwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 480, "heightPx": 1280}], "prompt": "На основе этих фото сделай так, чтобы фотография двух людей выглядела так, будто её сняли на Polaroid. На ней не должно быть никаких очевидных объектов или реквизита. Она должна выглядеть как мгновенный снимок без особых деталей. Добавь легкое размытие движения и свет вспышки камеры к тёмной области, чтобы он равномерно распределился по всей фотографии. Не искажайте лицо. Замени фон за двумя людьми на белую завесу. Парень должен обнимать и целовать меня в щёку.", "operation": "gen-multi-input"}', 'p4y9zfdtknrme0ct0q6s4dzaar', 'succeeded', '{"date": 1761033946, "chatId": 7915148308, "messageId": 117617}', '{"date": 1761033955, "chatId": 7915148308, "messageId": 117621}', '[{"date": 1761033974, "chatId": 7915148308, "messageId": 117625}]');
