INSERT INTO public.operations VALUES ('a6b4f2a4-9b8d-4ebd-8899-ddbbd87923db', '2025-10-21 15:00:57.490428', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzL9o93XfaHk4Jm4QFsjBgqUC1Y4qygACcP0xG68OuEtl-xrvTD7nIAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 982, "heightPx": 1280}], "prompt": "На фотографии изображена женщина с темными волосами и карими глазами. Её волосы черные, длинные, уложены большими волнами, они объемны и они ниспадают на плечи. цепочка на шее. Она смотрит в сторону от камеры. Фон изображения - бежевый и на лицо попадает лучик солнца Плечи обнажены. Фото сделано более естественным и четким", "operation": "gen-multi-input"}', 'zk0xtmyqdhrm80ct0tjadvnkfw', 'failed', '{"date": 1761048031, "chatId": 1287537311, "messageId": 117951}', '{"date": 1761048056, "chatId": 1287537311, "messageId": 117957}', '[{"date": 1761048056, "chatId": 1287537311, "messageId": 117957}]');
