INSERT INTO public.operations VALUES ('0a530495-517c-44e3-8e2e-7c9c981906a8', '2025-10-29 00:01:49.297524', false, 9920339733, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAAGTaQEszmKrQmvYRGuSrJ_QhZgBXM4AAp3-MRv-AQlIIWa64kbzP4YBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1120, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAGmaQEuJqzaiOyv5GbKHxHcgfMBawoAAvj5MRsTyyFIfNC8g4nxkP0BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAG0aQEvNfG5FcyfuxL2ZLFpWZXMacoAAhb9MRtkfQhIZTNGT_JRyPUBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Эталонное изображение: [нагруженное фото] \nЛицо: сохраните исходное лицо с эталонного изображения, но с натуральным светлым цветом волос, слегка влажной текстурой, выразительным взглядом с сильными тенями на лице, сияющей на солнце кожей. \nПоза: женщина, стоящая на мелководье, опираясь на руки, грациозно выгнув спину, повернув голову к камере, элегантная и властная поза. \nОдежда: платье или боди цвета золотистого металла с мерцающей отражающей текстурой, мокрая поверхность которых отражает солнечный свет, при этом сохраняются естественные складки и блеск. \nАксессуары: широкий золотой браслет-металлик на запястье, маленькие золотые серьги. \nПрическа: влажные светлые волосы зачесаны назад, плавно и естественно струятся. \nФон: открытая вода со спокойной поверхностью, отражающей голубое небо, слегка размытый горизонт, вечерний или ранний утренний солнечный свет, создающий теплые блики. \nАтмосфера: кинематографическая, чувственная и в то же время элегантная, сильный контраст между золотистыми тонами и холодными голубыми отблесками, освещение в редакционном стиле, подчеркивающее форму и текстуру. \nФормат: 2:3 \nНе заменять лицо", "operation": "gen-multi-input"}', 'g8vyrqw80srme0ct5jg9aj6w58', 'succeeded', '{"date": 1761685301, "chatId": 702968411, "messageId": 131250}', '{"date": 1761685306, "chatId": 702968411, "messageId": 131255}', '[{"date": 1761685321, "chatId": 702968411, "messageId": 131256}]');
