INSERT INTO public.operations VALUES ('d645acc7-73b4-46ce-8812-ba5ad2b4033b', '2025-10-21 15:32:40.435157', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzTto931jmt5huQcE3J6Tda4YlI7goAACwP0xG68OuEurey-7-WrJ5wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 591, "heightPx": 1280}], "prompt": "На фото изображены мама и дочь. Молодая Девушка стоит позади женщины слева и положила руку на плечо , чуть касаясь подбородком руку. Другой рукой она обнимает женщину по стороны шеи положив руку на грудь. Женщина положил свою руку на руку девушки которой она ее обнимает. Девушка одета в черную кофту, женщина одета в черную кофту. Волосы женщин черные, длинные и ухоженны большими волнами. Фото сделано по пояс, женщина и девушка смотрят прямо в камеру. Максимально сохрани внешность. Фон бежевый. На женщину  и девушку падает солнечный свет. На руке девушки тонкий золотой браслет. На шее женщины цепочка .", "operation": "gen-multi-input"}', 'mqeytjq195rm80ct0v0rvp172r', 'succeeded', '{"date": 1761049955, "chatId": 1287537311, "messageId": 118075}', '{"date": 1761049959, "chatId": 1287537311, "messageId": 118080}', '[{"date": 1761049971, "chatId": 1287537311, "messageId": 118083}]');
INSERT INTO public.operations VALUES ('ad2efe3f-5071-4ae9-b1b3-9c8eb579d773', '2025-10-27 12:44:53.123132', false, 7116811525, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB9nto_z7tHDtbfoHOZ5nT4kUjtYbjewACDv4xG5t9-Uve1ubZ-pvufQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 1176}, {"file": {"fileId": "AgACAgIAAxkBAAEB9nxo_z7tmEol6HVGgF6XnSxc4mjM3AACevoxGz9D4Eu2u_-HEiYXkAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Фотореалистичное портретное фото в формате вертикального кадра, высокая детализация, мягкий естественный свет на открытом воздухе. Женщина слегка наклоняет голову и бережно держит младенца, прижатого к груди; ребёнок накрыт лёгким белым пледом с мелким детским принтом (милые синие зверюшки, пастельные оттенки). Женщина в простой белой рубашке с мягкой текстурой хлопка, видны руки, аккуратно поддерживающие спину и голову ребёнка. Фон — зелёная трава с мягким боке и тёплым дневным светом, нежные тени, спокойная тёплая цветовая палитра (зелёный, белый, пастель). Низкая глубина резкости, естественная кожа, мягкая фильмовая зернистость, реалистичные текстуры ткани и волос, интимная тёплая атмосфера, 85mm портретный объектив, f/1.8, мягкая постобработка, высокое разрешение.", "operation": "gen-multi-input"}', 'c3rckd3cjxrmc0ct4m7agathz0', 'succeeded', '{"date": 1761558253, "chatId": 1966741829, "messageId": 128635}', '{"date": 1761558279, "chatId": 1966741829, "messageId": 128639}', '[{"date": 1761558308, "chatId": 1966741829, "messageId": 128640}]');
INSERT INTO public.operations VALUES ('5995bc4e-00c1-409a-9355-c70baaaeff20', '2025-10-21 15:36:23.743672', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzTto931jmt5huQcE3J6Tda4YlI7goAACwP0xG68OuEurey-7-WrJ5wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 591, "heightPx": 1280}], "prompt": "На фото изображены 2 женщины. Одна стоит позади другой с левой стороны и положила руку на плечо. Обе женщины одеты в черные кофты с рукавами . У обоих женщин черные длинные волосы уложены большими волнами. Обе женщины смотрят прямо в камеру. Фон - бежевый . На лицо женщин падает солнечный свет.", "operation": "gen-multi-input"}', 'x4ddgv28w1rmc0ct0v2r38s21r', 'succeeded', '{"date": 1761050177, "chatId": 1287537311, "messageId": 118095}', '{"date": 1761050182, "chatId": 1287537311, "messageId": 118100}', '[{"date": 1761050193, "chatId": 1287537311, "messageId": 118101}]');
