INSERT INTO public.operations VALUES ('b90983e2-b3e8-4d6c-ab6e-044ab25c05e5', '2025-10-21 15:35:46.549559', false, 9427303225, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzUVo933gk1b8EyVV5iQfeMjrCbRuGgACDP0xG7dXuUtyMC1DyYjVrgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 719, "heightPx": 1138}], "prompt": "Сделай так, чтобы были кадры с фотосессии. Девочка одета в нежно голубое платье", "operation": "gen-multi-input"}', '0as2gkdqr1rm80ct0v2a0sty14', 'succeeded', '{"date": 1761050080, "chatId": 7521835327, "messageId": 118085}', '{"date": 1761050144, "chatId": 7521835327, "messageId": 118092}', '[{"date": 1761050157, "chatId": 7521835327, "messageId": 118093}]');
INSERT INTO public.operations VALUES ('7439bd36-8f6d-422a-a6e9-6df5838bf86d', '2025-10-21 15:32:49.197874', false, 9427303225, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzTdo930cgRrZhLbh9oYItGQjF9l5egACB_0xG7dXuUsUBmEvMaZ6owEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}, {"file": {"fileId": "AgACAgIAAxkBAAEBzTho930cp80BMwu6IZI6exIheu0uXAACCP0xG7dXuUse02GS3W62GAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 414, "heightPx": 1280}], "prompt": "На основе этих фото сделай так, чтобы фотография двух людей выглядела так, будто её сняли на Polaroid. На ней не должно быть никаких очевидных объектов или реквизита. Она должна выглядеть как мгновенный снимок без особых деталей. Добавь легкое размытие движения и свет вспышки камеры к тёмной области, чтобы он равномерно распределился по всей фотографии. Не искажайте лицо. Замени фон за двумя людьми на белую завесу. Парень должен обнимать и целовать меня в щёку", "operation": "gen-multi-input"}', '1g718zg3gdrme0ct0v18qmmgec', 'succeeded', '{"date": 1761049885, "chatId": 7521835327, "messageId": 118071}', '{"date": 1761049964, "chatId": 7521835327, "messageId": 118082}', '[{"date": 1761049983, "chatId": 7521835327, "messageId": 118084}]');
