INSERT INTO public.operations VALUES ('c5fc6bd6-d69f-4959-ac4a-a18a75e76f3e', '2025-10-21 17:30:53.11279', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzkNo95jO6fRXkUNPB1K_Ol5flWrFxQACn_4xG68OuEt62JfhYQtDWAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1109, "heightPx": 791}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото по пояс.", "operation": "gen-multi-input"}', '72wapjgtm5rmc0ct0wqassj87r', 'succeeded', '{"date": 1761056974, "chatId": 1287537311, "messageId": 118339}', '{"date": 1761057052, "chatId": 1287537311, "messageId": 118344}', '[{"date": 1761057064, "chatId": 1287537311, "messageId": 118345}]');
INSERT INTO public.operations VALUES ('590be0f9-9e12-40a5-a6e4-8c6fea8f2530', '2025-10-27 13:09:10.95374', false, 8399924077, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [], "prompt": "Сгенерируй изображение с мотоциклетным шлемом agv pista, который лежит на столе", "operation": "gen-multi-input"}', '01t5d9da0nrme0ct4mjbpe0qjc', 'succeeded', '{"date": 1761559719, "chatId": 5001877117, "messageId": 128680}', '{"date": 1761559719, "chatId": 5001877117, "messageId": 128681}', '[{"date": 1761559762, "chatId": 5001877117, "messageId": 128682}]');
INSERT INTO public.operations VALUES ('7fdc9c41-d6d1-4364-9605-ecb2976f6745', '2025-10-27 13:22:13.823313', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB9qto_0fM3ceSqPBIr16Gr-h_xcA7BgACbgABMhs2oPlL9gVbZXiUHzQBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 577, "heightPx": 1280}], "prompt": "Задание для обработки фотографии:\nИсходное изображение:\nСохранить все естественные черты лица без искажений\nСохранить пропорции лица и общую композицию фото\nТрансформация внешности:\nПреобразовать прическу в стильную стрижку до плеч\nДобавить объем и текстуру волосам\nИзменить цвет волос на естественный блонд с теплым подтоном\nВыполнить профессиональный макияж:\nАкцент на глаза (естественные тени, тушь)\nРовный тон кожи без излишнего блеска\nНежные румяна\nНатуральный блеск для губ или нюдовая помада\nКачество изображения:\nСохранить исходное разрешение\nОбеспечить четкость и детализацию\nИзбежать артефактов и размытия\nСохранить естественное освещение\nДополнительные требования:\nРезультат должен выглядеть естественно\nНикаких неестественных эффектов или фильтров\nСохранение общего стиля и характера модели\nПрофессиональное качество обработки", "operation": "gen-multi-input"}', 'mxxrsqww9hrm80ct4mrbs9mcf4', 'succeeded', '{"date": 1761560524, "chatId": 1091595273, "messageId": 128683}', '{"date": 1761560531, "chatId": 1091595273, "messageId": 128688}', '[{"date": 1761560547, "chatId": 1091595273, "messageId": 128689}]');
INSERT INTO public.operations VALUES ('f4677d64-27ca-4c82-99ec-9be519cce4b5', '2025-10-21 15:52:46.720796', false, 9427303225, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzZVo94HWGEq_jzZ8_ZM5aUFVvuLgRQACpQcyG7dXwUtx57SQjj3GJAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 719, "heightPx": 1138}, {"file": {"fileId": "AgACAgIAAxkBAAEBzZZo94HWFbr6eZD9N-8R8VAQdDGWigACpgcyG7dXwUsP-zrOQzkGPgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "На основе этих фото сделай так, чтобы фотография двух людей выглядела так, будто её сняли на Polaroid. На ней не должно быть никаких очевидных объектов или реквизита. Она должна выглядеть как мгновенный снимок без особых деталей. Добавь легкое размытие движения и свет вспышки камеры к тёмной области, чтобы он равномерно распределился по всей фотографии. Не искажайте лицо. Замени фон за двумя людьми на белую завесу. Парень должен обнимать и целовать меня в щёку", "operation": "gen-multi-input"}', 'yws8dsj8whrme0ct0va8a0bja8', 'succeeded', '{"date": 1761051157, "chatId": 7521835327, "messageId": 118174}', '{"date": 1761051164, "chatId": 7521835327, "messageId": 118178}', '[{"date": 1761051180, "chatId": 7521835327, "messageId": 118179}]');
INSERT INTO public.operations VALUES ('29238ff8-2997-421f-b45f-29c88fe8d290', '2025-10-21 16:12:30.72728', false, 4959953036, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzapo94ZgR18eZgQG_EVUYtCejiWx2AAC3_8xG1tIwEtfhqnGrED0NQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Сделай фон в стиле гангстеров в светлых оттенках", "operation": "gen-multi-input"}', '7yrz5njsw1rm80ct0vk9shmtar', 'succeeded', '{"date": 1761052256, "chatId": 865051954, "messageId": 118186}', '{"date": 1761052337, "chatId": 865051954, "messageId": 118198}', '[{"date": 1761052362, "chatId": 865051954, "messageId": 118199}]');
INSERT INTO public.operations VALUES ('d8658957-5fe6-48a0-a463-407b20faef1a', '2025-10-28 21:02:26.092997', false, 9160907275, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB_5ppAQUtJibFoD2IMnLNpBYymWsbhAACWyYyGwABXwhI4jit0kGGsXoBAAMCAAN4AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 640}], "prompt": "Используя это фото сделай модный портрет женщины стоящий перед камерой. Она держит черную корону над головой, богато украшенную. Освещение падает сверху. Платье её чёрное круживо", "operation": "gen-multi-input"}', 'akp2ptjcpnrma0ct5fyb4c059c', 'succeeded', '{"date": 1761674541, "chatId": 6067128586, "messageId": 130970}', '{"date": 1761674544, "chatId": 6067128586, "messageId": 130973}', '[{"date": 1761674557, "chatId": 6067128586, "messageId": 130974}]');
