INSERT INTO public.operations VALUES ('9c9cef1a-4e3b-43d6-ac9c-c5ba576030c7', '2025-10-21 19:15:06.741269', false, 1113296352, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzzJo97FvSTD0TOmXhc2VVwVf9HID4AACyfwxG1KUuEttHkhX9-LZgQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 694}], "prompt": "Сделай видео как эта машина превращается в робота из трансформеров", "operation": "gen-multi-input"}', 't0109n4ayhrme0ct0y6sm9c5pr', 'failed', '{"date": 1761063279, "chatId": 930572084, "messageId": 118578}', '{"date": 1761063295, "chatId": 930572084, "messageId": 118581}', '[{"date": 1761063295, "chatId": 930572084, "messageId": 118581}]');
INSERT INTO public.operations VALUES ('f2c9ea3c-d2c2-424d-8be9-8f002ba0f91a', '2025-10-21 16:33:47.963446', false, 4028882151, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzdFo94pc4iaXKaSpAfpQGopPfZz3JQAC6wMyGy7MwUsZDKJ0OAJNTwEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 710}], "prompt": "Создать реалистичную фотографию в полный рост в стиле «Полароид» на которой селфи девушка стоит перед ковром с советским узором, висящим на стене. Лицо более худое , подчеркнуть скулы , добавить легкий красивый  макияж , нос более аккуратый ,улыбается без зубов , в носу пирсинг  кольцо , в ушах серьги кольца на  ней[классический спортивный костюм Adidas и синяя бейсболка США]. лицо должно соответствовать загруженному селфи 1:1, естественное и неискаженное  сцена должна напоминать обычный домашний снимок 1990-х годов, сырой и аутентичный. белая рамка Polaroid с расширенной нижней рамкой, видимыми зернами пленки, фактурой бумаги, пылью, царапинами и едва заметным рассеянием света. цвета слегка блеклые с пастельными тонами. освещение от резкой вспышки на камере в темной комнате создает легкую передержку и плоские тени. откровенная фотография со вспышкой папарацци, неотредактированная и спонтанная", "operation": "gen-multi-input"}', '8mt6dz6qjhrm80ct0vwvz804y4', 'succeeded', '{"date": 1761053276, "chatId": 8262988091, "messageId": 118225}', '{"date": 1761053622, "chatId": 8262988091, "messageId": 118228}', '[{"date": 1761053639, "chatId": 8262988091, "messageId": 118229}]');
