INSERT INTO public.operations VALUES ('0c796039-4080-4d83-bef4-46d096c0f0bb', '2025-10-21 17:31:37.30599', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzipo95egLrlzeqUJwICFRW4Znw3GoAAClf4xG68OuEuJD6331PIP9AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 997}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото по пояс.", "operation": "gen-multi-input"}', 'hfe63ge7c5rm80ct0wq9tcey6r', 'succeeded', '{"date": 1761057075, "chatId": 1287537311, "messageId": 118346}', '{"date": 1761057096, "chatId": 1287537311, "messageId": 118351}', '[{"date": 1761057108, "chatId": 1287537311, "messageId": 118352}]');
