INSERT INTO public.operations VALUES ('81145de1-35e1-45ab-a3e9-552b936233b1', '2025-10-21 16:37:49.563151', false, 4028882151, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzdZo94yCHWF4M7YfjO1hFiQoBjW6tAACAgQyGy7MwUsMswNhnWeZYgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 992, "heightPx": 1056}], "prompt": "Создать реалистичную фотографию в полный рост в стиле «Полароид» на которой селфи девушка стоит перед ковром с советским узором, висящим на стене , подчеркнуть скулы , добавить легкий красивый  макияж , нос более аккуратый   , в ушах серьги кольца на  ней[классический спортивный костюм Adidas и синяя бейсболка США]. лицо должно соответствовать загруженному селфи 1:1, естественное и неискаженное  сцена должна напоминать обычный домашний снимок 1990-х годов, сырой и аутентичный. белая рамка Polaroid с расширенной нижней рамкой, видимыми зернами пленки, фактурой бумаги, пылью, царапинами и едва заметным рассеянием света. цвета слегка блеклые с пастельными тонами. освещение от резкой вспышки на камере в темной комнате создает легкую передержку и плоские тени. откровенная фотография со вспышкой папарацци, неотредактированная и спонтанная", "operation": "gen-multi-input"}', '007tknm6xnrm80ct0vyrd2ajzc', 'succeeded', '{"date": 1761053827, "chatId": 8262988091, "messageId": 118230}', '{"date": 1761053868, "chatId": 8262988091, "messageId": 118239}', '[{"date": 1761053881, "chatId": 8262988091, "messageId": 118240}]');
