INSERT INTO public.operations VALUES ('506dbd06-f4c8-47c4-9022-922bfa950d9f', '2025-10-21 17:32:46.764245', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzipo95egLrlzeqUJwICFRW4Znw3GoAAClf4xG68OuEuJD6331PIP9AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 997}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди.", "operation": "gen-multi-input"}', 'p411gy6pedrme0ct0wqrtzme9w', 'succeeded', '{"date": 1761057125, "chatId": 1287537311, "messageId": 118356}', '{"date": 1761057165, "chatId": 1287537311, "messageId": 118361}', '[{"date": 1761057177, "chatId": 1287537311, "messageId": 118362}]');
INSERT INTO public.operations VALUES ('1bfb0c6d-1cc2-45af-9689-360d1ca1a5e3', '2025-10-27 13:34:28.202583', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB9rNo_0p4b7OAOodNHg9dToKihVpI2wACgwABMhs2oPlL6Bc1zm1DXmUBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 1280}], "prompt": "Задание для обработки фотографии:\nИсходное изображение:\nСохранить все естественные черты лица без искажений\nСохранить пропорции лица и общую композицию фото\nТрансформация внешности:\nПреобразовать прическу в стильную стрижку до плеч\nДобавить объем и текстуру волосам\nИзменить цвет волос на естественный блонд с теплым подтоном\nВыполнить профессиональный макияж:\nАкцент на глаза (естественные тени, тушь)\nРовный тон кожи без излишнего блеска\nНежные румяна\nНатуральный блеск для губ или нюдовая помада\nКачество изображения:\nСохранить исходное разрешение\nОбеспечить четкость и детализацию\nИзбежать артефактов и размытия\nСохранить естественное освещение\nДополнительные требования:\nРезультат должен выглядеть естественно\nНикаких неестественных эффектов или фильтров\nСохранение общего стиля и характера модели\nПрофессиональное качество обработки\nОдежда: красивое платье на бретельках красного цвета с жемчугом\nВ руках шикарный букет белых и красных роз", "operation": "gen-multi-input"}', '8cwdp7egwhrmc0ct4mxs6pdzhg', 'succeeded', '{"date": 1761561208, "chatId": 1091595273, "messageId": 128691}', '{"date": 1761561264, "chatId": 1091595273, "messageId": 128696}', '[{"date": 1761561278, "chatId": 1091595273, "messageId": 128697}]');
