INSERT INTO public.operations VALUES ('a0150c0d-d58f-4f59-98c1-b154d062ca40', '2025-10-27 15:55:39.770843', false, 7116811525, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB905o_2u8duZy2j4dngFZlokL_lhwlwACsv8xG5t9-UsKh0rbPdK3mgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 629, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB76Fo_ZrV0I6I3MW-hgXJd-NOboK1PgACtwUyG-3i6Ut-skriPdv_VgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Фотореалистичное портретное фото в формате вертикального кадра, высокая детализация, мягкий естественный свет на открытом воздухе. Женщина слегка наклоняет голову и бережно держит младенца, прижатого к груди; ребёнок накрыт лёгким белым пледом с мелким детским принтом (милые синие зверюшки, пастельные оттенки). Женщина в простой белой рубашке с мягкой текстурой хлопка, видны руки, аккуратно поддерживающие спину и голову ребёнка. Фон — зелёная трава с мягким боке и тёплым дневным светом, нежные тени, спокойная тёплая цветовая палитра (зелёный, белый, пастель). Низкая глубина резкости, естественная кожа, мягкая фильмовая зернистость, реалистичные текстуры ткани и волос, интимная тёплая атмосфера, 85mm портретный объектив, f/1.8, мягкая постобработка, высокое разрешение.", "operation": "gen-multi-input"}', 'r3m0968n2nrm80ct4pyvkp0rm8', 'succeeded', '{"date": 1761569724, "chatId": 1966741829, "messageId": 128846}', '{"date": 1761569738, "chatId": 1966741829, "messageId": 128850}', '[{"date": 1761569757, "chatId": 1966741829, "messageId": 128851}]');
