INSERT INTO public.operations VALUES ('6081067f-2449-4ae3-a0b6-0e33b63876f1', '2025-10-27 16:58:43.599152', false, 6051416747, 6, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "1K", "custom": false, "aspectRatio": "3:4"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [], "prompt": "сгенерируй фотографию 3:4 от первого лица, где мужская рука держит изящное свадебное приглашение с письменным от руки шрифтом. Текст приглашения будет следующим: «Дорогие Дьяченко Кристина и Максимчук Константин,\n Спешим пригласить вас на празднование по поводу бракосочетания Екатерины и Ивана, \nкоторое состоится 31 октября 2025 года в 17:00\n в банкетном зале гостиницы «Княжеский двор», \nпо адресу: г. Гродно, ул. Красноармейская, д.2.\n Будем счастливы видеть вас на нашем празднике!».\n Фон должен создавать ощущение домашней осенней обстановки.", "operation": "gen-multi-input"}', '1k8256phydrmc0ct4qv8mf74nr', 'succeeded', '{"date": 1761573498, "chatId": 1120625770, "messageId": 128965}', '{"date": 1761573498, "chatId": 1120625770, "messageId": 128966}', '[{"date": 1761573536, "chatId": 1120625770, "messageId": 128967}]');
