INSERT INTO public.operations VALUES ('a6808b0c-cc46-42d7-9ef7-44e90d705fc4', '2025-10-22 02:57:23.837589', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB0iNo-B3BSooEuijt8Lmp5qnWKasGFAAC4vsxG-XUwUsFhXQPfmi5ggEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "На фотографии изображена женщина с темными волосами и карими глазами. Её волосы коричневые, длинные, уложены большими волнами, они объемны и они ниспадают на плечи. цепочка на шее. Она смотрит в сторону от камеры. Фон изображения - бежевый и на лицо попадает лучик солнца Плечи обнажены. Фото сделано более естественным и четким. Максимально сохрани внешность", "operation": "gen-multi-input"}', '125wtnp2x1rme0ct14t81rfmpw', 'succeeded', '{"date": 1761091009, "chatId": 1287537311, "messageId": 119331}', '{"date": 1761091041, "chatId": 1287537311, "messageId": 119336}', '[{"date": 1761091053, "chatId": 1287537311, "messageId": 119337}]');
INSERT INTO public.operations VALUES ('5850200d-376e-4c36-b069-0ab97e51b06d', '2025-11-11 06:06:12.830437', false, 9984949942, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECnBZpEqgMViinNihkryPcMNgene9_9gACIwtrG99GmUgUFWwJ7eXBRQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Сделай так что как будто зади снег и новогодняя шапка", "operation": "gen-multi-input"}', 'fgakaaygsnrme0cte3g8e1thvg', 'succeeded', '{"date": 1762830348, "chatId": 6318163880, "messageId": 171030}', '{"date": 1762830370, "chatId": 6318163880, "messageId": 171035}', '[{"date": 1762830392, "chatId": 6318163880, "messageId": 171036}]');
INSERT INTO public.operations VALUES ('3cc6a8b4-15f7-4786-833f-a2c194f6421a', '2025-10-22 02:38:14.1463', false, 8710657973, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB0hlo-BlRHdTiiTQFKXLuLEsKoUvNwQAC2QQyG9HPwEuQqoz9Sc6trQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Портрет девушки под дождём в вечернем свете. Крупный план, стоит боком запрокинув голову — лицо с закрытыми глазами, капли воды стекают по щекам и волосам. Мягкий синий и холодный свет освещает кожу, создавая атмосферу покоя и грусти.\nДевушка слегка улыбается, голова боком и запрокинута назад. ощущая дождь. Фон тёмный, с неоновым свечением фиолетовый и розовый, размытый, чтобы внимание было на лице. Одежда — тёмная куртка или ветровка, влажные волосы прилипают к коже. Фото реалистичное, кинематографическое освещение, неоновое свечение фиолетовое и розовое , акцент на эмоциях, каплях и текстуре кожи.\n﻿﻿стиль: cinematic portrait, moody lighting, soft focus\n﻿﻿параметры: high detail, 4K, natural skin texture, rain atmosphere, bokeh background", "operation": "gen-multi-input"}', 'p894r1ss39rme0ct14hv79mjcc', 'succeeded', '{"date": 1761089873, "chatId": 1427776517, "messageId": 119321}', '{"date": 1761089884, "chatId": 1427776517, "messageId": 119326}', '[{"date": 1761089905, "chatId": 1427776517, "messageId": 119327}]');
INSERT INTO public.operations VALUES ('255911cd-8403-4d2b-a85f-7ecfedc8164e', '2025-10-27 17:00:05.31593', false, 6051416747, 8, 0.04, '{"config": {"model": "bfl/flux-kontext-pro", "fluxKontextPro": {"format": "jpg", "aspectRatio": "3:4"}}, "photos": [], "prompt": "сгенерируй фотографию 3:4 от первого лица, где мужская рука держит изящное свадебное приглашение с изящным шрифтом на русском языке. Текст приглашения будет строго следующим: «Дорогие Дьяченко Кристина и Максимчук Константин,\n Спешим пригласить вас на празднование по поводу бракосочетания Екатерины и Ивана, \nкоторое состоится 31 октября 2025 года в 17:00\n в банкетном зале гостиницы «Княжеский двор», \nпо адресу: г. Гродно, ул. Красноармейская, д.2.\n Будем счастливы видеть вас на нашем празднике!».\n Фон должен создавать ощущение домашней осенней обстановки.", "operation": "gen-multi-input"}', 'nkssxx0hasrme0ct4qw84b7ev8', 'succeeded', '{"date": 1761573591, "chatId": 1120625770, "messageId": 128972}', '{"date": 1761573591, "chatId": 1120625770, "messageId": 128973}', '[{"date": 1761573610, "chatId": 1120625770, "messageId": 128974}]');
