INSERT INTO public.operations VALUES ('34029172-ef57-4efb-8bcf-ad289b6254b8', '2025-10-27 17:03:29.039877', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB99to_3uHhPWGDajvq_Q5AweAj5d_nAACmgIyGzag-UvLXs4uyIjjqQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEB989o_3rsYQJFJ8k0SBGI8szQZ5lF9AACkwIyGzag-UsCVFxVFvrMPgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 853, "heightPx": 1280}], "prompt": "Задание для нейросети по замене лица на студийной фотографии\nИсходные данные:\nДве фотографии высокого качества в формате JPG/JPEG\nПервое фото — исходное студийное изображение с человеком, которому нужно заменить лицо\nВторое фото — фотография лица, которое будет использоваться для замены\nТребования к результату:\nЕстественная интеграция нового лица в исходное фото\nСохранение освещения и теней студийного фото\nТочное соответствие ракурса и положения головы\nПлавные переходы между новым лицом и остальной частью фотографии\nСохранение качества исходного студийного снимка\nВажные условия:\nНа обоих фото лица должны быть хорошо видны\nОсвещение на фото с новым лицом должно быть равномерным\nЖелательно, чтобы ракурс фото с новым лицом был максимально близок к исходному\nКачество исходных фото — не менее 1024 пикселей\nОжидаемый результат:\nПрофессионально выглядящая студийная фотография\nРеалистичная замена лица без видимых артефактов\nСохранение всех деталей исходного студийного освещения и обработки", "operation": "gen-multi-input"}', 'tj9myqsd09rmc0ct4qxrwq4gec', 'succeeded', '{"date": 1761573767, "chatId": 1091595273, "messageId": 128987}', '{"date": 1761573776, "chatId": 1091595273, "messageId": 128991}', '[{"date": 1761573824, "chatId": 1091595273, "messageId": 128998}]');
