INSERT INTO public.operations VALUES ('0d436bc5-9734-476d-bdb0-cdb0cd747bea', '2025-10-22 03:19:49.385045', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzipo95egLrlzeqUJwICFRW4Znw3GoAAClf4xG68OuEuJD6331PIP9AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 997}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди. Они смотрят друг на друга.", "operation": "gen-multi-input"}', '8dame4jap9rme0ct154ttsk1h8', 'succeeded', '{"date": 1761092385, "chatId": 1287537311, "messageId": 119497}', '{"date": 1761092388, "chatId": 1287537311, "messageId": 119502}', '[{"date": 1761092399, "chatId": 1287537311, "messageId": 119503}]');
