INSERT INTO public.operations VALUES ('d1be3674-feaf-4609-95d8-b7fb16d2e95f', '2025-10-22 03:06:51.27685', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzmJo95oxdkbU02M9NVYJ43alb58HFAACtP4xG68OuEvqGaBmI7OoxAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 896, "heightPx": 1152}, {"file": {"fileId": "AgACAgIAAxkBAAEBzlxo95nSgZtDMnGJDSeEM9meb5st6AACr_4xG68OuEv4UgtpLV51lwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 731, "heightPx": 1280}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди. Они смотрят друг на друга.", "operation": "gen-multi-input"}', '2m0jmqbbadrme0ct14yrg7q2jw', 'succeeded', '{"date": 1761091595, "chatId": 1287537311, "messageId": 119414}', '{"date": 1761091609, "chatId": 1287537311, "messageId": 119424}', '[{"date": 1761091623, "chatId": 1287537311, "messageId": 119426}]');
INSERT INTO public.operations VALUES ('9012a728-44a1-440f-942f-8353beaf149c', '2025-10-22 11:50:15.699193', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку прямо , а другую руку согнула в локте. Девушка легла головой на руку. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'kvyad6wwthrmc0ct1ceb9rv500', 'succeeded', '{"date": 1761123011, "chatId": 1287537311, "messageId": 119968}', '{"date": 1761123014, "chatId": 1287537311, "messageId": 119973}', '[{"date": 1761123025, "chatId": 1287537311, "messageId": 119974}]');
