INSERT INTO public.operations VALUES ('e6270b7c-080c-426d-9d56-b7ebb34c39b5', '2025-10-22 13:17:28.740688', false, 7267149040, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB1P9o-K8oYGjIEx3RrFMHRSYGKzhwswAC8PsxG4swwEvJRL_Z6CWdewEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}, {"file": {"fileId": "AgACAgIAAxkBAAEB1QABaPivKMgH7GXn2vHniWQuxCPMx64AAvH7MRuLMMBLO4jSxDIaiLYBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 531, "heightPx": 854}], "prompt": "На основе этих фото сделай так, чтобы фотография двух людей выглядела так, будто её сняли на Polaroid. На ней не должно быть никаких очевидных объектов или реквизита. Она должна выглядеть как мгновенный снимок без особых деталей. Добавь легкое размытие движения и свет вспышки камеры к тёмной области, чтобы он равномерно распределился по всей фотографии. Не искажайте лицо. Замени фон за двумя людьми на белую завесу. Парень должен обнимать и целовать меня в щёку.", "operation": "gen-multi-input"}', '70f6bq3pfsrmc0ct1dp8wq13jc', 'succeeded', '{"date": 1761128232, "chatId": 7915148308, "messageId": 120063}', '{"date": 1761128245, "chatId": 7915148308, "messageId": 120067}', '[{"date": 1761128262, "chatId": 7915148308, "messageId": 120068}]');
