INSERT INTO public.operations VALUES ('c75b0e51-c9cf-4e99-ba41-627e32ff79b6', '2025-10-22 03:09:06.299486', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzlto95nSNub-AaYbMPhjnn4eAmBAmQACrv4xG68OuEsulJO8Og1oWgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 896, "heightPx": 1152}, {"file": {"fileId": "AgACAgIAAxkBAAEBzlxo95nSgZtDMnGJDSeEM9meb5st6AACr_4xG68OuEv4UgtpLV51lwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 731, "heightPx": 1280}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди. Они смотрят друг на друга.", "operation": "gen-multi-input"}', '6kardpvtp5rma0ct14zsjy09nr', 'succeeded', '{"date": 1761091701, "chatId": 1287537311, "messageId": 119448}', '{"date": 1761091705, "chatId": 1287537311, "messageId": 119452}', '[{"date": 1761091758, "chatId": 1287537311, "messageId": 119457}]');
INSERT INTO public.operations VALUES ('f86da9eb-0e14-4d67-afa1-11926d38b3aa', '2025-10-22 13:36:37.186836', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка поднимается из бассейна по лестнице, одна нога согнута в голени, держится руками за поручни с боку. Фото сделано сверху. У девушки черный слитный купальник с глубоким вырезом. Из украшений - цепочка, и маленькие серьги. У девушки черные, длинные, мокрые волосы уложены назад. Девушка смотрит в бок.", "operation": "gen-multi-input"}', 'j6m88rfwh9rmc0ct1dyvj3gznm', 'succeeded', '{"date": 1761129365, "chatId": 1287537311, "messageId": 120084}', '{"date": 1761129395, "chatId": 1287537311, "messageId": 120089}', '[{"date": 1761129407, "chatId": 1287537311, "messageId": 120090}]');
