INSERT INTO public.operations VALUES ('b6ddbaf3-6b57-4b9c-885d-5ec76e0ed1b5', '2025-10-22 03:22:09.216297', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzmJo95oxdkbU02M9NVYJ43alb58HFAACtP4xG68OuEvqGaBmI7OoxAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 896, "heightPx": 1152}, {"file": {"fileId": "AgACAgIAAxkBAAEBzlxo95nSgZtDMnGJDSeEM9meb5st6AACr_4xG68OuEv4UgtpLV51lwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 731, "heightPx": 1280}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди.", "operation": "gen-multi-input"}', 'd1d3w83d2srme0ct155sb9hg44', 'succeeded', '{"date": 1761092521, "chatId": 1287537311, "messageId": 119517}', '{"date": 1761092528, "chatId": 1287537311, "messageId": 119521}', '[{"date": 1761092542, "chatId": 1287537311, "messageId": 119522}]');
