INSERT INTO public.operations VALUES ('4d30d266-69cd-4afe-92db-4b967b20b076', '2025-10-22 11:15:48.558137', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне , вытянув ноги в воде, оперевшись грудью на край и положив одну руку прямо, а другую руку согнула в локте, положив голову на руки. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'g5f08krjs9rma0ct1byv0vhqa0', 'succeeded', '{"date": 1761120909, "chatId": 1287537311, "messageId": 119789}', '{"date": 1761120947, "chatId": 1287537311, "messageId": 119794}', '[{"date": 1761120959, "chatId": 1287537311, "messageId": 119795}]');
