INSERT INTO public.operations VALUES ('fe857b21-f954-4684-a774-c0fc1829f226', '2025-10-27 20:44:07.509467', false, 5388181978, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB-NZo_6698tLdATVyK6e-bEqAHu3A6AACDwABMhv_MgFIGwNp5VNYpSsBAAMCAAN4AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 719, "heightPx": 719}, {"file": {"fileId": "AgACAgIAAxkBAAEB-Ndo_669JTdBBy0DPRr2o9pMCEd3bgACEAABMhv_MgFIRo0wUTphtCcBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "сделай пожалуйста чтобы на второй фотографии глаза были примерно как на первой, а рот прикрыт.\n  и ещё сделай пожалуйста так, чтобы был такой бирюзовый оттенок, как на первой фотографии :)", "operation": "gen-multi-input"}', 't6ambx9dtdrmc0ct4v2rzpm5v8', 'succeeded', '{"date": 1761586877, "chatId": 5242511897, "messageId": 129238}', '{"date": 1761587044, "chatId": 5242511897, "messageId": 129242}', '[{"date": 1761587065, "chatId": 5242511897, "messageId": 129243}]');
INSERT INTO public.operations VALUES ('60ba03a2-4c88-46cd-b758-ee2a60ecc724', '2025-10-22 07:58:16.744254', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzmJo95oxdkbU02M9NVYJ43alb58HFAACtP4xG68OuEvqGaBmI7OoxAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 896, "heightPx": 1152}, {"file": {"fileId": "AgACAgIAAxkBAAEBzlxo95nSgZtDMnGJDSeEM9meb5st6AACr_4xG68OuEv4UgtpLV51lwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 731, "heightPx": 1280}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди.", "operation": "gen-multi-input"}', '8th6ka1st1rma0ct194bc46xer', 'succeeded', '{"date": 1761109090, "chatId": 1287537311, "messageId": 119561}', '{"date": 1761109093, "chatId": 1287537311, "messageId": 119565}', '[{"date": 1761109109, "chatId": 1287537311, "messageId": 119566}]');
INSERT INTO public.operations VALUES ('023758ae-4a7a-46fe-a30f-623b5fdd6b42', '2025-10-22 11:04:13.473878', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создание фото девушки в бассейне. Максимально сохрани мою внешность. Я стою в бассейне по пояс. На мне одет черный раздельный купальник без лямок. Я смотрю в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка двумя руками поправляет волосы. На лице у девушки надеты черные очки. Фото сделано в близи.", "operation": "gen-multi-input"}', 'dfa4vekq55rmc0ct1bsahmd7a4', 'failed', '{"date": 1761120249, "chatId": 1287537311, "messageId": 119737}', '{"date": 1761120252, "chatId": 1287537311, "messageId": 119742}', '[{"date": 1761120252, "chatId": 1287537311, "messageId": 119742}]');
