INSERT INTO public.operations VALUES ('46b074b0-1531-4f9b-988c-0393f1399edc', '2025-10-22 07:59:16.660265', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzQNo93hFI4baWTU6gycG68mjh0pXygACo_0xG68OuEsBhIsYQssWlQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 739, "heightPx": 1280}], "prompt": "фон белый, пол белый, студийная фотография женщины, сидящей в приседшей позе и закутанной в большой пушистый белый меховой плащ. Ее обнаженные плечи и ноги частично видны, голова нежно опирается на руку. Фон простой и минималистичный, создающий мягкий редакционный образ в стиле модной фотосессии.\nСнимок обладает утонченной, элегантной атмосферой, напоминающей профессиональную журнальную съемку.\nХудая девушка, волос черный , длинный и прямой. Максимально сохрани мою внешность . Девушка смотрит прямо в камеру, у нее пухлые губы и реснички. Качество фото не замыленно, четкие черты лица.", "operation": "gen-multi-input"}', '7j7j69h4j5rma0ct194thb6d3w', 'succeeded', '{"date": 1761109122, "chatId": 1287537311, "messageId": 119567}', '{"date": 1761109155, "chatId": 1287537311, "messageId": 119572}', '[{"date": 1761109168, "chatId": 1287537311, "messageId": 119573}]');
INSERT INTO public.operations VALUES ('bce15906-a4cd-4e5a-844c-144de097754a', '2025-10-22 11:08:30.286607', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка стоит в бассейне по пояс. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. На лице у девушки надеты черные очки чуть приспущены и видны глаза . Фото сделано чуть сверху.", "operation": "gen-multi-input"}', 'axmce33259rmc0ct1bva1j0eec', 'succeeded', '{"date": 1761120471, "chatId": 1287537311, "messageId": 119750}', '{"date": 1761120508, "chatId": 1287537311, "messageId": 119755}', '[{"date": 1761120519, "chatId": 1287537311, "messageId": 119756}]');
