INSERT INTO public.operations VALUES ('4b133cc8-d066-4294-8a2e-4d22d8848a67', '2025-10-22 08:01:34.134153', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzPFo93dnV9w6vUe9vgc25ZWjV7yergACif0xG68OuEvErTU8vT3vEgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 626, "heightPx": 834}, {"file": {"fileId": "AgACAgIAAxkBAAEBzVdo9350VMtIDVsT5e8C8DU0gW-T-gACyP0xG68OuEvuIGXe0MX3OAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди.", "operation": "gen-multi-input"}', '6z0ags9wvxrme0ct195r1pzmwr', 'succeeded', '{"date": 1761109289, "chatId": 1287537311, "messageId": 119593}', '{"date": 1761109293, "chatId": 1287537311, "messageId": 119597}', '[{"date": 1761109306, "chatId": 1287537311, "messageId": 119598}]');
INSERT INTO public.operations VALUES ('8eb30be7-5a56-4f3f-9670-63e21fbf2e63', '2025-10-22 11:12:59.808905', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку, а другую руку согнула в локте, положив голову на руки. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'sg82yebzg1rm80ct1bx83x6b0r', 'succeeded', '{"date": 1761120551, "chatId": 1287537311, "messageId": 119757}', '{"date": 1761120724, "chatId": 1287537311, "messageId": 119762}', '[{"date": 1761120790, "chatId": 1287537311, "messageId": 119767}]');
