INSERT INTO public.operations VALUES ('44da78f4-d8ac-427b-adf9-8a42cb64bd67', '2025-10-22 20:18:52.818231', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай сексуальное фото девушки которая лежит на шезлонге  . Максимально сохрани внешность. У девушки черные, длинные, прямые волосы. Она одета в черный слитный купальник с глубоким вырезом. Из украшений - цепочка, маленькие серьги и тонкий золотой браслет.", "operation": "gen-multi-input"}', 'vw3h9ya4m5rm80ct1kqa6bk3y8', 'succeeded', '{"date": 1761153490, "chatId": 1287537311, "messageId": 120994}', '{"date": 1761153531, "chatId": 1287537311, "messageId": 120999}', '[{"date": 1761153542, "chatId": 1287537311, "messageId": 121000}]');
