INSERT INTO public.operations VALUES ('39ada97f-beb8-42ec-950c-59ad59bc9f87', '2025-10-22 08:03:00.705993', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzlxo95nSgZtDMnGJDSeEM9meb5st6AACr_4xG68OuEv4UgtpLV51lwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 731, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAEBzlto95nSNub-AaYbMPhjnn4eAmBAmQACrv4xG68OuEsulJO8Og1oWgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 896, "heightPx": 1152}], "prompt": "Сделай совместное фото в студии. Максимально сохрани внешность обоих женщин. Черты лица четкие , без ретуши, без макияжа. На фото изображены молодая девушка и женщина, женщина стоит спереди, другая позади нее. Фон - бежевый. На лица женщин падает солнечный свет, волосы женщин черные , длинные и уложены большими волнами. Женщины одеты в черные свободные футболки. Максимально сохрани внешность женщин. Фото сделано чуть выше груди.", "operation": "gen-multi-input"}', 'c6jmyqwf49rme0ct196944mtj8', 'succeeded', '{"date": 1761109376, "chatId": 1287537311, "messageId": 119611}', '{"date": 1761109379, "chatId": 1287537311, "messageId": 119615}', '[{"date": 1761109394, "chatId": 1287537311, "messageId": 119616}]');
INSERT INTO public.operations VALUES ('870ccd74-1e5c-4db1-acda-af5e2bc31736', '2025-10-22 11:14:47.755607', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку, а другую руку согнула в локте, положив голову на руки. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'wsf6xd94vhrme0ct1bybvbkj30', 'succeeded', '{"date": 1761120882, "chatId": 1287537311, "messageId": 119782}', '{"date": 1761120885, "chatId": 1287537311, "messageId": 119787}', '[{"date": 1761120897, "chatId": 1287537311, "messageId": 119788}]');
