INSERT INTO public.operations VALUES ('f7ccf45d-0438-4431-bb3b-1b0d49419356', '2025-11-11 08:01:34.664381', false, 1943496863, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECnMhpEsMZLvaUoq0CT54vKeCYofyPUgAC1AtrG-yZmFAdK6-A4HWteQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Show me your best edit", "operation": "gen-multi-input"}', '87jvydkfg1rm80cte558mrync8', 'succeeded', '{"date": 1762837273, "chatId": 6037733416, "messageId": 171208}', '{"date": 1762837288, "chatId": 6037733416, "messageId": 171211}', '[{"date": 1762837304, "chatId": 6037733416, "messageId": 171212}]');
INSERT INTO public.operations VALUES ('fbb0dde8-4716-4930-b7df-a162a4e09d61', '2025-10-22 08:07:02.564474', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzVdo9350VMtIDVsT5e8C8DU0gW-T-gACyP0xG68OuEvuIGXe0MX3OAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай портрет на открытом воздухе в стиле высокой моды, вдохновлённый редакционной фотографией Vogue.\nЧеловек элегантно позирует на фоне заснеженных гор под ярким солнечным светом.\nНа заднем плане - кинематографический альпийский пейзаж с чистым небом и свежим воздухом. Модель одета в роскошную ультра-белую пышную шубу с плотной текстурой, украшенная детализированным ювелирным головным убором похожий на кокошник и подходящими серьгами, которые сверкают на свету, черные солнцезащитные очки в стиле Прада. В руках бокал проссеко.\nВолосы длинные распущенные, прямые. Кожа светящаяся, губы слегка приоткрыты, макияж с ярким румянцем и глянцевым финишем.\nОсвещение яркое, насыщенное и кинематографическое, белой шубой и холодными тонами заснеженных гор.\nПоза: плечи повернуты, подбородок слегка приподнят, взгляд уверенный. Не меняй черты лица.\nСтиль: мода Vogue, высокая мода, ультрареализм, богатая цветовая палитра, разрешение 8K, естественный солнечный свет, редакционная элегантность.", "operation": "gen-multi-input"}', 'szv9r31zy5rm80ct198954ew1m', 'succeeded', '{"date": 1761109570, "chatId": 1287537311, "messageId": 119624}', '{"date": 1761109621, "chatId": 1287537311, "messageId": 119629}', '[{"date": 1761109634, "chatId": 1287537311, "messageId": 119630}]');
INSERT INTO public.operations VALUES ('e9b7591b-ebb7-4fa7-ae34-604e073ad103', '2025-10-22 08:05:28.023057', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEBzVdo9350VMtIDVsT5e8C8DU0gW-T-gACyP0xG68OuEvuIGXe0MX3OAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Crie uma fotografia hiper-realista em altíssima definição (8K), retratando uma mulher com o mesmo rosto, cabelo, corpo e tom de pele da imagem de referência, sem alterar suas feições.\nEla está sentada elegantemente em uma mesa de restaurante sofisticado, segurando uma taça de vinho tinto com a mão direita e olhando levemente para o lado com expressão confiante e serena.\nO ambiente é noturno e refinado, com luzes quentes de lustres de cristal, * reflexos dourados e fundo desfocado com pessoas jantando ao fundo.\nA mulher usa um vestido justo de gola alta em tom marrom chocolate, casaco de pele caramelo caído sobre os ombros, meia-calça estampada com o logo da Gucci, e uma bolsa\nGucci bege com monograma sobre a mesa.\n, Ela tem cabelos naturais com ondas suaves, uma faixa marrom combinando com o look, brincos grandes dourados em argola, e colares finos sobrepostos em ouro.\nA maquiagem é perfeita e glamourosa, com olhos esfumados, pele iluminada e batom nude elegante.\nO clima é sofisticado e acolhedor, transmitindo luxo, feminilidade e poder com sutileza.\nIluminação: quente e suave, vinda de lustres e velas, com foco no rosto e reflexo sutil no vinho.\nEstilo de fotografia: editorial de moda noturno e elegante, inspirado em campanhas da Gucci, Dolce & Gabbana e Vogue Paris Night Edition.\nExpressão: sofisticada, confiante e serena, com olhar levemente lateral e postura", "operation": "gen-multi-input"}', '2a2bkheexsrme0ct197a4c5zyw', 'succeeded', '{"date": 1761109513, "chatId": 1287537311, "messageId": 119617}', '{"date": 1761109527, "chatId": 1287537311, "messageId": 119622}', '[{"date": 1761109539, "chatId": 1287537311, "messageId": 119623}]');
