INSERT INTO public.operations VALUES ('3e411a9a-052c-41b4-8054-810051d60f22', '2025-10-22 11:18:29.01765', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку прямо , а другую руку согнула в локте, положив голову на руки. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'ehnknaw54xrma0ct1bzr8m6xxr', 'succeeded', '{"date": 1761121104, "chatId": 1287537311, "messageId": 119810}', '{"date": 1761121108, "chatId": 1287537311, "messageId": 119815}', '[{"date": 1761121118, "chatId": 1287537311, "messageId": 119816}]');
INSERT INTO public.operations VALUES ('4f0ba577-dec7-4210-b491-d2c7296ba64a', '2025-10-22 11:19:10.110332', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку прямо , а другую руку согнула в локте, положив голову на руки. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', '6vrd6sh5f5rme0ct1c0bmqpfvr', 'succeeded', '{"date": 1761121141, "chatId": 1287537311, "messageId": 119817}', '{"date": 1761121146, "chatId": 1287537311, "messageId": 119822}', '[{"date": 1761121160, "chatId": 1287537311, "messageId": 119823}]');
INSERT INTO public.operations VALUES ('7ab10b88-b179-40d7-831c-fa38a05ad442', '2025-10-27 21:50:36.522367', false, 2417679402, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB-SBo_76MaO-4So0oHE84ujHuxNZD0wACQgUyGzag-UttxFpuAAHo-LQBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "Идея для нейрофото🔥\n\nПромпт: Используй фото как основу,  сохрани черты, мимику и естественную форму лица.\nВсе детали должны остаться такими же: глаза, губы, скулы, оттенок кожи и волос.\nФото должно быть реалистичным, не «ИИ-куклой», а будто сделано в студии с идеальным светом.\n\nСцена: Профильный портрет в мягком боковом свете.\nФон — тёплый, бежево-карамельный, без отвлекающих деталей.\nГолова чуть повернута влево, подбородок приподнят.\nГлаза закрыты или направлены вдаль.\nОдна рука поднята к губам в тонкой чёрной перчатке.\n\nСвет:Тёплый боковой, с золотистым отливом, как солнце на закате.\nОн подчёркивает рельеф лица, скулы и изгиб губ.\nКожа сияет естественным блеском — без фильтров, без ретуши, только мягкое свечение.\n\nОбраз:Чистый, уверенный, минималистичный.\nГладкие собранные волосы цвет волос блонд, чёрные стрелки, яркие губы и крупные золотые серьги.\nФокус — на лице, эмоции и силе взгляда.\n\nКачество: Фотореализм, крупный план, ощущение кадра с профессиональной камеры.\nБез цифрового налёта — кожа с текстурой, как в живом фото.\n\nНастроение: Женственность, уверенность и лёгкая драма.", "operation": "gen-multi-input"}', 'dzwyjz8c2nrmc0ct4w1a2w58br', 'succeeded', '{"date": 1761590924, "chatId": 1091595273, "messageId": 129312}', '{"date": 1761591001, "chatId": 1091595273, "messageId": 129317}', '[{"date": 1761591047, "chatId": 1091595273, "messageId": 129322}]');
INSERT INTO public.operations VALUES ('d472e9e6-9243-430a-a533-62f5c657d2e5', '2025-10-22 11:47:41.180158', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка поднимается из бассейна по лестнице, одна нога согнута в голени, держится руками за поручни с боку. Фото сделано сверху. У девушки черный раздельный купальник. Из украшений - цепочка, и маленькие серьги. У девушки черные, длинные, мокрые волосы уложены назад. Девушка смотрит в бок.", "operation": "gen-multi-input"}', '28pxwb219drma0ct1cd830wnxc', 'succeeded', '{"date": 1761122853, "chatId": 1287537311, "messageId": 119945}', '{"date": 1761122860, "chatId": 1287537311, "messageId": 119950}', '[{"date": 1761122872, "chatId": 1287537311, "messageId": 119951}]');
