INSERT INTO public.operations VALUES ('632f7ad6-01db-418a-9ca2-7c62fdfac0cb', '2025-10-22 11:21:48.189671', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край, положив одну руку прямо на кафель, а другую руку согнула в локте, положив голову на руки. На девушки из украшений надеты маленькие серьги.На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'pkbq9kwexxrm80ct1c1as5bjxr', 'succeeded', '{"date": 1761121229, "chatId": 1287537311, "messageId": 119831}', '{"date": 1761121307, "chatId": 1287537311, "messageId": 119836}', '[{"date": 1761121319, "chatId": 1287537311, "messageId": 119837}]');
