INSERT INTO public.operations VALUES ('f71ddf4d-69fc-454c-8f5e-5ac932559bb2', '2025-10-22 11:26:07.331027', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку прямо , а другую руку согнула в локте. Девушка легла головой на руку. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'av0sshw33nrma0ct1c399mjtem', 'succeeded', '{"date": 1761121562, "chatId": 1287537311, "messageId": 119863}', '{"date": 1761121566, "chatId": 1287537311, "messageId": 119868}', '[{"date": 1761121576, "chatId": 1287537311, "messageId": 119869}]');
INSERT INTO public.operations VALUES ('b0ecbc9a-8d2e-4d42-b2f8-6478611dea68', '2025-10-22 11:26:46.174069', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край и вытянув одну руку вперед , а другую руку согнула в локте. Девушка легла головой на руку. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', '5pwfgr0vw9rm80ct1c3tnk00a0', 'succeeded', '{"date": 1761121585, "chatId": 1287537311, "messageId": 119870}', '{"date": 1761121605, "chatId": 1287537311, "messageId": 119875}', '[{"date": 1761121616, "chatId": 1287537311, "messageId": 119876}]');
INSERT INTO public.operations VALUES ('90385292-8da7-4ac3-b57b-1d1fcea5f63d', '2025-10-22 11:36:08.42852', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в бассейне оперевшись грудью на край , вытянув и положив руки вперед ,. Девушка легла головой на руку. На девушке черный раздельный купальник . Девушка смотрит в камеру. У девушки черные длинные мокрые волосы уложены назад. Девушка руками поправляет волосы. Фото сделано с боку.", "operation": "gen-multi-input"}', 'ypd067nfndrma0ct1c7r6ad1nm', 'succeeded', '{"date": 1761122131, "chatId": 1287537311, "messageId": 119877}', '{"date": 1761122167, "chatId": 1287537311, "messageId": 119882}', '[{"date": 1761122183, "chatId": 1287537311, "messageId": 119883}]');
INSERT INTO public.operations VALUES ('3929426b-23b2-4c80-b796-07a8722ee05a', '2025-11-11 08:26:40.584375', false, 7430431672, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAECnP1pEsj-2jgl66AJ2qDAOcDJr9K6vQACjAtrG386mFT1l1xWl3-LFAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Молодой мужчина с небрежно уложенными тёмными волосами стоит на фоне городских офисных зданий, снят крупным планом полубоком, во рту сигарета, взгляд прямой, резкий и задумчивый, губы сжаты, выражение лица холодное и уверенное, создающее атмосферу нуара и внутреннего напряжения; он одет в тёмный пиджак, полосатую рубашку с расстёгнутым верхним пуговицей и ослабленным чёрным галстуком, придающим образу усталую элегантность и лёгкий хаос; фон — стеклянные фасады современного города, отражающие свет, создают геометричный рисунок теней; освещение жёсткое дневное, контрастное, с сильными тенями на лице, подчёркивающими скулы и морщины лба; параметры съёмки — объектив 85 мм, f/2.2, выдержка 1/500 сек, ISO 200, акцент на текстуре кожи и ткани; обработка в стиле чёрно-белой плёнки, глубокие тени, мягкие переходы света, киношный драматизм и винтажная зернистость; фокус на лице, фон слегка размытый, композиция по центру, качество 4K HD, ультрареалистично, в эстетике урбан-нуар портрета 2025 года.", "operation": "gen-multi-input"}', '3keey8b9mdrme0cte5grjjh62g', 'succeeded', '{"date": 1762838782, "chatId": 7066908846, "messageId": 171261}', '{"date": 1762838797, "chatId": 7066908846, "messageId": 171269}', '[{"date": 1762838813, "chatId": 7066908846, "messageId": 171270}]');
