INSERT INTO public.operations VALUES ('d31977a3-4f2f-4c97-b656-ad68afcd620f', '2025-10-22 13:56:42.712631', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в воде на спине головой к камере, макушку головы положила на край бассейна, руки согнуты в локтях положила на край бассейна , кисти рук свисают в воде. Ноги находятся в воде, одна нога выпрямлена, другая согнута в колене. Фото сделано сзади, со стороны головы. Фото сделано сверху. У девушки черный слитный купальник с глубоким вырезом. Из украшений - цепочка и маленькие серьги. У девушки черные, длинные, мокрые волосы. Девушка смотрит вверх в камеру.", "operation": "gen-multi-input"}', 'ampkacb1hnrmc0ct1e8afxq15g', 'succeeded', '{"date": 1761130586, "chatId": 1287537311, "messageId": 120155}', '{"date": 1761130601, "chatId": 1287537311, "messageId": 120160}', '[{"date": 1761130612, "chatId": 1287537311, "messageId": 120161}]');
