INSERT INTO public.operations VALUES ('0377455a-cba9-4fe1-95db-dba2387e72ea', '2025-10-22 17:14:37.689566', false, 6436190654, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB1iJo-OanzQbP2Pi2cMTVw--dZjvclAACyvsxGzVRyUsi_S949ZKtLQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 836, "heightPx": 1280}], "prompt": "Сделай фото как на Polaroid, где два человека из предложенных фото встречаются позади зеленый деревенский домик фоном. Создайте вид спереди, показывая их обоих.\nСоздайте атмосферу золотого часа,\nДедушка худой по телосложению и высокий, улыбается смотрит в камеру, а девушка с любовью на дедушку и он ее обнимает одной рукой на плечо. Не меняйте их лицо и волосы, улыбка на лицах должна быть без отображения зубов.\nДевушка одета как на фото в белом платье в пол , а дедушка в голубой рубашке и серых брюках. Изображение людей по пояс. Черты лица не меняй", "operation": "gen-multi-input"}', 'jk8rbh4ngdrme0ct1h2ty4mst8', 'failed', '{"date": 1761142439, "chatId": 561125526, "messageId": 120354}', '{"date": 1761142472, "chatId": 561125526, "messageId": 120357}', '[{"date": 1761142472, "chatId": 561125526, "messageId": 120357}]');
