INSERT INTO public.operations VALUES ('1bd60481-d7b4-48fb-8abd-d677a00ef71f', '2025-10-22 17:17:42.00194', false, 6436190654, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB1iho-OdE-dOKAS04XzIq1gJcFCMZAwACzfsxGzVRyUvn2N-Ls3JBLwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 821, "heightPx": 1279}, {"file": {"fileId": "AgACAgIAAxkBAAEB1ilo-OdE2HFRsEpPLCDWyszdetOZYwAC0fsxGzVRyUuxY00JVohBZAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Сделай фото как на Polaroid, где два человека из предложенных фото встречаются позади зеленый деревенский домик фоном. Создайте вид спереди, показывая их обоих.\nСоздайте атмосферу золотого часа,\nДедушка худой по телосложению и высокий, улыбается смотрит в камеру, а девушка с любовью на дедушку и он ее обнимает одной рукой на плечо. Не меняйте их лицо и волосы, улыбка на лицах должна быть без отображения зубов.\nДевушка одета как на фото в юбке и майке, а дедушка в голубой рубашке и серых брюках. Изображение людей по пояс", "operation": "gen-multi-input"}', 'rwqszmv4n5rm80ct1h4bny7e84', 'succeeded', '{"date": 1761142596, "chatId": 561125526, "messageId": 120360}', '{"date": 1761142644, "chatId": 561125526, "messageId": 120364}', '[{"date": 1761142675, "chatId": 561125526, "messageId": 120365}]');
INSERT INTO public.operations VALUES ('b0caf1bc-211e-4d21-87ed-2c65d07b43b6', '2025-10-22 21:36:57.067621', false, 7985523166, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB2Z5o-SQsO6pH_N83btc53KR8mU5hygACjPsxG4PtiUsCAQLiKzJH0wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 878, "heightPx": 1080}], "prompt": "Сделай девочке грустное лицо", "operation": "gen-multi-input"}', 'd71anrnyrdrmc0ct1mttf7cm04', 'failed', '{"date": 1761158188, "chatId": 1363648279, "messageId": 121246}', '{"date": 1761158207, "chatId": 1363648279, "messageId": 121251}', '[{"date": 1761158207, "chatId": 1363648279, "messageId": 121251}]');
INSERT INTO public.operations VALUES ('ca0c516d-e506-4976-a62d-662f98fea00d', '2025-10-28 02:21:44.683028', false, 2574576068, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB-lFo__6AeMH8hifKJM_m2P0oKN9WmQACLvgxG4VTAUj5bo1znM7CXgEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 640}, {"file": {"fileId": "AgACAgIAAxkBAAEB-kxo__4KGORrgBOt-eglUFykOdgQxQACi_MxG49JAUiCDR5PZTE_bAEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 572, "heightPx": 572}], "prompt": "Фотореалистичный\nдвухуровневый коллаж в стиле папарацци.\nВерхнее фото: мужчина и женщина в BMW M5 ночью, крупный план через лобовое стекло. Женщина откинулась назад и смотрит в камеру с отстранённым выражением.\nМужчина слегка подался вперед, его рука на руле, он тоже смотрит в камеру. Освещение - ночной свет и мягкая вспышка, пленочное зерно 35 мм.\nНижнее фото: тот же мужчина и женщина, ракурс через пассажирское окно снаружи.\nЖенщина опирает голову на руку, смотрит в сторону. Мужчина подался вперёд, его рука на руле, он смотрит на пассажирку.\nАтмосфера сырая, неотредактированная, с натуральным зерном плёнки 35 мм.", "operation": "gen-multi-input"}', 'pjy89e27dhrm80ct4zx90vve6g', 'succeeded', '{"date": 1761607296, "chatId": 1430142779, "messageId": 129617}', '{"date": 1761607301, "chatId": 1430142779, "messageId": 129621}', '[{"date": 1761607319, "chatId": 1430142779, "messageId": 129622}]');
