INSERT INTO public.operations VALUES ('43d52fcd-7f0f-4425-9353-03ca412d41ff', '2025-10-22 18:52:31.551194', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки в бассейне. Максимально сохрани внешность. Девушка лежит в воде на спине, на углу бассейна головой к камере. Девушка облокотилась на локти рук которые поставила по краям бассейна, кисти рук свисают в воде, спина приподнята, макушку головы положила на край бассейна. Ноги находятся в воде, одна нога выпрямлена, другая согнута в колене. Фото сделано сзади с верху, со стороны головы. Фото сделано сверху. У девушки черный слитный купальник с глубоким вырезом. Из украшений - цепочка и маленькие серьги. У девушки черные, длинные, мокрые волосы. Девушка смотрит вверх в камеру.", "operation": "gen-multi-input"}', 'tbm7mk1p69rm80ct1jfrvrhmt8', 'succeeded', '{"date": 1761148321, "chatId": 1287537311, "messageId": 120472}', '{"date": 1761148350, "chatId": 1287537311, "messageId": 120477}', '[{"date": 1761148362, "chatId": 1287537311, "messageId": 120478}]');
