INSERT INTO public.operations VALUES ('d72c361c-4312-4c12-9f64-4f12763e9373', '2025-10-28 02:29:20.453217', false, 7923130237, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB-mlpAAJJoHxb39oZNkKjy8zcKCte8QACFvsxG4SXAUj_49lBocVJDQEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 640, "heightPx": 640}, {"file": {"fileId": "AgACAgIAAxkBAAEB-mZpAAIvVi-OpFrNDHwECovaeP67ygACFfsxG4SXAUjQRub7lkroeAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Фотореалистичный\nдвухуровневый коллаж в стиле папарацци.\nВерхнее фото: мужчина и женщина в BMW M5 ночью, крупный план через лобовое стекло. Женщина откинулась назад и смотрит в камеру с отстранённым выражением.\nМужчина слегка подался вперед, его рука на руле, он тоже смотрит в камеру. Освещение - ночной свет и мягкая вспышка, пленочное зерно 35 мм.\nНижнее фото: тот же мужчина и женщина, ракурс через пассажирское окно снаружи.\nЖенщина опирает голову на руку, смотрит в сторону. Мужчина подался вперёд, его рука на руле, он смотрит на пассажирку.\nАтмосфера сырая, неотредактированная, с натуральным зерном плёнки 35 мм.", "operation": "gen-multi-input"}', '683xwf9wh9rma0ct500sn3vy2c', 'succeeded', '{"date": 1761607753, "chatId": 6883484306, "messageId": 129641}', '{"date": 1761607758, "chatId": 6883484306, "messageId": 129645}', '[{"date": 1761607774, "chatId": 6883484306, "messageId": 129646}]');
INSERT INTO public.operations VALUES ('71a97ddb-1cec-41b0-8b39-1c40b1cbb8b1', '2025-10-22 19:38:26.963541', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB07lo-I_5Q1EeFsuxewG1bXVJtQ0DrAACF_0xG-XUwUtx_O4yafMbegEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай сексуальное фото девушки в бассейне. Максимально сохрани внешность. У девушки черные, длинные, мокрые волосы. Она одета в черный слитный купальник с глубоким вырезом. Из украшений - цепочка, маленькие серьги и тонкий золотой браслет. На лице у девушки одеты очки, которые чуть чуть приспущены и чуть чуть видны глаза.", "operation": "gen-multi-input"}', 'mkg9rat0n9rm80ct1k4s5p8g6g', 'succeeded', '{"date": 1761151098, "chatId": 1287537311, "messageId": 120637}', '{"date": 1761151105, "chatId": 1287537311, "messageId": 120642}', '[{"date": 1761151117, "chatId": 1287537311, "messageId": 120643}]');
