INSERT INTO public.operations VALUES ('55019543-9e22-4fd8-a1f2-5552d86ca968', '2025-10-22 20:28:14.877276', false, 4123445461, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB2PVo-ROdK3oUXxLgnqV6uYV4VLzM7QACpfgxG84pyUteVh1eg_Pz5QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Сделать одежду как Фидель Кастро, но лицо оставить прежним. Поменять задний фон, шикарный ресторан. На столе красивая еда и напитки.", "operation": "gen-multi-input"}', '8rq9jferq1rma0ct1kv95sd798', 'succeeded', '{"date": 1761153949, "chatId": 5093210111, "messageId": 121077}', '{"date": 1761154086, "chatId": 5093210111, "messageId": 121082}', '[{"date": 1761154106, "chatId": 5093210111, "messageId": 121083}]');
