INSERT INTO public.operations VALUES ('c09789ae-c5be-4b57-8896-f8e339891d74', '2025-10-29 20:12:35.222984', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECA-BpAkoPW3mpeqDQYfUF7zbgPMiH4AACaQUyG4qQEUjDhyYHoKEqfQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1005, "heightPx": 1280}], "prompt": "Создай фото девушки. Максимально сохрани мою внешность. Девушка лежит горизонтально дивана , головой к подлокотнику на спине , фото сделано сверху . На девушке одет черный пиджак на обношенное тело. У девушки черные длинные волосы уложены большими локонами коровье лежит на диване в разные стороны . У девушки маленькие серьги и цепочка.", "operation": "gen-multi-input"}', 'p04hv9r5ehrmc0ct63tvtcf0gc', 'succeeded', '{"date": 1761757913, "chatId": 1287537311, "messageId": 132093}', '{"date": 1761757954, "chatId": 1287537311, "messageId": 132103}', '[{"date": 1761757965, "chatId": 1287537311, "messageId": 132104}]');
INSERT INTO public.operations VALUES ('ef1a6b60-693a-4b5a-957c-f0ebca8d1cb6', '2025-10-22 20:39:16.299112', false, 2673793500, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB2RFo-RZXoiVujykiqd0DS6Pdaw3S2gACcfcxG-8F0Uu7vbwqv4WD6QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "На основе этих фото сделай так, чтобы фотография двух людей выглядела так, будто её сняли на Polaroid. На ней не должно быть никаких очевидных объектов или реквизита. Она должна выглядеть как мгновенный снимок без особых деталей. Добавь легкое размытие движения и свет вспышки камеры к тёмной области, чтобы он равномерно распределился по всей фотографии. Не искажайте лицо. Замени фон за двумя людьми на белую завесу. Парень должен обнимать и целовать меня в губы", "operation": "gen-multi-input"}', 'ajf2y5zfynrma0ct1m09b1tmnr', 'failed', '{"date": 1761154648, "chatId": 6198109625, "messageId": 121105}', '{"date": 1761154730, "chatId": 6198109625, "messageId": 121110}', '[{"date": 1761154730, "chatId": 6198109625, "messageId": 121110}]');
