INSERT INTO public.operations VALUES ('a94e4d50-56f8-44f6-b2e2-a6053628e5f2', '2025-10-28 23:52:08.823334', false, 9920339733, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAAGTaQEszmKrQmvYRGuSrJ_QhZgBXM4AAp3-MRv-AQlIIWa64kbzP4YBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1120, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAGUaQEszo6lShQUupmxDpgQPcHDsGUAApT-MRv-AQlIIGl7_Hfdf3IBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1022, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAGVaQEszt7fVqSaY9w8a1ZZYJ4eKboAApj-MRv-AQlIPGp6PzgPKYgBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 846, "heightPx": 1280}], "prompt": "ультрареалистичная фэшн-редакция в формате 8K в стиле Ива Сен-Лорана: элегантная женщина в черном классическом брючном костюме с глубоким вырезом без рубашки, идеально подогнанном жакете, волосы зачесаны назад, эффект мокрой укладки, сидит в кожаном винтажном кресле, сбоку падает свет, на заднем плане винтажные жалюзи высокая мода и атмосфера доверия -соотношение сторон 2:3 -стиль raw", "operation": "gen-multi-input"}', 'rphfvd5cy9rmc0ct5jbtqpw7sm', 'succeeded', '{"date": 1761684686, "chatId": 702968411, "messageId": 131219}', '{"date": 1761684716, "chatId": 702968411, "messageId": 131224}', '[{"date": 1761684756, "chatId": 702968411, "messageId": 131225}]');
INSERT INTO public.operations VALUES ('ac5f61dd-a4bc-4bb1-abc7-fe4e0920030e', '2025-10-23 11:09:23.269403', false, 7551186811, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB20Jo-eKnWWvZtnnEhnHWqcxt8MCvEwACRPYxG1UN0UuxSn7br9v7SgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 736, "heightPx": 1104}], "prompt": "Сделай его как будто он на фотосессии на белом фоне.\nОн сидит на коленях, руки сзади спины, голова наклонена вправо и он смотрит прямо. Сделай фото максимально реалистично, не размыто, не искажая лицо", "operation": "gen-multi-input"}', '362r5tce4drm80ct20erdtss3g', 'succeeded', '{"date": 1761206951, "chatId": 6476248690, "messageId": 121666}', '{"date": 1761206957, "chatId": 6476248690, "messageId": 121669}', '[{"date": 1761206975, "chatId": 6476248690, "messageId": 121670}]');
