INSERT INTO public.operations VALUES ('b4f22257-9912-4da7-b4b6-800461aa6e67', '2025-11-11 10:04:50.608686', false, 8606488014, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAECngJpEt_S_EMwor0bycNcmcaX1P84_AACewxrG7OxmVRI6t4KV7vYJwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Remove hand", "operation": "gen-multi-input"}', 'cmn2pk2a5hrme0cte6xr8r22cm', 'succeeded', '{"date": 1762844626, "chatId": 600937350, "messageId": 171522}', '{"date": 1762844675, "chatId": 600937350, "messageId": 171531}', '[{"date": 1762844703, "chatId": 600937350, "messageId": 171534}]');
INSERT INTO public.operations VALUES ('51cd3407-c4d3-4d7d-8a0b-43ee4fe9b516', '2025-10-28 23:57:24.144428', false, 9920339733, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAAGTaQEszmKrQmvYRGuSrJ_QhZgBXM4AAp3-MRv-AQlIIWa64kbzP4YBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1120, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAGmaQEuJqzaiOyv5GbKHxHcgfMBawoAAvj5MRsTyyFIfNC8g4nxkP0BAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAAGVaQEszt7fVqSaY9w8a1ZZYJ4eKboAApj-MRv-AQlIPGp6PzgPKYgBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 846, "heightPx": 1280}], "prompt": "Эталонное изображение: [нагруженное фото] \nЛицо: сохраните исходное лицо с эталонного изображения, но с натуральным светлым цветом волос, слегка влажной текстурой, выразительным взглядом с сильными тенями на лице, сияющей на солнце кожей. \nПоза: женщина, стоящая на мелководье, опираясь на руки, грациозно выгнув спину, повернув голову к камере, элегантная и властная поза. \nОдежда: платье или боди цвета золотистого металла с мерцающей отражающей текстурой, мокрая поверхность которых отражает солнечный свет, при этом сохраняются естественные складки и блеск. \nАксессуары: широкий золотой браслет-металлик на запястье, маленькие золотые серьги. \nПрическа: влажные светлые волосы зачесаны назад, плавно и естественно струятся. \nФон: открытая вода со спокойной поверхностью, отражающей голубое небо, слегка размытый горизонт, вечерний или ранний утренний солнечный свет, создающий теплые блики. \nАтмосфера: кинематографическая, чувственная и в то же время элегантная, сильный контраст между золотистыми тонами и холодными голубыми отблесками, освещение в редакционном стиле, подчеркивающее форму и текстуру. \nФормат: 2:3 \nНе заменять лицо", "operation": "gen-multi-input"}', 'gr7abrbx5hrmc0ct5jebkwq6cr', 'succeeded', '{"date": 1761685030, "chatId": 702968411, "messageId": 131237}', '{"date": 1761685037, "chatId": 702968411, "messageId": 131242}', '[{"date": 1761685055, "chatId": 702968411, "messageId": 131243}]');
