INSERT INTO public.operations VALUES ('64f3953c-e5bf-4c15-9f85-88dbbac23b49', '2025-10-23 11:11:04.53349', false, 7551186811, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB20Jo-eKnWWvZtnnEhnHWqcxt8MCvEwACRPYxG1UN0UuxSn7br9v7SgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 736, "heightPx": 1104}], "prompt": "Сделай его как будто он на фотосессии на белом фоне.\nОн сидит на коленях прямо, руки сзади спины, голова наклонена вправо и он смотрит прямо слегка улыбаясь. Сделай фото максимально реалистично, не размыто, не искажая лицо", "operation": "gen-multi-input"}', '9gkf47gs7nrmc0ct20fvnmfgtm', 'succeeded', '{"date": 1761207028, "chatId": 6476248690, "messageId": 121673}', '{"date": 1761207059, "chatId": 6476248690, "messageId": 121676}', '[{"date": 1761207076, "chatId": 6476248690, "messageId": 121677}]');
INSERT INTO public.operations VALUES ('0bce09b9-3642-4a82-8b62-4cbf6c642d2e', '2025-10-29 12:09:34.28344', false, 7513945372, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAdtpAdYzTEIMtI9DtwSt7InGZB9sSwACzfMxG_AYEEh2QpHyz9ikTwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Сделай фото девушки перед камерой в нежном оттенке. На фоне осеннего леса. В коротком кружевном платье белого цвета. Что бы рядом с девушкой был мерседес серого цвета", "operation": "gen-multi-input"}', '2yg64mper1rme0ct5wxb48x8rr', 'succeeded', '{"date": 1761728158, "chatId": 8053638727, "messageId": 131557}', '{"date": 1761728970, "chatId": 8053638727, "messageId": 131593}', '[{"date": 1761728984, "chatId": 8053638727, "messageId": 131594}]');
INSERT INTO public.operations VALUES ('83c8002d-aa7a-4b7a-b3bc-30ceb2c07132', '2025-10-23 11:12:02.746672', false, 7551186811, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEB205o-eM7fywF43oB4-NAOhihu9DHcAACGRkyG030yEvHBaMcB3tZZwEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 312, "heightPx": 420}], "prompt": "Сделай его как будто он на фотосессии на белом фоне. Он стоит, скрестив руки на груди, и смотрит прямо.\nЛицо будто бы доминирующее и серьёзное. Сделай фото максимально реалистично, не размыто, не искажая лицо", "operation": "gen-multi-input"}', '5tytfdqwpxrm80ct20fs0hgdvc', 'succeeded', '{"date": 1761207099, "chatId": 6476248690, "messageId": 121678}', '{"date": 1761207119, "chatId": 6476248690, "messageId": 121683}', '[{"date": 1761207136, "chatId": 6476248690, "messageId": 121684}]');
