INSERT INTO public.operations VALUES ('e97dd933-828e-4fbe-bba0-f0defd529913', '2025-10-29 00:34:48.327367', false, 6068391019, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAAH3aQE2ayk8pEUyLupRGZatrgxaIo4AAs0CMhuy_glIDLh4NZVFgssBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 715, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAQFpATbypjh5MZkVwZs89U2Z3fPu1QACzwIyG7L-CUhVjRdNwBgIZAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECAQJpATbyNJ4hGgFHHfya6NKTMbkligAC1AIyG7L-CUijsrV5lnUrZAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "«Создай изображение в Ultra-HD (8K) студийного портрета девушки с ярким летним макияжем. Одна половина её лица прикрыта сочной долькой апельсина. Макияж насыщенный: оранжевые тени, подчёркнутые чёрной графичной стрелкой, выразительные ресницы, матовые розово-нюдовые губы, сияющая кожа с лёгким эффектом свечения. Волосы темные, уложены гладко. Образ дополнен яркими жёлтыми серьгами геометрической формы. Фон - насыщенно-синий или контрастно тёплый, подчёркивающий свежесть композиции. В chatgpt.com изображении максимально повтори черты лица из фотографии, которую я загрузила»", "operation": "gen-multi-input"}', 'dfpw0qnts9rma0ct5jzan086aw', 'succeeded', '{"date": 1761687282, "chatId": 5155579201, "messageId": 131328}', '{"date": 1761687283, "chatId": 5155579201, "messageId": 131333}', '[{"date": 1761687305, "chatId": 5155579201, "messageId": 131340}]');
INSERT INTO public.operations VALUES ('e06ba286-273f-4278-9905-7d7a435a002a', '2025-10-29 00:35:03.017987', false, 6533000631, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAAH9aQE27XDbgG8U4OENATBKNrC25ikAAvn7MRva5glInZDwqYFvMSIBAAMCAAN4AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 678, "heightPx": 677}], "prompt": "Женщина, грациозно позирующая за белым роялем, в белой атласной юбке и изысканном жемчужном топе с многослойными ожерельями. Ее поза уверенная, плечи расправлены, одна рука элегантно опущена. Фон мягко освещен, что подчеркивает текстуру атласной ткани и жемчужные детали. Освещение: рассеянный софтбокс сбоку с теплыми оттенками. Камера: средний кадр, низкий угол для удлинения силуэта. Настроение: модная редакция, роскошная элегантность.", "operation": "gen-multi-input"}', '1r5mevfm01rm80ct5jz8kvk5g8', 'succeeded', '{"date": 1761687277, "chatId": 5023869138, "messageId": 131325}', '{"date": 1761687300, "chatId": 5023869138, "messageId": 131339}', '[{"date": 1761687313, "chatId": 5023869138, "messageId": 131341}]');
