INSERT INTO public.operations VALUES ('5343ba85-01cc-4498-a6b6-fa4ad01a4a3f', '2025-10-29 20:06:39.260491', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECAytpAg6fi4TsLlED4iQ1b6f5smYQ4AACOQIyG4qQEUgDW-cuUs0x6AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки. Максимально сохрани мою внешность. Девушка лежит на спине на диване , фото сделано сверху . На девушке одета белая свободная рубашка с глубоким открытым вырезом на груди. У девушки черные длинные волосы уложены большими локонами коровье лежит на диване в разные стороны . У девушки маленькие серьги и цепочка. Девушка лежит головой к подлокотнику, на фото попадает часть стены которая выкрашена в серый  цвет. Девушка одной рукой касается губ, рот слегка приоткрыт", "operation": "gen-multi-input"}', 'g9q2gg4r8nrme0ct63qs08xgh0', 'failed', '{"date": 1761757567, "chatId": 1287537311, "messageId": 132047}', '{"date": 1761757598, "chatId": 1287537311, "messageId": 132052}', '[{"date": 1761757598, "chatId": 1287537311, "messageId": 132052}]');
