INSERT INTO public.operations VALUES ('d2528781-78ef-4936-b765-8a1edb19f247', '2025-10-29 20:40:27.627038', false, 6051602240, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECBIJpAlF38empBxc-6xGY7v5SfHqb3gACmPwxG5XYGEgzgh6PofKLawEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "1️⃣ Создай насыщенный, атмосферный, реалистичный зимний портрет в русском стиле. Я нахожусь в заснеженном лесу среди елей. На мне роскошная длинная коричневая шуба с густым мехом и яркий красный кокошник, украшенный золотой вышивкой, жемчужными подвесками и красными камнями. На губах яркая красная помада. Я с лёгкой улыбкой ем красную икру большой серебряной ложкой из хрустальной миски, стоящей на столе. На столе — старинный самовар с баранками, мандарины, хлеб, сладости, бокалы, пар от чая.\nВокруг снежный лес, всё покрыто инеем, мягкий золотистый свет зимнего солнца, лёгкое боке, кинематографическое освещение. Реалистичная фотография с богатой детализацией — мех, икра, снег, металл, отражения.\n—ar 9:12 —v 6", "operation": "gen-multi-input"}', 'epg4jrwavxrme0ct64797w58km', 'failed', '{"date": 1761759607, "chatId": 875745807, "messageId": 132226}', '{"date": 1761759613, "chatId": 875745807, "messageId": 132229}', '[{"date": 1761759613, "chatId": 875745807, "messageId": 132229}]');
