INSERT INTO public.operations VALUES ('38b25ca4-0be3-4d3c-a306-4344df1e5e83', '2025-10-29 20:41:59.182751', false, 6051602240, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECBIJpAlF38empBxc-6xGY7v5SfHqb3gACmPwxG5XYGEgzgh6PofKLawEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "1️⃣ Создай насыщенный, атмосферный, реалистичный зимний портрет в русском стиле. Я нахожусь в заснеженном лесу среди елей. На мне роскошная длинная коричневая шуба с густым мехом и яркий красный кокошник, украшенный золотой вышивкой, жемчужными подвесками и красными камнями. На губах яркая красная помада. Я с лёгкой улыбкой ем красную икру большой серебряной ложкой из хрустальной миски, стоящей на столе. На столе — старинный самовар с баранками, мандарины, хлеб, сладости, бокалы, пар от чая.\nВокруг снежный лес, всё покрыто инеем, мягкий золотистый свет зимнего солнца, лёгкое боке, кинематографическое освещение. Реалистичная фотография с богатой детализацией — мех, икра, снег, металл, отражения.\n—ar 9:12 —v 6", "operation": "gen-multi-input"}', 'zeydbmfjqdrma0ct647rtvbz44', 'failed', '{"date": 1761759665, "chatId": 875745807, "messageId": 132232}', '{"date": 1761759676, "chatId": 875745807, "messageId": 132235}', '[{"date": 1761759676, "chatId": 875745807, "messageId": 132235}]');
