INSERT INTO public.operations VALUES ('2cb4a9ef-0812-476d-ab4d-165e66e4e957', '2025-10-30 14:29:12.207286', false, 1699908121, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECBxJpA0v81mCmjxNAkFIVkdQnJE0qAwACJgMyG3csGEj5X10r9kcGxQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECBxNpA0v8rItjfW6anhthtSe3wwzIYAACJwMyG3csGEh8AiXTVd5ZcAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "сделай так, чтобы фото двух людей выглядело как настоящий Polaroid-снимок Атмосфера должна быть спонтанный и живой,будто кадр случайно поймали без позирования и реквизита\nДобавь легкое размытие от движения и мягкий свет вспышки,равномерно рассеивающийся в темном пространстве .Лица не искажай - они должны сохраниться такими же, как на присланном фото. Замени фон на простую белую занавеску,создавая ощущение домашней непринужденности.\nДвое людей обнимаются и смотрят прямо в камеру , момент выглядит интимным и естественным,без постановочности", "operation": "gen-multi-input"}', 'm3k0g4g171rme0ct6kgvk8fms0', 'failed', '{"date": 1761823740, "chatId": 1118260170, "messageId": 132882}', '{"date": 1761823746, "chatId": 1118260170, "messageId": 132886}', '[{"date": 1761823746, "chatId": 1118260170, "messageId": 132886}]');
