INSERT INTO public.operations VALUES ('60114184-a802-42ab-bf15-97bc01a6a2ae', '2025-10-31 14:30:48.692351', false, 8551817670, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECC5tpBJ3fi5tEmhi6K2T3CAVmhmFslwACNgIyG8xGKUhr9gN9_OM32wEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 474, "heightPx": 474}], "prompt": "Создай картинку в этом же стиле. Как мать укладывает ребёнка лет 3-4 спать, сидит рядом и гладит его по голове. И между ними какая-то невидимая едва уловимая связь. А рядом в углу на полке стоят иконы и подсвечники. Интерьер напоминает деревенский домик.", "operation": "gen-multi-input"}', 'd5qa99eqj9rmc0ct7849awq27m', 'succeeded', '{"date": 1761910239, "chatId": 6978951501, "messageId": 134043}', '{"date": 1761910246, "chatId": 6978951501, "messageId": 134048}', '[{"date": 1761910259, "chatId": 6978951501, "messageId": 134049}]');
