INSERT INTO public.operations VALUES ('b8524c80-fd3b-422e-bb1e-b6c45e123228', '2025-10-31 17:53:17.83697', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECDIJpBMzp4zuTEaXuzR0_Nm-NeIhW6wACC_wxG_EZKEhZPqruC11-tQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 951, "heightPx": 1280}], "prompt": "Создай фото девушки. Максимально сохрани внешность. Девушка на море делает селфи. Девушка делает фото вблизи что фона почти не видноПогода яркая солнечная. Девушка одета в черный слитный купальник с глубоким вырезом на груди. У девушки черные , длинные, прямые полосы. Левой рукой девушка как будто нежно гладит подбородок подняв локоть руки вверх. У девушки одета тонка цепочка.", "operation": "gen-multi-input"}', 'gcbm8njsjdrme0ct7b19jccnm0', 'failed', '{"date": 1761922344, "chatId": 1287537311, "messageId": 134281}', '{"date": 1761922372, "chatId": 1287537311, "messageId": 134286}', '[{"date": 1761922372, "chatId": 1287537311, "messageId": 134286}]');
INSERT INTO public.operations VALUES ('3abac4af-07b4-41e7-9cfb-dd33481930b5', '2025-11-15 05:03:11.442762', false, 2924622094, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgEAAxkBAAEC3LZpF986P-kjDENqBsVfajxvIk7btAACYgtrG-XFuUT-pbUZHRra4QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "сделай чтобы эта авария была как в рюеальности", "operation": "gen-multi-input"}', 'qennyawe6drmc0ctgn08bdsaa8', 'succeeded', '{"date": 1763172154, "chatId": 6739927328, "messageId": 187574}', '{"date": 1763172181, "chatId": 6739927328, "messageId": 187579}', '[{"date": 1763172205, "chatId": 6739927328, "messageId": 187580}]');
INSERT INTO public.operations VALUES ('83804031-26d5-4690-a512-cfbf75af0683', '2025-10-31 17:49:34.732031', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECDC9pBMqVeCgxrFFCmzYZ5Eg-FP422gAC-PsxG_EZKEjIz0SyJtvpbQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создайте образ девушки сидящей на яхте в открытом море, на фоне морского пейзажа.\nДевушка с черными волосами , лицо не меняй , одета в элегантный черный Боди корсетного плана (без лямок) и в накидке белой изящно струящейся из мягкой, воздушной ткани, которая мягко колышется на ветру. Боди слегка блестит, подчеркивая гладкую текстуру материала, похожего на шелк, и мягко ниспадает к низу. Она сидит с безмятежным выражением Ю лица с закрытыми глазами, девушка подняла две руки и одну руку засунула себе в волосы, вторая поднята вверх.\nумиротворяющая атмосфера, присутствует на снимке.\nНа заднем плане море , создавая обширную,открытую и естественную обстановку. Солнце освещает.", "operation": "gen-multi-input"}', 'dnfdh4efydrma0ct7az8vybypr', 'succeeded', '{"date": 1761922159, "chatId": 1287537311, "messageId": 134249}', '{"date": 1761922163, "chatId": 1287537311, "messageId": 134254}', '[{"date": 1761922186, "chatId": 1287537311, "messageId": 134261}]');
INSERT INTO public.operations VALUES ('8cfe64ee-f1aa-4cee-a8f9-792c80e8ea05', '2025-10-31 17:48:45.355337', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECA9lpAknjSzVatHy2c5wwu3M8plX64AACaAUyG4qQEUhaieTm1uuqAwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создайте образ девушки сидящей на яхте в открытом море, на фоне морского пейзажа.\nДевушка с черными волосами , лицо не меняй , одета в элегантный черный Боди корсетного плана (без лямок) и в накидке белой изящно струящейся из мягкой, воздушной ткани, которая мягко колышется на ветру. Боди слегка блестит, подчеркивая гладкую текстуру материала, похожего на шелк, и мягко ниспадает к низу. Она сидит с безмятежным выражением Ю лица с закрытыми глазами, девушка подняла две руки и одну руку засунула себе в волосы, вторая поднята вверх.\nумиротворяющая атмосфера, присутствует на снимке.\nНа заднем плане море , создавая обширную,открытую и естественную обстановку. Солнце освещает.", "operation": "gen-multi-input"}', '61t2k78fc9rma0ct7azahyttzw', 'succeeded', '{"date": 1761922103, "chatId": 1287537311, "messageId": 134236}', '{"date": 1761922124, "chatId": 1287537311, "messageId": 134242}', '[{"date": 1761922139, "chatId": 1287537311, "messageId": 134243}]');
