INSERT INTO public.operations VALUES ('ba3d2113-1c02-49b0-9543-af2790431e3c', '2025-10-31 17:50:53.222017', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECDC9pBMqVeCgxrFFCmzYZ5Eg-FP422gAC-PsxG_EZKEjIz0SyJtvpbQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай фото девушки. Максимально сохрани внешность. Девушка на море делает селфи близки по грудь. Погода яркая солнечная. Девушка одета в черный слитный купальник с глубоким вырезом на груди. У девушки черные , длинные, прямые полосы. На голову у девушки завязана бандана коричневого цвета. Левой рукой девушка как будто нежно гладит подбородок подняв локоть руки вверх. У девушки одета тонка цепочка.", "operation": "gen-multi-input"}', 'e6jxsh853xrmc0ct7b0bzd1h7r', 'succeeded', '{"date": 1761922235, "chatId": 1287537311, "messageId": 134266}', '{"date": 1761922249, "chatId": 1287537311, "messageId": 134272}', '[{"date": 1761922263, "chatId": 1287537311, "messageId": 134273}]');
