INSERT INTO public.operations VALUES ('66a6d722-20e1-43b9-bb2a-93528f3078aa', '2025-10-31 18:12:00.524543', false, 4319239834, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECDLBpBNFRYvvXXdggJU_8-HL7F7_qNwACk_8xG-hCKUiU7MSB7j2AAwEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1919, "heightPx": 2560}], "prompt": "Создай те мою фотографию в стиле y2k, где девушка и Легион из игры Dead by Deadlight делают фотографию в зеркале. Он обнимает её за талию. Комната за их спинами выглядит в готическом стиле с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Фон позади должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', '8tqkmxas1drm80ct7b9vqj5nt8', 'succeeded', '{"date": 1761923409, "chatId": 5240551542, "messageId": 134320}', '{"date": 1761923517, "chatId": 5240551542, "messageId": 134332}', '[{"date": 1761923533, "chatId": 5240551542, "messageId": 134333}]');
