INSERT INTO public.operations VALUES ('4689d7d3-2920-4a95-b13b-46d251b78653', '2025-10-31 21:53:02.607441', false, 4319239834, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECDyZpBQVfveIAAQhXR-w8N8VLhmXUiGwAAgUBMhvoQilIMT7_nTQ4yYoBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 949, "heightPx": 1280}], "prompt": "Создайте мою фотографию в мечтательном стиле y2k, где девушка лежит на леопардовом постельном белье, держа в руках большой розовый ретро-телефон с проводом из 90-х.\nНа мне готические украшения. Комната за ее спиной выглядит, как у подростка в готическом стиле с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. \nGhostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. Фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', '181v5zdp2nrma0ct7eet4pd61m', 'failed', '{"date": 1761936735, "chatId": 5240551542, "messageId": 134950}', '{"date": 1761936780, "chatId": 5240551542, "messageId": 134955}', '[{"date": 1761936780, "chatId": 5240551542, "messageId": 134955}]');
