INSERT INTO public.operations VALUES ('1787b413-87fd-494c-9b69-7adc86d7d662', '2025-10-31 21:58:12.982973', false, 4319239834, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECDyZpBQVfveIAAQhXR-w8N8VLhmXUiGwAAgUBMhvoQilIMT7_nTQ4yYoBAAMCAAN5AAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 949, "heightPx": 1280}], "prompt": "Создайте мою фотографию в стиле y2k, где девушка лежит на бордовом постельном белье, держа в руках большой черный ретро-телефон с проводом из 90-х. На девушке белые украшения. Комната за ее спиной выглядит, как у подростка с плакатами в стиле 90-х. Ее макияж простой. Фотография должна иметь зернистый стиль 90-х с источником света, например, лампой в тускло освещенной комнате ночью. Рядом с ней стоит миска попкорна, чипсы и несколько журналов в стиле 90-х. Ghostface должен быть позади нее и смотреть на нее, его тело должно быть тускло освещено, и он должен стоять в дверном проеме тускло освещенного коридора. Фон позади него должен быть слегка темным и зловещим. Фото должно быль вертикальным, немного с киношным вайбом.", "operation": "gen-multi-input"}', 'tjgzagbjfxrmc0ct7eh9fz3430', 'succeeded', '{"date": 1761937082, "chatId": 5240551542, "messageId": 134992}', '{"date": 1761937091, "chatId": 5240551542, "messageId": 134997}', '[{"date": 1761937125, "chatId": 5240551542, "messageId": 135003}]');
INSERT INTO public.operations VALUES ('9c0bd9c1-e6ed-4cc5-ac81-26c1ad9d90a1', '2025-11-11 12:44:01.282817', false, 2931447169, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECoFRpEwVJ6r0a9LYF_ecZ0WbkBaZUgQAC1AxrG4A3mUhHRotEDOcFyQEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1920, "heightPx": 2560}], "prompt": "Преобразовать это изображение в профессиональную, детализированную предметную фотографию подвески. Подвеска из холодного мягкого, светлого белого золота. С узорами точно так как на фото. Крупный план, чтобы были видны все детали. Удалить весь фон и заменить его на чистый белый фон #fff. Улучшить освещение и четкость бриллиантов, чтобы подчеркнуть их блеск и игру. Сохранить общий дизайн и пропорции подвески. Высокое разрешение.\n\nУбери лишние тени. Сделай так словно подвеска парит ( добавь снизу тень )", "operation": "gen-multi-input"}', '51dc3s04rxrmc0cte96sc2frsc', 'succeeded', '{"date": 1762854217, "chatId": 8269341146, "messageId": 172116}', '{"date": 1762854238, "chatId": 8269341146, "messageId": 172121}', '[{"date": 1762854255, "chatId": 8269341146, "messageId": 172122}]');
