INSERT INTO public.operations VALUES ('0f9eeb9b-91de-4550-b062-13d1c7d5dfba', '2025-11-01 17:13:32.395384', false, 4264175294, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAECFftpBhWE3-hn_vFnu3mLN50WA-CzqgACpw5rGzXjMFRuoJG5v7h1rAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}, {"file": {"fileId": "AgACAgUAAxkBAAECFfxpBhWEhsXZHalRt9TCh8fzYwGbngACqA5rGzXjMFSRxNm0bRxa1gEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1024, "heightPx": 1024}], "prompt": "یک لحظه عاشقانه...\n\nدست‌هایت در دست‌های من، قلب‌هایمان به هم متصل شده‌اند\nدر این لحظه، دنیا برای ما متوقف شده است\nچشمانت به چشمان من خیره شده‌اند، و من در عمق آنها غرق شده‌ام\nلب‌هایت به لب‌های من نزدیک شده‌اند، و من احساس می‌کنم که دنیا از بین رفته است\n\nما در این لحظه، تنها دو نفر در جهان هستیم\nدنیا برای ما متوقف شده است، و زمان به حرکت در نیامده است\nما فقط به هم نگاه می‌کنیم، و قلب‌هایمان به هم می‌تپند\nدر این لحظه، عشق ما به اوج خود رسیده است\n\nدست‌هایت را دور من حلقه کن، و مرا به خود بچسبان\nچشمانت را به چشمان من بچسبان، و مرا با عشق خود پر کن\nلب‌هایت را به لب‌های من بچسبان، و مرا با عشق خود ببوس\nدر این لحظه، ما فقط دو نفر در جهان هستیم، و عشق ما به اوج خود رسیده است.\n\nدر صورتی که قصد دارید راجع به مسئله جدیدی با ربات صحبت کنید از دکمه شروع مکالمه جدید استفاده کنید!", "operation": "gen-multi-input"}', 'r74h729d9srma0ct7z2a54pc20', 'succeeded', '{"date": 1762006404, "chatId": 8372150474, "messageId": 136699}', '{"date": 1762006409, "chatId": 8372150474, "messageId": 136703}', '[{"date": 1762006426, "chatId": 8372150474, "messageId": 136704}]');
