INSERT INTO public.operations VALUES ('0329e4d2-7e8e-41dc-9b4b-06e2c3e61f7d', '2025-11-11 17:47:32.86167', false, 9528068843, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "4:3"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [], "prompt": "🎧Аким - Ты меня люби\n\nТы меня люби люби люби\nНикому любовь не отдавай\nСердце умирает от тоски\nВ твоих глазах я вижу рай\nТы меня люби люби люби\nВ жизни моей вечный ты маяк\nСердце умирает от тоски\nЕсли рядом нет нет тебя\n\nВ глазах карих карих\nТону снова снова\nТебя вновь увидеть\nИщу повод повод\nВ жизни так бывает\nЛюбить больно больно\nНо всё забываю\nКогда на меня смотришь\n\nУуу красивая\nНе могу тебя я потерять\nБез тебя никак\n\nТы меня люби люби люби\nНикому любовь не отдавай\nСердце умирает от тоски\nВ твоих глазах я вижу рай\nТы меня люби люби люби\nВ жизни моей вечный ты маяк\nСердце умирает от тоски\nЕсли рядом нет нет тебя\n\nГлаза карие карие\nЯ обезумил словно\nСлеза будто болит\nКогда я делал больно\nКрепко обнимаю\nИ ты уже простила\nВсе что хочу я\nЧтобы меня любила\n\nУуу красивая\nНе могу тебя я потерять\nБез тебя никак\n\nТы меня люби люби люби\nНикому любовь не отдавай\nСердце умирает от тоски\nВ твоих глазах я вижу рай\nТы меня люби люби люби\nВ жизни моей вечный ты маяк\nСердце умирает от тоски\nЕсли рядом нет нет тебя\n\nMusiqalar matni 😘", "operation": "gen-multi-input"}', 'w6g0w0780hrme0ctedhbstwf30', 'succeeded', '{"date": 1762872421, "chatId": 7650483773, "messageId": 172883}', '{"date": 1762872421, "chatId": 7650483773, "messageId": 172884}', '[{"date": 1762872468, "chatId": 7650483773, "messageId": 172888}]');
