INSERT INTO public.operations VALUES ('18f7cda9-e041-417c-b15e-d0af8e8296e3', '2025-11-06 08:49:16.033516', false, 2072545847, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECQC9pDDbN54Yedz99SvMd121jP6t9EgAC5AxrGymIYEg5NiHR8GEPSwEAAwIAA3gAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 272, "heightPx": 608}], "prompt": "Интерьер лифта из нержавеющей стали с зеркальными стенами, подсвеченными кнопками и мягким светом. Атмосфера холодная, элегантная, с мягкими отражениями.\n(не менять лицо). Уверенный взгляд в камеру, лёгкая полуулыбка.\n Чёрные красивые одежда, в левой руке часы из ролекса. В правой руке S24 ultra, делает селфи;  закрывает тело.\nКамера S 24 ultra, фронтальная, 4:3, уровень глаз, поворот плеч ¾, фокус на лице и букетах. Освещение мягкое — потолочный свет и экран телефона, баланс ≈ 4800 K, лёгкая недоэкспозиция.\nМакияж: чистая кожа, лёгкий контур, чёрные глаза, \nСтиль: ультрареализм, отражения естественные, без CGI.", "operation": "gen-multi-input"}', 'emhgcxadz9rm80ctayv8tqgqw4', 'succeeded', '{"date": 1762408141, "chatId": 8304200490, "messageId": 147503}', '{"date": 1762408148, "chatId": 8304200490, "messageId": 147506}', '[{"date": 1762408167, "chatId": 8304200490, "messageId": 147507}]');
