INSERT INTO public.operations VALUES ('eee8f2ed-3471-4173-8c97-b677b0be0b99', '2025-11-12 17:36:57.039228', false, 5228683414, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECsvNpFJt9sZIZgFQsROAxsZf3OYRdtwACdA5rGyNrqEhBDNNZEa39swEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "«Модный портрет женщины, стоящей прямо перед камерой, слегка наклонив подбородок вверх. Она держит замысловатую золотую корону, почти над головой, с богато украшенной филиграной и большими, блестящими драгоценностями. Корона находится в резком фокусе, отбрасывая мягкую тень на ее лицо. Освещение падает сверху, подчеркивая корону и создавая драматический, высококонтрастный эффект. Легкая тень на ее лице усиливает чувство тайны и элегантности. Ее платье\n- это нежное черное кружево с высоким вырезом, а оправа отрезается на плечах. Фон остается темным и минималистичным, усиливая угрюмую и царственную атмосферу сцены.", "operation": "gen-multi-input"}', 'bwjf5ycgpsrmc0ctf1zv4167f4', 'succeeded', '{"date": 1762958205, "chatId": 5074519088, "messageId": 176883}', '{"date": 1762958211, "chatId": 5074519088, "messageId": 176886}', '[{"date": 1762958231, "chatId": 5074519088, "messageId": 176887}]');
