INSERT INTO public.operations VALUES ('6dad440c-0fc8-442e-8bd2-c830fa131cde', '2025-11-12 17:39:36.656493', false, 5228683414, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECsvNpFJt9sZIZgFQsROAxsZf3OYRdtwACdA5rGyNrqEhBDNNZEa39swEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 720, "heightPx": 1280}], "prompt": "Я держу замысловатую золотую корону, почти над головой, с богато украшенной филиграной и большими, блестящими драгоценностями. Корона находится в резком фокусе, отбрасывая мягкую тень на ее лицо. Освещение падает сверху, подчеркивая корону и создавая драматический, высококонтрастный эффект. Легкая тень на ее лице усиливает чувство тайны и элегантности. Ее платье\n- это нежное черное кружево с высоким вырезом, а оправа отрезается на плечах. Фон остается темным и минималистичным, усиливая угрюмую и царственную атмосферу сцены.", "operation": "gen-multi-input"}', '721ta9qzx1rmc0ctf20t0cktv0', 'succeeded', '{"date": 1762958316, "chatId": 5074519088, "messageId": 176893}', '{"date": 1762958373, "chatId": 5074519088, "messageId": 176906}', '[{"date": 1762958389, "chatId": 5074519088, "messageId": 176907}]');
