INSERT INTO public.operations VALUES ('83c85909-b433-4eff-ad9e-f12f65a703fd', '2025-11-07 16:37:33.719598', false, 9093213906, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECS0tpDfQ9hDXjP7Jp-vwdAgE728hgfgACNQ9rG6CacEj8IIBbpino1QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Эта куртка темно-зеленого цвета надета на молодого человека. Привлекательной внешности. Молодой человек идёт по улице , вдалеке видно здания Москва сити , смотрит в сторону объектива. Людей поблизости нет.\nвсе детали куртки хорошо видны.нашивка на левом рукаве тоже хорошо видна. Капюшон поднят, но не застегнут.\nМолодой человек красиво одет в стиле стрит стайл. Джоггеры с карманами и лентами, ботинки в стиле стрит стайл.", "operation": "gen-multi-input"}', 'shzgjj35mnrm80ctbt4s4jsa5g', 'succeeded', '{"date": 1762522173, "chatId": 7511659669, "messageId": 150347}', '{"date": 1762522629, "chatId": 7511659669, "messageId": 150363}', '[{"date": 1762522671, "chatId": 7511659669, "messageId": 150370}]');
INSERT INTO public.operations VALUES ('6f29fc13-62e7-4dce-b5ab-58c11d6ff546', '2025-11-07 16:23:20.389186', false, 9093213906, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECS0RpDfHIzoe3TNziCEZ8TyNMp9_sCQACGw9rG6CacEiP_dPdeupFNQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 629, "heightPx": 1280}], "prompt": "Эти джоггеры надеты на молодом человеке среднего роста, подросток, похож на Хулио Иглесиас. Футболка, аксессуары на шее, на руке перстень  в стиле готика , кроссовки стрит стайл.\nОн идет возле светлой стены на улице, безлюдно.", "operation": "gen-multi-input"}', 'egazrv2zqhrm80ctbsyan7rez0', 'succeeded', '{"date": 1762521544, "chatId": 7511659669, "messageId": 150340}', '{"date": 1762521798, "chatId": 7511659669, "messageId": 150345}', '[{"date": 1762521811, "chatId": 7511659669, "messageId": 150346}]');
