INSERT INTO public.operations VALUES ('e6c45902-fdc7-4ad2-b2e0-bcd6e7f0a029', '2025-11-08 10:29:50.868401', false, 7282308082, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAECU6NpDu7JnJQi5pmGJurgsEHMzogNUQAC9gxrG0SIeFQEbr3bfhvDdgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 576, "heightPx": 1280}], "prompt": "\"A minimalist celestial necklace pendant featuring only the planet Saturn with its rings. A single five-pointed star is attached to Saturn''s ring. There are no other stars, no moons, and no astronauts in the design. Clean, solid dark background, professional jewelry photography, silver.\"\n\nWhy this prompt works:\n\n· \"A minimalist celestial necklace pendant featuring only the planet Saturn with its rings\": Clearly defines the main subject and removes all other elements (like moons or astronauts) that are often in \"celestial\" designs.\n· \"A single five-pointed star is attached to Saturn''s ring\": This is the critical detail you asked for, placing the star specifically on the ring.\n· \"There are no other stars, no moons, and no astronauts in the design\": This negative prompt explicitly removes the triple stars and any other unwanted elements.\n· \"Clean, solid dark background, professional jewelry photography, silver\": Sets the style for a high-quality, clear product image.", "operation": "gen-multi-input"}', '11pdjm8t1srme0ctc9fszxb07m', 'succeeded', '{"date": 1762586973, "chatId": 6626913375, "messageId": 152516}', '{"date": 1762586988, "chatId": 6626913375, "messageId": 152519}', '[{"date": 1762587000, "chatId": 6626913375, "messageId": 152520}]');
