INSERT INTO public.operations VALUES ('576a2475-33c9-4c78-99c8-3f8efb4a953d', '2025-11-13 14:33:40.892151', false, 1790102601, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECwHZpFcIFoXg8C7W5dS3dbmLlQ-KpvgAClg1rGxJjsUh3zk1jJvQO_AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 519, "heightPx": 828}, {"file": {"fileId": "AgACAgIAAxkBAAECwHdpFcIF1pUNa1Hwj2-ILOEjTN4dqAACBA1rG4ZasUgEHnIUIJvejQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "Реалистичная черно-белая фотография пары.\nМужчина в черной рубашке крепко держит женщину на руках и целует ее шею. Женщина в коротком черном платье с открытыми плечами, откидывается назад с закрытыми глазами, ее волнистые волосы свободно падают вниз.\nМягкий рассеянный студийный свет, простой светлый фон. Атмосфера страсти, нежности и близости. Съемка крупным планом, в высоком разрешении, без эффектов, максимально естественная кожа, реалистичная текстура ткани и волос, стиль - художественная студийная фотография", "operation": "gen-multi-input"}', 'j65j6js329rma0ctfkz9kd7484', 'succeeded', '{"date": 1763033605, "chatId": 1088463466, "messageId": 180342}', '{"date": 1763033612, "chatId": 1088463466, "messageId": 180347}', '[{"date": 1763033633, "chatId": 1088463466, "messageId": 180351}]');
