INSERT INTO public.operations VALUES ('af13d225-1ffb-4b9a-a3f3-07c7daaa180b', '2025-11-14 00:44:20.027185', false, 6872151340, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "as-input"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECyGppFlC4WAtMY79m8GT9QEJVaa8BNgAC5xBrG-JwsEiT2UURcHRKaAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECyHFpFlEeHJgv4AT4Wm5uvNg7BIwuOgACuRBrGwP7sUiyF4X8648z1QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 682, "heightPx": 1195}], "prompt": "Создай черно-белую фотографию в стиле двойной экспозиции: мужчина и девушка в черной одежде стоят, соприкасаясь лбами. Их\n\nосновные силуэты должны\n\nбыть четкими, а\n\nсмещенные призрачные\n\nкопии - бледными,\n\nсоздавая глубину. Важно\n\nсохранить точные черты\n\nлиц и все детали (серьги-\n\nцепочки, колье, корсет, ть\n\nперчатки, браслет) на\n\nфоне светлой стены", "operation": "gen-multi-input"}', 'sgr84nsmk5rme0ctfwpt03xk8c', 'succeeded', '{"date": 1763070238, "chatId": 921800217, "messageId": 182384}', '{"date": 1763070247, "chatId": 921800217, "messageId": 182388}', '[{"date": 1763070286, "chatId": 921800217, "messageId": 182396}]');
INSERT INTO public.operations VALUES ('1cddd472-2380-4288-8405-5574295bb883', '2025-11-14 00:52:50.146921', false, 6872151340, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECyGppFlC4WAtMY79m8GT9QEJVaa8BNgAC5xBrG-JwsEiT2UURcHRKaAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}, {"file": {"fileId": "AgACAgIAAxkBAAECyH9pFlMJsazBDJJZvzwXuxxQIbWGQgACxBBrGwP7sUgzB9fCjwtIpAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Двое в возрасте 20-21 года, стоящие на белом фоне, сочетающие позы и черты лица с двух предоставленных эталонных фотографий. Оба стоят, слегка развернувшись на 10-20°, один чуть впереди другого, руки расслаблены (по желанию, одна рука в кармане). Черно-белая фотография, высокая контрастность (или мягкие оттенки серого), студийное освещение в софтбоксе с тонкими тенями, подчеркивающими текстуру кожи и ткани. Камера: портретный объектив 50 мм/85 мм, малая глубина резкости f/2,8–f/4, съемка в полный рост или по пояс. Фотореалистичный, сверхдетализированный снимок.\"", "operation": "gen-multi-input"}', 'ah3jhkfwxsrm80ctfwtaa9h1z4', 'succeeded', '{"date": 1763070729, "chatId": 921800217, "messageId": 182398}', '{"date": 1763070766, "chatId": 921800217, "messageId": 182402}', '[{"date": 1763070788, "chatId": 921800217, "messageId": 182403}]');
