INSERT INTO public.operations VALUES ('448268b6-5fa5-4836-9e4e-4e8914aafff2', '2025-11-10 12:06:11.78186', false, 7472974079, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAECiklpEardV0UIjYcStfj6DEwXtmYgiAACQwxrGylQkEjvhgGG2im1OgEAAwIAA3cAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1922, "heightPx": 2560}], "prompt": "Преобразовать это изображение в профессиональную, детализированную предметную фотографию серег. Серьги из холодного мягкого, светлого белого золота и теплого светлого золота ( в точности в тех местах, как на фото ) инкрустированое бриллиантами. Крупный план, чтобы были видны все детали. Логично посмотри и обдумай где расположение бриллиантов, а затем чётко очерти их и все остальные детали. Удалить весь фон и заменить его на чистый белый фон #fff. Улучшить освещение и четкость бриллиантов, чтобы подчеркнуть их блеск и игру. Сохранить общий дизайн и пропорции серег. Высокое разрешение.\n\nУбери лишние тени. Сделай так словно пусеты парят ( добавь снизу тень )", "operation": "gen-multi-input"}', 'yd62d388anrme0ctdm2bt5w4w4', 'succeeded', '{"date": 1762765533, "chatId": 6435850309, "messageId": 166473}', '{"date": 1762765565, "chatId": 6435850309, "messageId": 166476}', '[{"date": 1762765581, "chatId": 6435850309, "messageId": 166477}]');
INSERT INTO public.operations VALUES ('571cfbe2-f46a-4df6-9b3d-6ddb7e0fdccd', '2025-11-14 04:26:51.515813', false, 4992410355, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAECyX5pFoOUZwABRPe-EDaV9BDa5HagENsAAuMMaxuc3bFQ84jr_vXFZNoBAAMCAANtAAM2BA", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 176, "heightPx": 255}, {"file": {"fileId": "AgACAgQAAxkBAAECyYZpFoUsaI4pgqre7auhjR3jCQThHgAC5AxrG5zdsVAm2jSZg9Zr7QEAAwIAA20AAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 199, "heightPx": 279}], "prompt": "\"A realistic black-and-white close-up portrait of a young boy and girl, both holding a calm gaze toward the camera as if the girl is holding a phone in her hand. (Use the reference faces and make no changes to the expression, smile, hair, jaw angle, or anything else.) The young girl, wearing a white hoodie, is kissing the boy (matching the reference subject exactly without altering any details like facial expression, hair, beard, mustache, lips, or nose). The girl has her arm around the boy’s neck and presses her cheek against his, symbolizing closeness and intimacy. The boy is wearing a black hoodie and holding a cigarette in his hand.\"", "operation": "gen-multi-input"}', '254y2x7ee5rma0ctfzwbp80cf4', 'failed', '{"date": 1763083600, "chatId": 1966774840, "messageId": 182668}', '{"date": 1763083608, "chatId": 1966774840, "messageId": 182672}', '[{"date": 1763083608, "chatId": 1966774840, "messageId": 182672}]');
