INSERT INTO public.operations VALUES ('ec7c89b6-42db-4efb-af3b-43d50113452d', '2025-11-15 11:16:29.156274', false, 4649496730, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgUAAxkBAAEC341pGDbQA-dnLnrxAgIdWkyytddOvwAC3AtrGwvlwVS0goEGWAIRAgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1052, "heightPx": 780}], "prompt": "Nude", "operation": "gen-multi-input"}', '42x6ng2h7drmc0ctgtb89jefk8', 'succeeded', '{"date": 1763194576, "chatId": 8229542894, "messageId": 188301}', '{"date": 1763194581, "chatId": 8229542894, "messageId": 188304}', '[{"date": 1763194601, "chatId": 8229542894, "messageId": 188305}]');
INSERT INTO public.operations VALUES ('c5fe38a4-529b-4a75-8d07-ff1abed9ac6c', '2025-11-15 12:38:21.424475', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEC3_5pGEk-oEincmS0pHH6sSEvpXVEXQACwwxrG262yUi-wntcvjij8QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай изображение,максимально сохрани мою внешность и черты лица.\nИнтерьер лифта из нержавеющей стали с зеркальными стенами, подсвеченными кнопками и мягким светом. Атмосфера холодная, элегантная, с мягкими отражениями.\nМолодая стройная женщина (не менять лицо). Уверенный взгляд в камеру, лёгкая полуулыбка.\nСерая оверсайз толстовка из хлопкового флиса, белая дутая оверсайз жилетка. серебряные серьги и кольцо, белый маникюр. В правой руке iPhone, делает селфи; левой держит огромный букет бело-кремовых роз в матовой бумаге с лентой. Букет полностью закрывает тело.\nКамера iPhone 16 Pro, фронтальная, 4:3, уровень глаз, поворот плеч ¾, фокус на лице и букетах. Освещение мягкое — потолочный свет и экран телефона, баланс ≈ 4800 K, лёгкая недоэкспозиция.\nМакияж: чистая кожа, лёгкий контур, дымчатые глаза, блестящие губы холодно-розового оттенка.\nСтиль: ультрареализм, отражения естественные, без CGI.", "operation": "gen-multi-input"}', 'dz76x2t589rma0ctgvgsevkecr', 'succeeded', '{"date": 1763199485, "chatId": 1287537311, "messageId": 188442}', '{"date": 1763199500, "chatId": 1287537311, "messageId": 188447}', '[{"date": 1763199512, "chatId": 1287537311, "messageId": 188448}]');
INSERT INTO public.operations VALUES ('9f6b6ac4-a118-4b31-b7ba-ecba49520252', '2025-11-15 12:35:12.175074', false, 5013320058, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEC3_5pGEk-oEincmS0pHH6sSEvpXVEXQACwwxrG262yUi-wntcvjij8QEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создай изображение не меняя черты лица. Крупноплановый студийный портрет, хедшот (headshot), сфокусированный на лице. Женщина в элегантной, объемной, белой пушистой меховой шапке и белом облегающем лонгсливе с горлом. Глаза закрыты, голова слегка опрокинута назад. Рука мягко обрамляет лицо, яркое, мягкое студийное освещение (high-key), рассеянный свет, чистый белый фон. Снимок в высоком разрешении, гипердетализированный, с реалистичной текстурой кожи. Фэшн-съёмка, кадр из бьюти-рекламы или глянцевого журнала. Макияж нюдовый, акцент на серо-голубых глазах, полные губы с блеском, аккуратные брови, французский маникюр (белые кончики), крупные золотые серьги-шары. Сверхвысокое разрешение, 8K, DSLR, профессиональная фотография. Волосы длинные, спадают по плечам, на руках браслеты золотого цвета.", "operation": "gen-multi-input"}', 'qp1bwyb289rmc0ctgvfaak6hj8', 'succeeded', '{"date": 1763199294, "chatId": 1287537311, "messageId": 188414}', '{"date": 1763199310, "chatId": 1287537311, "messageId": 188419}', '[{"date": 1763199322, "chatId": 1287537311, "messageId": 188422}]');
