INSERT INTO public.operations VALUES ('56028def-1709-4ff7-b975-044451de681c', '2025-11-18 23:54:53.844348', false, 9268205733, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDGeZpHN0CP23JlRZswbUT7zk3Gu8kKQACaBZrG3hS4UgarptekZeyTAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "На фоне зимнего поля с зелёными ёлками . Атмосфера холодная, элегантная. \nМолодая девушка (не менять лицо). Уверенный взгляд в камеру, лёгкая полуулыбка.\nРозовая оверсайз толстовка из хлопкового флиса, серебряные серьги и кольцо, красный маникюр. В руках держит огромный букет бело-кремовых цветов (розы, пионы, гортензии и др.) в матовой бумаге с лентой. Букет полностью закрывает тело.\nКамера iPhone 16 Pro, фронтальная, 4:3, уровень глаз, поворот плеч ¾, фокус на лице и букетах. Освещение мягкое —   , баланс ≈ 4800 K, лёгкая недоэкспозиция.\nМакияж: чистая кожа, лёгкий контур, дымчатые глаза, блестящие губы холодно-красного оттенка.\nСтиль: ультрареализм, отражения естественные, без CGI.", "operation": "gen-multi-input"}', 'brqd1pnxr9rma0ctk2zv7x47vr', 'succeeded', '{"date": 1763499266, "chatId": 6527318256, "messageId": 203238}', '{"date": 1763499276, "chatId": 6527318256, "messageId": 203241}', '[{"date": 1763499306, "chatId": 6527318256, "messageId": 203242}]');
