INSERT INTO public.operations VALUES ('19f51527-0779-409d-8495-b10ece7a0e45', '2025-11-18 23:57:34.76751', false, 9268205733, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDGfFpHN1ez7fykdYX0Nr9o1IPUTS9KwACaxZrG3hS4UgCnmck5HvlwQEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1280, "heightPx": 960}], "prompt": "На фоне зимнего поля с зелёными ёлками . Атмосфера холодная, элегантная. \nМолодая девушка (не менять лицо). Уверенный взгляд в сторону, отвернувшись. \nРозовая оверсайз толстовка из хлопкового флиса, серебряные серьги и кольцо, красный маникюр, копюшон надет. В руках держит огромный букет бело-кремовых цветов (розы, пионы, гортензии и др.) в матовой бумаге с лентой. Букет полностью закрывает тело.\nКамера iPhone 16 Pro, фронтальная, 4:3, уровень глаз, поворот плеч ¾, фокус на лице и букетах. Освещение мягкое —   , баланс ≈ 4800 K, лёгкая недоэкспозиция.\nМакияж: чистая кожа, лёгкий контур, дымчатые глаза, блестящие губы холодно-красного оттенка.\nСтиль: ультрареализм, отражения естественные, без CGI.", "operation": "gen-multi-input"}', '317yn2shy5rma0ctk31b1rvzng', 'succeeded', '{"date": 1763499358, "chatId": 6527318256, "messageId": 203249}', '{"date": 1763499452, "chatId": 6527318256, "messageId": 203254}', '[{"date": 1763499466, "chatId": 6527318256, "messageId": 203255}]');
INSERT INTO public.operations VALUES ('3fa8f716-3dbf-423b-999e-290a28315996', '2025-11-19 00:00:02.174376', false, 9268205733, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDGfhpHN3vwI8YpOVtLG5QnbODFUYhkAACbxZrG3hS4UhD_9vwzOnVxAEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 959, "heightPx": 1280}], "prompt": "На фоне зимнего поля с зелёными ёлками . Атмосфера холодная, элегантная. \nМолодая девушка (не менять лицо). Голова повернутая в бок, лица самого не видно. \nРозовая оверсайз толстовка из хлопкового флиса, серебряные серьги и кольцо, красный маникюр. Волосы спадают вперёд по плечам. В руках держит огромный букет бело-кремовых цветов (розы, пионы, гортензии и др.) в матовой бумаге с лентой. Букет полностью закрывает тело.\nКамера iPhone 16 Pro, фронтальная, 4:3, уровень глаз, поворот плеч ¾, фокус на лице и букетах. Освещение мягкое —   , баланс ≈ 4800 K, лёгкая недоэкспозиция.\nМакияж: чистая кожа, лёгкий контур, дымчатые глаза, блестящие губы холодно-красного оттенка.\nСтиль: ультрареализм, отражения естественные, без CGI.", "operation": "gen-multi-input"}', 'yj72kfkjf9rma0ctk3285hz9g4', 'succeeded', '{"date": 1763499503, "chatId": 6527318256, "messageId": 203256}', '{"date": 1763499600, "chatId": 6527318256, "messageId": 203262}', '[{"date": 1763499612, "chatId": 6527318256, "messageId": 203263}]');
