INSERT INTO public.operations VALUES ('aba6736f-aa21-47cd-9d07-2fd3d67d1b15', '2025-11-19 20:34:04.837179', false, 4795581232, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDIp5pHf99THMahArJ7etenzDFc6aA-AAC3xBrG9dT8UgHSaiaO_6A4wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 992, "heightPx": 1280}], "prompt": "Сделай красивую надпись стандартным белым шрифтом сверху по центру: сначала напиши «••Для бережного очищения зубов и брекетов» маленьким шрифтом, ниже большим шрифтом напиши «ёршики», пониже напиши средним шрифтом «межзубные». Текст должен быть одно длины. Также в правом нижнем углу сделай розовый круг, границы которого обрезают угол фотографии, круг сделай с двумя тонкими белыми границами. В этом кругу белым стандартным шрифтом напиши большими цифрами «20», под цифрами шрифтом поменьше напиши «штук»", "operation": "gen-multi-input"}', 'pstw1w9zesrma0ctkmq962x930', 'succeeded', '{"date": 1763573629, "chatId": 1443523754, "messageId": 205470}', '{"date": 1763573642, "chatId": 1443523754, "messageId": 205475}', '[{"date": 1763573654, "chatId": 1443523754, "messageId": 205478}]');
