INSERT INTO public.operations VALUES ('d10f1a34-2623-4ade-b673-30de8cf78bdc', '2025-11-19 20:42:16.796985', false, 7382462063, 7, 0.03, '{"config": {"model": "bytedance/seedream-4", "seedream4": {"size": {"size": "2K", "custom": false, "aspectRatio": "9:16"}, "maxImages": 1, "sequentialGeneration": "disable"}}, "photos": [{"file": {"fileId": "AgACAgQAAxkBAAEDIs5pHgEOUmHuq0NTu3y4F7lFBJHC_wAChAxrGyzl8FC1_J42R2kPkwEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1170, "heightPx": 1160}], "prompt": "Transform this photo into a Dragon Ball Z–style illustration.\nReplace the father’s face with Son Goku’s adult face, keeping his real facial features adapted to the anime style.\nReplace the child’s face with young Son Gohan’s face, also adapted to the anime style.\nRecreate the classic scene of Goku flying on the Flying Nimbus (Kinto’un), bright yellow with its characteristic yellow trail.\nGoku must wear his original outfit: orange-red gi, blue belt, blue wristbands.\nThe child (Gohan) must sit on Goku’s shoulders, just like in the anime.\nGohan must wear his iconic yellow outfit with red hat and blue trim.\nUse the authentic Dragon Ball Z anime look: sharp line art, saturated colors, 90s-style shading.\nBackground: simple blue sky with soft clouds.\nMaintain realistic resemblance of both faces while fully converting them into the DBZ anime aesthetic.”", "operation": "gen-multi-input"}', 'b4v1hqp0v9rm80ctkmttg5ez4r', 'failed', '{"date": 1763574107, "chatId": 879032628, "messageId": 205528}', '{"date": 1763574115, "chatId": 879032628, "messageId": 205531}', '[{"date": 1763574115, "chatId": 879032628, "messageId": 205531}]');
