INSERT INTO public.operations VALUES ('3751e021-64b5-4476-b80a-89d177b6e1ef', '2025-11-21 08:56:05.842082', false, 9093213906, 8, 0.039, '{"config": {"model": "google/nano-banana", "nanoBanana": {"format": "jpg"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDNhxpH_xAUDvs212SbFK89Kddd5edWAACLA1rGw2VAUmJKDt5YdKv8wEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Этот пуловер надет на  молодом человеке с длинными вьющимися волосами ,креативная причёска, он модельной внешности и телосложения.Славянская внешность , московская. Пуловер облегает его фигуру, показывая атлетическое телосложение.Черные джинсы и кожаные кеды. На одной руке аксессуар из букв MGNM, на пальце другой руки кольцо .\nМолодой человек идёт вдоль стены на улице, улыбается", "operation": "gen-multi-input"}', '78zqvazhrhrm80ctmkxs0yznmw', 'succeeded', '{"date": 1763703872, "chatId": 7511659669, "messageId": 210460}', '{"date": 1763704534, "chatId": 7511659669, "messageId": 210466}', '[{"date": 1763704579, "chatId": 7511659669, "messageId": 210471}]');
