INSERT INTO public.operations VALUES ('4ddc0949-4e1c-4075-8453-f7340bb1f5ff', '2025-11-22 08:15:27.212569', false, 5013320058, 15, 0.14, '{"config": {"model": "google/nano-banana-pro", "nanoBananaPro": {"size": "1K", "format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDPiRpIUbjST0ugOUZDeXZwNuTlpaH_QACgxFrG9e9CUkOCVb27xygvgEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 1005, "heightPx": 1280}], "prompt": "Создайте образ девушки сидящей на яхте в открытом море, на фоне морского пейзажа.\nДевушка с черными волосами , лицо не меняй , одета в элегантный черный Боди корсетного плана (без лямок) и в накидке белой изящно струящейся из мягкой, воздушной ткани, которая мягко колышется на ветру. Боди слегка блестит, подчеркивая гладкую текстуру материала, похожего на шелк, и мягко ниспадает к низу. Она сидит с безмятежным выражением Ю лица с закрытыми глазами, девушка подняла две руки и одну руку засунула себе в волосы, вторая поднята вверх.\nумиротворяющая атмосфера, присутствует на снимке.\nНа заднем плане море , создавая обширную,открытую и естественную обстановку. Солнце освещает.", "operation": "gen-multi-input"}', 'h2yaw20qkxrmc0ctn7yvjgwrdc', 'succeeded', '{"date": 1763788515, "chatId": 1287537311, "messageId": 212516}', '{"date": 1763788520, "chatId": 1287537311, "messageId": 212521}', '[{"date": 1763788567, "chatId": 1287537311, "messageId": 212522}]');
INSERT INTO public.operations VALUES ('496231b3-27df-4417-9431-61413e508a2b', '2025-11-22 08:17:39.183656', false, 5013320058, 15, 0.14, '{"config": {"model": "google/nano-banana-pro", "nanoBananaPro": {"size": "1K", "format": "jpg", "aspectRatio": "as-input"}}, "photos": [{"file": {"fileId": "AgACAgIAAxkBAAEDPitpIUdupPTkJ_JgmYB92if6ZHJAhAAChxFrG9e9CUmiWeLWU8Tj0AEAAwIAA3kAAzYE", "storage": "telegram", "mimeType": "image/jpeg"}, "widthPx": 960, "heightPx": 1280}], "prompt": "Создайте образ девушки сидящей на яхте в открытом море, на фоне морского пейзажа.\nДевушка с черными волосами , лицо не меняй , одета в элегантный черный Боди корсетного плана (без лямок) и в накидке белой изящно струящейся из мягкой, воздушной ткани, которая мягко колышется на ветру. Боди слегка блестит, подчеркивая гладкую текстуру материала, похожего на шелк, и мягко ниспадает к низу. Она сидит с безмятежным выражением Ю лица с закрытыми глазами, девушка подняла две руки и одну руку засунула себе в волосы, вторая поднята вверх.\nумиротворяющая атмосфера, присутствует на снимке.\nНа заднем плане море , создавая обширную,открытую и естественную обстановку. Солнце освещает.", "operation": "gen-multi-input"}', 'tsy84q0tmxrm80ctn7zs8trx7g', 'succeeded', '{"date": 1763788654, "chatId": 1287537311, "messageId": 212523}', '{"date": 1763788657, "chatId": 1287537311, "messageId": 212528}', '[{"date": 1763788699, "chatId": 1287537311, "messageId": 212529}]');
